const HSK3_DATA = {"lessons":[{"id":1,"title_cn":"我们去机场接你们","title_pinyin":"Wǒmen qù jīchǎng jiē nǐmen","title_vn":"Chúng tôi đi đón các bạn ở sân bay","goals":["Có thể nghe hiểu và sử dụng định ngữ nhiều lớp để miêu tả đặc điểm của người hoặc sự vật.","Có thể nghe hiểu và giải quyết các vấn đề liên quan đến việc làm mất đồ vật.","Nắm vững cách dùng của đại từ nghi vấn, có thể diễn đạt thông tin về người, sự vật hoặc địa điểm không xác định."],"vocab":[{"hanzi":"以为","pinyin":"yǐwéi","pos":"dgt.","vn":"nghĩ rằng, cho rằng (nhưng thực tế không phải vậy)","examples":[{"cn":"我以为你不来了。","pinyin":"Wǒ yǐwéi nǐ bù lái le.","vn":"Tôi cứ tưởng bạn không đến nữa."},{"cn":"我以为今天是星期五，原来是星期四。","pinyin":"Wǒ yǐwéi jīntiān shì xīngqīwǔ, yuánlái shì xīngqīsì.","vn":"Tôi tưởng hôm nay là thứ Sáu, hóa ra là thứ Năm."},{"cn":"他以为我生气了，其实我没有。","pinyin":"Tā yǐwéi wǒ shēngqì le, qíshí wǒ méiyǒu.","vn":"Anh ấy tưởng tôi giận, thực ra thì không."}]},{"hanzi":"像","pinyin":"xiàng","pos":"dgt.","vn":"giống","examples":[{"cn":"你长得很像你妈妈。","pinyin":"Nǐ zhǎng de hěn xiàng nǐ māma.","vn":"Bạn trông rất giống mẹ bạn."},{"cn":"这朵云像一只小狗。","pinyin":"Zhè duǒ yún xiàng yì zhī xiǎo gǒu.","vn":"Đám mây này giống như một chú chó con."},{"cn":"他说话的样子像老师。","pinyin":"Tā shuōhuà de yàngzi xiàng lǎoshī.","vn":"Cách anh ấy nói chuyện giống như giáo viên."}]},{"hanzi":"长","pinyin":"zhǎng","pos":"dgt.","vn":"lớn lên, phát triển","examples":[{"cn":"孩子长得真快。","pinyin":"Háizi zhǎng de zhēn kuài.","vn":"Trẻ con lớn thật nhanh."},{"cn":"他在北京长大。","pinyin":"Tā zài Běijīng zhǎngdà.","vn":"Anh ấy lớn lên ở Bắc Kinh."},{"cn":"这棵树长得很高了。","pinyin":"Zhè kē shù zhǎng de hěn gāo le.","vn":"Cái cây này đã lớn rất cao rồi."}]},{"hanzi":"身高","pinyin":"shēngāo","pos":"dt.","vn":"chiều cao","examples":[{"cn":"你的身高是多少？","pinyin":"Nǐ de shēngāo shì duōshao?","vn":"Chiều cao của bạn là bao nhiêu?"},{"cn":"他身高一米八，是我们班最高的。","pinyin":"Tā shēngāo yì mǐ bā, shì wǒmen bān zuì gāo de.","vn":"Anh ấy cao 1m8, là người cao nhất lớp chúng tôi."},{"cn":"这个工作对身高有要求。","pinyin":"Zhège gōngzuò duì shēngāo yǒu yāoqiú.","vn":"Công việc này có yêu cầu về chiều cao."}]},{"hanzi":"米","pinyin":"mǐ","pos":"lượng.","vn":"mét","examples":[{"cn":"这条路有一百米长。","pinyin":"Zhè tiáo lù yǒu yì bǎi mǐ cháng.","vn":"Con đường này dài một trăm mét."},{"cn":"他跑一百米只用了十二秒。","pinyin":"Tā pǎo yìbǎi mǐ zhǐ yòng le shí'èr miǎo.","vn":"Anh ấy chạy một trăm mét chỉ mất mười hai giây."},{"cn":"我家离学校大概五百米。","pinyin":"Wǒ jiā lí xuéxiào dàgài wǔ bǎi mǐ.","vn":"Nhà tôi cách trường khoảng năm trăm mét."}]},{"hanzi":"瘦","pinyin":"shòu","pos":"tt.","vn":"gầy","examples":[{"cn":"你最近怎么瘦了这么多？","pinyin":"Nǐ zuìjìn zěnme shòu le zhème duō?","vn":"Sao dạo này bạn gầy đi nhiều vậy?"},{"cn":"她一直想减肥，想变瘦一点。","pinyin":"Tā yìzhí xiǎng jiǎnféi, xiǎng biàn shòu yìdiǎn.","vn":"Cô ấy luôn muốn giảm cân, muốn gầy hơn một chút."},{"cn":"这件衣服太瘦了，我穿不下。","pinyin":"Zhè jiàn yīfu tài shòu le, wǒ chuān bu xià.","vn":"Chiếc áo này quá chật, tôi mặc không vừa."}]},{"hanzi":"接","pinyin":"jiē","pos":"dgt.","vn":"đón","examples":[{"cn":"我去机场接你。","pinyin":"Wǒ qù jīchǎng jiē nǐ.","vn":"Tôi đi ra sân bay đón bạn."},{"cn":"你今天几点能来接我？","pinyin":"Nǐ jīntiān jǐ diǎn néng lái jiē wǒ?","vn":"Hôm nay mấy giờ bạn có thể đến đón tôi?"},{"cn":"他每天下班去幼儿园接孩子。","pinyin":"Tā měitiān xiàbān qù yòu'éryuán jiē háizi.","vn":"Ngày nào anh ấy cũng tan làm đi đón con ở nhà trẻ."}]},{"hanzi":"行李","pinyin":"xíngli","pos":"dt.","vn":"hành lý","examples":[{"cn":"你的行李太多了，我来帮你拿。","pinyin":"Nǐ de xíngli tài duō le, wǒ lái bāng nǐ ná.","vn":"Hành lý của bạn nhiều quá, để tôi giúp bạn xách."},{"cn":"我们先去办理行李托运吧。","pinyin":"Wǒmen xiān qù bànlǐ xíngli tuōyùn ba.","vn":"Chúng ta đi làm thủ tục ký gửi hành lý trước đi."},{"cn":"机场的行李还没出来。","pinyin":"Jīchǎng de xíngli hái méi chūlái.","vn":"Hành lý ở sân bay vẫn chưa ra."}]},{"hanzi":"丢","pinyin":"diū","pos":"dgt.","vn":"mất, làm mất","examples":[{"cn":"我把手机丢了。","pinyin":"Wǒ bǎ shǒujī diū le.","vn":"Tôi làm mất điện thoại rồi."},{"cn":"别把护照弄丢了。","pinyin":"Bié bǎ hùzhào nòng diū le.","vn":"Đừng làm mất hộ chiếu đấy."},{"cn":"他总是丢三落四的。","pinyin":"Tā zǒngshì diū sān là sì de.","vn":"Anh ấy lúc nào cũng hay đãng trí làm mất đồ."}]},{"hanzi":"箱子","pinyin":"xiāngzi","pos":"dt.","vn":"va li, hộp","examples":[{"cn":"这个箱子太重了，我提不动。","pinyin":"Zhège xiāngzi tài zhòng le, wǒ tí bu dòng.","vn":"Cái va li này nặng quá, tôi xách không nổi."},{"cn":"东西都放在箱子里了。","pinyin":"Dōngxi dōu fàng zài xiāngzi lǐ le.","vn":"Đồ đạc đều đã để trong hộp rồi."},{"cn":"我买了一个新箱子去旅行。","pinyin":"Wǒ mǎi le yí gè xīn xiāngzi qù lǚxíng.","vn":"Tôi đã mua một cái va li mới để đi du lịch."}]},{"hanzi":"号码","pinyin":"hàomǎ","pos":"dt.","vn":"số (điện thoại, mã số)","examples":[{"cn":"你能告诉我你的电话号码吗？","pinyin":"Nǐ néng gàosu wǒ nǐ de diànhuà hàomǎ ma?","vn":"Bạn có thể cho tôi biết số điện thoại của bạn không?"},{"cn":"我忘了房间号码。","pinyin":"Wǒ wàng le fángjiān hàomǎ.","vn":"Tôi quên mất số phòng rồi."},{"cn":"这个号码是空号。","pinyin":"Zhège hàomǎ shì kōnghào.","vn":"Số này không tồn tại."}]},{"hanzi":"好像","pinyin":"hǎoxiàng","pos":"phó.","vn":"hình như, dường như","examples":[{"cn":"外面好像在下雨。","pinyin":"Wàimiàn hǎoxiàng zài xiàyǔ.","vn":"Hình như bên ngoài đang mưa."},{"cn":"他好像不太高兴。","pinyin":"Tā hǎoxiàng bú tài gāoxìng.","vn":"Anh ấy có vẻ không vui lắm."},{"cn":"我好像在哪儿见过你。","pinyin":"Wǒ hǎoxiàng zài nǎr jiàn guo nǐ.","vn":"Hình như tôi đã gặp bạn ở đâu đó rồi."}]},{"hanzi":"重要","pinyin":"zhòngyào","pos":"tt.","vn":"quan trọng","examples":[{"cn":"这件事对我来说很重要。","pinyin":"Zhè jiàn shì duì wǒ lái shuō hěn zhòngyào.","vn":"Việc này rất quan trọng đối với tôi."},{"cn":"健康比什么都重要。","pinyin":"Jiànkāng bǐ shénme dōu zhòngyào.","vn":"Sức khỏe quan trọng hơn mọi thứ."},{"cn":"明天有一个重要的会议。","pinyin":"Míngtiān yǒu yí gè zhòngyào de huìyì.","vn":"Ngày mai có một cuộc họp quan trọng."}]},{"hanzi":"着急","pinyin":"zháojí","pos":"tt.","vn":"lo lắng, sốt ruột","examples":[{"cn":"别着急，慢慢说。","pinyin":"Bié zháojí, mànmàn shuō.","vn":"Đừng lo, từ từ nói."},{"cn":"他还没到，我有点着急。","pinyin":"Tā hái méi dào, wǒ yǒudiǎn zháojí.","vn":"Anh ấy vẫn chưa đến, tôi hơi sốt ruột."},{"cn":"你这么着急去哪儿？","pinyin":"Nǐ zhème zháojí qù nǎr?","vn":"Bạn vội vàng đi đâu vậy?"}]},{"hanzi":"护照","pinyin":"hùzhào","pos":"dt.","vn":"hộ chiếu","examples":[{"cn":"出国旅行一定要带护照。","pinyin":"Chūguó lǚxíng yídìng yào dài hùzhào.","vn":"Đi du lịch nước ngoài nhất định phải mang hộ chiếu."},{"cn":"我的护照快过期了。","pinyin":"Wǒ de hùzhào kuài guòqī le.","vn":"Hộ chiếu của tôi sắp hết hạn rồi."},{"cn":"请出示一下您的护照。","pinyin":"Qǐng chūshì yíxià nín de hùzhào.","vn":"Xin vui lòng xuất trình hộ chiếu của bạn."}]},{"hanzi":"服务台","pinyin":"fúwùtái","pos":"dt.","vn":"quầy phục vụ, quầy lễ tân","examples":[{"cn":"有问题可以去服务台问一下。","pinyin":"Yǒu wèntí kěyǐ qù fúwùtái wèn yíxià.","vn":"Có vấn đề gì có thể ra quầy lễ tân hỏi thử."},{"cn":"服务台在一楼大厅。","pinyin":"Fúwùtái zài yī lóu dàtīng.","vn":"Quầy lễ tân ở sảnh tầng một."},{"cn":"我在服务台丢了东西，去问问看。","pinyin":"Wǒ zài fúwùtái diū le dōngxi, qù wènwen kàn.","vn":"Tôi để quên đồ ở quầy lễ tân, để tôi ra hỏi thử."}]},{"hanzi":"应该","pinyin":"yīnggāi","pos":"đtnn.","vn":"nên, phải","examples":[{"cn":"你应该多休息休息。","pinyin":"Nǐ yīnggāi duō xiūxi xiūxi.","vn":"Bạn nên nghỉ ngơi nhiều hơn."},{"cn":"我们应该准时到。","pinyin":"Wǒmen yīnggāi zhǔnshí dào.","vn":"Chúng ta nên đến đúng giờ."},{"cn":"这件事应该不难。","pinyin":"Zhè jiàn shì yīnggāi bù nán.","vn":"Việc này chắc là không khó."}]},{"hanzi":"站","pinyin":"zhàn","pos":"dgt.","vn":"đứng","examples":[{"cn":"请大家站起来。","pinyin":"Qǐng dàjiā zhàn qǐlai.","vn":"Mời mọi người đứng dậy."},{"cn":"他一直站在门口等我。","pinyin":"Tā yìzhí zhàn zài ménkǒu děng wǒ.","vn":"Anh ấy cứ đứng ở cửa đợi tôi."},{"cn":"车上人太多，我只能站着。","pinyin":"Chē shàng rén tài duō, wǒ zhǐ néng zhàn zhe.","vn":"Trên xe đông người quá, tôi chỉ có thể đứng."}]},{"hanzi":"中间","pinyin":"zhōngjiān","pos":"dt.","vn":"ở giữa","examples":[{"cn":"把花放在桌子中间。","pinyin":"Bǎ huā fàng zài zhuōzi zhōngjiān.","vn":"Đặt hoa ở giữa bàn."},{"cn":"他站在我们中间。","pinyin":"Tā zhàn zài wǒmen zhōngjiān.","vn":"Anh ấy đứng ở giữa chúng tôi."},{"cn":"休息中间我们聊了一会儿天。","pinyin":"Xiūxi zhōngjiān wǒmen liáo le yíhuìr tiān.","vn":"Trong lúc nghỉ giữa giờ, chúng tôi đã trò chuyện một lát."}]},{"hanzi":"短","pinyin":"duǎn","pos":"tt.","vn":"ngắn","examples":[{"cn":"她剪了一个很短的头发。","pinyin":"Tā jiǎn le yí gè hěn duǎn de tóufa.","vn":"Cô ấy cắt một kiểu tóc rất ngắn."},{"cn":"这篇文章太短了。","pinyin":"Zhè piān wénzhāng tài duǎn le.","vn":"Bài văn này ngắn quá."},{"cn":"我们见面的时间很短。","pinyin":"Wǒmen jiànmiàn de shíjiān hěn duǎn.","vn":"Thời gian chúng tôi gặp nhau rất ngắn."}]},{"hanzi":"头发","pinyin":"tóufa","pos":"dt.","vn":"tóc","examples":[{"cn":"你的头发真漂亮。","pinyin":"Nǐ de tóufa zhēn piàoliang.","vn":"Tóc của bạn thật đẹp."},{"cn":"他每天早上都要洗头发。","pinyin":"Tā měitiān zǎoshang dōu yào xǐ tóufa.","vn":"Sáng nào anh ấy cũng gội đầu."},{"cn":"我想去染一下头发。","pinyin":"Wǒ xiǎng qù rǎn yíxià tóufa.","vn":"Tôi muốn đi nhuộm tóc."}]},{"hanzi":"年轻","pinyin":"niánqīng","pos":"tt.","vn":"trẻ, trẻ tuổi","examples":[{"cn":"你看起来比实际年龄年轻。","pinyin":"Nǐ kàn qǐlai bǐ shíjì niánlíng niánqīng.","vn":"Trông bạn trẻ hơn so với tuổi thật."},{"cn":"他还很年轻，才二十岁。","pinyin":"Tā hái hěn niánqīng, cái èrshí suì.","vn":"Anh ấy còn rất trẻ, mới hai mươi tuổi."},{"cn":"年轻的时候应该多出去看看。","pinyin":"Niánqīng de shíhou yīnggāi duō chūqu kànkan.","vn":"Lúc còn trẻ nên đi ra ngoài nhiều để xem thế giới."}]},{"hanzi":"发现","pinyin":"fāxiàn","pos":"dgt.","vn":"phát hiện","examples":[{"cn":"我发现他今天不太一样。","pinyin":"Wǒ fāxiàn tā jīntiān bú tài yíyàng.","vn":"Tôi phát hiện hôm nay anh ấy có vẻ khác thường."},{"cn":"科学家发现了一种新的药。","pinyin":"Kēxuéjiā fāxiàn le yì zhǒng xīn de yào.","vn":"Các nhà khoa học đã phát hiện ra một loại thuốc mới."},{"cn":"我一回家就发现钥匙不见了。","pinyin":"Wǒ yì huí jiā jiù fāxiàn yàoshi bújiàn le.","vn":"Vừa về đến nhà tôi liền phát hiện chìa khóa biến mất."}]},{"hanzi":"不见","pinyin":"bújiàn","pos":"dgt.","vn":"biến mất, không thấy đâu","examples":[{"cn":"我的钥匙怎么不见了？","pinyin":"Wǒ de yàoshi zěnme bújiàn le?","vn":"Sao chìa khóa của tôi lại biến mất rồi?"},{"cn":"他突然不见了，我们到处找他。","pinyin":"Tā tūrán bújiàn le, wǒmen dàochù zhǎo tā.","vn":"Anh ấy đột nhiên biến mất, chúng tôi tìm khắp nơi."},{"cn":"桌子上的钱不见了。","pinyin":"Zhuōzi shàng de qián bújiàn le.","vn":"Tiền để trên bàn biến mất rồi."}]},{"hanzi":"带","pinyin":"dài","pos":"dgt.","vn":"mang theo, mang","examples":[{"cn":"出门别忘了带伞。","pinyin":"Chūmén bié wàng le dài sǎn.","vn":"Ra ngoài đừng quên mang ô."},{"cn":"我可以带朋友一起来吗？","pinyin":"Wǒ kěyǐ dài péngyou yìqǐ lái ma?","vn":"Tôi có thể dẫn bạn bè đi cùng không?"},{"cn":"他带了很多礼物给我们。","pinyin":"Tā dài le hěn duō lǐwù gěi wǒmen.","vn":"Anh ấy mang rất nhiều quà tặng cho chúng tôi."}]},{"hanzi":"帮助","pinyin":"bāngzhù","pos":"dgt.","vn":"giúp đỡ","examples":[{"cn":"谢谢你的帮助。","pinyin":"Xièxie nǐ de bāngzhù.","vn":"Cảm ơn sự giúp đỡ của bạn."},{"cn":"我们应该互相帮助。","pinyin":"Wǒmen yīnggāi hùxiāng bāngzhù.","vn":"Chúng ta nên giúp đỡ lẫn nhau."},{"cn":"他经常帮助别人。","pinyin":"Tā jīngcháng bāngzhù biérén.","vn":"Anh ấy thường xuyên giúp đỡ người khác."}]},{"hanzi":"照片","pinyin":"zhàopiàn","pos":"dt.","vn":"ảnh, hình chụp","examples":[{"cn":"这张照片拍得真好看。","pinyin":"Zhè zhāng zhàopiàn pāi de zhēn hǎokàn.","vn":"Tấm ảnh này chụp thật đẹp."},{"cn":"给我看看你的旅行照片吧。","pinyin":"Gěi wǒ kànkan nǐ de lǚxíng zhàopiàn ba.","vn":"Cho tôi xem thử ảnh du lịch của bạn đi."},{"cn":"我把照片发到了朋友圈。","pinyin":"Wǒ bǎ zhàopiàn fā dào le péngyouquān.","vn":"Tôi đã đăng ảnh lên vòng bạn bè."}]}],"grammar":[{"title":"固定短语\"看上去/看起来\" - Cụm cố định \"看上去/看起来\"","explanation_vn":"Cụm từ cố định \"看上去\" và \"看起来\" được dùng để miêu tả vẻ ngoài hoặc trạng thái của một người hoặc một vật.","examples":[{"cn":"他们看上去有点儿像。","pinyin":"Tāmen kàn shàngqù yǒudiǎnr xiàng.","vn":""},{"cn":"这些菜看起来都很好吃。","pinyin":"Zhèxiē cài kàn qǐlái dōu hěn hǎochī.","vn":""},{"cn":"那个新来的老师看上去很年轻。","pinyin":"Nàge xīn lái de lǎoshī kàn shàngqù hěn niánqīng.","vn":""}]},{"title":"疑问代词的非疑问用法（1） - Cách dùng phi nghi vấn của đại từ nghi vấn (1)","explanation_vn":"Các đại từ nghi vấn như \"哪儿\", \"什么\", \"谁\", \"哪\" khi dùng trong câu trần thuật (không phải câu hỏi) biểu thị địa điểm, sự vật hoặc người không xác định hoặc không cần chỉ rõ cụ thể.","examples":[{"cn":"我好像在哪儿看到过这个箱子。","pinyin":"Wǒ hǎoxiàng zài nǎr kàndào guo zhège xiāngzi.","vn":""},{"cn":"你吃点儿什么再走吧。","pinyin":"Nǐ chī diǎnr shénme zài zǒu ba.","vn":""},{"cn":"我们哪天一起去踢足球吧。","pinyin":"Wǒmen nǎ tiān yìqǐ qù tī zúqiú ba.","vn":""}]},{"title":"多项定语 - Định ngữ nhiều lớp (Multiple Attributives)","explanation_vn":"Trung tâm ngữ danh từ có thể đồng thời có nhiều định ngữ đứng trước. Các định ngữ này thường được sắp xếp theo thứ tự: thời gian/nơi chốn → động tác/trạng thái → đặc điểm. Cụm số lượng hoặc cụm chỉ định-lượng có vị trí tương đối linh hoạt, có thể đặt trước hoặc sau định ngữ biểu thị động tác hoặc trạng thái.","examples":[{"cn":"李文是那个穿着黑衣服的短头发的年轻人吗？","pinyin":"Lǐ Wén shì nàge chuānzhe hēi yīfu de duǎn tóufa de niánqīng rén ma?","vn":""},{"cn":"昨天和家月一起看电影的两个人是我的朋友。","pinyin":"Zuótiān hé Jiāyuè yìqǐ kàn diànyǐng de liǎng ge rén shì wǒ de péngyou.","vn":""},{"cn":"我那件新买的白色的衣服在哪儿？","pinyin":"Wǒ nà jiàn xīn mǎi de báisè de yīfu zài nǎr?","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"刘明","cn":"这是杨同乐吗？他怎么跟白家月在一起？","pinyin":"Zhè shì Yáng Tónglè ma? Tā zěnme gēn Bái Jiāyuè zài yìqǐ?"},{"speaker":"王一雪","cn":"他不是杨同乐，他叫李文，是白家月的好朋友。","pinyin":"Tā bú shì Yáng Tónglè, tā jiào Lǐ Wén, shì Bái Jiāyuè de hǎo péngyou."},{"speaker":"刘明","cn":"我还以为是同乐呢，他们看上去有点儿像。","pinyin":"Wǒ hái yǐwéi shì Tónglè ne, tāmen kàn shàngqù yǒudiǎnr xiàng."},{"speaker":"王一雪","cn":"是长得有点儿像，但是他比同乐高，身高有一米八。","pinyin":"Shì zhǎng de yǒudiǎnr xiàng, dànshì tā bǐ Tónglè gāo, shēngāo yǒu yì mǐ bā."},{"speaker":"刘明","cn":"看起来也比同乐瘦一点儿。","pinyin":"Kàn qǐlái yě bǐ Tónglè shòu yìdiǎnr."},{"speaker":"王一雪","cn":"下个星期家月和李文要来北京，我去机场接他们。","pinyin":"Xià ge xīngqī Jiāyuè hé Lǐ Wén yào lái Běijīng, wǒ qù jīchǎng jiē tāmen."},{"speaker":"刘明","cn":"他们哪天到北京？我跟你一起去机场接他们吧。","pinyin":"Tāmen nǎ tiān dào Běijīng? Wǒ gēn nǐ yìqǐ qù jīchǎng jiē tāmen ba."}],"translation_vn":"Lưu Minh: Đây là Dương Đồng Nhạc à? Sao anh ấy lại ở cùng Bạch Gia Nguyệt vậy?\nVương Nhất Tuyết: Anh ấy không phải Dương Đồng Nhạc, anh ấy tên Lý Văn, là bạn thân của Bạch Gia Nguyệt.\nLưu Minh: Em còn tưởng là Đồng Nhạc chứ, nhìn họ hơi giống nhau.\nVương Nhất Tuyết: Đúng là trông hơi giống, nhưng anh ấy cao hơn Đồng Nhạc, cao một mét tám.\nLưu Minh: Nhìn cũng gầy hơn Đồng Nhạc một chút.\nVương Nhất Tuyết: Tuần sau Gia Nguyệt và Lý Văn sẽ đến Bắc Kinh, em sẽ ra sân bay đón họ.\nLưu Minh: Hôm nào họ đến Bắc Kinh? Anh cùng em ra sân bay đón họ nhé.","audio_dialogue":"1-1.mp3","audio_vocab":"1-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"白家月","cn":"我的行李怎么还没出来？是不是丢了？","pinyin":"Wǒ de xíngli zěnme hái méi chūlái? Shì bú shì diū le?"},{"speaker":"李文","cn":"你的行李箱是什么样的？","pinyin":"Nǐ de xínglixiāng shì shénme yàng de?"},{"speaker":"白家月","cn":"是一个黑色的箱子，上面写着我的名字和电话号码。","pinyin":"Shì yí ge hēisè de xiāngzi, shàngmiàn xiězhe wǒ de míngzi hé diànhuà hàomǎ."},{"speaker":"李文","cn":"我好像在哪儿看到过这个箱子，是不是有人拿错了？","pinyin":"Wǒ hǎoxiàng zài nǎr kàndào guo zhège xiāngzi, shì bú shì yǒurén ná cuò le?"},{"speaker":"白家月","cn":"我们快找谁问一下吧，箱子里有不少重要的东西。","pinyin":"Wǒmen kuài zhǎo shéi wèn yíxià ba, xiāngzi li yǒu bùshǎo zhòngyào de dōngxi."},{"speaker":"李文","cn":"别着急，我们拿着护照和机票，去服务台问问吧。","pinyin":"Bié zháojí, wǒmen názhe hùzhào hé jīpiào, qù fúwùtái wènwen ba."}],"translation_vn":"Bạch Gia Nguyệt: Sao hành lý của mình vẫn chưa ra vậy? Có bị mất không nhỉ?\nLý Văn: Va li của cậu trông như thế nào?\nBạch Gia Nguyệt: Là một chiếc va li màu đen, trên đó có ghi tên và số điện thoại của mình.\nLý Văn: Hình như mình đã thấy chiếc va li này ở đâu đó rồi, hay là có ai lấy nhầm?\nBạch Gia Nguyệt: Chúng ta mau tìm ai đó hỏi thử đi, trong va li có không ít đồ quan trọng.\nLý Văn: Đừng lo lắng, chúng ta cầm theo hộ chiếu và vé máy bay, đến quầy phục vụ hỏi thử xem.","audio_dialogue":"1-3.mp3","audio_vocab":"1-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"刘明","cn":"飞机早就到了，你看见白家月他们了吗？","pinyin":"Fēijī zǎo jiù dào le, nǐ kànjiàn Bái Jiāyuè tāmen le ma?"},{"speaker":"王一雪","cn":"没有，他们应该快出来了。","pinyin":"Méiyǒu, tāmen yīnggāi kuài chūlái le."},{"speaker":"刘明","cn":"我们站到中间去吧，这样他们好找一些。","pinyin":"Wǒmen zhàn dào zhōngjiān qù ba, zhèyàng tāmen hǎo zhǎo yìxiē."},{"speaker":"王一雪","cn":"你看那个高个子的人是李文吗？","pinyin":"Nǐ kàn nàge gāo gèzi de rén shì Lǐ Wén ma?"},{"speaker":"刘明","cn":"你说的是哪个？那个穿着黑衣服的短头发的年轻人？","pinyin":"Nǐ shuō de shì nǎge? Nàge chuānzhe hēi yīfu de duǎn tóufa de niánqīng rén?"},{"speaker":"王一雪","cn":"对，那个人就是李文！你看，家月在他后面呢。","pinyin":"Duì, nàge rén jiù shì Lǐ Wén! Nǐ kàn, Jiāyuè zài tā hòumiàn ne."}],"translation_vn":"Lưu Minh: Máy bay hạ cánh lâu rồi, em có thấy Bạch Gia Nguyệt họ chưa?\nVương Nhất Tuyết: Chưa, chắc họ sắp ra rồi.\nLưu Minh: Chúng ta đứng vào giữa đi, như vậy họ dễ tìm thấy hơn.\nVương Nhất Tuyết: Anh xem người cao cao kia có phải Lý Văn không?\nLưu Minh: Em nói người nào? Cái anh chàng trẻ tuổi tóc ngắn mặc áo đen đó à?\nVương Nhất Tuyết: Đúng rồi, người đó chính là Lý Văn! Anh xem kìa, Gia Nguyệt ở phía sau anh ấy đấy.","audio_dialogue":"1-5.mp3","audio_vocab":"1-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"昨天我到北京了。","pinyin":"Zuótiān wǒ dào Běijīng le."},{"speaker":"","cn":"虽然路上花了十几个小时，但是跟家月坐在一起，我觉得时间过得很快。","pinyin":"Suīrán lùshang huāle shí jǐ ge xiǎoshí, dànshì gēn Jiāyuè zuò zài yìqǐ, wǒ juéde shíjiān guò de hěn kuài."},{"speaker":"","cn":"到机场的时候，家月发现行李箱不见了，我带她去服务台，帮助她找到了行李箱。","pinyin":"Dào jīchǎng de shíhou, Jiāyuè fāxiàn xínglixiāng bújiàn le, wǒ dài tā qù fúwùtái, bāngzhù tā zhǎodàole xínglixiāng."},{"speaker":"","cn":"走出机场的时候，已经八点多了，我们一出来就看见了王老师的姐姐，她看起来比照片上年轻。","pinyin":"Zǒuchū jīchǎng de shíhou, yǐjīng bā diǎn duō le, wǒmen yì chūlái jiù kànjiànle Wáng lǎoshī de jiějie, tā kàn qǐlái bǐ zhàopiàn shàng niánqīng."},{"speaker":"","cn":"晚上，一雪姐带我们去吃了一家很好吃的中国菜。","pinyin":"Wǎnshang, Yīxuě jiě dài wǒmen qù chīle yì jiā hěn hǎochī de Zhōngguó cài."}],"translation_vn":"Hôm qua mình đã đến Bắc Kinh. Tuy trên đường đi mất hơn mười mấy tiếng đồng hồ, nhưng vì ngồi cùng Gia Nguyệt nên mình cảm thấy thời gian trôi qua rất nhanh. Khi đến sân bay, Gia Nguyệt phát hiện va li bị mất, mình đưa cô ấy đến quầy phục vụ, giúp cô ấy tìm lại được va li. Khi ra khỏi sân bay, đã hơn tám giờ rồi, vừa ra ngoài chúng mình đã nhìn thấy chị gái của thầy Vương, chị ấy trông trẻ hơn trong ảnh. Buổi tối, chị Nhất Tuyết đưa chúng mình đi ăn một quán món Trung rất ngon.","audio_dialogue":"1-7.mp3","audio_vocab":"1-8.mp3"}]},{"id":2,"title_cn":"你们想吃什么就点什么","title_pinyin":"Nǐmen xiǎng chī shénme jiù diǎn shénme","title_vn":"Các bạn muốn ăn gì thì gọi món đó","goals":["Có thể nghe hiểu và nói về món ăn, dịch vụ của nhà hàng và thói quen ăn uống cá nhân.","Có thể nghe hiểu và sử dụng đại từ nghi vấn để chỉ bất kỳ đối tượng nào.","Hiểu biết về dụng cụ ăn uống mà người Trung Quốc sử dụng khi dùng bữa."],"vocab":[{"hanzi":"菜单","pinyin":"càidān","pos":"dt.","vn":"thực đơn","examples":[{"cn":"服务员，能给我看一下菜单吗？","pinyin":"Fúwùyuán, néng gěi wǒ kàn yíxià càidān ma?","vn":"Phục vụ ơi, cho tôi xem thực đơn được không?"},{"cn":"这家餐厅的菜单很丰富。","pinyin":"Zhè jiā cāntīng de càidān hěn fēngfù.","vn":"Thực đơn của nhà hàng này rất phong phú."},{"cn":"我们先看看菜单再点菜。","pinyin":"Wǒmen xiān kànkan càidān zài diǎn cài.","vn":"Chúng ta xem thực đơn trước rồi gọi món sau."}]},{"hanzi":"又","pinyin":"yòu","pos":"phó.","vn":"vừa... vừa (dùng trong又...又...)","examples":[{"cn":"这个苹果又大又红。","pinyin":"Zhège píngguǒ yòu dà yòu hóng.","vn":"Quả táo này vừa to vừa đỏ."},{"cn":"她又聪明又漂亮。","pinyin":"Tā yòu cōngming yòu piàoliang.","vn":"Cô ấy vừa thông minh vừa xinh đẹp."},{"cn":"今天又下雨了。","pinyin":"Jīntiān yòu xiàyǔ le.","vn":"Hôm nay lại mưa nữa rồi."}]},{"hanzi":"饿","pinyin":"è","pos":"tt.","vn":"đói","examples":[{"cn":"我好饿，想吃东西。","pinyin":"Wǒ hǎo è, xiǎng chī dōngxi.","vn":"Tôi đói quá, muốn ăn gì đó."},{"cn":"你饿了吗？要不要先吃点东西？","pinyin":"Nǐ è le ma? Yào bu yào xiān chī diǎn dōngxi?","vn":"Bạn đói chưa? Có muốn ăn chút gì trước không?"},{"cn":"别饿着自己，到点就吃饭。","pinyin":"Bié è zhe zìjǐ, dào diǎn jiù chīfàn.","vn":"Đừng để mình bị đói, đến giờ là ăn cơm."}]},{"hanzi":"渴","pinyin":"kě","pos":"tt.","vn":"khát","examples":[{"cn":"跑完步我特别渴。","pinyin":"Pǎo wán bù wǒ tèbié kě.","vn":"Chạy bộ xong tôi khát ơi là khát."},{"cn":"你渴不渴？要不要喝点水？","pinyin":"Nǐ kě bu kě? Yào bu yào hē diǎn shuǐ?","vn":"Bạn có khát không? Có muốn uống nước không?"},{"cn":"天气太热了，我很快就渴了。","pinyin":"Tiānqì tài rè le, wǒ hěn kuài jiù kě le.","vn":"Trời nóng quá, tôi nhanh chóng thấy khát."}]},{"hanzi":"客气","pinyin":"kèqi","pos":"dgt./tt.","vn":"khách sáo; lịch sự","examples":[{"cn":"别客气，多吃点。","pinyin":"Bié kèqi, duō chī diǎn.","vn":"Đừng khách sáo, ăn nhiều vào."},{"cn":"他对谁都很客气。","pinyin":"Tā duì shéi dōu hěn kèqi.","vn":"Anh ấy đối với ai cũng rất lịch sự."},{"cn":"你太客气了，这是我应该做的。","pinyin":"Nǐ tài kèqi le, zhè shì wǒ yīnggāi zuò de.","vn":"Bạn khách sáo quá, đây là việc tôi nên làm mà."}]},{"hanzi":"饮料","pinyin":"yǐnliào","pos":"dt.","vn":"đồ uống","examples":[{"cn":"你想喝什么饮料？","pinyin":"Nǐ xiǎng hē shénme yǐnliào?","vn":"Bạn muốn uống đồ uống gì?"},{"cn":"这家店的饮料种类很多。","pinyin":"Zhè jiā diàn de yǐnliào zhǒnglèi hěn duō.","vn":"Đồ uống của cửa hàng này có nhiều loại."},{"cn":"少喝点含糖的饮料对身体好。","pinyin":"Shǎo hē diǎn hán táng de yǐnliào duì shēntǐ hǎo.","vn":"Uống ít đồ uống có đường sẽ tốt cho sức khỏe."}]},{"hanzi":"好久","pinyin":"hǎojiǔ","pos":"tt.","vn":"đã lâu, lâu rồi","examples":[{"cn":"好久不见，你最近怎么样？","pinyin":"Hǎojiǔ bújiàn, nǐ zuìjìn zěnmeyàng?","vn":"Lâu rồi không gặp, dạo này bạn thế nào?"},{"cn":"我等了好久你才来。","pinyin":"Wǒ děng le hǎojiǔ nǐ cái lái.","vn":"Tôi đợi rất lâu bạn mới đến."},{"cn":"我们好久没一起吃饭了。","pinyin":"Wǒmen hǎojiǔ méi yìqǐ chīfàn le.","vn":"Chúng ta đã lâu rồi không cùng ăn cơm."}]},{"hanzi":"服务","pinyin":"fúwù","pos":"dgt.","vn":"phục vụ","examples":[{"cn":"这家酒店的服务非常好。","pinyin":"Zhè jiā jiǔdiàn de fúwù fēicháng hǎo.","vn":"Dịch vụ của khách sạn này rất tốt."},{"cn":"我们应该为顾客提供更好的服务。","pinyin":"Wǒmen yīnggāi wèi gùkè tígōng gèng hǎo de fúwù.","vn":"Chúng ta nên cung cấp dịch vụ tốt hơn cho khách hàng."},{"cn":"他在银行工作，每天为客户服务。","pinyin":"Tā zài yínháng gōngzuò, měitiān wèi kèhù fúwù.","vn":"Anh ấy làm việc ở ngân hàng, hàng ngày phục vụ khách hàng."}]},{"hanzi":"员","pinyin":"yuán","pos":"htố.","vn":"(hậu tố thêm sau danh/động từ để chỉ người)","examples":[{"cn":"她是一名售货员。","pinyin":"Tā shì yì míng shòuhuòyuán.","vn":"Cô ấy là một nhân viên bán hàng."},{"cn":"我哥哥是公司的职员。","pinyin":"Wǒ gēge shì gōngsī de zhíyuán.","vn":"Anh trai tôi là nhân viên công ty."},{"cn":"这个饭店招聘服务员。","pinyin":"Zhège fàndiàn zhāopìn fúwùyuán.","vn":"Nhà hàng này tuyển nhân viên phục vụ."}]},{"hanzi":"双","pinyin":"shuāng","pos":"lượng.","vn":"đôi","examples":[{"cn":"我买了一双新鞋。","pinyin":"Wǒ mǎi le yì shuāng xīn xié.","vn":"Tôi đã mua một đôi giày mới."},{"cn":"请给我一双筷子。","pinyin":"Qǐng gěi wǒ yì shuāng kuàizi.","vn":"Làm ơn cho tôi một đôi đũa."},{"cn":"她送了我一双手套。","pinyin":"Tā sòng le wǒ yì shuāng shǒutào.","vn":"Cô ấy tặng tôi một đôi găng tay."}]},{"hanzi":"筷子","pinyin":"kuàizi","pos":"dt.","vn":"đũa","examples":[{"cn":"你会用筷子吗？","pinyin":"Nǐ huì yòng kuàizi ma?","vn":"Bạn biết dùng đũa không?"},{"cn":"请再给我拿一双筷子。","pinyin":"Qǐng zài gěi wǒ ná yì shuāng kuàizi.","vn":"Làm ơn lấy thêm cho tôi một đôi đũa nữa."},{"cn":"中国人吃饭一般用筷子。","pinyin":"Zhōngguórén chīfàn yìbān yòng kuàizi.","vn":"Người Trung Quốc ăn cơm thường dùng đũa."}]},{"hanzi":"勺子","pinyin":"sháozi","pos":"dt.","vn":"thìa, muỗng","examples":[{"cn":"喝汤的时候用勺子比较方便。","pinyin":"Hē tāng de shíhou yòng sháozi bǐjiào fāngbiàn.","vn":"Khi uống canh dùng thìa sẽ tiện hơn."},{"cn":"请给我一个勺子。","pinyin":"Qǐng gěi wǒ yí gè sháozi.","vn":"Làm ơn cho tôi một cái thìa."},{"cn":"宝宝还不太会用勺子吃饭。","pinyin":"Bǎobao hái bú tài huì yòng sháozi chīfàn.","vn":"Em bé vẫn chưa biết dùng thìa ăn cơm lắm."}]},{"hanzi":"碗","pinyin":"wǎn","pos":"dt.","vn":"bát, chén","examples":[{"cn":"再给我盛一碗饭。","pinyin":"Zài gěi wǒ chéng yì wǎn fàn.","vn":"Múc thêm cho tôi một bát cơm nữa."},{"cn":"这个碗是我妈妈买的。","pinyin":"Zhège wǎn shì wǒ māma mǎi de.","vn":"Cái bát này là mẹ tôi mua."},{"cn":"吃完饭把碗洗一下。","pinyin":"Chī wán fàn bǎ wǎn xǐ yíxià.","vn":"Ăn xong cơm thì rửa bát nhé."}]},{"hanzi":"马上","pinyin":"mǎshàng","pos":"phó.","vn":"ngay lập tức","examples":[{"cn":"你等一下，我马上就来。","pinyin":"Nǐ děng yíxià, wǒ mǎshàng jiù lái.","vn":"Bạn đợi chút, tôi đến ngay đây."},{"cn":"饭马上就好了。","pinyin":"Fàn mǎshàng jiù hǎo le.","vn":"Cơm sắp xong ngay rồi."},{"cn":"我们马上要出发了，快点！","pinyin":"Wǒmen mǎshàng yào chūfā le, kuài diǎn!","vn":"Chúng ta sắp xuất phát rồi, nhanh lên!"}]},{"hanzi":"热情","pinyin":"rèqíng","pos":"tt.","vn":"nhiệt tình","examples":[{"cn":"这里的人都很热情。","pinyin":"Zhèlǐ de rén dōu hěn rèqíng.","vn":"Người ở đây đều rất nhiệt tình."},{"cn":"他热情地帮我介绍这个城市。","pinyin":"Tā rèqíng de bāng wǒ jièshào zhège chéngshì.","vn":"Anh ấy nhiệt tình giúp tôi giới thiệu về thành phố này."},{"cn":"谢谢你们这么热情地招待我们。","pinyin":"Xièxie nǐmen zhème rèqíng de zhāodài wǒmen.","vn":"Cảm ơn mọi người đã tiếp đãi chúng tôi nhiệt tình như vậy."}]},{"hanzi":"尝","pinyin":"cháng","pos":"dgt.","vn":"nếm, thử","examples":[{"cn":"你尝尝这个菜怎么样。","pinyin":"Nǐ chángchang zhège cài zěnmeyàng.","vn":"Bạn thử nếm món này xem thế nào."},{"cn":"我想尝一下中国菜。","pinyin":"Wǒ xiǎng cháng yíxià Zhōngguócài.","vn":"Tôi muốn thử món ăn Trung Quốc."},{"cn":"这是我第一次尝榴莲。","pinyin":"Zhè shì wǒ dì yī cì cháng liúlián.","vn":"Đây là lần đầu tiên tôi nếm thử sầu riêng."}]},{"hanzi":"记","pinyin":"jì","pos":"dgt.","vn":"nhớ","examples":[{"cn":"我记不住他的名字。","pinyin":"Wǒ jì bu zhù tā de míngzi.","vn":"Tôi không nhớ nổi tên anh ấy."},{"cn":"你一定要记住这个号码。","pinyin":"Nǐ yídìng yào jìzhù zhège hàomǎ.","vn":"Bạn nhất định phải nhớ số này."},{"cn":"我记得我们第一次见面的情景。","pinyin":"Wǒ jìde wǒmen dì yī cì jiànmiàn de qíngjǐng.","vn":"Tôi nhớ cảnh lần đầu tiên chúng tôi gặp nhau."}]},{"hanzi":"用","pinyin":"yòng","pos":"dgt.","vn":"ăn; uống; dùng","examples":[{"cn":"请慢用。","pinyin":"Qǐng màn yòng.","vn":"Mời dùng từ từ, chúc ngon miệng."},{"cn":"您用点什么？","pinyin":"Nín yòng diǎn shénme?","vn":"Quý khách dùng gì ạ?"},{"cn":"我们可以用微信支付。","pinyin":"Wǒmen kěyǐ yòng wēixìn zhīfù.","vn":"Chúng ta có thể dùng WeChat để thanh toán."}]},{"hanzi":"鸡","pinyin":"jī","pos":"dt.","vn":"gà","examples":[{"cn":"今天晚上我们吃鸡吧。","pinyin":"Jīntiān wǎnshang wǒmen chī jī ba.","vn":"Tối nay chúng ta ăn gà nhé."},{"cn":"这家店的烤鸡很有名。","pinyin":"Zhè jiā diàn de kǎojī hěn yǒumíng.","vn":"Gà nướng của cửa hàng này rất nổi tiếng."},{"cn":"他家养了很多鸡。","pinyin":"Tā jiā yǎng le hěn duō jī.","vn":"Nhà anh ấy nuôi rất nhiều gà."}]},{"hanzi":"张","pinyin":"zhāng","pos":"lượng.","vn":"tờ, tấm (dùng cho giấy, tranh...)","examples":[{"cn":"请给我一张纸。","pinyin":"Qǐng gěi wǒ yì zhāng zhǐ.","vn":"Làm ơn cho tôi một tờ giấy."},{"cn":"墙上挂着一张照片。","pinyin":"Qiáng shàng guà zhe yì zhāng zhàopiàn.","vn":"Trên tường treo một tấm ảnh."},{"cn":"我买了两张去上海的票。","pinyin":"Wǒ mǎi le liǎng zhāng qù Shànghǎi de piào.","vn":"Tôi đã mua hai vé đi Thượng Hải."}]},{"hanzi":"不用","pinyin":"búyòng","pos":"phó.","vn":"không cần","examples":[{"cn":"不用谢，这是我应该做的。","pinyin":"Búyòng xiè, zhè shì wǒ yīnggāi zuò de.","vn":"Không cần cảm ơn, đây là việc tôi nên làm."},{"cn":"你不用担心我，我没事。","pinyin":"Nǐ búyòng dānxīn wǒ, wǒ méishì.","vn":"Bạn không cần lo cho tôi, tôi không sao."},{"cn":"今天不用上班，我们出去玩吧。","pinyin":"Jīntiān búyòng shàngbān, wǒmen chūqu wán ba.","vn":"Hôm nay không cần đi làm, chúng ta ra ngoài chơi đi."}]},{"hanzi":"选","pinyin":"xuǎn","pos":"dgt.","vn":"chọn","examples":[{"cn":"你帮我选一件衣服吧。","pinyin":"Nǐ bāng wǒ xuǎn yí jiàn yīfu ba.","vn":"Bạn chọn giúp tôi một bộ quần áo đi."},{"cn":"这么多菜，我不知道选哪个。","pinyin":"Zhème duō cài, wǒ bù zhīdào xuǎn nǎge.","vn":"Nhiều món thế này, tôi không biết chọn món nào."},{"cn":"他被选为班长。","pinyin":"Tā bèi xuǎn wéi bānzhǎng.","vn":"Anh ấy được chọn làm lớp trưởng."}]},{"hanzi":"外卖","pinyin":"wàimài","pos":"dt./dgt.","vn":"đồ ăn mang đi; giao đồ ăn","examples":[{"cn":"今天太累了，我们点外卖吧。","pinyin":"Jīntiān tài lèi le, wǒmen diǎn wàimài ba.","vn":"Hôm nay mệt quá, chúng ta gọi đồ ăn giao đi."},{"cn":"这家餐厅也送外卖吗？","pinyin":"Zhè jiā cāntīng yě sòng wàimài ma?","vn":"Nhà hàng này cũng giao đồ ăn à?"},{"cn":"他每天靠送外卖赚钱。","pinyin":"Tā měitiān kào sòng wàimài zhuànqián.","vn":"Hàng ngày anh ấy kiếm tiền bằng việc giao đồ ăn."}]},{"hanzi":"方便","pinyin":"fāngbiàn","pos":"tt.","vn":"tiện lợi","examples":[{"cn":"网上买东西很方便。","pinyin":"Wǎngshàng mǎi dōngxi hěn fāngbiàn.","vn":"Mua đồ trên mạng rất tiện lợi."},{"cn":"你什么时候方便，我们再约。","pinyin":"Nǐ shénme shíhou fāngbiàn, wǒmen zài yuē.","vn":"Khi nào bạn tiện thì chúng ta hẹn lại."},{"cn":"手机支付真方便。","pinyin":"Shǒujī zhīfù zhēn fāngbiàn.","vn":"Thanh toán bằng điện thoại thật tiện lợi."}]},{"hanzi":"蛋糕","pinyin":"dàngāo","pos":"dt.","vn":"bánh kem","examples":[{"cn":"今天是她的生日，我们买个蛋糕吧。","pinyin":"Jīntiān shì tā de shēngrì, wǒmen mǎi gè dàngāo ba.","vn":"Hôm nay là sinh nhật cô ấy, chúng ta mua bánh kem đi."},{"cn":"这个蛋糕是我自己做的。","pinyin":"Zhège dàngāo shì wǒ zìjǐ zuò de.","vn":"Cái bánh kem này là tự tôi làm."},{"cn":"我最喜欢吃巧克力蛋糕。","pinyin":"Wǒ zuì xǐhuan chī qiǎokèlì dàngāo.","vn":"Tôi thích ăn bánh kem socola nhất."}]},{"hanzi":"只","pinyin":"zhǐ","pos":"phó.","vn":"chỉ","examples":[{"cn":"我只想休息一下。","pinyin":"Wǒ zhǐ xiǎng xiūxi yíxià.","vn":"Tôi chỉ muốn nghỉ ngơi một chút."},{"cn":"他只喝水，不喝饮料。","pinyin":"Tā zhǐ hē shuǐ, bù hē yǐnliào.","vn":"Anh ấy chỉ uống nước, không uống đồ uống có ga."},{"cn":"这件事只有他知道。","pinyin":"Zhè jiàn shì zhǐyǒu tā zhīdào.","vn":"Việc này chỉ có anh ấy biết."}]},{"hanzi":"方便面","pinyin":"fāngbiànmiàn","pos":"dt.","vn":"mì ăn liền","examples":[{"cn":"太晚了，我煮点方便面吃吧。","pinyin":"Tài wǎn le, wǒ zhǔ diǎn fāngbiànmiàn chī ba.","vn":"Muộn quá rồi, tôi nấu ít mì ăn liền ăn vậy."},{"cn":"方便面不能经常吃，不健康。","pinyin":"Fāngbiànmiàn bù néng jīngcháng chī, bú jiànkāng.","vn":"Mì ăn liền không nên ăn thường xuyên, không tốt cho sức khỏe."},{"cn":"宿舍里还有一包方便面。","pinyin":"Sùshè lǐ hái yǒu yì bāo fāngbiànmiàn.","vn":"Trong ký túc xá vẫn còn một gói mì ăn liền."}]},{"hanzi":"简单","pinyin":"jiǎndān","pos":"tt.","vn":"đơn giản","examples":[{"cn":"这道题很简单。","pinyin":"Zhè dào tí hěn jiǎndān.","vn":"Bài toán này rất đơn giản."},{"cn":"做饭其实没那么简单。","pinyin":"Zuòfàn qíshí méi nàme jiǎndān.","vn":"Nấu ăn thực ra không đơn giản như vậy."},{"cn":"他说话总是很简单明了。","pinyin":"Tā shuōhuà zǒngshì hěn jiǎndān míngliǎo.","vn":"Anh ấy nói chuyện luôn đơn giản dễ hiểu."}]}],"grammar":[{"title":"并列复句“又……又……” (Câu phức liên hợp “又……又……”)","explanation_vn":"Câu phức liên hợp \"又……又……\" được dùng kết hợp với tính từ, biểu thị người hoặc sự vật đồng thời có hai đặc điểm. Cấu trúc cơ bản: 又 + tính từ 1 + 又 + tính từ 2.","examples":[{"cn":"我现在还真是又饿又渴。","pinyin":"Wǒ xiànzài hái zhēnshi yòu è yòu kě.","vn":""},{"cn":"那个女孩儿又高又漂亮。","pinyin":"Nàge nǚháir yòu gāo yòu piàoliang.","vn":""},{"cn":"这个饭馆的菜又便宜又好吃。","pinyin":"Zhège fànguǎn de cài yòu piányi yòu hǎochī.","vn":""}]},{"title":"疑问代词的非疑问用法（2）(Cách dùng không nghi vấn của đại từ nghi vấn - phần 2)","explanation_vn":"Các đại từ nghi vấn như \"哪、哪儿、什么、谁、怎么\" còn có thể dùng để biểu thị ý phiếm chỉ (chỉ bất kỳ đối tượng nào), ví dụ \"谁\" chỉ bất kỳ người nào, \"什么\" chỉ bất kỳ vật gì; trong câu thường dùng phó từ \"都\" để hô ứng.","examples":[{"cn":"哪个菜都好吃。","pinyin":"Nǎge cài dōu hǎochī.","vn":""},{"cn":"这次旅游，我去哪儿都可以。","pinyin":"Zhè cì lǚyóu, wǒ qù nǎr dōu kěyǐ.","vn":""},{"cn":"我下午有时间，你想什么时候来都没问题。","pinyin":"Wǒ xiàwǔ yǒu shíjiān, nǐ xiǎng shénme shíhou lái dōu méi wèntí.","vn":""}]},{"title":"疑问代词的非疑问用法（3）(Cách dùng không nghi vấn của đại từ nghi vấn - phần 3)","explanation_vn":"Hai đại từ nghi vấn giống nhau có thể dùng để biểu thị ý phiếm chỉ, hô ứng với nhau, cùng chỉ một người, một việc, một cách thức, một thời điểm hoặc một địa điểm. Khi chủ ngữ của hai mệnh đề giống nhau, chủ ngữ của mệnh đề sau có thể lược bỏ; khi chủ ngữ của hai mệnh đề khác nhau, chủ ngữ thứ hai phải đặt trước \"就\".","examples":[{"cn":"你们想吃什么就点什么。","pinyin":"Nǐmen xiǎng chī shénme jiù diǎn shénme.","vn":""},{"cn":"你觉得哪个好看就买哪个。","pinyin":"Nǐ juéde nǎge hǎokàn jiù mǎi nǎge.","vn":""},{"cn":"你想去哪儿，我们就去哪儿。","pinyin":"Nǐ xiǎng qù nǎr, wǒmen jiù qù nǎr.","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"王一雪","cn":"家月、李文，你们看看菜单，想吃点儿什么？","pinyin":"Jiāyuè, Lǐ Wén, nǐmen kànkan càidān, xiǎng chī diǎnr shénme?"},{"speaker":"李文","cn":"谢谢一雪姐，我都可以，你们点吧。","pinyin":"Xièxie Yīxuě jiě, wǒ dōu kěyǐ, nǐmen diǎn ba."},{"speaker":"白家月","cn":"飞了这么远，现在还真是又饿又渴。","pinyin":"Fēile zhème yuǎn, xiànzài hái zhēnshi yòu è yòu kě."},{"speaker":"王一雪","cn":"那多点点儿，别客气。你们喝什么饮料？","pinyin":"Nà duō diǎn diǎnr, bié kèqi. Nǐmen hē shénme yǐnliào?"},{"speaker":"白家月","cn":"好久没喝中国茶，也好久没吃饺子了。我想喝绿茶、吃饺子，可以吗？","pinyin":"Hǎojiǔ méi hē Zhōngguó chá, yě hǎojiǔ méi chī jiǎozi le. Wǒ xiǎng hē lǜchá, chī jiǎozi, kěyǐ ma?"},{"speaker":"王一雪","cn":"没问题。你们看看还想吃什么。","pinyin":"Méi wèntí. Nǐmen kànkan hái xiǎng chī shénme."}],"translation_vn":"Vương Nhất Tuyết: Gia Nguyệt, Lý Văn, hai em xem thực đơn đi, muốn ăn gì nào?\nLý Văn: Cảm ơn chị Nhất Tuyết, em ăn gì cũng được, các chị gọi đi ạ.\nBạch Gia Nguyệt: Bay xa như vậy, bây giờ đúng là vừa đói vừa khát.\nVương Nhất Tuyết: Vậy gọi nhiều một chút, đừng khách sáo. Các em uống đồ uống gì?\nBạch Gia Nguyệt: Đã lâu không uống trà Trung Quốc, cũng đã lâu không ăn sủi cảo rồi. Em muốn uống trà xanh, ăn sủi cảo, được không ạ?\nVương Nhất Tuyết: Không vấn đề gì. Các em xem còn muốn ăn gì nữa không.","audio_dialogue":"2-1.mp3","audio_vocab":"2-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"王一雪","cn":"服务员，再给我们拿一双筷子、一个勺子和一个碗。","pinyin":"Fúwùyuán, zài gěi wǒmen ná yì shuāng kuàizi, yí ge sháozi hé yí ge wǎn."},{"speaker":"服务员","cn":"好的，请等一下，我马上去拿。","pinyin":"Hǎo de, qǐng děng yíxià, wǒ mǎshàng qù ná."},{"speaker":"王一雪","cn":"这家饭馆的服务很热情，菜也都做得很好吃。你们尝尝，看喜不喜欢这些菜。","pinyin":"Zhè jiā fànguǎn de fúwù hěn rèqíng, cài yě dōu zuò de hěn hǎochī. Nǐmen chángchang, kàn xǐ bu xǐhuan zhèxiē cài."},{"speaker":"白家月","cn":"哪个菜都好吃。您点的这些菜真不错。","pinyin":"Nǎge cài dōu hǎochī. Nín diǎn de zhèxiē cài zhēn búcuò."},{"speaker":"王一雪","cn":"这里的饭菜又便宜又好吃，我们经常来，服务员都记住我们爱吃的菜了。","pinyin":"Zhèlǐ de fàncài yòu piányi yòu hǎochī, wǒmen jīngcháng lái, fúwùyuán dōu jìzhù wǒmen ài chī de cài le."},{"speaker":"服务员","cn":"王姐，您经常来吃饭，今天送您一些水果，请慢用。","pinyin":"Wáng jiě, nín jīngcháng lái chīfàn, jīntiān sòng nín yìxiē shuǐguǒ, qǐng màn yòng."}],"translation_vn":"Vương Nhất Tuyết: Phục vụ ơi, cho chúng tôi thêm một đôi đũa, một cái thìa và một cái bát nữa.\nNhân viên phục vụ: Vâng ạ, xin chờ một chút, tôi đi lấy ngay.\nVương Nhất Tuyết: Dịch vụ của quán này rất nhiệt tình, món ăn cũng đều nấu rất ngon. Các em nếm thử xem có thích những món này không.\nBạch Gia Nguyệt: Món nào cũng ngon cả. Những món chị gọi thật tuyệt.\nVương Nhất Tuyết: Đồ ăn ở đây vừa rẻ vừa ngon, chúng tôi thường xuyên đến đây, nhân viên phục vụ đều nhớ những món chúng tôi thích ăn.\nNhân viên phục vụ: Chị Vương, chị thường xuyên đến ăn, hôm nay tặng chị ít hoa quả, mời chị dùng chậm rãi.","audio_dialogue":"2-3.mp3","audio_vocab":"2-4 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"白家月","cn":"这个鸡肉饭太好吃了，我要再来吃一次。","pinyin":"Zhège jīròu fàn tài hǎochī le, wǒ yào zài lái chī yí cì."},{"speaker":"李文","cn":"你可以拿走这张菜单，看看下次还吃点儿什么。","pinyin":"Nǐ kěyǐ ná zǒu zhè zhāng càidān, kànkan xià cì hái chī diǎnr shénme."},{"speaker":"王一雪","cn":"不用拿菜单，在手机上就能看到，也可以选好了让他们给你送。","pinyin":"Búyòng ná càidān, zài shǒujī shang jiù néng kàndào, yě kěyǐ xuǎn hǎo le ràng tāmen gěi nǐ sòng."},{"speaker":"白家月","cn":"他们家还能送外卖？","pinyin":"Tāmen jiā hái néng sòng wàimài?"},{"speaker":"王一雪","cn":"对，现在很多饭馆都能送外卖，想吃什么就点什么。","pinyin":"Duì, xiànzài hěn duō fànguǎn dōu néng sòng wàimài, xiǎng chī shénme jiù diǎn shénme."},{"speaker":"白家月","cn":"那真是太方便了！","pinyin":"Nà zhēnshi tài fāngbiàn le!"}],"translation_vn":"Bạch Gia Nguyệt: Món cơm gà này ngon quá, em phải đến ăn lại lần nữa mới được.\nLý Văn: Chị có thể mang tờ thực đơn này về, xem lần sau còn muốn ăn gì.\nVương Nhất Tuyết: Không cần mang thực đơn đâu, trên điện thoại là xem được rồi, cũng có thể chọn xong rồi để họ giao đến cho em.\nBạch Gia Nguyệt: Quán này còn giao đồ ăn nữa à?\nVương Nhất Tuyết: Đúng vậy, bây giờ rất nhiều nhà hàng đều có thể giao đồ ăn, muốn ăn gì thì gọi món đó.\nBạch Gia Nguyệt: Vậy thì tiện quá đi mất!","audio_dialogue":"2-5 @xitoytili_luoluodafang.mp3","audio_vocab":"2-6 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"这些年在国外，我很少自己做饭。","pinyin":"Zhèxiē nián zài guówài, wǒ hěn shǎo zìjǐ zuò fàn."},{"speaker":"","cn":"早饭我吃一个面包，有时候吃一块蛋糕，再喝一杯咖啡。","pinyin":"Zǎofàn wǒ chī yí ge miànbāo, yǒu shíhou chī yí kuài dàngāo, zài hē yì bēi kāfēi."},{"speaker":"","cn":"午饭和晚饭也都在外面吃。","pinyin":"Wǔfàn hé wǎnfàn yě dōu zài wàimian chī."},{"speaker":"","cn":"快要考试的时候又忙又累，没时间出去吃饭，家里又什么吃的都没有，我可能好几天只吃方便面。","pinyin":"Kuài yào kǎoshì de shíhou yòu máng yòu lèi, méi shíjiān chūqù chīfàn, jiā li yòu shénme chī de dōu méiyǒu, wǒ kěnéng hǎojǐ tiān zhǐ chī fāngbiànmiàn."},{"speaker":"","cn":"现在回到中国了，每天能吃到妈妈做的饭，我真是太高兴了！","pinyin":"Xiànzài huídào Zhōngguó le, měi tiān néng chīdào māma zuò de fàn, wǒ zhēnshi tài gāoxìng le!"},{"speaker":"","cn":"有时候妈妈只做几个简单的菜，我也非常爱吃，因为什么都没有妈妈做的饭好吃。","pinyin":"Yǒu shíhou māma zhǐ zuò jǐ ge jiǎndān de cài, wǒ yě fēicháng ài chī, yīnwèi shénme dōu méiyǒu māma zuò de fàn hǎochī."}],"translation_vn":"Những năm nay ở nước ngoài, tôi rất ít khi tự nấu ăn. Bữa sáng tôi ăn một chiếc bánh mì, có lúc ăn một miếng bánh kem, rồi uống thêm một ly cà phê. Bữa trưa và bữa tối cũng đều ăn ở ngoài. Vào lúc gần thi vừa bận vừa mệt, không có thời gian ra ngoài ăn, trong nhà lại chẳng có gì để ăn, có lẽ mấy ngày liền tôi chỉ ăn mì ăn liền. Bây giờ đã về Trung Quốc rồi, ngày nào cũng được ăn cơm mẹ nấu, tôi thực sự rất vui! Có lúc mẹ chỉ làm vài món đơn giản, tôi cũng rất thích ăn, vì chẳng có gì ngon bằng cơm mẹ nấu.","audio_dialogue":"2-7 @xitoytili_luoluodafang.mp3","audio_vocab":"2-8 @xitoytili_luoluodafang.mp3"}]},{"id":3,"title_cn":"这个小区挺好的","title_pinyin":"Zhège xiǎoqū tǐng hǎo de","title_vn":"Khu dân cư này khá tốt","goals":["Có thể nghe hiểu và trò chuyện về môi trường sống và tình hình nhà cửa.","Có thể nghe hiểu và sử dụng \"挺\" (tǐng), \"坏了\" (huài le) để biểu thị mức độ.","Nắm vững cách dùng \"就\" (jiù) và \"才\" (cái), có thể diễn đạt thông tin về thời điểm sớm/muộn, nhanh/chậm của hành động."],"vocab":[{"hanzi":"初中","pinyin":"chūzhōng","pos":"dt.","vn":"trường trung học cơ sở (cấp 2)","examples":[{"cn":"我弟弟今年上初中了。","pinyin":"Wǒ dìdi jīnnián shàng chūzhōng le.","vn":"Năm nay em trai tôi học cấp 2 rồi."},{"cn":"我们是初中同学。","pinyin":"Wǒmen shì chūzhōng tóngxué.","vn":"Chúng tôi là bạn học cấp 2."},{"cn":"初中三年过得很快。","pinyin":"Chūzhōng sān nián guò de hěn kuài.","vn":"Ba năm cấp 2 trôi qua thật nhanh."}]},{"hanzi":"咱们","pinyin":"zánmen","pos":"đt.","vn":"chúng ta","examples":[{"cn":"咱们一起去吃饭吧。","pinyin":"Zánmen yìqǐ qù chīfàn ba.","vn":"Chúng ta cùng đi ăn cơm đi."},{"cn":"咱们明天几点见面？","pinyin":"Zánmen míngtiān jǐ diǎn jiànmiàn?","vn":"Mai chúng ta gặp nhau lúc mấy giờ?"},{"cn":"这件事咱们商量一下吧。","pinyin":"Zhè jiàn shì zánmen shāngliang yíxià ba.","vn":"Việc này chúng ta bàn bạc một chút đi."}]},{"hanzi":"换","pinyin":"huàn","pos":"dgt.","vn":"đổi, thay","examples":[{"cn":"这件衣服太小了，我想换一件。","pinyin":"Zhè jiàn yīfu tài xiǎo le, wǒ xiǎng huàn yí jiàn.","vn":"Chiếc áo này nhỏ quá, tôi muốn đổi cái khác."},{"cn":"我们换个地方坐吧。","pinyin":"Wǒmen huàn gè dìfang zuò ba.","vn":"Chúng ta đổi chỗ ngồi đi."},{"cn":"他换了新工作。","pinyin":"Tā huàn le xīn gōngzuò.","vn":"Anh ấy đã đổi công việc mới."}]},{"hanzi":"房子","pinyin":"fángzi","pos":"dt.","vn":"nhà, căn nhà","examples":[{"cn":"他们刚买了一套新房子。","pinyin":"Tāmen gāng mǎi le yí tào xīn fángzi.","vn":"Họ vừa mới mua một căn nhà mới."},{"cn":"这个房子租金很贵。","pinyin":"Zhège fángzi zūjīn hěn guì.","vn":"Căn nhà này tiền thuê rất đắt."},{"cn":"我家的房子在市中心。","pinyin":"Wǒ jiā de fángzi zài shì zhōngxīn.","vn":"Nhà tôi ở trung tâm thành phố."}]},{"hanzi":"小区","pinyin":"xiǎoqū","pos":"dt.","vn":"khu dân cư, khu chung cư","examples":[{"cn":"我们小区环境很好。","pinyin":"Wǒmen xiǎoqū huánjìng hěn hǎo.","vn":"Khu dân cư chúng tôi môi trường rất tốt."},{"cn":"这个小区有游泳池吗？","pinyin":"Zhège xiǎoqū yǒu yóuyǒngchí ma?","vn":"Khu dân cư này có bể bơi không?"},{"cn":"他住在离公司很近的小区。","pinyin":"Tā zhù zài lí gōngsī hěn jìn de xiǎoqū.","vn":"Anh ấy sống trong khu dân cư gần công ty."}]},{"hanzi":"环境","pinyin":"huánjìng","pos":"dt.","vn":"môi trường, hoàn cảnh xung quanh","examples":[{"cn":"这里的环境非常安静。","pinyin":"Zhèlǐ de huánjìng fēicháng ānjìng.","vn":"Môi trường ở đây rất yên tĩnh."},{"cn":"我们应该保护环境。","pinyin":"Wǒmen yīnggāi bǎohù huánjìng.","vn":"Chúng ta nên bảo vệ môi trường."},{"cn":"工作环境对心情影响很大。","pinyin":"Gōngzuò huánjìng duì xīnqíng yǐngxiǎng hěn dà.","vn":"Môi trường làm việc ảnh hưởng rất lớn đến tâm trạng."}]},{"hanzi":"挺","pinyin":"tǐng","pos":"phó.","vn":"khá, rất","examples":[{"cn":"这个电影挺好看的。","pinyin":"Zhège diànyǐng tǐng hǎokàn de.","vn":"Bộ phim này khá hay."},{"cn":"今天天气挺不错的。","pinyin":"Jīntiān tiānqì tǐng búcuò de.","vn":"Hôm nay thời tiết khá đẹp."},{"cn":"他做的菜挺好吃的。","pinyin":"Tā zuò de cài tǐng hǎochī de.","vn":"Món ăn anh ấy nấu khá ngon."}]},{"hanzi":"空调","pinyin":"kōngtiáo","pos":"dt.","vn":"điều hòa, máy lạnh","examples":[{"cn":"房间里有空调吗？","pinyin":"Fángjiān lǐ yǒu kōngtiáo ma?","vn":"Trong phòng có điều hòa không?"},{"cn":"天太热了，开一下空调吧。","pinyin":"Tiān tài rè le, kāi yíxià kōngtiáo ba.","vn":"Trời nóng quá, bật điều hòa lên đi."},{"cn":"睡觉前记得关空调。","pinyin":"Shuìjiào qián jìde guān kōngtiáo.","vn":"Trước khi ngủ nhớ tắt điều hòa."}]},{"hanzi":"洗衣机","pinyin":"xǐyījī","pos":"dt.","vn":"máy giặt","examples":[{"cn":"这些衣服可以用洗衣机洗。","pinyin":"Zhèxiē yīfu kěyǐ yòng xǐyījī xǐ.","vn":"Mấy bộ quần áo này có thể dùng máy giặt để giặt."},{"cn":"我家的洗衣机坏了。","pinyin":"Wǒ jiā de xǐyījī huài le.","vn":"Máy giặt nhà tôi bị hỏng rồi."},{"cn":"新房子里已经装了洗衣机。","pinyin":"Xīn fángzi lǐ yǐjīng zhuāng le xǐyījī.","vn":"Nhà mới đã lắp sẵn máy giặt rồi."}]},{"hanzi":"层","pinyin":"céng","pos":"lượng.","vn":"tầng","examples":[{"cn":"我家住在五层。","pinyin":"Wǒ jiā zhù zài wǔ céng.","vn":"Nhà tôi ở tầng năm."},{"cn":"这栋楼一共有十层。","pinyin":"Zhè dòng lóu yígòng yǒu shí céng.","vn":"Tòa nhà này tổng cộng có mười tầng."},{"cn":"电梯坏了，我们只能爬楼梯上三层。","pinyin":"Diàntī huài le, wǒmen zhǐ néng pá lóutī shàng sān céng.","vn":"Thang máy hỏng rồi, chúng ta chỉ có thể leo cầu thang lên tầng ba."}]},{"hanzi":"花园","pinyin":"huāyuán","pos":"dt.","vn":"vườn hoa","examples":[{"cn":"他们家有一个很大的花园。","pinyin":"Tāmen jiā yǒu yí gè hěn dà de huāyuán.","vn":"Nhà họ có một khu vườn hoa rất lớn."},{"cn":"周末我喜欢在花园里散步。","pinyin":"Zhōumò wǒ xǐhuan zài huāyuán lǐ sànbù.","vn":"Cuối tuần tôi thích đi dạo trong vườn hoa."},{"cn":"小区中间有一个小花园。","pinyin":"Xiǎoqū zhōngjiān yǒu yí gè xiǎo huāyuán.","vn":"Ở giữa khu dân cư có một vườn hoa nhỏ."}]},{"hanzi":"灯","pinyin":"dēng","pos":"dt.","vn":"đèn","examples":[{"cn":"睡觉前请把灯关了。","pinyin":"Shuìjiào qián qǐng bǎ dēng guān le.","vn":"Trước khi ngủ làm ơn tắt đèn."},{"cn":"房间里的灯有点暗。","pinyin":"Fángjiān lǐ de dēng yǒudiǎn àn.","vn":"Đèn trong phòng hơi tối."},{"cn":"这盏灯是什么时候坏的？","pinyin":"Zhè zhǎn dēng shì shénme shíhou huài de?","vn":"Cái đèn này hỏng từ bao giờ vậy?"}]},{"hanzi":"关","pinyin":"guān","pos":"dgt.","vn":"tắt, đóng","examples":[{"cn":"出门的时候记得关灯。","pinyin":"Chūmén de shíhou jìde guān dēng.","vn":"Lúc ra ngoài nhớ tắt đèn."},{"cn":"请把门关上。","pinyin":"Qǐng bǎ mén guān shàng.","vn":"Làm ơn đóng cửa lại."},{"cn":"空调太冷了，关一下吧。","pinyin":"Kōngtiáo tài lěng le, guān yíxià ba.","vn":"Điều hòa lạnh quá, tắt đi."}]},{"hanzi":"冰箱","pinyin":"bīngxiāng","pos":"dt.","vn":"tủ lạnh","examples":[{"cn":"把水果放进冰箱里吧。","pinyin":"Bǎ shuǐguǒ fàng jìn bīngxiāng lǐ ba.","vn":"Để hoa quả vào tủ lạnh đi."},{"cn":"冰箱里没有什么吃的了。","pinyin":"Bīngxiāng lǐ méiyǒu shénme chī de le.","vn":"Trong tủ lạnh không còn gì để ăn cả."},{"cn":"这个冰箱是新买的。","pinyin":"Zhège bīngxiāng shì xīn mǎi de.","vn":"Cái tủ lạnh này mới mua."}]},{"hanzi":"卫生间","pinyin":"wèishēngjiān","pos":"dt.","vn":"nhà vệ sinh","examples":[{"cn":"请问卫生间在哪儿？","pinyin":"Qǐngwèn wèishēngjiān zài nǎr?","vn":"Xin hỏi nhà vệ sinh ở đâu ạ?"},{"cn":"这个房子有两个卫生间。","pinyin":"Zhège fángzi yǒu liǎng gè wèishēngjiān.","vn":"Căn nhà này có hai nhà vệ sinh."},{"cn":"卫生间需要打扫一下了。","pinyin":"Wèishēngjiān xūyào dǎsǎo yíxià le.","vn":"Nhà vệ sinh cần dọn dẹp một chút rồi."}]},{"hanzi":"打扫","pinyin":"dǎsǎo","pos":"dgt.","vn":"dọn dẹp, quét dọn","examples":[{"cn":"周末我要打扫房间。","pinyin":"Zhōumò wǒ yào dǎsǎo fángjiān.","vn":"Cuối tuần tôi phải dọn dẹp phòng."},{"cn":"房间还没打扫干净。","pinyin":"Fángjiān hái méi dǎsǎo gānjìng.","vn":"Phòng vẫn chưa dọn sạch."},{"cn":"我们一起打扫一下卫生吧。","pinyin":"Wǒmen yìqǐ dǎsǎo yíxià wèishēng ba.","vn":"Chúng ta cùng dọn dẹp vệ sinh một chút đi."}]},{"hanzi":"搬家","pinyin":"bānjiā","pos":"dgt.","vn":"chuyển nhà, dọn nhà","examples":[{"cn":"我们下个月要搬家了。","pinyin":"Wǒmen xià gè yuè yào bānjiā le.","vn":"Tháng sau chúng tôi sẽ chuyển nhà."},{"cn":"搬家真是太累了。","pinyin":"Bānjiā zhēnshi tài lèi le.","vn":"Chuyển nhà thật là mệt quá."},{"cn":"他帮朋友搬家搬了一整天。","pinyin":"Tā bāng péngyou bānjiā bān le yì zhěngtiān.","vn":"Anh ấy giúp bạn chuyển nhà cả một ngày trời."}]},{"hanzi":"办","pinyin":"bàn","pos":"dgt.","vn":"làm, xử lý (thủ tục)","examples":[{"cn":"我要去银行办一张卡。","pinyin":"Wǒ yào qù yínháng bàn yì zhāng kǎ.","vn":"Tôi phải đi ngân hàng làm một cái thẻ."},{"cn":"这件事怎么办比较好？","pinyin":"Zhè jiàn shì zěnme bàn bǐjiào hǎo?","vn":"Việc này xử lý thế nào thì tốt hơn?"},{"cn":"办护照需要什么材料？","pinyin":"Bàn hùzhào xūyào shénme cáiliào?","vn":"Làm hộ chiếu cần những giấy tờ gì?"}]},{"hanzi":"信用卡","pinyin":"xìnyòngkǎ","pos":"dt.","vn":"thẻ tín dụng","examples":[{"cn":"我可以用信用卡付款吗？","pinyin":"Wǒ kěyǐ yòng xìnyòngkǎ fùkuǎn ma?","vn":"Tôi có thể dùng thẻ tín dụng để thanh toán không?"},{"cn":"他办了一张新的信用卡。","pinyin":"Tā bàn le yì zhāng xīn de xìnyòngkǎ.","vn":"Anh ấy đã làm một cái thẻ tín dụng mới."},{"cn":"用信用卡买东西要按时还钱。","pinyin":"Yòng xìnyòngkǎ mǎi dōngxi yào ànshí huánqián.","vn":"Dùng thẻ tín dụng mua đồ thì phải trả tiền đúng hạn."}]},{"hanzi":"还","pinyin":"huán","pos":"dgt.","vn":"trả (nợ, tiền)","examples":[{"cn":"我下个月就能还你钱了。","pinyin":"Wǒ xià gè yuè jiù néng huán nǐ qián le.","vn":"Tháng sau tôi có thể trả tiền cho bạn rồi."},{"cn":"他借的钱还没还。","pinyin":"Tā jiè de qián hái méi huán.","vn":"Tiền anh ấy vay vẫn chưa trả."},{"cn":"信用卡要按时还款。","pinyin":"Xìnyòngkǎ yào ànshí huánkuǎn.","vn":"Thẻ tín dụng phải trả nợ đúng hạn."}]},{"hanzi":"听说","pinyin":"tīngshuō","pos":"dgt.","vn":"nghe nói","examples":[{"cn":"听说这家餐厅的菜很好吃。","pinyin":"Tīngshuō zhè jiā cāntīng de cài hěn hǎochī.","vn":"Nghe nói món ăn của nhà hàng này rất ngon."},{"cn":"我听说他要搬家了。","pinyin":"Wǒ tīngshuō tā yào bānjiā le.","vn":"Tôi nghe nói anh ấy sắp chuyển nhà."},{"cn":"听说明天会下雪。","pinyin":"Tīngshuō míngtiān huì xiàxuě.","vn":"Nghe nói mai sẽ có tuyết."}]},{"hanzi":"银行","pinyin":"yínháng","pos":"dt.","vn":"ngân hàng","examples":[{"cn":"我要去银行取点钱。","pinyin":"Wǒ yào qù yínháng qǔ diǎn qián.","vn":"Tôi phải đi ngân hàng rút ít tiền."},{"cn":"银行几点下班？","pinyin":"Yínháng jǐ diǎn xiàbān?","vn":"Mấy giờ ngân hàng đóng cửa?"},{"cn":"他在银行工作了五年。","pinyin":"Tā zài yínháng gōngzuò le wǔ nián.","vn":"Anh ấy đã làm việc ở ngân hàng năm năm."}]},{"hanzi":"才","pinyin":"cái","pos":"phó.","vn":"mới (lúc đó mới...)","examples":[{"cn":"我等了半天他才来。","pinyin":"Wǒ děng le bàntiān tā cái lái.","vn":"Tôi đợi rất lâu anh ấy mới đến."},{"cn":"都十点了，他才起床。","pinyin":"Dōu shí diǎn le, tā cái qǐchuáng.","vn":"Đã mười giờ rồi, anh ấy mới dậy."},{"cn":"这件事我今天才知道。","pinyin":"Zhè jiàn shì wǒ jīntiān cái zhīdào.","vn":"Việc này hôm nay tôi mới biết."}]},{"hanzi":"纸","pinyin":"zhǐ","pos":"dt.","vn":"giấy","examples":[{"cn":"请给我一张纸。","pinyin":"Qǐng gěi wǒ yì zhāng zhǐ.","vn":"Làm ơn cho tôi một tờ giấy."},{"cn":"这是用纸做的花。","pinyin":"Zhè shì yòng zhǐ zuò de huā.","vn":"Đây là hoa làm bằng giấy."},{"cn":"桌子上有一些纸和笔。","pinyin":"Zhuōzi shàng yǒu yìxiē zhǐ hé bǐ.","vn":"Trên bàn có một ít giấy và bút."}]},{"hanzi":"搬","pinyin":"bān","pos":"dgt.","vn":"chuyển, dọn, khiêng","examples":[{"cn":"帮我把这个箱子搬到楼上。","pinyin":"Bāng wǒ bǎ zhège xiāngzi bān dào lóushàng.","vn":"Giúp tôi khiêng cái hộp này lên lầu."},{"cn":"他一个人把冰箱搬进了房间。","pinyin":"Tā yí gè rén bǎ bīngxiāng bān jìn le fángjiān.","vn":"Anh ấy một mình khiêng tủ lạnh vào phòng."},{"cn":"我们下周要搬到新房子。","pinyin":"Wǒmen xià zhōu yào bān dào xīn fángzi.","vn":"Tuần sau chúng tôi sẽ chuyển đến nhà mới."}]},{"hanzi":"需要","pinyin":"xūyào","pos":"dgt.","vn":"cần, nhu cầu","examples":[{"cn":"你需要我帮忙吗？","pinyin":"Nǐ xūyào wǒ bāngmáng ma?","vn":"Bạn có cần tôi giúp không?"},{"cn":"办护照需要身份证。","pinyin":"Bàn hùzhào xūyào shēnfènzhèng.","vn":"Làm hộ chiếu cần chứng minh thư."},{"cn":"这个工作需要很多时间。","pinyin":"Zhège gōngzuò xūyào hěn duō shíjiān.","vn":"Công việc này cần rất nhiều thời gian."}]}],"grammar":[{"title":"程度副词\"挺\" (tǐng) - Phó từ chỉ mức độ \"挺\"","explanation_vn":"Phó từ chỉ mức độ \"挺\" dùng trước tính từ hoặc động từ tâm lý, biểu thị mức độ khá cao, thường dùng trong khẩu ngữ. Cấu trúc cơ bản: 挺 + tính từ/động từ tâm lý + 的.","examples":[{"cn":"这个小区环境挺好的。","pinyin":"Zhège xiǎoqū huánjìng tǐng hǎo de.","vn":""},{"cn":"这家饭馆的菜挺好吃的。","pinyin":"Zhè jiā fànguǎn de cài tǐng hǎochī de.","vn":""},{"cn":"买这个吧，我挺喜欢这个颜色的。","pinyin":"Mǎi zhège ba, wǒ tǐng xǐhuan zhège yánsè de.","vn":""}]},{"title":"程度补语（1）\"坏了\" (huài le) - Bổ ngữ chỉ mức độ (1)","explanation_vn":"Bổ ngữ chỉ mức độ \"坏了\" đặt sau tính từ, biểu thị mức độ cực cao, mang giọng điệu phóng đại, thường dùng trong tình huống mang nghĩa tiêu cực.","examples":[{"cn":"我这几天忙坏了。","pinyin":"Wǒ zhè jǐ tiān máng huài le.","vn":""},{"cn":"我渴坏了，哪里能买水？","pinyin":"Wǒ kě huài le, nǎlǐ néng mǎi shuǐ?","vn":""},{"cn":"这几天非常忙，大家都累坏了。","pinyin":"Zhè jǐ tiān fēicháng máng, dàjiā dōu lèi huài le.","vn":""}]},{"title":"\"就\"和\"才\" (jiù/cái) - So sánh \"就\" và \"才\"","explanation_vn":"Phó từ \"就\" và \"才\" dùng trước động từ làm trạng ngữ. \"就\" biểu thị người nói cho rằng động tác xảy ra sớm, diễn ra nhanh và thuận lợi; \"才\" biểu thị người nói cho rằng động tác xảy ra muộn, diễn ra chậm và không thuận lợi.","examples":[{"cn":"中国银行很近，走路几分钟就能到。","pinyin":"Zhōngguó Yínháng hěn jìn, zǒulù jǐ fēnzhōng jiù néng dào.","vn":""},{"cn":"我下午要去医院，很晚才能回来。","pinyin":"Wǒ xiàwǔ yào qù yīyuàn, hěn wǎn cái néng huílái.","vn":""},{"cn":"我早上五点就起床了。","pinyin":"Wǒ zǎoshang wǔ diǎn jiù qǐchuáng le.","vn":""},{"cn":"坐火车去北京，五个小时才能到。","pinyin":"Zuò huǒchē qù Běijīng, wǔ gè xiǎoshí cái néng dào.","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"王一雪","cn":"小雪的初中离家有点儿远，咱们换一个近点儿的房子吧。","pinyin":"Xiǎoxuě de chūzhōng lí jiā yǒudiǎnr yuǎn, zánmen huàn yí gè jìn diǎnr de fángzi ba."},{"speaker":"刘明","cn":"好啊，我上网看看。你觉得这个小区怎么样？","pinyin":"Hǎo a, wǒ shàngwǎng kànkan. Nǐ juéde zhège xiǎoqū zěnmeyàng?"},{"speaker":"王一雪","cn":"环境挺好的，离地铁站还不远。","pinyin":"Huánjìng tǐng hǎo de, lí dìtiězhàn hái bù yuǎn."},{"speaker":"刘明","cn":"房子里面也不错，空调和洗衣机都是新的。","pinyin":"Fángzi lǐmiàn yě búcuò, kōngtiáo hé xǐyījī dōu shì xīn de."},{"speaker":"王一雪","cn":"是不错，但是我不喜欢住一层。","pinyin":"Shì búcuò, dànshì wǒ bù xǐhuan zhù yì céng."},{"speaker":"刘明","cn":"这个一层带一个小花园，我觉得咱们可以去看看。","pinyin":"Zhège yì céng dài yí gè xiǎo huāyuán, wǒ juéde zánmen kěyǐ qù kànkan."}],"translation_vn":"Vương Nhất Tuyết: Trường cấp 2 của Tiểu Tuyết cách nhà hơi xa, chúng ta đổi một căn nhà gần hơn một chút đi.\nLưu Minh: Được đấy, để anh lên mạng xem thử. Em thấy khu dân cư này thế nào?\nVương Nhất Tuyết: Môi trường khá tốt, cách ga tàu điện ngầm cũng không xa.\nLưu Minh: Bên trong nhà cũng không tệ, điều hòa và máy giặt đều là đồ mới.\nVương Nhất Tuyết: Đúng là không tệ, nhưng em không thích ở tầng một.\nLưu Minh: Tầng một này có kèm một khu vườn nhỏ, anh thấy chúng ta có thể đi xem thử.","audio_dialogue":"3-1 @xitoytili_luoluodafang.mp3","audio_vocab":"3-2 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"王一雪","cn":"我今天早上来的时候，灯还开着。","pinyin":"Wǒ jīntiān zǎoshang lái de shíhou, dēng hái kāizhe."},{"speaker":"刘明","cn":"我这几天忙坏了，可能走的时候忘关了。","pinyin":"Wǒ zhè jǐ tiān máng huài le, kěnéng zǒu de shíhou wàng guān le."},{"speaker":"王一雪","cn":"冰箱不能用，这些吃的东西放在哪儿？","pinyin":"Bīngxiāng bù néng yòng, zhèxiē chī de dōngxi fàng zài nǎr?"},{"speaker":"刘明","cn":"不可能吧？冰箱是新买的，我来看看。","pinyin":"Bù kěnéng ba? Bīngxiāng shì xīn mǎi de, wǒ lái kànkan."},{"speaker":"王一雪","cn":"洗衣机也坏了吗？","pinyin":"Xǐyījī yě huài le ma?"},{"speaker":"刘明","cn":"没坏，但是卫生间没打扫好，还不能洗衣服。","pinyin":"Méi huài, dànshì wèishēngjiān méi dǎsǎo hǎo, hái bù néng xǐ yīfu."},{"speaker":"王一雪","cn":"星期天我们真的能搬家吗？","pinyin":"Xīngqītiān wǒmen zhēn de néng bānjiā ma?"}],"translation_vn":"Vương Nhất Tuyết: Sáng nay lúc em đến, đèn vẫn còn bật.\nLưu Minh: Mấy hôm nay anh bận muốn chết, có thể lúc đi quên tắt rồi.\nVương Nhất Tuyết: Tủ lạnh không dùng được, mấy thứ đồ ăn này để ở đâu đây?\nLưu Minh: Không thể nào? Tủ lạnh mới mua mà, để anh xem thử.\nVương Nhất Tuyết: Máy giặt cũng hỏng rồi à?\nLưu Minh: Không hỏng, nhưng nhà vệ sinh chưa dọn xong, vẫn chưa giặt quần áo được.\nVương Nhất Tuyết: Chủ nhật chúng ta có thật sự chuyển nhà được không?","audio_dialogue":"3-3 @xitoytili_luoluodafang.mp3","audio_vocab":"3-4 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"王一雪","cn":"这个月花了不少钱。","pinyin":"Zhège yuè huā le bù shǎo qián."},{"speaker":"刘明","cn":"是的，我们买了很多搬家时要用的东西。","pinyin":"Shì de, wǒmen mǎi le hěn duō bānjiā shí yào yòng de dōngxi."},{"speaker":"王一雪","cn":"咱们办张信用卡吧，花的钱可以慢慢还。听说中国银行的服务不错，办了信用卡买东西还能便宜。","pinyin":"Zánmen bàn zhāng xìnyòngkǎ ba, huā de qián kěyǐ mànmàn huán. Tīngshuō Zhōngguó Yínháng de fúwù búcuò, bàn le xìnyòngkǎ mǎi dōngxi hái néng piányi."},{"speaker":"刘明","cn":"好啊！中国银行很近，走路几分钟就能到。咱们什么时候去？","pinyin":"Hǎo a! Zhōngguó Yínháng hěn jìn, zǒulù jǐ fēnzhōng jiù néng dào. Zánmen shénme shíhou qù?"},{"speaker":"王一雪","cn":"今天下午？","pinyin":"Jīntiān xiàwǔ?"},{"speaker":"刘明","cn":"我下午要去医院，很晚才能回来。","pinyin":"Wǒ xiàwǔ yào qù yīyuàn, hěn wǎn cái néng huílái."},{"speaker":"王一雪","cn":"那我下午自己去吧。","pinyin":"Nà wǒ xiàwǔ zìjǐ qù ba."}],"translation_vn":"Vương Nhất Tuyết: Tháng này tiêu không ít tiền nhỉ.\nLưu Minh: Đúng vậy, chúng ta đã mua rất nhiều đồ cần dùng khi chuyển nhà.\nVương Nhất Tuyết: Chúng ta làm một thẻ tín dụng đi, tiền tiêu có thể trả dần dần. Nghe nói dịch vụ của Ngân hàng Trung Quốc khá tốt, làm thẻ tín dụng rồi mua đồ còn được rẻ hơn.\nLưu Minh: Được đấy! Ngân hàng Trung Quốc rất gần, đi bộ vài phút là đến. Chúng ta đi khi nào?\nVương Nhất Tuyết: Chiều nay nhé?\nLưu Minh: Chiều nay anh phải đi bệnh viện, rất muộn mới về được.\nVương Nhất Tuyết: Vậy chiều nay em tự đi vậy.","audio_dialogue":"3-5 @xitoytili_luoluodafang.mp3","audio_vocab":"3-6 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 4","type":"dialogue","lines":[{"speaker":"刘明","cn":"我觉得这个星期就能搬家。我明天去买一些纸箱，很快就能准备好。搬家那天，我想请几位朋友来帮忙，最多一天就能搬完。","pinyin":"Wǒ juéde zhège xīngqī jiù néng bānjiā. Wǒ míngtiān qù mǎi yìxiē zhǐxiāng, hěn kuài jiù néng zhǔnbèi hǎo. Bānjiā nà tiān, wǒ xiǎng qǐng jǐ wèi péngyou lái bāngmáng, zuìduō yì tiān jiù néng bān wán."},{"speaker":"王一雪","cn":"我觉得下个月才能搬家。这周开始准备，下周去打扫新家，这么多事情最少需要两个星期才能做完。搬家那天，我们应该找一家搬家公司。","pinyin":"Wǒ juéde xià gè yuè cái néng bānjiā. Zhè zhōu kāishǐ zhǔnbèi, xiàzhōu qù dǎsǎo xīnjiā, zhème duō shìqing zuìshǎo xūyào liǎng gè xīngqī cái néng zuò wán. Bānjiā nà tiān, wǒmen yīnggāi zhǎo yì jiā bānjiā gōngsī."}],"translation_vn":"Lưu Minh: Anh thấy tuần này là có thể chuyển nhà được rồi. Ngày mai anh đi mua mấy cái thùng giấy, rất nhanh là chuẩn bị xong thôi. Hôm chuyển nhà, anh muốn mời vài người bạn đến giúp, nhiều nhất một ngày là chuyển xong.\nVương Nhất Tuyết: Em thấy tháng sau mới chuyển nhà được. Tuần này bắt đầu chuẩn bị, tuần sau đi dọn dẹp nhà mới, nhiều việc như vậy ít nhất cần hai tuần mới làm xong. Hôm chuyển nhà, chúng ta nên tìm một công ty chuyển nhà.","audio_dialogue":"3-7 @xitoytili_luoluodafang.mp3","audio_vocab":"3-8 @xitoytili_luoluodafang.mp3"}]},{"id":4,"title_cn":"这家宾馆跟别的都不一样","title_pinyin":"Zhè jiā bīnguǎn gēn biéde dōu bù yíyàng","title_vn":"Khách sạn này khác hẳn những nơi khác","goals":["Có thể nghe hiểu và trao đổi về kế hoạch kỳ nghỉ, diễn đạt cảm nhận trong quá trình du lịch.","Có thể nghe hiểu và diễn đạt ý nghĩa phủ định hoàn toàn.","Nắm được cách dùng của \"除了\", có thể diễn đạt ý loại trừ hoặc bổ sung."],"vocab":[{"hanzi":"假期","pinyin":"jiàqī","pos":"dt.","vn":"kỳ nghỉ","examples":[{"cn":"暑假假期你打算去哪儿玩?","pinyin":"shǔjià jiàqī nǐ dǎsuàn qù nǎr wán?","vn":"Kỳ nghỉ hè bạn định đi đâu chơi?"},{"cn":"假期太短了,我还没玩够呢。","pinyin":"jiàqī tài duǎn le, wǒ hái méi wán gòu ne.","vn":"Kỳ nghỉ ngắn quá, mình chơi chưa đã."},{"cn":"每年假期我都会回老家看爷爷奶奶。","pinyin":"měi nián jiàqī wǒ dōu huì huí lǎojiā kàn yéye nǎinai.","vn":"Năm nào vào kỳ nghỉ tôi cũng về quê thăm ông bà."}]},{"hanzi":"海","pinyin":"hǎi","pos":"dt.","vn":"biển","examples":[{"cn":"我们明天去海边玩吧。","pinyin":"wǒmen míngtiān qù hǎibiān wán ba.","vn":"Mai chúng ta đi biển chơi nhé."},{"cn":"这里的海水特别蓝。","pinyin":"zhèlǐ de hǎishuǐ tèbié lán.","vn":"Nước biển ở đây xanh lắm."},{"cn":"我从小就喜欢看大海。","pinyin":"wǒ cóngxiǎo jiù xǐhuan kàn dàhǎi.","vn":"Từ nhỏ tôi đã thích ngắm biển."}]},{"hanzi":"草原","pinyin":"cǎoyuán","pos":"dt.","vn":"thảo nguyên","examples":[{"cn":"草原上有很多马和羊。","pinyin":"cǎoyuán shàng yǒu hěn duō mǎ hé yáng.","vn":"Trên thảo nguyên có rất nhiều ngựa và cừu."},{"cn":"我一直想去内蒙古的草原看看。","pinyin":"wǒ yìzhí xiǎng qù Nèiménggǔ de cǎoyuán kànkan.","vn":"Tôi vẫn luôn muốn đi thảo nguyên Nội Mông xem thử."},{"cn":"草原的风景真美,一望无边。","pinyin":"cǎoyuán de fēngjǐng zhēn měi, yíwàng wúbiān.","vn":"Phong cảnh thảo nguyên thật đẹp, bát ngát không bờ bến."}]},{"hanzi":"主意","pinyin":"zhǔyi","pos":"dt.","vn":"ý kiến, chủ ý","examples":[{"cn":"这个主意不错,我们试试吧。","pinyin":"zhège zhǔyi búcuò, wǒmen shìshi ba.","vn":"Ý kiến này không tồi, chúng ta thử xem."},{"cn":"你有什么好主意吗?","pinyin":"nǐ yǒu shénme hǎo zhǔyi ma?","vn":"Bạn có ý kiến gì hay không?"},{"cn":"他总是拿不定主意。","pinyin":"tā zǒngshì ná bu dìng zhǔyi.","vn":"Anh ấy lúc nào cũng không quyết định được."}]},{"hanzi":"骑","pinyin":"qí","pos":"dgt.","vn":"cưỡi","examples":[{"cn":"我每天骑自行车上班。","pinyin":"wǒ měitiān qí zìxíngchē shàngbān.","vn":"Mỗi ngày tôi đạp xe đi làm."},{"cn":"你会骑马吗?","pinyin":"nǐ huì qí mǎ ma?","vn":"Bạn biết cưỡi ngựa không?"},{"cn":"他骑摩托车骑得特别快。","pinyin":"tā qí mótuōchē qí de tèbié kuài.","vn":"Anh ấy lái xe máy rất nhanh."}]},{"hanzi":"马","pinyin":"mǎ","pos":"dt.","vn":"ngựa","examples":[{"cn":"小时候我没骑过马。","pinyin":"xiǎoshíhou wǒ méi qí guo mǎ.","vn":"Lúc nhỏ tôi chưa từng cưỡi ngựa."},{"cn":"草原上的马跑得真快。","pinyin":"cǎoyuán shàng de mǎ pǎo de zhēn kuài.","vn":"Những con ngựa trên thảo nguyên chạy nhanh thật."},{"cn":"这匹马是他最喜欢的。","pinyin":"zhè pǐ mǎ shì tā zuì xǐhuan de.","vn":"Con ngựa này là con anh ấy thích nhất."}]},{"hanzi":"羊","pinyin":"yáng","pos":"dt.","vn":"cừu, dê","examples":[{"cn":"草原上有一群羊在吃草。","pinyin":"cǎoyuán shàng yǒu yì qún yáng zài chī cǎo.","vn":"Trên thảo nguyên có một đàn cừu đang ăn cỏ."},{"cn":"我们家乡的人喜欢养羊。","pinyin":"wǒmen jiāxiāng de rén xǐhuan yǎng yáng.","vn":"Người ở quê tôi thích nuôi cừu."},{"cn":"这道菜是用羊肉做的。","pinyin":"zhè dào cài shì yòng yángròu zuò de.","vn":"Món này được làm từ thịt cừu."}]},{"hanzi":"月亮","pinyin":"yuèliang","pos":"dt.","vn":"mặt trăng","examples":[{"cn":"今天晚上的月亮真圆真亮。","pinyin":"jīntiān wǎnshang de yuèliang zhēn yuán zhēn liàng.","vn":"Trăng tối nay thật tròn thật sáng."},{"cn":"我喜欢坐在阳台上看月亮。","pinyin":"wǒ xǐhuan zuò zài yángtái shàng kàn yuèliang.","vn":"Tôi thích ngồi trên ban công ngắm trăng."},{"cn":"中秋节那天,大家一起赏月亮。","pinyin":"Zhōngqiūjié nà tiān, dàjiā yìqǐ shǎng yuèliang.","vn":"Vào ngày Trung thu, mọi người cùng nhau ngắm trăng."}]},{"hanzi":"一定","pinyin":"yídìng","pos":"phó.","vn":"nhất định","examples":[{"cn":"明天你一定要来参加我的生日会。","pinyin":"míngtiān nǐ yídìng yào lái cānjiā wǒ de shēngrìhuì.","vn":"Mai bạn nhất định phải đến dự sinh nhật của tôi."},{"cn":"这件事一定能成功。","pinyin":"zhè jiàn shì yídìng néng chénggōng.","vn":"Việc này nhất định sẽ thành công."},{"cn":"他说的话不一定是真的。","pinyin":"tā shuō de huà bù yídìng shì zhēn de.","vn":"Lời anh ấy nói chưa chắc đã là thật."}]},{"hanzi":"刻","pinyin":"kè","pos":"lượng.","vn":"khắc (15 phút)","examples":[{"cn":"现在是三点一刻。","pinyin":"xiànzài shì sān diǎn yí kè.","vn":"Bây giờ là ba giờ mười lăm."},{"cn":"再等一刻钟就到了。","pinyin":"zài děng yí kè zhōng jiù dào le.","vn":"Đợi thêm mười lăm phút nữa là đến."},{"cn":"会议差一刻七点开始。","pinyin":"huìyì chà yí kè qī diǎn kāishǐ.","vn":"Cuộc họp bắt đầu lúc bảy giờ kém mười lăm."}]},{"hanzi":"起飞","pinyin":"qǐfēi","pos":"dgt.","vn":"cất cánh","examples":[{"cn":"飞机马上就要起飞了。","pinyin":"fēijī mǎshàng jiù yào qǐfēi le.","vn":"Máy bay sắp cất cánh rồi."},{"cn":"起飞前请关闭手机。","pinyin":"qǐfēi qián qǐng guānbì shǒujī.","vn":"Trước khi cất cánh xin hãy tắt điện thoại."},{"cn":"因为大雨,航班起飞晚点了。","pinyin":"yīnwèi dàyǔ, hángbān qǐfēi wǎndiǎn le.","vn":"Vì mưa to, chuyến bay cất cánh trễ giờ."}]},{"hanzi":"宾馆","pinyin":"bīnguǎn","pos":"dt.","vn":"khách sạn","examples":[{"cn":"我们在这家宾馆住了三天。","pinyin":"wǒmen zài zhè jiā bīnguǎn zhù le sān tiān.","vn":"Chúng tôi đã ở khách sạn này ba ngày."},{"cn":"这个宾馆离机场很近。","pinyin":"zhège bīnguǎn lí jīchǎng hěn jìn.","vn":"Khách sạn này gần sân bay."},{"cn":"你帮我订一间宾馆的房间吧。","pinyin":"nǐ bāng wǒ dìng yì jiān bīnguǎn de fángjiān ba.","vn":"Bạn giúp tôi đặt một phòng khách sạn nhé."}]},{"hanzi":"特别","pinyin":"tèbié","pos":"tt./phó.","vn":"đặc biệt","examples":[{"cn":"今天的天气特别好。","pinyin":"jīntiān de tiānqì tèbié hǎo.","vn":"Thời tiết hôm nay đặc biệt đẹp."},{"cn":"我特别喜欢吃辣的。","pinyin":"wǒ tèbié xǐhuan chī là de.","vn":"Tôi đặc biệt thích ăn cay."},{"cn":"这个地方很特别,跟别的不一样。","pinyin":"zhège dìfang hěn tèbié, gēn biéde bù yíyàng.","vn":"Nơi này rất đặc biệt, khác với những nơi khác."}]},{"hanzi":"别的","pinyin":"biéde","pos":"đt.","vn":"cái khác","examples":[{"cn":"这件衣服卖完了,你看看别的吧。","pinyin":"zhè jiàn yīfu mài wán le, nǐ kànkan biéde ba.","vn":"Chiếc áo này bán hết rồi, bạn xem cái khác đi."},{"cn":"除了这个问题,你还有别的问题吗?","pinyin":"chúle zhège wèntí, nǐ hái yǒu biéde wèntí ma?","vn":"Ngoài vấn đề này ra, bạn còn câu hỏi nào khác không?"},{"cn":"我不想听别的,我只想听你的意见。","pinyin":"wǒ bù xiǎng tīng biéde, wǒ zhǐ xiǎng tīng nǐ de yìjiàn.","vn":"Tôi không muốn nghe cái khác, tôi chỉ muốn nghe ý kiến của bạn."}]},{"hanzi":"一样","pinyin":"yíyàng","pos":"tt.","vn":"giống nhau","examples":[{"cn":"我们俩的想法一样。","pinyin":"wǒmen liǎ de xiǎngfǎ yíyàng.","vn":"Suy nghĩ của hai chúng tôi giống nhau."},{"cn":"这两件衣服的颜色不一样。","pinyin":"zhè liǎng jiàn yīfu de yánsè bù yíyàng.","vn":"Màu của hai chiếc áo này không giống nhau."},{"cn":"他跟他哥哥长得一样高。","pinyin":"tā gēn tā gēge zhǎng de yíyàng gāo.","vn":"Anh ấy cao bằng anh trai mình."}]},{"hanzi":"牛","pinyin":"niú","pos":"dt.","vn":"bò","examples":[{"cn":"农村里有很多牛和羊。","pinyin":"nóngcūn lǐ yǒu hěn duō niú hé yáng.","vn":"Ở nông thôn có rất nhiều bò và cừu."},{"cn":"我喜欢喝牛奶。","pinyin":"wǒ xǐhuan hē niúnǎi.","vn":"Tôi thích uống sữa bò."},{"cn":"这头牛特别大。","pinyin":"zhè tóu niú tèbié dà.","vn":"Con bò này to lắm."}]},{"hanzi":"相机","pinyin":"xiàngjī","pos":"dt.","vn":"máy ảnh","examples":[{"cn":"出去玩别忘了带相机。","pinyin":"chūqù wán bié wàng le dài xiàngjī.","vn":"Đi chơi đừng quên mang theo máy ảnh."},{"cn":"这台相机是我生日的时候爸爸送我的。","pinyin":"zhè tái xiàngjī shì wǒ shēngrì de shíhou bàba sòng wǒ de.","vn":"Máy ảnh này là bố tặng tôi vào sinh nhật."},{"cn":"我的相机没电了,先充一下电。","pinyin":"wǒ de xiàngjī méi diàn le, xiān chōng yíxià diàn.","vn":"Máy ảnh của tôi hết pin rồi, sạc một chút đã."}]},{"hanzi":"欢迎","pinyin":"huānyíng","pos":"dgt.","vn":"hoan nghênh, chào đón","examples":[{"cn":"欢迎来到我家!","pinyin":"huānyíng lái dào wǒ jiā!","vn":"Hoan nghênh đến nhà tôi!"},{"cn":"我们热烈欢迎新同学的到来。","pinyin":"wǒmen rèliè huānyíng xīn tóngxué de dàolái.","vn":"Chúng tôi nhiệt liệt chào đón bạn học mới."},{"cn":"欢迎下次再来。","pinyin":"huānyíng xiàcì zài lái.","vn":"Hoan nghênh lần sau lại đến."}]},{"hanzi":"司机","pinyin":"sījī","pos":"dt.","vn":"tài xế","examples":[{"cn":"出租车司机很热情地跟我聊天。","pinyin":"chūzūchē sījī hěn rèqíng de gēn wǒ liáotiān.","vn":"Tài xế taxi rất nhiệt tình trò chuyện với tôi."},{"cn":"他的梦想是当一名公交车司机。","pinyin":"tā de mèngxiǎng shì dāng yì míng gōngjiāochē sījī.","vn":"Ước mơ của anh ấy là trở thành tài xế xe buýt."},{"cn":"司机,麻烦您到前面停一下车。","pinyin":"sījī, máfan nín dào qiánmiàn tíng yíxià chē.","vn":"Bác tài, phiền bác dừng xe ở phía trước giúp em."}]},{"hanzi":"晚点","pinyin":"wǎndiǎn","pos":"dgt.","vn":"trễ giờ (tàu xe)","examples":[{"cn":"我坐的那趟火车晚点了两个小时。","pinyin":"wǒ zuò de nà tàng huǒchē wǎndiǎn le liǎng ge xiǎoshí.","vn":"Chuyến tàu tôi đi đã trễ giờ hai tiếng."},{"cn":"飞机因为天气不好晚点了。","pinyin":"fēijī yīnwèi tiānqì bù hǎo wǎndiǎn le.","vn":"Máy bay trễ giờ vì thời tiết xấu."},{"cn":"请问,这班车会不会晚点?","pinyin":"qǐngwèn, zhè bān chē huì bu huì wǎndiǎn?","vn":"Xin hỏi, chuyến xe này có bị trễ giờ không?"}]},{"hanzi":"久","pinyin":"jiǔ","pos":"tt.","vn":"lâu","examples":[{"cn":"好久不见,你最近怎么样?","pinyin":"hǎo jiǔ bú jiàn, nǐ zuìjìn zěnmeyàng?","vn":"Lâu rồi không gặp, dạo này bạn thế nào?"},{"cn":"我等了很久他才来。","pinyin":"wǒ děng le hěn jiǔ tā cái lái.","vn":"Tôi đợi rất lâu anh ấy mới đến."},{"cn":"这个工作我做了没多久就辞职了。","pinyin":"zhège gōngzuò wǒ zuò le méi duō jiǔ jiù cízhí le.","vn":"Công việc này tôi làm chưa bao lâu đã nghỉ."}]},{"hanzi":"除了","pinyin":"chúle","pos":"giới.","vn":"ngoài, trừ","examples":[{"cn":"除了小李,大家都到了。","pinyin":"chúle Xiǎo Lǐ, dàjiā dōu dào le.","vn":"Ngoài Tiểu Lý ra, mọi người đều đã đến."},{"cn":"除了下雨,我们什么时候都可以去。","pinyin":"chúle xiàyǔ, wǒmen shénme shíhou dōu kěyǐ qù.","vn":"Trừ khi trời mưa, lúc nào chúng ta cũng có thể đi."},{"cn":"除了咖啡,我还喜欢喝茶。","pinyin":"chúle kāfēi, wǒ hái xǐhuan hē chá.","vn":"Ngoài cà phê ra, tôi còn thích uống trà."}]},{"hanzi":"以外","pinyin":"yǐwài","pos":"dt.","vn":"ngoài ra","examples":[{"cn":"除了这件事以外,别的我都不知道。","pinyin":"chúle zhè jiàn shì yǐwài, biéde wǒ dōu bù zhīdào.","vn":"Ngoài chuyện này ra, những chuyện khác tôi đều không biết."},{"cn":"这个班除了他以外,都是女生。","pinyin":"zhège bān chúle tā yǐwài, dōu shì nǚshēng.","vn":"Lớp này ngoài anh ấy ra, đều là con gái."},{"cn":"周末以外,我每天都要上班。","pinyin":"zhōumò yǐwài, wǒ měitiān dōu yào shàngbān.","vn":"Ngoài cuối tuần ra, mỗi ngày tôi đều phải đi làm."}]},{"hanzi":"先","pinyin":"xiān","pos":"phó.","vn":"trước","examples":[{"cn":"你先走,我随后就到。","pinyin":"nǐ xiān zǒu, wǒ suíhòu jiù dào.","vn":"Bạn đi trước đi, tôi đến ngay sau."},{"cn":"我们先吃饭再去看电影吧。","pinyin":"wǒmen xiān chīfàn zài qù kàn diànyǐng ba.","vn":"Chúng ta ăn cơm trước rồi hãy đi xem phim."},{"cn":"先把作业写完,然后再玩手机。","pinyin":"xiān bǎ zuòyè xiě wán, ránhòu zài wán shǒujī.","vn":"Làm xong bài tập trước đã rồi mới chơi điện thoại."}]},{"hanzi":"一直","pinyin":"yìzhí","pos":"phó.","vn":"luôn, mãi","examples":[{"cn":"我一直想去中国旅游。","pinyin":"wǒ yìzhí xiǎng qù Zhōngguó lǚyóu.","vn":"Tôi vẫn luôn muốn đi Trung Quốc du lịch."},{"cn":"他一直在等你的电话。","pinyin":"tā yìzhí zài děng nǐ de diànhuà.","vn":"Anh ấy vẫn đang đợi điện thoại của bạn."},{"cn":"你一直往前走就能看到宾馆了。","pinyin":"nǐ yìzhí wǎng qián zǒu jiù néng kàndào bīnguǎn le.","vn":"Bạn cứ đi thẳng về phía trước là thấy khách sạn."}]},{"hanzi":"干净","pinyin":"gānjìng","pos":"tt.","vn":"sạch sẽ","examples":[{"cn":"你的房间打扫得真干净。","pinyin":"nǐ de fángjiān dǎsǎo de zhēn gānjìng.","vn":"Phòng của bạn dọn dẹp thật sạch sẽ."},{"cn":"吃饭前要把手洗干净。","pinyin":"chīfàn qián yào bǎ shǒu xǐ gānjìng.","vn":"Trước khi ăn cơm phải rửa tay cho sạch."},{"cn":"这家宾馆又干净又安静。","pinyin":"zhè jiā bīnguǎn yòu gānjìng yòu ānjìng.","vn":"Khách sạn này vừa sạch sẽ vừa yên tĩnh."}]},{"hanzi":"满意","pinyin":"mǎnyì","pos":"dgt.","vn":"hài lòng","examples":[{"cn":"我对这次的结果很满意。","pinyin":"wǒ duì zhè cì de jiéguǒ hěn mǎnyì.","vn":"Tôi rất hài lòng với kết quả lần này."},{"cn":"老板对他的工作不太满意。","pinyin":"lǎobǎn duì tā de gōngzuò bú tài mǎnyì.","vn":"Sếp không hài lòng lắm với công việc của anh ấy."},{"cn":"顾客对我们的服务非常满意。","pinyin":"gùkè duì wǒmen de fúwù fēicháng mǎnyì.","vn":"Khách hàng rất hài lòng với dịch vụ của chúng tôi."}]}],"grammar":[{"title":"固定格式\"一……也/都+不/没……\" - Cụm cố định \"一……也/都+不/没……\"","explanation_vn":"Cụm cố định \"一……也/都+不/没……\" biểu thị ý phủ định hoàn toàn. Đôi khi \"一+lượng từ\" phía trước có thể thay bằng \"一点儿\". Khi vị ngữ là tính từ, thường dùng mẫu \"一点儿也/都+不/没+tính từ\" để biểu thị phủ định hoàn toàn.","examples":[{"cn":"她一件衣服都不想买。","pinyin":"Tā yí jiàn yīfu dōu bù xiǎng mǎi.","vn":""},{"cn":"我一个中国电影也没看过。","pinyin":"Wǒ yí ge Zhōngguó diànyǐng yě méi kànguò.","vn":""},{"cn":"我一点儿东西也不想吃。","pinyin":"Wǒ yìdiǎnr dōngxi yě bù xiǎng chī.","vn":""},{"cn":"他对打球一点儿兴趣都没有。","pinyin":"Tā duì dǎqiú yìdiǎnr xìngqù dōu méiyǒu.","vn":""},{"cn":"草原一点儿也不冷。","pinyin":"Cǎoyuán yìdiǎnr yě bù lěng.","vn":""},{"cn":"他们一点儿也没着急。","pinyin":"Tāmen yìdiǎnr yě méi zháojí.","vn":""}]},{"title":"比较句（9） - Câu so sánh (9)","explanation_vn":"Câu so sánh \"A跟B一样\" biểu thị A và B sau khi so sánh có kết quả giống nhau. Phía sau \"一样\" có thể dùng tính từ để chỉ rõ phương diện so sánh, cấu trúc cơ bản: A跟B一样+tính từ. Dạng phủ định thì thêm \"不\" trước \"一样\".","examples":[{"cn":"这家宾馆跟别的都不一样。","pinyin":"Zhè jiā bīnguǎn gēn biéde dōu bù yíyàng.","vn":""},{"cn":"他买的新手机跟我的一样。","pinyin":"Tā mǎi de xīn shǒujī gēn wǒ de yíyàng.","vn":""},{"cn":"这个房间跟那个房间一样大。","pinyin":"Zhège fángjiān gēn nàge fángjiān yíyàng dà.","vn":""}]},{"title":"固定格式\"除了……（以外），……都/还/也……\" - Cụm cố định \"除了……（以外），……都/还/也……\"","explanation_vn":"\"除了……（以外），……都……\" biểu thị trong một phạm vi nào đó, loại trừ một bộ phận, các phần còn lại đều ở cùng một tình huống; \"以外\" có thể lược bỏ. \"除了……（以外），……还/也……\" biểu thị loại trừ một bộ phận, đồng thời bổ sung thêm cái khác. Chủ ngữ của câu đặt ở đầu câu, hoặc đặt trước \"还/也\".","examples":[{"cn":"除了我以外，大家都在玩手机。","pinyin":"Chúle wǒ yǐwài, dàjiā dōu zài wán shǒujī.","vn":""},{"cn":"除了这个汉字，别的汉字我都会写。","pinyin":"Chúle zhège Hànzì, biéde Hànzì wǒ dōu huì xiě.","vn":""},{"cn":"除了这个行李箱以外，还有别的东西吗？","pinyin":"Chúle zhège xínglixiāng yǐwài, hái yǒu biéde dōngxi ma?","vn":""},{"cn":"除了唱歌以外，他也喜欢跳舞。","pinyin":"Chúle chànggē yǐwài, tā yě xǐhuan tiàowǔ.","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"杨同乐","cn":"这个假期咱们去哪儿玩玩吧。","pinyin":"Zhège jiàqī zánmen qù nǎr wánwan ba."},{"speaker":"王一飞","cn":"好啊，你想去哪儿，咱们就去哪儿。","pinyin":"Hǎo a, nǐ xiǎng qù nǎr, zánmen jiù qù nǎr."},{"speaker":"杨同乐","cn":"你喜欢海，找个海边住几天，怎么样？","pinyin":"Nǐ xǐhuan hǎi, zhǎo ge hǎibiān zhù jǐ tiān, zěnmeyàng?"},{"speaker":"王一飞","cn":"现在去海边有点儿冷。","pinyin":"Xiànzài qù hǎibiān yǒudiǎnr lěng."},{"speaker":"杨同乐","cn":"那去草原吧？草原一点儿也不冷。","pinyin":"Nà qù cǎoyuán ba? Cǎoyuán yìdiǎnr yě bù lěng."},{"speaker":"王一飞","cn":"这个主意好！我好久没骑马了。","pinyin":"Zhège zhǔyi hǎo! Wǒ hǎojiǔ méi qí mǎ le."},{"speaker":"杨同乐","cn":"对，在草原上骑马、吃羊肉、看月亮，一定很有意思。","pinyin":"Duì, zài cǎoyuán shàng qí mǎ, chī yángròu, kàn yuèliang, yídìng hěn yǒuyìsi."}],"translation_vn":"Dương Đồng Nhạc: Kỳ nghỉ này chúng ta đi đâu chơi đi.\nVương Nhất Phi: Được đấy, cậu muốn đi đâu, chúng ta đi đó.\nDương Đồng Nhạc: Cậu thích biển, tìm một vùng biển ở vài ngày, thế nào?\nVương Nhất Phi: Bây giờ đi biển hơi lạnh.\nDương Đồng Nhạc: Vậy đi thảo nguyên nhé? Thảo nguyên chẳng lạnh chút nào.\nVương Nhất Phi: Ý này hay đấy! Mình lâu rồi không cưỡi ngựa.\nDương Đồng Nhạc: Đúng vậy, ở thảo nguyên cưỡi ngựa, ăn thịt cừu, ngắm trăng, chắc chắn rất thú vị.","audio_dialogue":"4-1 @xitoytili_luoluodafang.mp3","audio_vocab":"4-2 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"杨同乐","cn":"出去玩的机票买好了吗？","pinyin":"Chūqù wán de jīpiào mǎihǎo le ma?"},{"speaker":"王一飞","cn":"买好了。星期六上午十点一刻起飞。","pinyin":"Mǎihǎo le. Xīngqīliù shàngwǔ shí diǎn yí kè qǐfēi."},{"speaker":"杨同乐","cn":"宾馆也选好了吗？","pinyin":"Bīnguǎn yě xuǎnhǎo le ma?"},{"speaker":"王一飞","cn":"是的，这家宾馆很特别，跟别的都不一样，一出门就能看见牛和羊！","pinyin":"Shì de, zhè jiā bīnguǎn hěn tèbié, gēn biéde dōu bù yíyàng, yì chūmén jiù néng kànjiàn niú hé yáng!"},{"speaker":"杨同乐","cn":"太好了！你看看要带什么东西？","pinyin":"Tài hǎo le! Nǐ kànkan yào dài shénme dōngxi?"},{"speaker":"王一飞","cn":"我们不用带太多东西，别忘了拿上新买的相机。","pinyin":"Wǒmen búyòng dài tài duō dōngxi, bié wàng le ná shàng xīn mǎi de xiàngjī."},{"speaker":"杨同乐","cn":"一定不会忘带的。我现在就去准备行李。","pinyin":"Yídìng bú huì wàng dài de. Wǒ xiànzài jiù qù zhǔnbèi xíngli."}],"translation_vn":"Dương Đồng Nhạc: Vé máy bay đi chơi mua xong chưa?\nVương Nhất Phi: Mua xong rồi. Sáng thứ Bảy mười giờ mười lăm cất cánh.\nDương Đồng Nhạc: Khách sạn cũng chọn xong rồi chứ?\nVương Nhất Phi: Rồi, khách sạn này rất đặc biệt, khác hẳn những nơi khác, vừa ra cửa là thấy bò với cừu!\nDương Đồng Nhạc: Tuyệt quá! Cậu xem cần mang gì không?\nVương Nhất Phi: Chúng ta không cần mang quá nhiều đồ, đừng quên mang theo máy ảnh mới mua.\nDương Đồng Nhạc: Chắc chắn sẽ không quên mang đâu. Mình đi chuẩn bị hành lý ngay đây.","audio_dialogue":"4-3 @xitoytili_luoluodafang.mp3","audio_vocab":"4-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"小李","cn":"欢迎你们！我是你们的司机，我姓李，叫我小李就可以。","pinyin":"Huānyíng nǐmen! Wǒ shì nǐmen de sījī, wǒ xìng Lǐ, jiào wǒ Xiǎo Lǐ jiù kěyǐ."},{"speaker":"杨同乐","cn":"您好！不好意思，飞机晚点了，让您久等了。","pinyin":"Nín hǎo! Bù hǎoyìsi, fēijī wǎndiǎn le, ràng nín jiǔ děng le."},{"speaker":"小李","cn":"没关系。除了这个行李箱以外，还有别的东西吗？","pinyin":"Méi guānxi. Chúle zhège xínglixiāng yǐwài, hái yǒu biéde dōngxi ma?"},{"speaker":"杨同乐","cn":"还有一个包，我自己拿就可以。","pinyin":"Hái yǒu yí ge bāo, wǒ zìjǐ ná jiù kěyǐ."},{"speaker":"小李","cn":"车在一层，请跟我来。","pinyin":"Chē zài yī céng, qǐng gēn wǒ lái."},{"speaker":"杨同乐","cn":"我们住的宾馆离机场远吗？","pinyin":"Wǒmen zhù de bīnguǎn lí jīchǎng yuǎn ma?"},{"speaker":"小李","cn":"不远，三十分钟就能到。两位到了可以先休息休息，晚饭的时候我叫你们。","pinyin":"Bù yuǎn, sānshí fēnzhōng jiù néng dào. Liǎng wèi dào le kěyǐ xiān xiūxi xiūxi, wǎnfàn de shíhou wǒ jiào nǐmen."}],"translation_vn":"Tiểu Lý: Chào mừng hai vị! Tôi là tài xế của hai vị, tôi họ Lý, gọi tôi là Tiểu Lý là được.\nDương Đồng Nhạc: Chào anh! Xin lỗi, máy bay trễ giờ, để anh chờ lâu rồi.\nTiểu Lý: Không sao. Ngoài chiếc vali này ra, còn đồ gì khác không?\nDương Đồng Nhạc: Còn một cái túi nữa, tôi tự cầm được.\nTiểu Lý: Xe đỗ ở tầng một, mời đi theo tôi.\nDương Đồng Nhạc: Khách sạn chúng tôi ở có xa sân bay không?\nTiểu Lý: Không xa, ba mươi phút là tới. Hai vị đến nơi có thể nghỉ ngơi một chút, đến giờ ăn tối tôi sẽ gọi hai vị.","audio_dialogue":"4-5.mp3","audio_vocab":"4-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"今天是我们旅游的第一天。我们很早就起床去机场了，没想到飞机晚点了。我们到的时候，天已经黑了，但是司机小李一直在机场等我们，一点儿也没着急。他特别热情，路上给我们介绍了很多东西，还准备了水果。宾馆的房间跟我想的一样漂亮，又大又干净，我非常满意。","pinyin":"Jīntiān shì wǒmen lǚyóu de dì-yī tiān. Wǒmen hěn zǎo jiù qǐchuáng qù jīchǎng le, méi xiǎngdào fēijī wǎndiǎn le. Wǒmen dào de shíhou, tiān yǐjīng hēi le, dànshì sījī Xiǎo Lǐ yìzhí zài jīchǎng děng wǒmen, yìdiǎnr yě méi zháojí. Tā tèbié rèqíng, lùshang gěi wǒmen jièshào le hěn duō dōngxi, hái zhǔnbèi le shuǐguǒ. Bīnguǎn de fángjiān gēn wǒ xiǎng de yíyàng piàoliang, yòu dà yòu gānjìng, wǒ fēicháng mǎnyì."}],"translation_vn":"Hôm nay là ngày đầu tiên của chuyến du lịch chúng tôi. Chúng tôi dậy rất sớm để ra sân bay, không ngờ máy bay bị trễ giờ. Khi chúng tôi đến nơi, trời đã tối rồi, nhưng tài xế Tiểu Lý vẫn luôn chờ chúng tôi ở sân bay, không hề sốt ruột chút nào. Anh ấy rất nhiệt tình, trên đường giới thiệu cho chúng tôi rất nhiều thứ, còn chuẩn bị sẵn hoa quả. Phòng khách sạn đẹp đúng như tôi tưởng tượng, vừa rộng vừa sạch sẽ, tôi rất hài lòng.","audio_dialogue":"4-7.mp3","audio_vocab":"4-8.mp3"}]},{"id":5,"title_cn":"这样的照片才好看","title_pinyin":"Zhèyàng de zhàopiàn cái hǎokàn","title_vn":"Ảnh như thế này mới đẹp","goals":["Có thể nghe hiểu và giới thiệu về cuộc sống giải trí yêu thích của bản thân.","Có thể nghe hiểu và diễn đạt hai hành động xảy ra kế tiếp nhau.","Nắm được cách dùng của câu tồn hiện (3), có thể diễn đạt sự xuất hiện hoặc biến mất của người hay sự vật."],"vocab":[{"hanzi":"总是","pinyin":"zǒngshì","pos":"phó.","vn":"luôn luôn","examples":[{"cn":"他总是迟到。","pinyin":"tā zǒngshì chídào.","vn":"Anh ấy lúc nào cũng đến muộn."},{"cn":"你怎么总是忘记带钥匙?","pinyin":"nǐ zěnme zǒngshì wàngjì dài yàoshi?","vn":"Sao bạn cứ hay quên mang chìa khóa vậy?"},{"cn":"妈妈总是第一个起床做早饭。","pinyin":"māma zǒngshì dì yī ge qǐchuáng zuò zǎofàn.","vn":"Mẹ luôn là người đầu tiên dậy nấu bữa sáng."}]},{"hanzi":"终于","pinyin":"zhōngyú","pos":"phó.","vn":"cuối cùng","examples":[{"cn":"我终于找到工作了!","pinyin":"wǒ zhōngyú zhǎodào gōngzuò le!","vn":"Cuối cùng tôi cũng tìm được việc làm rồi!"},{"cn":"等了半天,车终于来了。","pinyin":"děng le bàntiān, chē zhōngyú lái le.","vn":"Đợi nửa ngày, xe cuối cùng cũng đến."},{"cn":"经过努力,他终于考上了大学。","pinyin":"jīngguò nǔlì, tā zhōngyú kǎoshàng le dàxué.","vn":"Qua nỗ lực, cuối cùng anh ấy cũng thi đỗ đại học."}]},{"hanzi":"爬","pinyin":"pá","pos":"dgt.","vn":"leo, trèo","examples":[{"cn":"周末我们一起去爬山吧。","pinyin":"zhōumò wǒmen yìqǐ qù páshān ba.","vn":"Cuối tuần chúng ta cùng đi leo núi nhé."},{"cn":"小孩子喜欢在地上爬来爬去。","pinyin":"xiǎoháizi xǐhuan zài dìshang pá lái pá qù.","vn":"Trẻ con thích bò qua bò lại trên nền nhà."},{"cn":"我家的猫老是爬到树上去。","pinyin":"wǒ jiā de māo lǎoshi pá dào shù shàng qù.","vn":"Con mèo nhà tôi cứ hay leo lên cây."}]},{"hanzi":"山","pinyin":"shān","pos":"dt.","vn":"núi","examples":[{"cn":"这座山很高,爬上去要三个小时。","pinyin":"zhè zuò shān hěn gāo, pá shàngqù yào sān ge xiǎoshí.","vn":"Ngọn núi này rất cao, leo lên mất ba tiếng."},{"cn":"我喜欢住在山里,空气很好。","pinyin":"wǒ xǐhuan zhù zài shān lǐ, kōngqì hěn hǎo.","vn":"Tôi thích sống trong núi, không khí rất trong lành."},{"cn":"从山上往下看,风景特别美。","pinyin":"cóng shān shàng wǎng xià kàn, fēngjǐng tèbié měi.","vn":"Từ trên núi nhìn xuống, phong cảnh đẹp vô cùng."}]},{"hanzi":"锻炼","pinyin":"duànliàn","pos":"dgt.","vn":"rèn luyện, tập luyện","examples":[{"cn":"我每天早上都去公园锻炼身体。","pinyin":"wǒ měitiān zǎoshang dōu qù gōngyuán duànliàn shēntǐ.","vn":"Mỗi sáng tôi đều ra công viên rèn luyện sức khỏe."},{"cn":"多锻炼对身体有好处。","pinyin":"duō duànliàn duì shēntǐ yǒu hǎochù.","vn":"Tập luyện nhiều có lợi cho sức khỏe."},{"cn":"他每天坚持锻炼一个小时。","pinyin":"tā měitiān jiānchí duànliàn yí ge xiǎoshí.","vn":"Anh ấy kiên trì tập luyện một tiếng mỗi ngày."}]},{"hanzi":"照","pinyin":"zhào","pos":"dgt.","vn":"chụp (ảnh)","examples":[{"cn":"你能帮我照一张相吗?","pinyin":"nǐ néng bāng wǒ zhào yì zhāng xiàng ma?","vn":"Bạn có thể chụp giúp tôi một tấm ảnh không?"},{"cn":"阳光照在脸上很暖和。","pinyin":"yángguāng zhào zài liǎn shàng hěn nuǎnhuo.","vn":"Ánh nắng chiếu lên mặt rất ấm áp."},{"cn":"她每天都照镜子打扮自己。","pinyin":"tā měitiān dōu zhào jìngzi dǎbàn zìjǐ.","vn":"Cô ấy ngày nào cũng soi gương trang điểm."}]},{"hanzi":"鞋","pinyin":"xié","pos":"dt.","vn":"giày","examples":[{"cn":"这双鞋是我新买的。","pinyin":"zhè shuāng xié shì wǒ xīn mǎi de.","vn":"Đôi giày này là tôi mới mua."},{"cn":"进门前请把鞋脱了。","pinyin":"jìnmén qián qǐng bǎ xié tuō le.","vn":"Trước khi vào nhà xin hãy cởi giày ra."},{"cn":"这双鞋有点儿大,我想换一双小的。","pinyin":"zhè shuāng xié yǒudiǎnr dà, wǒ xiǎng huàn yì shuāng xiǎo de.","vn":"Đôi giày này hơi rộng, tôi muốn đổi đôi nhỏ hơn."}]},{"hanzi":"大衣","pinyin":"dàyī","pos":"dt.","vn":"áo khoác dài","examples":[{"cn":"天气冷了,你该穿大衣了。","pinyin":"tiānqì lěng le, nǐ gāi chuān dàyī le.","vn":"Trời lạnh rồi, bạn nên mặc áo khoác dài vào."},{"cn":"这件大衣是我妈妈送我的生日礼物。","pinyin":"zhè jiàn dàyī shì wǒ māma sòng wǒ de shēngrì lǐwù.","vn":"Chiếc áo khoác dài này là quà sinh nhật mẹ tặng tôi."},{"cn":"商场里的大衣太贵了,我没买。","pinyin":"shāngchǎng lǐ de dàyī tài guì le, wǒ méi mǎi.","vn":"Áo khoác dài trong trung tâm thương mại đắt quá, tôi không mua."}]},{"hanzi":"拍照","pinyin":"pāizhào","pos":"dgt.","vn":"chụp ảnh","examples":[{"cn":"我们在这里拍照留念吧。","pinyin":"wǒmen zài zhèlǐ pāizhào liúniàn ba.","vn":"Chúng ta chụp ảnh lưu niệm ở đây đi."},{"cn":"她特别喜欢旅游时拍照。","pinyin":"tā tèbié xǐhuan lǚyóu shí pāizhào.","vn":"Cô ấy rất thích chụp ảnh khi đi du lịch."},{"cn":"你帮我们拍照好吗?","pinyin":"nǐ bāng wǒmen pāizhào hǎo ma?","vn":"Bạn chụp ảnh giúp chúng tôi được không?"}]},{"hanzi":"感兴趣","pinyin":"gǎn xìngqù","pos":"dgt.","vn":"hứng thú, quan tâm","examples":[{"cn":"我对中国历史很感兴趣。","pinyin":"wǒ duì Zhōngguó lìshǐ hěn gǎn xìngqù.","vn":"Tôi rất hứng thú với lịch sử Trung Quốc."},{"cn":"他对音乐一点儿都不感兴趣。","pinyin":"tā duì yīnyuè yìdiǎnr dōu bù gǎn xìngqù.","vn":"Anh ấy chẳng hứng thú gì với âm nhạc cả."},{"cn":"你对什么运动比较感兴趣?","pinyin":"nǐ duì shénme yùndòng bǐjiào gǎn xìngqù?","vn":"Bạn hứng thú với môn thể thao nào hơn?"}]},{"hanzi":"照相","pinyin":"zhàoxiàng","pos":"dgt.","vn":"chụp ảnh","examples":[{"cn":"我们站在这儿照相吧。","pinyin":"wǒmen zhàn zài zhèr zhàoxiàng ba.","vn":"Chúng ta đứng ở đây chụp ảnh đi."},{"cn":"他不喜欢照相,总是躲起来。","pinyin":"tā bù xǐhuan zhàoxiàng, zǒngshì duǒ qǐlái.","vn":"Anh ấy không thích chụp ảnh, lúc nào cũng trốn đi."},{"cn":"来,大家一起照相!","pinyin":"lái, dàjiā yìqǐ zhàoxiàng!","vn":"Nào, mọi người cùng chụp ảnh đi!"}]},{"hanzi":"难看","pinyin":"nánkàn","pos":"tt.","vn":"xấu, khó coi","examples":[{"cn":"这件衣服颜色太难看了。","pinyin":"zhè jiàn yīfu yánsè tài nánkàn le.","vn":"Màu của chiếc áo này xấu quá."},{"cn":"别担心,这张照片一点儿都不难看。","pinyin":"bié dānxīn, zhè zhāng zhàopiàn yìdiǎnr dōu bù nánkàn.","vn":"Đừng lo, tấm ảnh này không xấu chút nào."},{"cn":"他的字写得很难看。","pinyin":"tā de zì xiě de hěn nánkàn.","vn":"Chữ anh ấy viết xấu lắm."}]},{"hanzi":"比较","pinyin":"bǐjiào","pos":"dgt./phó.","vn":"so sánh; tương đối","examples":[{"cn":"这两家宾馆我们比较一下再决定。","pinyin":"zhè liǎng jiā bīnguǎn wǒmen bǐjiào yíxià zài juédìng.","vn":"Hai khách sạn này chúng ta so sánh một chút rồi hãy quyết định."},{"cn":"今天的天气比较冷。","pinyin":"jīntiān de tiānqì bǐjiào lěng.","vn":"Thời tiết hôm nay tương đối lạnh."},{"cn":"我比较喜欢安静的地方。","pinyin":"wǒ bǐjiào xǐhuan ānjìng de dìfang.","vn":"Tôi tương đối thích những nơi yên tĩnh."}]},{"hanzi":"水平","pinyin":"shuǐpíng","pos":"dt.","vn":"trình độ","examples":[{"cn":"他的汉语水平提高了很多。","pinyin":"tā de Hànyǔ shuǐpíng tígāo le hěn duō.","vn":"Trình độ tiếng Trung của anh ấy đã tiến bộ nhiều."},{"cn":"这次考试能看出你的真实水平。","pinyin":"zhè cì kǎoshì néng kànchū nǐ de zhēnshí shuǐpíng.","vn":"Bài thi lần này có thể cho thấy trình độ thật của bạn."},{"cn":"我的英语水平还需要提高。","pinyin":"wǒ de Yīngyǔ shuǐpíng hái xūyào tígāo.","vn":"Trình độ tiếng Anh của tôi vẫn cần được nâng cao."}]},{"hanzi":"太阳","pinyin":"tàiyáng","pos":"dt.","vn":"mặt trời","examples":[{"cn":"今天的太阳特别大。","pinyin":"jīntiān de tàiyáng tèbié dà.","vn":"Hôm nay nắng to lắm."},{"cn":"太阳出来了,天气会暖和一些。","pinyin":"tàiyáng chūlái le, tiānqì huì nuǎnhuo yìxiē.","vn":"Mặt trời đã lên rồi, thời tiết sẽ ấm hơn chút."},{"cn":"我喜欢晒太阳,觉得很舒服。","pinyin":"wǒ xǐhuan shài tàiyáng, juéde hěn shūfu.","vn":"Tôi thích phơi nắng, cảm thấy rất dễ chịu."}]},{"hanzi":"树","pinyin":"shù","pos":"dt.","vn":"cây","examples":[{"cn":"公园里种了很多树。","pinyin":"gōngyuán lǐ zhòng le hěn duō shù.","vn":"Trong công viên trồng rất nhiều cây."},{"cn":"小猫爬到树上下不来了。","pinyin":"xiǎomāo pá dào shù shàng xià bu lái le.","vn":"Con mèo nhỏ leo lên cây mà không xuống được."},{"cn":"夏天坐在树下乘凉真舒服。","pinyin":"xiàtiān zuò zài shù xià chéngliáng zhēn shūfu.","vn":"Mùa hè ngồi dưới gốc cây hóng mát thật dễ chịu."}]},{"hanzi":"干","pinyin":"gàn","pos":"dgt.","vn":"làm","examples":[{"cn":"你在干什么呢?","pinyin":"nǐ zài gàn shénme ne?","vn":"Bạn đang làm gì vậy?"},{"cn":"这件事我一个人干不了。","pinyin":"zhè jiàn shì wǒ yí ge rén gàn bu liǎo.","vn":"Việc này một mình tôi không làm nổi."},{"cn":"他每天都干活儿干到很晚。","pinyin":"tā měitiān dōu gànhuór gàn dào hěn wǎn.","vn":"Anh ấy ngày nào cũng làm việc đến tận khuya."}]},{"hanzi":"电","pinyin":"diàn","pos":"dt.","vn":"điện","examples":[{"cn":"家里突然停电了。","pinyin":"jiālǐ tūrán tíngdiàn le.","vn":"Nhà đột nhiên bị mất điện."},{"cn":"出门前记得关灯省电。","pinyin":"chūmén qián jìde guāndēng shěng diàn.","vn":"Trước khi ra khỏi nhà nhớ tắt đèn để tiết kiệm điện."},{"cn":"我的手机没电了,快帮我充一下。","pinyin":"wǒ de shǒujī méi diàn le, kuài bāng wǒ chōng yíxià.","vn":"Điện thoại tôi hết pin rồi, mau giúp tôi sạc một chút."}]},{"hanzi":"收到","pinyin":"shōudào","pos":"dgt.","vn":"nhận được","examples":[{"cn":"我收到你的邮件了,谢谢。","pinyin":"wǒ shōudào nǐ de yóujiàn le, xièxie.","vn":"Tôi đã nhận được thư điện tử của bạn, cảm ơn."},{"cn":"昨天我收到了一份生日礼物。","pinyin":"zuótiān wǒ shōudào le yí fèn shēngrì lǐwù.","vn":"Hôm qua tôi đã nhận được một món quà sinh nhật."},{"cn":"你收到我的短信了吗?","pinyin":"nǐ shōudào wǒ de duǎnxìn le ma?","vn":"Bạn nhận được tin nhắn của tôi chưa?"}]},{"hanzi":"封","pinyin":"fēng","pos":"lượng.","vn":"bức, phong (thư)","examples":[{"cn":"我给他写了一封信。","pinyin":"wǒ gěi tā xiě le yì fēng xìn.","vn":"Tôi đã viết cho anh ấy một bức thư."},{"cn":"今天早上收到一封很重要的邮件。","pinyin":"jīntiān zǎoshang shōudào yì fēng hěn zhòngyào de yóujiàn.","vn":"Sáng nay tôi nhận được một bức thư điện tử rất quan trọng."},{"cn":"他桌子上放着好几封没拆开的信。","pinyin":"tā zhuōzi shàng fàng zhe hǎo jǐ fēng méi chāikāi de xìn.","vn":"Trên bàn anh ấy để mấy bức thư chưa bóc."}]},{"hanzi":"邮件","pinyin":"yóujiàn","pos":"dt.","vn":"thư điện tử, bưu kiện","examples":[{"cn":"请把文件用邮件发给我。","pinyin":"qǐng bǎ wénjiàn yòng yóujiàn fā gěi wǒ.","vn":"Hãy gửi tài liệu cho tôi qua thư điện tử."},{"cn":"我还没查今天的邮件。","pinyin":"wǒ hái méi chá jīntiān de yóujiàn.","vn":"Tôi vẫn chưa kiểm tra email hôm nay."},{"cn":"他每天都要处理很多邮件。","pinyin":"tā měitiān dōu yào chǔlǐ hěn duō yóujiàn.","vn":"Mỗi ngày anh ấy đều phải xử lý rất nhiều email."}]},{"hanzi":"难过","pinyin":"nánguò","pos":"tt.","vn":"buồn","examples":[{"cn":"听到这个消息,我很难过。","pinyin":"tīngdào zhège xiāoxi, wǒ hěn nánguò.","vn":"Nghe tin này, tôi rất buồn."},{"cn":"别难过了,一切都会好起来的。","pinyin":"bié nánguò le, yíqiè dōu huì hǎo qǐlái de.","vn":"Đừng buồn nữa, mọi chuyện rồi sẽ ổn thôi."},{"cn":"她为什么看起来这么难过?","pinyin":"tā wèishénme kàn qǐlái zhème nánguò?","vn":"Sao cô ấy trông buồn vậy?"}]},{"hanzi":"哈哈","pinyin":"hāhā","pos":"ct.","vn":"haha (tiếng cười)","examples":[{"cn":"哈哈,这个笑话太好笑了!","pinyin":"hāhā, zhège xiàohua tài hǎoxiào le!","vn":"Haha, câu chuyện cười này buồn cười quá!"},{"cn":"他一边说一边哈哈大笑。","pinyin":"tā yìbiān shuō yìbiān hāhā dà xiào.","vn":"Anh ấy vừa nói vừa cười haha lớn tiếng."},{"cn":"哈哈,我也觉得你说得对。","pinyin":"hāhā, wǒ yě juéde nǐ shuō de duì.","vn":"Haha, tôi cũng thấy bạn nói đúng."}]},{"hanzi":"音乐","pinyin":"yīnyuè","pos":"dt.","vn":"âm nhạc","examples":[{"cn":"我喜欢听轻音乐放松一下。","pinyin":"wǒ xǐhuan tīng qīng yīnyuè fàngsōng yíxià.","vn":"Tôi thích nghe nhạc nhẹ để thư giãn một chút."},{"cn":"她从小就对音乐很感兴趣。","pinyin":"tā cóngxiǎo jiù duì yīnyuè hěn gǎn xìngqù.","vn":"Từ nhỏ cô ấy đã rất hứng thú với âm nhạc."},{"cn":"这首音乐真好听,是谁唱的?","pinyin":"zhè shǒu yīnyuè zhēn hǎotīng, shì shéi chàng de?","vn":"Bài nhạc này hay quá, ai hát vậy?"}]},{"hanzi":"兴趣","pinyin":"xìngqù","pos":"dt.","vn":"hứng thú, sở thích","examples":[{"cn":"我对画画儿特别有兴趣。","pinyin":"wǒ duì huàhuàr tèbié yǒu xìngqù.","vn":"Tôi đặc biệt có hứng thú với vẽ tranh."},{"cn":"他的兴趣很广泛,什么都喜欢学。","pinyin":"tā de xìngqù hěn guǎngfàn, shénme dōu xǐhuan xué.","vn":"Sở thích của anh ấy rất rộng, cái gì cũng thích học."},{"cn":"你对什么感兴趣?","pinyin":"nǐ duì shénme gǎn xìngqù?","vn":"Bạn có hứng thú với cái gì?"}]},{"hanzi":"会","pinyin":"huì","pos":"dt.","vn":"buổi (hòa nhạc...), hội","examples":[{"cn":"今天晚上有一场音乐会。","pinyin":"jīntiān wǎnshang yǒu yì chǎng yīnyuèhuì.","vn":"Tối nay có một buổi hòa nhạc."},{"cn":"明天公司有一个重要的会。","pinyin":"míngtiān gōngsī yǒu yí ge zhòngyào de huì.","vn":"Mai công ty có một cuộc họp quan trọng."},{"cn":"这场演唱会的票很难买。","pinyin":"zhè chǎng yǎnchànghuì de piào hěn nán mǎi.","vn":"Vé buổi hòa nhạc này rất khó mua."}]},{"hanzi":"结束","pinyin":"jiéshù","pos":"dgt.","vn":"kết thúc","examples":[{"cn":"电影几点结束?","pinyin":"diànyǐng jǐ diǎn jiéshù?","vn":"Phim mấy giờ kết thúc?"},{"cn":"会议终于结束了,我们可以下班了。","pinyin":"huìyì zhōngyú jiéshù le, wǒmen kěyǐ xiàbān le.","vn":"Cuộc họp cuối cùng cũng kết thúc, chúng ta có thể tan làm rồi."},{"cn":"假期结束了,我得回去上班了。","pinyin":"jiàqī jiéshù le, wǒ děi huíqù shàngbān le.","vn":"Kỳ nghỉ kết thúc rồi, tôi phải quay lại đi làm thôi."}]}],"grammar":[{"title":"程度补语（2） - Bổ ngữ trình độ (2)","explanation_vn":"Bổ ngữ trình độ \"得很\" dùng sau tính từ, biểu thị mức độ cao, thường dùng trong khẩu ngữ.","examples":[{"cn":"现在天气好得很。","pinyin":"Xiànzài tiānqì hǎo de hěn.","vn":""},{"cn":"房间里面热得很。","pinyin":"Fángjiān lǐmiàn rè de hěn.","vn":""},{"cn":"我觉得爬山累得很。","pinyin":"Wǒ juéde pá shān lèi de hěn.","vn":""}]},{"title":"量词重叠 - Láy lượng từ","explanation_vn":"Trong tiếng Hán, rất nhiều lượng từ có thể láy lại để nhấn mạnh mỗi thành viên trong một phạm vi nào đó đều có một đặc điểm nhất định, phía sau thường dùng \"都\".","examples":[{"cn":"这些照片张张都非常好看。（=每张照片都非常好看。）","pinyin":"Zhèxiē zhàopiàn zhāng zhāng dōu fēicháng hǎokàn. (= Měi zhāng zhàopiàn dōu fēicháng hǎokàn.)","vn":""},{"cn":"这些苹果个个都很大。（=每个苹果都很大。）","pinyin":"Zhèxiē píngguǒ gè gè dōu hěn dà. (= Měi ge píngguǒ dōu hěn dà.)","vn":""},{"cn":"我想出去拍照，但是天天下雨。（=每天都下雨。）","pinyin":"Wǒ xiǎng chūqù pāizhào, dànshì tiān tiān xiàyǔ. (= Měi tiān dōu xiàyǔ.)","vn":""}]},{"title":"存现句（3） - Câu tồn hiện (3)","explanation_vn":"Trong tiếng Hán, để trần thuật việc người hay sự vật xuất hiện hoặc biến mất ở một nơi nào đó, có thể dùng câu tồn hiện. Cấu trúc cơ bản: từ/cụm từ chỉ nơi chốn + động từ + bổ ngữ xu hướng/bổ ngữ kết quả + (trợ từ động thái) + cụm số lượng + người/vật.","examples":[{"cn":"后边走过去两个人。","pinyin":"Hòubian zǒu guòqù liǎng ge rén.","vn":""},{"cn":"前面开过来很多车。","pinyin":"Qiánmiàn kāi guòlái hěn duō chē.","vn":""},{"cn":"楼上下来了几个人。","pinyin":"Lóushàng xiàlái le jǐ ge rén.","vn":""}]},{"title":"紧缩复句\"……了……就……\" - Câu phức rút gọn \"……了……就……\"","explanation_vn":"Câu phức rút gọn \"……了……就……\" biểu thị hai hành động xảy ra kế tiếp ngay sau nhau. Nếu hành động thứ hai cũng đã hoàn thành thì cần thêm một \"了\" ở cuối câu. Cấu trúc cơ bản: Động từ1+了……就+Động từ2……","examples":[{"cn":"你听完了音乐会就来我家吃饭。","pinyin":"Nǐ tīngwán le yīnyuèhuì jiù lái wǒ jiā chīfàn.","vn":""},{"cn":"我吃了早饭就去学校了。","pinyin":"Wǒ chī le zǎofàn jiù qù xuéxiào le.","vn":""},{"cn":"昨天我们下了课就回家了。","pinyin":"Zuótiān wǒmen xià le kè jiù huíjiā le.","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"白家月","cn":"这个星期总是阴天，今天终于晴了。","pinyin":"Zhège xīngqī zǒngshì yīntiān, jīntiān zhōngyú qíng le."},{"speaker":"李文","cn":"现在天气好得很！我们去爬山怎么样？","pinyin":"Xiànzài tiānqì hǎo de hěn! Wǒmen qù pá shān zěnmeyàng?"},{"speaker":"白家月","cn":"好啊！又能锻炼身体，又能照好看的照片。","pinyin":"Hǎo a! Yòu néng duànliàn shēntǐ, yòu néng zhào hǎokàn de zhàopiàn."},{"speaker":"李文","cn":"那我带点儿水和吃的，咱们现在就去？","pinyin":"Nà wǒ dài diǎnr shuǐ hé chī de, zánmen xiànzài jiù qù?"},{"speaker":"白家月","cn":"我回去穿上运动鞋，拿上大衣。要不要叫一雪姐一起去？","pinyin":"Wǒ huíqù chuānshàng yùndòngxié, náshàng dàyī. Yào bu yào jiào Yīxuě jiě yìqǐ qù?"},{"speaker":"李文","cn":"好主意。给她打个电话吧。","pinyin":"Hǎo zhǔyi. Gěi tā dǎ ge diànhuà ba."}],"translation_vn":"Bạch Gia Nguyệt: Tuần này cứ toàn trời âm u, hôm nay cuối cùng cũng nắng rồi.\nLý Văn: Thời tiết hôm nay đẹp lắm! Chúng ta đi leo núi thế nào?\nBạch Gia Nguyệt: Được đấy! Vừa rèn luyện sức khỏe, vừa chụp được ảnh đẹp.\nLý Văn: Vậy mình mang ít nước và đồ ăn, chúng ta đi luôn bây giờ nhé?\nBạch Gia Nguyệt: Mình về mặc giày thể thao, lấy áo khoác. Có nên gọi chị Nhất Tuyết đi cùng không?\nLý Văn: Ý hay đấy. Gọi điện cho chị ấy đi.","audio_dialogue":"5-1.mp3","audio_vocab":"5-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"白家月","cn":"这些照片是谁给您照的？张张都非常好看。","pinyin":"Zhèxiē zhàopiàn shì shéi gěi nín zhào de? Zhāng zhāng dōu fēicháng hǎokàn."},{"speaker":"王一雪","cn":"一飞。她对拍照一直很感兴趣，经常给我照相。","pinyin":"Yīfēi. Tā duì pāizhào yìzhí hěn gǎn xìngqù, jīngcháng gěi wǒ zhàoxiàng."},{"speaker":"白家月","cn":"我喜欢您大笑的这张，看起来很漂亮。","pinyin":"Wǒ xǐhuan nín dàxiào de zhè zhāng, kànqǐlai hěn piàoliang."},{"speaker":"王一雪","cn":"我觉得这张有点儿难看，那时候我不知道她在给我照相。","pinyin":"Wǒ juéde zhè zhāng yǒudiǎnr nánkàn, nà shíhou wǒ bù zhīdào tā zài gěi wǒ zhàoxiàng."},{"speaker":"白家月","cn":"这样的照片才好看。我也喜欢拍照，爬山的时候我给您照几张照片吧。","pinyin":"Zhèyàng de zhàopiàn cái hǎokàn. Wǒ yě xǐhuan pāizhào, pá shān de shíhou wǒ gěi nín zhào jǐ zhāng zhàopiàn ba."},{"speaker":"王一雪","cn":"好，我可以比较一下你们两个谁的水平高。","pinyin":"Hǎo, wǒ kěyǐ bǐjiào yíxià nǐmen liǎng ge shéi de shuǐpíng gāo."}],"translation_vn":"Bạch Gia Nguyệt: Mấy tấm ảnh này ai chụp cho chị vậy? Tấm nào cũng đẹp cả.\nVương Nhất Tuyết: Nhất Phi đấy. Nó luôn rất hứng thú với việc chụp ảnh, thường xuyên chụp cho chị.\nBạch Gia Nguyệt: Em thích tấm chị cười lớn này, trông rất đẹp.\nVương Nhất Tuyết: Chị thấy tấm này hơi xấu, lúc đó chị không biết nó đang chụp mình.\nBạch Gia Nguyệt: Ảnh như vậy mới đẹp chứ. Em cũng thích chụp ảnh, lúc leo núi em chụp cho chị vài tấm nhé.\nVương Nhất Tuyết: Được, chị có thể so sánh xem ai trong hai đứa có trình độ cao hơn.","audio_dialogue":"5-3.mp3","audio_vocab":"5-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"王一雪","cn":"家月，这里挺漂亮的，咱们在这里拍照吧。","pinyin":"Jiāyuè, zhèlǐ tǐng piàoliang de, zánmen zài zhèlǐ pāizhào ba."},{"speaker":"白家月","cn":"这边没有太阳，咱们去那边吧。","pinyin":"Zhè biān méiyǒu tàiyáng, zánmen qù nà biān ba."},{"speaker":"王一雪","cn":"好。你觉得我站在这些树中间怎么样？","pinyin":"Hǎo. Nǐ juéde wǒ zhàn zài zhèxiē shù zhōngjiān zěnmeyàng?"},{"speaker":"白家月","cn":"挺好的。等一下，后边走过去两个人。","pinyin":"Tǐng hǎo de. Děng yíxià, hòubian zǒu guòqù liǎng ge rén."},{"speaker":"王一雪","cn":"我准备好了，你照的时候告诉我。","pinyin":"Wǒ zhǔnbèi hǎo le, nǐ zhào de shíhou gàosu wǒ."},{"speaker":"白家月","cn":"你不用看着我，想干什么都可以。","pinyin":"Nǐ búyòng kànzhe wǒ, xiǎng gàn shénme dōu kěyǐ."},{"speaker":"王一雪","cn":"树上飞来了几只鸟，我就看它们吧。","pinyin":"Shù shàng fēilái le jǐ zhī niǎo, wǒ jiù kàn tāmen ba."},{"speaker":"白家月","cn":"啊，手机没电了。","pinyin":"À, shǒujī méi diàn le."}],"translation_vn":"Vương Nhất Tuyết: Gia Nguyệt, chỗ này khá đẹp, chúng ta chụp ảnh ở đây đi.\nBạch Gia Nguyệt: Bên này không có nắng, chúng ta sang bên kia đi.\nVương Nhất Tuyết: Được. Em thấy chị đứng giữa mấy cây này thế nào?\nBạch Gia Nguyệt: Đẹp đấy. Đợi một chút, phía sau có hai người đi qua.\nVương Nhất Tuyết: Chị chuẩn bị xong rồi, lúc nào chụp thì nói chị nhé.\nBạch Gia Nguyệt: Chị không cần nhìn vào em, muốn làm gì cũng được.\nVương Nhất Tuyết: Trên cây có mấy con chim bay tới, chị ngắm chúng vậy.\nBạch Gia Nguyệt: A, điện thoại hết pin rồi.","audio_dialogue":"5-5.mp3","audio_vocab":"5-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"家月，我收到了你的那封邮件，也看到了你给我照的照片，张张都很漂亮。我已经告诉了一飞，你的拍照水平比她高，她难过得很，哈哈。不知道你对中国的音乐有没有兴趣？我送你一张明天下午音乐会的门票。音乐会七点多结束，你听完了音乐会就来我家吃饭，尝尝我做的中国菜。你觉得怎么样？","pinyin":"Jiāyuè, wǒ shōudào le nǐ de nà fēng yóujiàn, yě kàndào le nǐ gěi wǒ zhào de zhàopiàn, zhāng zhāng dōu hěn piàoliang. Wǒ yǐjīng gàosu le Yīfēi, nǐ de pāizhào shuǐpíng bǐ tā gāo, tā nánguò de hěn, hāhā. Bù zhīdào nǐ duì Zhōngguó de yīnyuè yǒu méiyǒu xìngqù? Wǒ sòng nǐ yì zhāng míngtiān xiàwǔ yīnyuèhuì de ménpiào. Yīnyuèhuì qī diǎn duō jiéshù, nǐ tīngwán le yīnyuèhuì jiù lái wǒ jiā chīfàn, chángchang wǒ zuò de Zhōngguó cài. Nǐ juéde zěnmeyàng?"}],"translation_vn":"Gia Nguyệt ơi, chị đã nhận được bức thư điện tử đó của em rồi, cũng xem những tấm ảnh em chụp cho chị, tấm nào cũng đẹp. Chị đã nói cho Nhất Phi biết rồi, trình độ chụp ảnh của em cao hơn nó đấy, nó buồn lắm, haha. Không biết em có hứng thú với âm nhạc Trung Quốc không? Chị tặng em một vé buổi hòa nhạc chiều mai. Buổi hòa nhạc kết thúc hơn bảy giờ, em nghe xong hòa nhạc thì đến nhà chị ăn cơm, nếm thử món Trung Quốc chị nấu nhé. Em thấy thế nào?","audio_dialogue":"5-7.mp3","audio_vocab":"5-8.mp3"}]},{"id":6,"title_cn":"高铁上还可以点外卖","title_pinyin":"Gāotiě shàng hái kěyǐ diǎn wàimài","title_vn":"Trên tàu cao tốc còn có thể gọi đồ ăn mang tới","goals":["Có thể nghe hiểu và giới thiệu về đặc điểm các phương tiện giao thông cũng như trải nghiệm đi lại.","Có thể nghe hiểu và sử dụng \"如果\" để diễn đạt tình huống giả thiết và kết quả.","Nắm được cụm từ \"越来越\", có thể miêu tả xu hướng biến đổi của sự vật.","Tìm hiểu phương thức giao thông hiện đại của Trung Quốc — tàu cao tốc."],"vocab":[{"hanzi":"该","pinyin":"gāi","pos":"đtnn.","vn":"nên, phải","examples":[{"cn":"你该好好休息一下了。","pinyin":"nǐ gāi hǎohāo xiūxi yíxià le.","vn":"Bạn nên nghỉ ngơi một chút rồi."},{"cn":"已经十点了,该睡觉了。","pinyin":"yǐjīng shí diǎn le, gāi shuìjiào le.","vn":"Đã mười giờ rồi, nên đi ngủ thôi."},{"cn":"这件事该怎么办呢?","pinyin":"zhè jiàn shì gāi zěnme bàn ne?","vn":"Việc này nên giải quyết thế nào đây?"}]},{"hanzi":"打算","pinyin":"dǎsuàn","pos":"dgt./dt.","vn":"dự định, kế hoạch","examples":[{"cn":"你周末打算做什么?","pinyin":"nǐ zhōumò dǎsuàn zuò shénme?","vn":"Cuối tuần bạn định làm gì?"},{"cn":"我打算明年去国外留学。","pinyin":"wǒ dǎsuàn míngnián qù guówài liúxué.","vn":"Tôi dự định sang năm đi du học nước ngoài."},{"cn":"他还没有明确的打算。","pinyin":"tā hái méiyǒu míngquè de dǎsuàn.","vn":"Anh ấy vẫn chưa có kế hoạch rõ ràng."}]},{"hanzi":"高铁","pinyin":"gāotiě","pos":"dt.","vn":"tàu cao tốc","examples":[{"cn":"我们坐高铁去北京吧,又快又方便。","pinyin":"wǒmen zuò gāotiě qù Běijīng ba, yòu kuài yòu fāngbiàn.","vn":"Chúng ta đi tàu cao tốc đến Bắc Kinh đi, vừa nhanh vừa tiện."},{"cn":"高铁票已经订好了,下午三点出发。","pinyin":"gāotiě piào yǐjīng dìng hǎo le, xiàwǔ sān diǎn chūfā.","vn":"Vé tàu cao tốc đã đặt xong rồi, ba giờ chiều xuất phát."},{"cn":"中国的高铁速度特别快。","pinyin":"Zhōngguó de gāotiě sùdù tèbié kuài.","vn":"Tốc độ tàu cao tốc của Trung Quốc rất nhanh."}]},{"hanzi":"行","pinyin":"xíng","pos":"dgt./tt.","vn":"được, ổn","examples":[{"cn":"明天见面,行吗?","pinyin":"míngtiān jiànmiàn, xíng ma?","vn":"Mai gặp nhau, được không?"},{"cn":"行,就这么定了。","pinyin":"xíng, jiù zhème dìng le.","vn":"Được, vậy quyết định thế nhé."},{"cn":"这个办法行不行?","pinyin":"zhège bànfǎ xíng bu xíng?","vn":"Cách này có ổn không?"}]},{"hanzi":"路口","pinyin":"lùkǒu","pos":"dt.","vn":"ngã tư, giao lộ","examples":[{"cn":"在前面的路口右转就到了。","pinyin":"zài qiánmiàn de lùkǒu yòu zhuǎn jiù dào le.","vn":"Rẽ phải ở ngã tư phía trước là đến."},{"cn":"过路口的时候一定要小心。","pinyin":"guò lùkǒu de shíhou yídìng yào xiǎoxīn.","vn":"Khi qua ngã tư nhất định phải cẩn thận."},{"cn":"路口的红绿灯坏了。","pinyin":"lùkǒu de hóng-lǜdēng huài le.","vn":"Đèn giao thông ở ngã tư bị hỏng rồi."}]},{"hanzi":"小心","pinyin":"xiǎoxīn","pos":"dgt./tt.","vn":"cẩn thận","examples":[{"cn":"过马路的时候要小心。","pinyin":"guò mǎlù de shíhou yào xiǎoxīn.","vn":"Khi qua đường phải cẩn thận."},{"cn":"小心点儿,地上很滑。","pinyin":"xiǎoxīn diǎnr, dìshang hěn huá.","vn":"Cẩn thận chút, nền nhà rất trơn."},{"cn":"他开车一直很小心。","pinyin":"tā kāichē yìzhí hěn xiǎoxīn.","vn":"Anh ấy lái xe luôn rất cẩn thận."}]},{"hanzi":"迟到","pinyin":"chídào","pos":"dgt.","vn":"đến muộn","examples":[{"cn":"今天路上堵车,我迟到了。","pinyin":"jīntiān lùshang dǔchē, wǒ chídào le.","vn":"Hôm nay đường tắc xe, tôi đến muộn rồi."},{"cn":"请不要再迟到了。","pinyin":"qǐng búyào zài chídào le.","vn":"Xin đừng đến muộn nữa."},{"cn":"如果你再迟到,老板会生气的。","pinyin":"rúguǒ nǐ zài chídào, lǎobǎn huì shēngqì de.","vn":"Nếu bạn còn đến muộn, sếp sẽ nổi giận đấy."}]},{"hanzi":"红绿灯","pinyin":"hóng-lǜdēng","pos":"dt.","vn":"đèn giao thông","examples":[{"cn":"前面有个红绿灯,我们在那儿等一下。","pinyin":"qiánmiàn yǒu ge hóng-lǜdēng, wǒmen zài nàr děng yíxià.","vn":"Phía trước có đèn giao thông, chúng ta đợi ở đó một chút."},{"cn":"红灯停,绿灯行,这是基本的交通规则。","pinyin":"hóngdēng tíng, lǜdēng xíng, zhè shì jīběn de jiāotōng guīzé.","vn":"Đèn đỏ dừng, đèn xanh đi, đây là quy tắc giao thông cơ bản."},{"cn":"这个路口的红绿灯坏了好几天了。","pinyin":"zhège lùkǒu de hóng-lǜdēng huài le hǎo jǐ tiān le.","vn":"Đèn giao thông ở ngã tư này đã hỏng mấy ngày rồi."}]},{"hanzi":"后来","pinyin":"hòulái","pos":"dt.","vn":"sau đó","examples":[{"cn":"我们以前是同学,后来就没联系了。","pinyin":"wǒmen yǐqián shì tóngxué, hòulái jiù méi liánxì le.","vn":"Trước đây chúng tôi là bạn học, sau đó thì mất liên lạc."},{"cn":"他一开始不同意,后来被我说服了。","pinyin":"tā yì kāishǐ bù tóngyì, hòulái bèi wǒ shuōfú le.","vn":"Lúc đầu anh ấy không đồng ý, sau đó bị tôi thuyết phục."},{"cn":"后来发生了什么事?","pinyin":"hòulái fāshēng le shénme shì?","vn":"Sau đó đã xảy ra chuyện gì?"}]},{"hanzi":"急","pinyin":"jí","pos":"tt./dgt.","vn":"gấp, nóng vội, sốt ruột","examples":[{"cn":"别急,慢慢来。","pinyin":"bié jí, mànmàn lái.","vn":"Đừng vội, từ từ thôi."},{"cn":"他有急事,先走了。","pinyin":"tā yǒu jí shì, xiān zǒu le.","vn":"Anh ấy có việc gấp nên đi trước rồi."},{"cn":"你这么急着去哪儿?","pinyin":"nǐ zhème jí zhe qù nǎr?","vn":"Bạn vội vàng đi đâu vậy?"}]},{"hanzi":"如果","pinyin":"rúguǒ","pos":"liên.","vn":"nếu","examples":[{"cn":"如果明天下雨,我们就不去爬山了。","pinyin":"rúguǒ míngtiān xiàyǔ, wǒmen jiù bú qù páshān le.","vn":"Nếu mai trời mưa, chúng ta sẽ không đi leo núi nữa."},{"cn":"如果你不喜欢,可以换别的。","pinyin":"rúguǒ nǐ bù xǐhuan, kěyǐ huàn biéde.","vn":"Nếu bạn không thích, có thể đổi cái khác."},{"cn":"如果有问题,随时给我打电话。","pinyin":"rúguǒ yǒu wèntí, suíshí gěi wǒ dǎ diànhuà.","vn":"Nếu có vấn đề gì, cứ gọi điện cho tôi bất cứ lúc nào."}]},{"hanzi":"以前","pinyin":"yǐqián","pos":"dt.","vn":"trước đây","examples":[{"cn":"我以前住在上海。","pinyin":"wǒ yǐqián zhù zài Shànghǎi.","vn":"Trước đây tôi sống ở Thượng Hải."},{"cn":"他以前的工作比现在轻松。","pinyin":"tā yǐqián de gōngzuò bǐ xiànzài qīngsōng.","vn":"Công việc trước đây của anh ấy nhàn hơn bây giờ."},{"cn":"以前这儿还没有高铁站。","pinyin":"yǐqián zhèr hái méiyǒu gāotiězhàn.","vn":"Trước đây ở đây còn chưa có ga tàu cao tốc."}]},{"hanzi":"耳机","pinyin":"ěrjī","pos":"dt.","vn":"tai nghe","examples":[{"cn":"我喜欢戴耳机听音乐。","pinyin":"wǒ xǐhuan dài ěrjī tīng yīnyuè.","vn":"Tôi thích đeo tai nghe để nghe nhạc."},{"cn":"我的耳机找不到了。","pinyin":"wǒ de ěrjī zhǎo bu dào le.","vn":"Tai nghe của tôi tìm không thấy rồi."},{"cn":"在图书馆看视频要戴耳机。","pinyin":"zài túshūguǎn kàn shìpín yào dài ěrjī.","vn":"Xem video trong thư viện phải đeo tai nghe."}]},{"hanzi":"充电宝","pinyin":"chōngdiànbǎo","pos":"dt.","vn":"sạc dự phòng","examples":[{"cn":"出门旅行要带个充电宝。","pinyin":"chūmén lǚxíng yào dài ge chōngdiànbǎo.","vn":"Đi du lịch phải mang theo một cục sạc dự phòng."},{"cn":"我的充电宝没电了。","pinyin":"wǒ de chōngdiànbǎo méi diàn le.","vn":"Sạc dự phòng của tôi hết pin rồi."},{"cn":"你能借我一下你的充电宝吗?","pinyin":"nǐ néng jiè wǒ yíxià nǐ de chōngdiànbǎo ma?","vn":"Bạn có thể cho tôi mượn sạc dự phòng một chút không?"}]},{"hanzi":"常用","pinyin":"chángyòng","pos":"tt.","vn":"thường dùng","examples":[{"cn":"这是我们公司常用的软件。","pinyin":"zhè shì wǒmen gōngsī chángyòng de ruǎnjiàn.","vn":"Đây là phần mềm mà công ty chúng tôi thường dùng."},{"cn":"这些都是日常生活中的常用词。","pinyin":"zhèxiē dōu shì rìcháng shēnghuó zhōng de chángyòng cí.","vn":"Đây đều là những từ thường dùng trong cuộc sống hàng ngày."},{"cn":"微信是中国人常用的聊天工具。","pinyin":"Wēixìn shì Zhōngguórén chángyòng de liáotiān gōngjù.","vn":"Wechat là công cụ trò chuyện mà người Trung Quốc thường dùng."}]},{"hanzi":"越","pinyin":"yuè","pos":"phó.","vn":"càng","examples":[{"cn":"天气越来越冷了。","pinyin":"tiānqì yuè lái yuè lěng le.","vn":"Thời tiết ngày càng lạnh hơn."},{"cn":"你越努力,就会越成功。","pinyin":"nǐ yuè nǔlì, jiù huì yuè chénggōng.","vn":"Bạn càng nỗ lực thì càng thành công."},{"cn":"这本书越看越有意思。","pinyin":"zhè běn shū yuè kàn yuè yǒu yìsi.","vn":"Cuốn sách này càng đọc càng thấy thú vị."}]},{"hanzi":"分开","pinyin":"fēnkāi","pos":"dgt.","vn":"tách ra, chia tay","examples":[{"cn":"我们俩在火车站分开了。","pinyin":"wǒmen liǎ zài huǒchēzhàn fēnkāi le.","vn":"Hai chúng tôi đã chia tay nhau ở ga tàu."},{"cn":"把这两件事分开来看。","pinyin":"bǎ zhè liǎng jiàn shì fēnkāi lái kàn.","vn":"Hãy tách hai việc này ra mà nhìn nhận."},{"cn":"他们两个人分开好几年了。","pinyin":"tāmen liǎng ge rén fēnkāi hǎo jǐ nián le.","vn":"Hai người họ đã chia tay mấy năm rồi."}]},{"hanzi":"检查","pinyin":"jiǎnchá","pos":"dgt.","vn":"kiểm tra","examples":[{"cn":"你再检查一下这些句子有没有错。","pinyin":"nǐ zài jiǎnchá yíxià zhèxiē jùzi yǒu méiyǒu cuò.","vn":"Bạn kiểm tra lại xem những câu này có lỗi không."},{"cn":"出国前要检查一下护照和机票。","pinyin":"chūguó qián yào jiǎnchá yíxià hùzhào hé jīpiào.","vn":"Trước khi ra nước ngoài phải kiểm tra hộ chiếu và vé máy bay."},{"cn":"医生给我做了一次全面检查。","pinyin":"yīshēng gěi wǒ zuò le yí cì quánmiàn jiǎnchá.","vn":"Bác sĩ đã kiểm tra toàn diện cho tôi một lần."}]},{"hanzi":"刷","pinyin":"shuā","pos":"dgt.","vn":"quẹt (thẻ)","examples":[{"cn":"现在坐地铁都用手机刷一下就行了。","pinyin":"xiànzài zuò dìtiě dōu yòng shǒujī shuā yíxià jiù xíng le.","vn":"Bây giờ đi tàu điện ngầm chỉ cần quẹt điện thoại một cái là được."},{"cn":"我可以刷卡吗?","pinyin":"wǒ kěyǐ shuākǎ ma?","vn":"Tôi có thể quẹt thẻ không?"},{"cn":"每天晚上睡觉前记得刷牙。","pinyin":"měitiān wǎnshang shuìjiào qián jìde shuāyá.","vn":"Mỗi tối trước khi ngủ nhớ đánh răng."}]},{"hanzi":"检票","pinyin":"jiǎnpiào","pos":"dgt.","vn":"soát vé","examples":[{"cn":"请大家排队检票上车。","pinyin":"qǐng dàjiā páiduì jiǎnpiào shàngchē.","vn":"Mời mọi người xếp hàng soát vé lên xe."},{"cn":"检票口在二楼。","pinyin":"jiǎnpiào kǒu zài èr lóu.","vn":"Cửa soát vé ở tầng hai."},{"cn":"检票的时候别忘了拿出车票。","pinyin":"jiǎnpiào de shíhou bié wàngjì náchū chēpiào.","vn":"Khi soát vé đừng quên lấy vé tàu ra."}]},{"hanzi":"电梯","pinyin":"diàntī","pos":"dt.","vn":"thang máy, thang cuốn","examples":[{"cn":"这栋楼没有电梯,只能走楼梯。","pinyin":"zhè dòng lóu méiyǒu diàntī, zhǐ néng zǒu lóutī.","vn":"Tòa nhà này không có thang máy, chỉ có thể đi cầu thang bộ."},{"cn":"电梯坏了,我们得爬楼梯上去。","pinyin":"diàntī huài le, wǒmen děi pá lóutī shàngqù.","vn":"Thang máy hỏng rồi, chúng ta phải leo cầu thang lên."},{"cn":"商场里的电梯特别多人。","pinyin":"shāngchǎng lǐ de diàntī tèbié duō rén.","vn":"Thang cuốn trong trung tâm thương mại rất đông người."}]},{"hanzi":"放假","pinyin":"fàngjià","pos":"dgt.","vn":"nghỉ (lễ, học)","examples":[{"cn":"我们学校下周放假。","pinyin":"wǒmen xuéxiào xià zhōu fàngjià.","vn":"Trường chúng tôi tuần sau nghỉ học."},{"cn":"放假了,我打算在家好好休息。","pinyin":"fàngjià le, wǒ dǎsuàn zài jiā hǎohāo xiūxi.","vn":"Nghỉ rồi, tôi định ở nhà nghỉ ngơi thật tốt."},{"cn":"你们公司什么时候放假?","pinyin":"nǐmen gōngsī shénme shíhou fàngjià?","vn":"Công ty các bạn khi nào nghỉ lễ?"}]},{"hanzi":"沙发","pinyin":"shāfā","pos":"dt.","vn":"ghế sofa","examples":[{"cn":"他躺在沙发上看电视。","pinyin":"tā tǎng zài shāfā shàng kàn diànshì.","vn":"Anh ấy nằm trên ghế sofa xem tivi."},{"cn":"这张沙发坐着很舒服。","pinyin":"zhè zhāng shāfā zuò zhe hěn shūfu.","vn":"Chiếc ghế sofa này ngồi rất thoải mái."},{"cn":"我们家的沙发是新买的。","pinyin":"wǒmen jiā de shāfā shì xīn mǎi de.","vn":"Ghế sofa nhà tôi mới mua."}]},{"hanzi":"安静","pinyin":"ānjìng","pos":"tt.","vn":"yên tĩnh","examples":[{"cn":"图书馆里很安静。","pinyin":"túshūguǎn lǐ hěn ānjìng.","vn":"Trong thư viện rất yên tĩnh."},{"cn":"请大家安静一下,我有话要说。","pinyin":"qǐng dàjiā ānjìng yíxià, wǒ yǒu huà yào shuō.","vn":"Mời mọi người yên lặng một chút, tôi có điều muốn nói."},{"cn":"我喜欢在安静的环境里学习。","pinyin":"wǒ xǐhuan zài ānjìng de huánjìng lǐ xuéxí.","vn":"Tôi thích học tập trong môi trường yên tĩnh."}]},{"hanzi":"选择","pinyin":"xuǎnzé","pos":"dgt.","vn":"lựa chọn","examples":[{"cn":"你有很多选择,慢慢想吧。","pinyin":"nǐ yǒu hěn duō xuǎnzé, mànmàn xiǎng ba.","vn":"Bạn có nhiều lựa chọn, từ từ suy nghĩ đi."},{"cn":"我选择了一份比较轻松的工作。","pinyin":"wǒ xuǎnzé le yí fèn bǐjiào qīngsōng de gōngzuò.","vn":"Tôi đã chọn một công việc tương đối nhàn."},{"cn":"在这两个之间,我真的不知道怎么选择。","pinyin":"zài zhè liǎng ge zhījiān, wǒ zhēnde bù zhīdào zěnme xuǎnzé.","vn":"Giữa hai cái này, tôi thực sự không biết chọn thế nào."}]},{"hanzi":"必须","pinyin":"bìxū","pos":"phó.","vn":"phải, bắt buộc","examples":[{"cn":"这件事你必须认真对待。","pinyin":"zhè jiàn shì nǐ bìxū rènzhēn duìdài.","vn":"Việc này bạn phải đối xử nghiêm túc."},{"cn":"上车前必须检票。","pinyin":"shàngchē qián bìxū jiǎnpiào.","vn":"Trước khi lên xe phải soát vé."},{"cn":"明天必须交作业,别忘了。","pinyin":"míngtiān bìxū jiāo zuòyè, bié wàng le.","vn":"Mai phải nộp bài tập, đừng quên đấy."}]},{"hanzi":"北京南站","pinyin":"Běijīng Nán Zhàn","pos":"danh từ riêng","vn":"Ga Nam Bắc Kinh","examples":[{"cn":"我们在北京南站下车。","pinyin":"wǒmen zài Běijīng Nán Zhàn xiàchē.","vn":"Chúng tôi xuống xe ở Ga Nam Bắc Kinh."},{"cn":"从北京南站坐高铁到上海很方便。","pinyin":"cóng Běijīng Nán Zhàn zuò gāotiě dào Shànghǎi hěn fāngbiàn.","vn":"Từ Ga Nam Bắc Kinh đi tàu cao tốc đến Thượng Hải rất tiện lợi."},{"cn":"北京南站人特别多,检票要排很长的队。","pinyin":"Běijīng Nán Zhàn rén tèbié duō, jiǎnpiào yào pái hěn cháng de duì.","vn":"Ga Nam Bắc Kinh rất đông người, soát vé phải xếp hàng rất dài."}]}],"grammar":[{"title":"固定格式\"该……了\" - Cụm cố định \"该……了\"","explanation_vn":"Cụm cố định \"该……了\" biểu thị đã đến lúc cần phải làm việc gì đó, thường dùng trong khẩu ngữ.","examples":[{"cn":"咱们该买去上海的票了。","pinyin":"Zánmen gāi mǎi qù Shànghǎi de piào le.","vn":""},{"cn":"八点了，该上课了。","pinyin":"Bā diǎn le, gāi shàngkè le.","vn":""},{"cn":"已经很晚了，我该睡觉了。","pinyin":"Yǐjīng hěn wǎn le, wǒ gāi shuìjiào le.","vn":""}]},{"title":"假设复句\"如果……，就……\" - Câu phức giả thiết \"如果……，就……\"","explanation_vn":"Trong câu phức giả thiết \"如果……，就……\", mệnh đề theo sau \"如果\" là một giả thiết, mệnh đề theo sau \"就\" là kết quả xảy ra trong tình huống giả thiết đó. Lưu ý, chủ ngữ của mệnh đề thứ hai đặt trước \"就\".","examples":[{"cn":"如果没走错，二十分钟以前就到了。","pinyin":"Rúguǒ méi zǒucuò, èrshí fēnzhōng yǐqián jiù dào le.","vn":""},{"cn":"如果你需要帮忙，就给我打电话。","pinyin":"Rúguǒ nǐ xūyào bāngmáng, jiù gěi wǒ dǎ diànhuà.","vn":""},{"cn":"如果有时间，我就去上海玩几天。","pinyin":"Rúguǒ yǒu shíjiān, wǒ jiù qù Shànghǎi wán jǐ tiān.","vn":""}]},{"title":"固定短语\"越来越\" - Cụm cố định \"越来越\"","explanation_vn":"Cụm cố định \"越来越\" phía sau theo sau một tính từ hoặc động từ tâm lý, biểu thị theo thời gian trôi qua, mức độ có sự biến đổi. Trước tính từ hoặc động từ tâm lý không được thêm phó từ chỉ mức độ.","examples":[{"cn":"前面的人越来越多。","pinyin":"Qiánmiàn de rén yuè lái yuè duō.","vn":""},{"cn":"我越来越喜欢这里的生活了。","pinyin":"Wǒ yuè lái yuè xǐhuan zhèlǐ de shēnghuó le.","vn":""},{"cn":"她越来越高，也越来越漂亮了。","pinyin":"Tā yuè lái yuè gāo, yě yuè lái yuè piàoliang le.","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"李文","cn":"家月，咱们该买去上海的票了。你打算怎么去上海？","pinyin":"Jiāyuè, zánmen gāi mǎi qù Shànghǎi de piào le. Nǐ dǎsuàn zěnme qù Shànghǎi?"},{"speaker":"白家月","cn":"我还没坐过高铁，咱们坐高铁去，怎么样？","pinyin":"Wǒ hái méi zuòguò gāotiě, zánmen zuò gāotiě qù, zěnmeyàng?"},{"speaker":"李文","cn":"没问题，从北京到上海的高铁很多，非常方便。","pinyin":"Méi wèntí, cóng Běijīng dào Shànghǎi de gāotiě hěn duō, fēicháng fāngbiàn."},{"speaker":"白家月","cn":"行！怎么买高铁票？","pinyin":"Xíng! Zěnme mǎi gāotiě piào?"},{"speaker":"李文","cn":"用手机App就能买。给我你的护照，我帮你买。","pinyin":"Yòng shǒujī App jiù néng mǎi. Gěi wǒ nǐ de hùzhào, wǒ bāng nǐ mǎi."},{"speaker":"白家月","cn":"早就听说过高铁，终于可以坐上了。","pinyin":"Zǎo jiù tīngshuōguò gāotiě, zhōngyú kěyǐ zuòshàng le."},{"speaker":"李文","cn":"高铁又快又舒服，你一定会喜欢的。","pinyin":"Gāotiě yòu kuài yòu shūfu, nǐ yídìng huì xǐhuan de."}],"translation_vn":"Lý Văn: Gia Nguyệt à, chúng ta nên mua vé đi Thượng Hải rồi. Cậu định đi Thượng Hải bằng cách nào?\nBạch Gia Nguyệt: Mình chưa đi tàu cao tốc bao giờ, chúng ta đi tàu cao tốc nhé?\nLý Văn: Không vấn đề gì, tàu cao tốc từ Bắc Kinh đến Thượng Hải rất nhiều, rất tiện lợi.\nBạch Gia Nguyệt: Được! Mua vé tàu cao tốc thế nào?\nLý Văn: Dùng App trên điện thoại là mua được. Đưa hộ chiếu cho mình, mình mua giúp cho.\nBạch Gia Nguyệt: Sớm đã nghe nói về tàu cao tốc rồi, cuối cùng cũng được đi rồi.\nLý Văn: Tàu cao tốc vừa nhanh vừa thoải mái, cậu chắc chắn sẽ thích đấy.","audio_dialogue":"6-1.mp3","audio_vocab":"6-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"刘明","cn":"过了前面的路口就到高铁站了。","pinyin":"Guò le qiánmiàn de lùkǒu jiù dào gāotiězhàn le."},{"speaker":"白家月","cn":"我看见了。马上就到了，这条路车很多，您小心点儿。","pinyin":"Wǒ kànjiàn le. Mǎshàng jiù dào le, zhè tiáo lù chē hěn duō, nín xiǎoxīn diǎnr."},{"speaker":"刘明","cn":"好，你们还有一个小时，应该不会迟到的。","pinyin":"Hǎo, nǐmen hái yǒu yí ge xiǎoshí, yīnggāi bú huì chídào de."},{"speaker":"白家月","cn":"我发现这条路车多，红绿灯也多。","pinyin":"Wǒ fāxiàn zhè tiáo lù chē duō, hóng-lǜdēng yě duō."},{"speaker":"刘明","cn":"是啊，这条路我走过一次，后来再也不走了。","pinyin":"Shì a, zhè tiáo lù wǒ zǒuguò yí cì, hòulái zài yě bù zǒu le."},{"speaker":"白家月","cn":"那您今天为什么走了这条路？","pinyin":"Nà nín jīntiān wèishénme zǒu le zhè tiáo lù?"},{"speaker":"刘明","cn":"我一急就走错了。如果没走错，二十分钟以前就到了。","pinyin":"Wǒ yì jí jiù zǒucuò le. Rúguǒ méi zǒucuò, èrshí fēnzhōng yǐqián jiù dào le."}],"translation_vn":"Lưu Minh: Qua ngã tư phía trước là đến ga tàu cao tốc rồi.\nBạch Gia Nguyệt: Em thấy rồi. Sắp đến nơi rồi, con đường này nhiều xe lắm, anh cẩn thận chút nhé.\nLưu Minh: Được, các em vẫn còn một tiếng nữa, chắc sẽ không muộn đâu.\nBạch Gia Nguyệt: Em thấy con đường này xe nhiều, đèn giao thông cũng nhiều.\nLưu Minh: Đúng vậy, con đường này anh từng đi một lần, sau đó không bao giờ đi nữa.\nBạch Gia Nguyệt: Vậy sao hôm nay anh lại đi đường này?\nLưu Minh: Anh vội quá nên đi nhầm đường. Nếu không đi nhầm thì hai mươi phút trước đã đến rồi.","audio_dialogue":"6-3.mp3","audio_vocab":"6-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"白家月","cn":"李文，我的耳机没电了，你有充电宝吗？","pinyin":"Lǐ Wén, wǒ de ěrjī méi diàn le, nǐ yǒu chōngdiànbǎo ma?"},{"speaker":"李文","cn":"有，这些常用的东西我都放在包里了，我给你拿。","pinyin":"Yǒu, zhèxiē chángyòng de dōngxi wǒ dōu fàng zài bāo lǐ le, wǒ gěi nǐ ná."},{"speaker":"白家月","cn":"前面的人越来越多。","pinyin":"Qiánmiàn de rén yuè lái yuè duō."},{"speaker":"李文","cn":"对，马上就进高铁站了。咱们一起走，别分开。","pinyin":"Duì, mǎshàng jiù jìn gāotiězhàn le. Zánmen yìqǐ zǒu, bié fēnkāi."},{"speaker":"白家月","cn":"好，你检查一下，高铁票都拿好了吗？","pinyin":"Hǎo, nǐ jiǎnchá yíxià, gāotiě piào dōu ná hǎo le ma?"},{"speaker":"李文","cn":"不用拿票，刷护照就能检票进站。","pinyin":"Búyòng ná piào, shuā hùzhào jiù néng jiǎnpiào jìn zhàn."},{"speaker":"白家月","cn":"去哪里检票？","pinyin":"Qù nǎlǐ jiǎnpiào?"},{"speaker":"李文","cn":"检票口在二层，我们一会儿坐电梯上去。","pinyin":"Jiǎnpiàokǒu zài èr céng, wǒmen yíhuìr zuò diàntī shàngqù."}],"translation_vn":"Bạch Gia Nguyệt: Lý Văn ơi, tai nghe của mình hết pin rồi, cậu có sạc dự phòng không?\nLý Văn: Có, mấy món đồ hay dùng này mình đều để trong túi rồi, để mình lấy cho cậu.\nBạch Gia Nguyệt: Người phía trước ngày càng đông.\nLý Văn: Đúng vậy, sắp vào ga cao tốc rồi. Chúng ta đi cùng nhau, đừng tách ra.\nBạch Gia Nguyệt: Được, cậu kiểm tra xem, vé tàu cao tốc đã cầm sẵn chưa?\nLý Văn: Không cần cầm vé, quẹt hộ chiếu là soát vé vào ga được rồi.\nBạch Gia Nguyệt: Soát vé ở đâu vậy?\nLý Văn: Cửa soát vé ở tầng hai, lát nữa chúng ta đi thang máy lên.","audio_dialogue":"6-5.mp3","audio_vocab":"6-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"这次放假，我去了北京，还去了上海。我是从北京南站坐高铁去的上海。我觉得坐在高铁上跟坐在家里的沙发上一样，又安静又舒服。坐累了就站一会儿，饿了就点外卖。对，你没听错，高铁上可以点外卖，只需要选择好车站和想吃的东西，到站时不用下车，服务员就会给你拿过来。现在喜欢坐高铁的人越来越多。我爸妈来中国旅游的时候，必须带他们也坐一次高铁。","pinyin":"Zhè cì fàngjià, wǒ qù le Běijīng, hái qù le Shànghǎi. Wǒ shì cóng Běijīng Nán Zhàn zuò gāotiě qù de Shànghǎi. Wǒ juéde zuò zài gāotiě shàng gēn zuò zài jiā lǐ de shāfā shàng yíyàng, yòu ānjìng yòu shūfu. Zuòlèi le jiù zhàn yíhuìr, è le jiù diǎn wàimài. Duì, nǐ méi tīngcuò, gāotiě shàng kěyǐ diǎn wàimài, zhǐ xūyào xuǎnzé hǎo chēzhàn hé xiǎng chī de dōngxi, dào zhàn shí búyòng xià chē, fúwùyuán jiù huì gěi nǐ ná guòlái. Xiànzài xǐhuan zuò gāotiě de rén yuè lái yuè duō. Wǒ bà mā lái Zhōngguó lǚyóu de shíhou, bìxū dài tāmen yě zuò yí cì gāotiě."}],"translation_vn":"Kỳ nghỉ lần này, mình đã đi Bắc Kinh, rồi còn đi Thượng Hải nữa. Mình đi tàu cao tốc từ Ga Nam Bắc Kinh đến Thượng Hải. Mình thấy ngồi trên tàu cao tốc cũng giống như ngồi trên ghế sofa ở nhà vậy, vừa yên tĩnh vừa thoải mái. Ngồi mỏi thì đứng dậy một lát, đói thì gọi đồ ăn mang tới. Đúng vậy, bạn không nghe nhầm đâu, trên tàu cao tốc có thể đặt đồ ăn, chỉ cần chọn đúng ga và món muốn ăn, đến ga không cần xuống tàu, nhân viên sẽ mang đến tận nơi cho bạn. Hiện nay người thích đi tàu cao tốc ngày càng nhiều. Khi bố mẹ mình sang Trung Quốc du lịch, nhất định phải cho họ đi tàu cao tốc một lần.","audio_dialogue":"6-7.mp3","audio_vocab":"6-8.mp3"}]},{"id":7,"title_cn":"那条裙子比短裤更好看","title_pinyin":"Nà tiáo qúnzi bǐ duǎnkù gèng hǎokàn","title_vn":"Chiếc váy đó đẹp hơn cái quần short","goals":["Có thể nghe hiểu và giới thiệu về trải nghiệm mua sắm.","Có thể nghe hiểu và đánh giá đặc điểm của sản phẩm.","Nắm vững cách dùng câu so sánh (10), có thể so sánh các sản phẩm.","Hiểu được phương thức mua sắm của người Trung Quốc."],"vocab":[{"hanzi":"辆","pinyin":"liàng","pos":"lượng.","vn":"lượng từ dùng cho xe cộ","examples":[{"cn":"我家有两辆自行车。","pinyin":"Wǒ jiā yǒu liǎng liàng zìxíngchē.","vn":"Nhà tôi có hai chiếc xe đạp."},{"cn":"路上停着一辆红色的车。","pinyin":"Lùshang tíngzhe yí liàng hóngsè de chē.","vn":"Trên đường đỗ một chiếc xe màu đỏ."},{"cn":"这辆车太旧了,我想换一辆新的。","pinyin":"Zhè liàng chē tài jiù le, wǒ xiǎng huàn yí liàng xīn de.","vn":"Chiếc xe này cũ quá rồi, tôi muốn đổi một chiếc mới."}]},{"hanzi":"自行车","pinyin":"zìxíngchē","pos":"dt.","vn":"xe đạp","examples":[{"cn":"我每天骑自行车上班。","pinyin":"Wǒ měitiān qí zìxíngchē shàngbān.","vn":"Tôi đi làm bằng xe đạp mỗi ngày."},{"cn":"他的自行车坏了,正在修。","pinyin":"Tā de zìxíngchē huài le, zhèngzài xiū.","vn":"Xe đạp của anh ấy bị hỏng, đang sửa."},{"cn":"周末我们一起骑自行车去公园吧。","pinyin":"Zhōumò wǒmen yìqǐ qí zìxíngchē qù gōngyuán ba.","vn":"Cuối tuần chúng ta cùng đi xe đạp đến công viên nhé."}]},{"hanzi":"旧","pinyin":"jiù","pos":"tt.","vn":"cũ","examples":[{"cn":"这双鞋太旧了,该扔了。","pinyin":"Zhè shuāng xié tài jiù le, gāi rēng le.","vn":"Đôi giày này cũ quá rồi, nên vứt đi."},{"cn":"我还穿着以前的旧衣服。","pinyin":"Wǒ hái chuānzhe yǐqián de jiù yīfu.","vn":"Tôi vẫn mặc quần áo cũ từ trước."},{"cn":"这是一本很旧的书,但内容很好。","pinyin":"Zhè shì yì běn hěn jiù de shū, dàn nèiróng hěn hǎo.","vn":"Đây là một quyển sách rất cũ, nhưng nội dung rất hay."}]},{"hanzi":"矮","pinyin":"ǎi","pos":"tt.","vn":"thấp (chiều cao)","examples":[{"cn":"他个子比较矮。","pinyin":"Tā gèzi bǐjiào ǎi.","vn":"Anh ấy có vóc dáng khá thấp."},{"cn":"这张桌子太矮了,不适合我。","pinyin":"Zhè zhāng zhuōzi tài ǎi le, bú shìhé wǒ.","vn":"Cái bàn này quá thấp, không hợp với tôi."},{"cn":"弟弟比哥哥矮一点儿。","pinyin":"Dìdi bǐ gēge ǎi yìdiǎnr.","vn":"Em trai thấp hơn anh trai một chút."}]},{"hanzi":"试","pinyin":"shì","pos":"dgt.","vn":"thử","examples":[{"cn":"你可以先试一下这件衣服。","pinyin":"Nǐ kěyǐ xiān shì yíxià zhè jiàn yīfu.","vn":"Bạn có thể thử cái áo này trước."},{"cn":"我想试试这个新方法。","pinyin":"Wǒ xiǎng shìshi zhège xīn fāngfǎ.","vn":"Tôi muốn thử phương pháp mới này."},{"cn":"这道菜你尝试一下,很好吃。","pinyin":"Zhè dào cài nǐ chángshì yíxià, hěn hǎochī.","vn":"Món này bạn thử xem, rất ngon."}]},{"hanzi":"黄色","pinyin":"huángsè","pos":"dt.","vn":"màu vàng","examples":[{"cn":"她喜欢穿黄色的衣服。","pinyin":"Tā xǐhuan chuān huángsè de yīfu.","vn":"Cô ấy thích mặc quần áo màu vàng."},{"cn":"这朵花是黄色的。","pinyin":"Zhè duǒ huā shì huángsè de.","vn":"Bông hoa này màu vàng."},{"cn":"我想买一件黄色的衬衫。","pinyin":"Wǒ xiǎng mǎi yí jiàn huángsè de chènshān.","vn":"Tôi muốn mua một chiếc áo sơ mi màu vàng."}]},{"hanzi":"短裤","pinyin":"duǎnkù","pos":"dt.","vn":"quần short","examples":[{"cn":"夏天我常常穿短裤。","pinyin":"Xiàtiān wǒ chángcháng chuān duǎnkù.","vn":"Mùa hè tôi thường mặc quần short."},{"cn":"这条短裤是新买的。","pinyin":"Zhè tiáo duǎnkù shì xīn mǎi de.","vn":"Chiếc quần short này mới mua."},{"cn":"打球的时候穿短裤比较方便。","pinyin":"Dǎqiú de shíhou chuān duǎnkù bǐjiào fāngbiàn.","vn":"Khi chơi bóng mặc quần short tiện hơn."}]},{"hanzi":"大小","pinyin":"dàxiǎo","pos":"dt.","vn":"kích cỡ, kích thước","examples":[{"cn":"这件衣服的大小正合适。","pinyin":"Zhè jiàn yīfu de dàxiǎo zhèng héshì.","vn":"Kích cỡ của chiếc áo này vừa vặn."},{"cn":"你穿多大的鞋,我帮你看看大小。","pinyin":"Nǐ chuān duō dà de xié, wǒ bāng nǐ kànkan dàxiǎo.","vn":"Bạn đi giày cỡ bao nhiêu, tôi giúp bạn xem kích cỡ."},{"cn":"这两件衣服大小一样。","pinyin":"Zhè liǎng jiàn yīfu dàxiǎo yíyàng.","vn":"Hai chiếc áo này kích cỡ giống nhau."}]},{"hanzi":"合适","pinyin":"héshì","pos":"tt.","vn":"phù hợp, vừa vặn","examples":[{"cn":"这双鞋穿着很合适。","pinyin":"Zhè shuāng xié chuānzhe hěn héshì.","vn":"Đôi giày này mang rất vừa."},{"cn":"现在不是说话的合适时间。","pinyin":"Xiànzài bú shì shuōhuà de héshì shíjiān.","vn":"Bây giờ không phải là thời điểm thích hợp để nói chuyện."},{"cn":"我觉得这个颜色很合适你。","pinyin":"Wǒ juéde zhège yánsè hěn héshì nǐ.","vn":"Tôi thấy màu này rất hợp với bạn."}]},{"hanzi":"裙子","pinyin":"qúnzi","pos":"dt.","vn":"váy","examples":[{"cn":"她今天穿了一条红裙子。","pinyin":"Tā jīntiān chuānle yì tiáo hóng qúnzi.","vn":"Hôm nay cô ấy mặc một chiếc váy đỏ."},{"cn":"这条裙子有点儿长。","pinyin":"Zhè tiáo qúnzi yǒudiǎnr cháng.","vn":"Chiếc váy này hơi dài."},{"cn":"我想买一条新裙子参加聚会。","pinyin":"Wǒ xiǎng mǎi yì tiáo xīn qúnzi cānjiā jùhuì.","vn":"Tôi muốn mua một chiếc váy mới để đi dự tiệc."}]},{"hanzi":"更","pinyin":"gèng","pos":"phó.","vn":"hơn, càng","examples":[{"cn":"今天比昨天更冷。","pinyin":"Jīntiān bǐ zuótiān gèng lěng.","vn":"Hôm nay lạnh hơn hôm qua."},{"cn":"他比我更喜欢运动。","pinyin":"Tā bǐ wǒ gèng xǐhuan yùndòng.","vn":"Anh ấy thích thể thao hơn tôi."},{"cn":"这样做会更好。","pinyin":"Zhèyàng zuò huì gèng hǎo.","vn":"Làm thế này sẽ tốt hơn."}]},{"hanzi":"决定","pinyin":"juédìng","pos":"dgt.","vn":"quyết định","examples":[{"cn":"我决定明天去旅游。","pinyin":"Wǒ juédìng míngtiān qù lǚyóu.","vn":"Tôi quyết định ngày mai đi du lịch."},{"cn":"这件事我还没决定好。","pinyin":"Zhè jiàn shì wǒ hái méi juédìng hǎo.","vn":"Việc này tôi vẫn chưa quyết định xong."},{"cn":"他最后决定不去了。","pinyin":"Tā zuìhòu juédìng bú qù le.","vn":"Cuối cùng anh ấy quyết định không đi nữa."}]},{"hanzi":"西瓜","pinyin":"xīguā","pos":"dt.","vn":"dưa hấu","examples":[{"cn":"夏天吃西瓜特别解渴。","pinyin":"Xiàtiān chī xīguā tèbié jiěkě.","vn":"Mùa hè ăn dưa hấu rất đã khát."},{"cn":"这个西瓜又大又甜。","pinyin":"Zhège xīguā yòu dà yòu tián.","vn":"Quả dưa hấu này vừa to vừa ngọt."},{"cn":"妈妈切了一盘西瓜给我们吃。","pinyin":"Māma qiēle yì pán xīguā gěi wǒmen chī.","vn":"Mẹ cắt một đĩa dưa hấu cho chúng tôi ăn."}]},{"hanzi":"新鲜","pinyin":"xīnxiān","pos":"tt.","vn":"tươi","examples":[{"cn":"这些蔬菜很新鲜。","pinyin":"Zhèxiē shūcài hěn xīnxiān.","vn":"Những loại rau này rất tươi."},{"cn":"早上的空气很新鲜。","pinyin":"Zǎoshang de kōngqì hěn xīnxiān.","vn":"Không khí buổi sáng rất trong lành."},{"cn":"超市的水果都很新鲜。","pinyin":"Chāoshì de shuǐguǒ dōu hěn xīnxiān.","vn":"Trái cây ở siêu thị đều rất tươi."}]},{"hanzi":"甜","pinyin":"tián","pos":"tt.","vn":"ngọt","examples":[{"cn":"这个西瓜很甜。","pinyin":"Zhège xīguā hěn tián.","vn":"Quả dưa hấu này rất ngọt."},{"cn":"我不喜欢吃太甜的东西。","pinyin":"Wǒ bù xǐhuan chī tài tián de dōngxi.","vn":"Tôi không thích ăn đồ quá ngọt."},{"cn":"这杯茶放了糖,有点儿甜。","pinyin":"Zhè bēi chá fàngle táng, yǒudiǎnr tián.","vn":"Cốc trà này cho đường, hơi ngọt."}]},{"hanzi":"公斤","pinyin":"gōngjīn","pos":"lượng.","vn":"kilôgam","examples":[{"cn":"我买了两公斤苹果。","pinyin":"Wǒ mǎile liǎng gōngjīn píngguǒ.","vn":"Tôi mua hai kilôgam táo."},{"cn":"这个箱子有十公斤重。","pinyin":"Zhège xiāngzi yǒu shí gōngjīn zhòng.","vn":"Cái thùng này nặng mười kilôgam."},{"cn":"我最近瘦了两公斤。","pinyin":"Wǒ zuìjìn shòule liǎng gōngjīn.","vn":"Dạo này tôi giảm hai cân."}]},{"hanzi":"冰","pinyin":"bīng","pos":"dgt.","vn":"ướp lạnh; nước đá","examples":[{"cn":"天气太热了,把西瓜冰一下吧。","pinyin":"Tiānqì tài rè le, bǎ xīguā bīng yíxià ba.","vn":"Trời nóng quá, ướp lạnh dưa hấu một chút đi."},{"cn":"我喜欢喝冰水。","pinyin":"Wǒ xǐhuan hē bīngshuǐ.","vn":"Tôi thích uống nước đá."},{"cn":"冰箱里的饮料都冰好了。","pinyin":"Bīngxiāng lǐ de yǐnliào dōu bīng hǎo le.","vn":"Đồ uống trong tủ lạnh đều đã ướp lạnh xong."}]},{"hanzi":"极","pinyin":"jí","pos":"phó.","vn":"cực kỳ","examples":[{"cn":"这个西瓜甜极了。","pinyin":"Zhège xīguā tián jíle.","vn":"Quả dưa hấu này ngọt cực kỳ."},{"cn":"今天天气好极了。","pinyin":"Jīntiān tiānqì hǎo jíle.","vn":"Hôm nay thời tiết đẹp cực kỳ."},{"cn":"听到这个消息我高兴极了。","pinyin":"Tīngdào zhège xiāoxi wǒ gāoxìng jíle.","vn":"Nghe tin này tôi vui cực kỳ."}]},{"hanzi":"斤","pinyin":"jīn","pos":"lượng.","vn":"cân (đơn vị đo lường của Trung Quốc, bằng 0,5kg)","examples":[{"cn":"老板,给我来两斤香蕉。","pinyin":"Lǎobǎn, gěi wǒ lái liǎng jīn xiāngjiāo.","vn":"Ông chủ ơi, cho tôi hai cân chuối."},{"cn":"这个西瓜有五斤重。","pinyin":"Zhège xīguā yǒu wǔ jīn zhòng.","vn":"Quả dưa hấu này nặng năm cân."},{"cn":"一斤大概等于半公斤。","pinyin":"Yì jīn dàgài děngyú bàn gōngjīn.","vn":"Một cân nói chung bằng nửa kilôgam."}]},{"hanzi":"香蕉","pinyin":"xiāngjiāo","pos":"dt.","vn":"chuối","examples":[{"cn":"我每天早上吃一根香蕉。","pinyin":"Wǒ měitiān zǎoshang chī yì gēn xiāngjiāo.","vn":"Mỗi sáng tôi ăn một quả chuối."},{"cn":"这些香蕉还没熟。","pinyin":"Zhèxiē xiāngjiāo hái méi shú.","vn":"Những quả chuối này còn chưa chín."},{"cn":"小猴子最爱吃香蕉。","pinyin":"Xiǎo hóuzi zuì ài chī xiāngjiāo.","vn":"Chú khỉ con thích ăn chuối nhất."}]},{"hanzi":"一共","pinyin":"yígòng","pos":"phó.","vn":"tổng cộng","examples":[{"cn":"这些东西一共多少钱?","pinyin":"Zhèxiē dōngxi yígòng duōshao qián?","vn":"Những thứ này tổng cộng bao nhiêu tiền?"},{"cn":"我们班一共有三十个学生。","pinyin":"Wǒmen bān yígòng yǒu sānshí ge xuésheng.","vn":"Lớp chúng tôi tổng cộng có ba mươi học sinh."},{"cn":"一共三个人去旅游。","pinyin":"Yígòng sān ge rén qù lǚyóu.","vn":"Tổng cộng ba người đi du lịch."}]},{"hanzi":"毛","pinyin":"máo","pos":"lượng.","vn":"hào (đơn vị tiền tệ)","examples":[{"cn":"这个苹果五块二毛钱。","pinyin":"Zhège píngguǒ wǔ kuài èr máo qián.","vn":"Quả táo này giá năm đồng hai hào."},{"cn":"找你三毛钱。","pinyin":"Zhǎo nǐ sān máo qián.","vn":"Trả lại bạn ba hào."},{"cn":"一块钱等于十毛钱。","pinyin":"Yí kuài qián děngyú shí máo qián.","vn":"Một đồng bằng mười hào."}]},{"hanzi":"结婚","pinyin":"jiéhūn","pos":"dgt.","vn":"kết hôn","examples":[{"cn":"他们明年打算结婚。","pinyin":"Tāmen míngnián dǎsuàn jiéhūn.","vn":"Họ dự định sang năm kết hôn."},{"cn":"我姐姐已经结婚了。","pinyin":"Wǒ jiějie yǐjīng jiéhūn le.","vn":"Chị gái tôi đã kết hôn rồi."},{"cn":"你打算什么时候结婚?","pinyin":"Nǐ dǎsuàn shénme shíhou jiéhūn?","vn":"Bạn dự định khi nào thì kết hôn?"}]},{"hanzi":"不但","pinyin":"búdàn","pos":"liên.","vn":"không những","examples":[{"cn":"她不但漂亮,而且很聪明。","pinyin":"Tā búdàn piàoliang, érqiě hěn cōngming.","vn":"Cô ấy không những xinh đẹp mà còn rất thông minh."},{"cn":"这家餐厅不但好吃,而且便宜。","pinyin":"Zhè jiā cāntīng búdàn hǎochī, érqiě piányi.","vn":"Nhà hàng này không những ngon mà còn rẻ."},{"cn":"他不但会说中文,而且会说英文。","pinyin":"Tā búdàn huì shuō Zhōngwén, érqiě huì shuō Yīngwén.","vn":"Anh ấy không những biết nói tiếng Trung mà còn biết nói tiếng Anh."}]},{"hanzi":"而且","pinyin":"érqiě","pos":"liên.","vn":"mà còn","examples":[{"cn":"这道菜很好吃,而且不贵。","pinyin":"Zhè dào cài hěn hǎochī, érqiě bú guì.","vn":"Món này rất ngon mà còn không đắt."},{"cn":"他很努力,而且很有耐心。","pinyin":"Tā hěn nǔlì, érqiě hěn yǒu nàixīn.","vn":"Anh ấy rất chăm chỉ mà còn rất kiên nhẫn."},{"cn":"今天不但下雨,而且刮风。","pinyin":"Jīntiān búdàn xiàyǔ, érqiě guāfēng.","vn":"Hôm nay không những mưa mà còn có gió."}]},{"hanzi":"声","pinyin":"shēng","pos":"lượng.","vn":"tiếng (đơn vị chỉ âm thanh)","examples":[{"cn":"外面传来一声狗叫。","pinyin":"Wàimiàn chuánlái yì shēng gǒu jiào.","vn":"Bên ngoài vọng vào một tiếng chó sủa."},{"cn":"他大叫一声就跑出去了。","pinyin":"Tā dà jiào yì shēng jiù pǎo chūqù le.","vn":"Anh ấy hét to một tiếng rồi chạy ra ngoài."},{"cn":"请大点儿声说话。","pinyin":"Qǐng dà diǎnr shēng shuōhuà.","vn":"Xin hãy nói to tiếng hơn một chút."}]},{"hanzi":"开机","pinyin":"kāijī","pos":"dgt.","vn":"khởi động, bật máy","examples":[{"cn":"请先开机再输入密码。","pinyin":"Qǐng xiān kāijī zài shūrù mìmǎ.","vn":"Hãy khởi động máy trước rồi mới nhập mật khẩu."},{"cn":"我的手机开机需要一分钟。","pinyin":"Wǒ de shǒujī kāijī xūyào yì fēnzhōng.","vn":"Điện thoại của tôi khởi động cần một phút."},{"cn":"电脑开机后速度有点儿慢。","pinyin":"Diànnǎo kāijī hòu sùdù yǒudiǎnr màn.","vn":"Sau khi máy tính khởi động tốc độ hơi chậm."}]}],"grammar":[{"title":"连动句（2）- Câu liên động (2)","explanation_vn":"Trợ từ động thái \"着\" dùng sau động từ thứ nhất trong câu liên động, biểu thị trạng thái hoặc cách thức khi thực hiện động tác thứ hai. Cấu trúc cơ bản: Động từ 1 + 着 + (Tân ngữ 1) + Động từ 2 + (Tân ngữ 2).","examples":[{"cn":"咱们可以走着去。","pinyin":"Zánmen kěyǐ zǒuzhe qù.","vn":""},{"cn":"弟弟吃着苹果写作业。","pinyin":"Dìdi chīzhe píngguǒ xiě zuòyè.","vn":""},{"cn":"他们坐着看电视。","pinyin":"Tāmen zuòzhe kàn diànshì.","vn":""}]},{"title":"比较句（10）- Câu so sánh (10)","explanation_vn":"Cấu trúc \"A不比B+形容词\" có nghĩa là A và B gần như tương đương nhau, không chênh lệch nhiều. Cấu trúc này thường dùng để nhấn mạnh tình trạng của hai đối tượng là gần giống nhau, hoặc dùng để phản bác lại ý kiến của người khác.","examples":[{"cn":"裙子不比短裤贵多少。","pinyin":"Qúnzi bù bǐ duǎnkù guì duōshao.","vn":""},{"cn":"他的中文不比你好。","pinyin":"Tā de Zhōngwén bù bǐ nǐ hǎo.","vn":""},{"cn":"他跑得不比我快多少。","pinyin":"Tā pǎo de bù bǐ wǒ kuài duōshao.","vn":""}]},{"title":"程度补语（3）- Bổ ngữ mức độ (3)","explanation_vn":"Bổ ngữ mức độ \"极了\" dùng sau tính từ hoặc động từ tâm lý, biểu thị tính chất, trạng thái của người/vật, hoặc cảm xúc tâm lý của người đạt đến mức độ rất cao.","examples":[{"cn":"这块冰西瓜甜极了。","pinyin":"Zhè kuài bīng xīguā tián jí le.","vn":""},{"cn":"今年夏天热极了。","pinyin":"Jīnnián xiàtiān rè jí le.","vn":""},{"cn":"这本书我喜欢极了。","pinyin":"Zhè běn shū wǒ xǐhuan jí le.","vn":""}]},{"title":"递进复句\"不但……，而且……\" - Câu phức tiến triển \"不但……，而且……\"","explanation_vn":"Câu phức tiến triển \"不但……，而且……\" nối hai vế câu, biểu thị quan hệ tăng tiến. Nếu chủ ngữ của hai vế giống nhau thì \"不但\" đặt sau chủ ngữ thứ nhất; nếu chủ ngữ của hai vế khác nhau thì \"不但\" đặt trước chủ ngữ thứ nhất.","examples":[{"cn":"现在的电视不但便宜，而且用着非常方便。","pinyin":"Xiànzài de diànshì búdàn piányi, érqiě yòngzhe fēicháng fāngbiàn.","vn":""},{"cn":"家月不但喜欢唱歌，而且唱得很好听。","pinyin":"Jiāyuè búdàn xǐhuan chànggē, érqiě chàng de hěn hǎotīng.","vn":""},{"cn":"不但家月会说汉语，而且天中也会说汉语。","pinyin":"Búdàn Jiāyuè huì shuō Hànyǔ, érqiě Tiānzhōng yě huì shuō Hànyǔ.","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"王一雪","cn":"这辆自行车是小雪八岁的时候买的，看起来有点儿旧了。","pinyin":"Zhè liàng zìxíngchē shì Xiǎoxuě bā suì de shíhou mǎi de, kàn qǐlai yǒudiǎnr jiù le."},{"speaker":"刘明","cn":"是啊，她现在长高了，这辆车已经太矮了。","pinyin":"Shì a, tā xiànzài zhǎnggāo le, zhè liàng chē yǐjīng tài ǎi le."},{"speaker":"王一雪","cn":"商场里开了一家自行车店，咱们给她买辆新的吧。","pinyin":"Shāngchǎng lǐ kāile yì jiā zìxíngchē diàn, zánmen gěi tā mǎi liàng xīn de ba."},{"speaker":"刘明","cn":"好，咱们带小雪一起去，让她试一下。","pinyin":"Hǎo, zánmen dài Xiǎoxuě yìqǐ qù, ràng tā shì yíxià."},{"speaker":"王一雪","cn":"那今天就去吧！我也想再看看衣服。咱们怎么去？","pinyin":"Nà jīntiān jiù qù ba! Wǒ yě xiǎng zài kànkan yīfu. Zánmen zěnme qù?"},{"speaker":"刘明","cn":"商场不远，咱们可以走着去。","pinyin":"Shāngchǎng bù yuǎn, zánmen kěyǐ zǒuzhe qù."}],"translation_vn":"Vương Nhất Tuyết: Chiếc xe đạp này là mua lúc Tiểu Tuyết tám tuổi, trông có vẻ hơi cũ rồi.\nLưu Minh: Đúng vậy, bây giờ con bé cao lên rồi, chiếc xe này đã quá thấp rồi.\nVương Nhất Tuyết: Trong trung tâm thương mại có mở một cửa hàng xe đạp, chúng ta mua cho con bé một chiếc mới đi.\nLưu Minh: Được, chúng ta đưa Tiểu Tuyết đi cùng, để con bé thử xem sao.\nVương Nhất Tuyết: Vậy hôm nay đi luôn đi! Em cũng muốn xem thêm quần áo nữa. Chúng ta đi bằng gì?\nLưu Minh: Trung tâm thương mại không xa, chúng ta có thể đi bộ.","audio_dialogue":"7-1.mp3","audio_vocab":"7-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"王一雪","cn":"你看我穿这条黄色的短裤好看吗？","pinyin":"Nǐ kàn wǒ chuān zhè tiáo huángsè de duǎnkù hǎokàn ma?"},{"speaker":"刘明","cn":"大小合适，但我觉得那条裙子比短裤更好看。","pinyin":"Dàxiǎo héshì, dàn wǒ juéde nà tiáo qúnzi bǐ duǎnkù gèng hǎokàn."},{"speaker":"王一雪","cn":"裙子比短裤贵一点儿。","pinyin":"Qúnzi bǐ duǎnkù guì yìdiǎnr."},{"speaker":"刘明","cn":"贵多少？","pinyin":"Guì duōshao?"},{"speaker":"王一雪","cn":"裙子480，短裤400。","pinyin":"Qúnzi sìbǎi bāshí, duǎnkù sìbǎi."},{"speaker":"刘明","cn":"裙子不比短裤贵多少，还是买裙子吧，你穿裙子更好看。","pinyin":"Qúnzi bù bǐ duǎnkù guì duōshao, háishi mǎi qúnzi ba, nǐ chuān qúnzi gèng hǎokàn."},{"speaker":"王一雪","cn":"我多看看再决定。你看，那边有买二送一！","pinyin":"Wǒ duō kànkan zài juédìng. Nǐ kàn, nàbiān yǒu mǎi èr sòng yī!"}],"translation_vn":"Vương Nhất Tuyết: Anh xem em mặc cái quần short màu vàng này có đẹp không?\nLưu Minh: Kích cỡ vừa vặn, nhưng anh thấy chiếc váy kia đẹp hơn quần short.\nVương Nhất Tuyết: Váy đắt hơn quần short một chút.\nLưu Minh: Đắt hơn bao nhiêu?\nVương Nhất Tuyết: Váy 480, quần short 400.\nLưu Minh: Váy không đắt hơn quần short bao nhiêu đâu, cứ mua váy đi, em mặc váy đẹp hơn.\nVương Nhất Tuyết: Để em xem thêm rồi quyết định. Anh xem kìa, đằng kia có chương trình mua hai tặng một!","audio_dialogue":"7-3.mp3","audio_vocab":"7-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"店员","cn":"西瓜又大又新鲜，不甜不要钱！","pinyin":"Xīguā yòu dà yòu xīnxiān, bù tián bú yào qián!"},{"speaker":"王一雪","cn":"西瓜看起来不错，怎么卖？","pinyin":"Xīguā kàn qǐlai búcuò, zěnme mài?"},{"speaker":"店员","cn":"五块钱一公斤。来，您先尝尝这块冰西瓜，甜极了！","pinyin":"Wǔ kuài qián yì gōngjīn. Lái, nín xiān chángchang zhè kuài bīng xīguā, tián jí le!"},{"speaker":"王一雪","cn":"是挺甜的！帮我选个大点儿的，再来两斤香蕉。","pinyin":"Shì tǐng tián de! Bāng wǒ xuǎn ge dà diǎnr de, zài lái liǎng jīn xiāngjiāo."},{"speaker":"店员","cn":"一共五十八块五毛。","pinyin":"Yígòng wǔshíbā kuài wǔ máo."},{"speaker":"王一雪","cn":"我买了这么多，便宜点儿吧。","pinyin":"Wǒ mǎile zhème duō, piányi diǎnr ba."},{"speaker":"店员","cn":"您给我五十五吧，不能再便宜了。","pinyin":"Nín gěi wǒ wǔshíwǔ ba, bù néng zài piányi le."}],"translation_vn":"Nhân viên bán hàng: Dưa hấu vừa to vừa tươi, không ngọt không lấy tiền!\nVương Nhất Tuyết: Dưa hấu trông ngon đấy, bán thế nào?\nNhân viên bán hàng: Năm đồng một ký. Nào, chị nếm thử miếng dưa hấu ướp lạnh này xem, ngọt lắm đấy!\nVương Nhất Tuyết: Đúng là khá ngọt! Giúp tôi chọn một quả to hơn một chút, với lại lấy thêm hai cân chuối.\nNhân viên bán hàng: Tổng cộng năm mươi tám đồng năm hào.\nVương Nhất Tuyết: Tôi mua nhiều như vậy, bớt cho tôi một chút đi.\nNhân viên bán hàng: Chị đưa tôi năm mươi lăm đồng thôi, không thể bớt thêm được nữa.","audio_dialogue":"7-5.mp3","audio_vocab":"7-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"这几天我们在新家坐着看电视的时候，又发现了新问题。","pinyin":"Zhè jǐ tiān wǒmen zài xīn jiā zuòzhe kàn diànshì de shíhou, yòu fāxiànle xīn wèntí."},{"speaker":"","cn":"房子大了，电视看起来就有点儿小。","pinyin":"Fángzi dà le, diànshì kàn qǐlai jiù yǒudiǎnr xiǎo."},{"speaker":"","cn":"这个电视是我们结婚时买的，是时候换个新电视了。","pinyin":"Zhège diànshì shì wǒmen jiéhūn shí mǎi de, shì shíhou huàn ge xīn diànshì le."},{"speaker":"","cn":"今天我一直在网上选电视，没想到，现在的电视不但便宜，而且用着非常方便。","pinyin":"Jīntiān wǒ yìzhí zài wǎngshàng xuǎn diànshì, méi xiǎngdào, xiànzài de diànshì búdàn piányi, érqiě yòngzhe fēicháng fāngbiàn."},{"speaker":"","cn":"有的电视叫它一声就能开机。","pinyin":"Yǒude diànshì jiào tā yì shēng jiù néng kāijī."},{"speaker":"","cn":"我看了好几个，都很满意，晚上让一雪来决定吧。","pinyin":"Wǒ kànle hǎojǐ ge, dōu hěn mǎnyì, wǎnshang ràng Yīxuě lái juédìng ba."}],"translation_vn":"Mấy ngày nay, khi chúng tôi ngồi xem ti vi trong nhà mới, lại phát hiện ra vấn đề mới. Nhà rộng hơn nên chiếc ti vi trông có vẻ hơi nhỏ. Chiếc ti vi này là mua từ lúc chúng tôi kết hôn, đã đến lúc đổi một cái ti vi mới rồi. Hôm nay tôi cứ lên mạng chọn ti vi mãi, không ngờ ti vi bây giờ không những rẻ mà dùng còn rất tiện lợi. Có loại ti vi chỉ cần gọi một tiếng là có thể bật lên được. Tôi đã xem mấy cái, đều thấy rất ưng ý, tối nay để Nhất Tuyết quyết định vậy.","audio_dialogue":"7-7.mp3","audio_vocab":"7-8.mp3"}]},{"id":8,"title_cn":"今天我出院了","title_pinyin":"Jīntiān wǒ chūyuàn le","title_vn":"Hôm nay tôi đã xuất viện","goals":["Có thể nghe hiểu và miêu tả trải nghiệm khám bệnh cùng cách dùng thuốc.","Có thể nghe hiểu và trao đổi về tình trạng sức khỏe và thói quen sống lành mạnh.","Nắm vững cách dùng bổ ngữ thời lượng (2), có thể diễn đạt khoảng thời gian kéo dài từ khi động tác kết thúc đến hiện tại."],"vocab":[{"hanzi":"最近","pinyin":"zuìjìn","pos":"dt.","vn":"gần đây, dạo này","examples":[{"cn":"最近工作很忙。","pinyin":"Zuìjìn gōngzuò hěn máng.","vn":"Dạo gần đây công việc rất bận."},{"cn":"你最近怎么样?","pinyin":"Nǐ zuìjìn zěnmeyàng?","vn":"Dạo này bạn thế nào?"},{"cn":"最近天气越来越冷了。","pinyin":"Zuìjìn tiānqì yuèláiyuè lěng le.","vn":"Dạo gần đây thời tiết càng ngày càng lạnh."}]},{"hanzi":"常","pinyin":"cháng","pos":"phó.","vn":"thường, hay","examples":[{"cn":"他常去健身房锻炼。","pinyin":"Tā cháng qù jiànshēnfáng duànliàn.","vn":"Anh ấy thường đi phòng tập thể dục để rèn luyện."},{"cn":"我们常在一起吃饭。","pinyin":"Wǒmen cháng zài yìqǐ chīfàn.","vn":"Chúng tôi thường ăn cơm cùng nhau."},{"cn":"她常忘记带手机。","pinyin":"Tā cháng wàngjì dài shǒujī.","vn":"Cô ấy hay quên mang điện thoại."}]},{"hanzi":"体育馆","pinyin":"tǐyùguǎn","pos":"dt.","vn":"nhà thi đấu, phòng tập thể thao","examples":[{"cn":"我们学校有一个很大的体育馆。","pinyin":"Wǒmen xuéxiào yǒu yí ge hěn dà de tǐyùguǎn.","vn":"Trường chúng tôi có một nhà thi đấu rất lớn."},{"cn":"今晚体育馆有一场篮球比赛。","pinyin":"Jīnwǎn tǐyùguǎn yǒu yì chǎng lánqiú bǐsài.","vn":"Tối nay ở nhà thi đấu có một trận bóng rổ."},{"cn":"我们常去体育馆打羽毛球。","pinyin":"Wǒmen cháng qù tǐyùguǎn dǎ yǔmáoqiú.","vn":"Chúng tôi thường đến nhà thi đấu chơi cầu lông."}]},{"hanzi":"习惯","pinyin":"xíguàn","pos":"dt./dgt.","vn":"thói quen; quen với","examples":[{"cn":"我已经习惯了早起。","pinyin":"Wǒ yǐjīng xíguàn le zǎoqǐ.","vn":"Tôi đã quen với việc dậy sớm."},{"cn":"早睡早起是个好习惯。","pinyin":"Zǎoshuì zǎoqǐ shì ge hǎo xíguàn.","vn":"Ngủ sớm dậy sớm là một thói quen tốt."},{"cn":"他还不太习惯这里的生活。","pinyin":"Tā hái bú tài xíguàn zhèlǐ de shēnghuó.","vn":"Anh ấy vẫn chưa quen lắm với cuộc sống ở đây."}]},{"hanzi":"胖","pinyin":"pàng","pos":"tt.","vn":"béo, mập","examples":[{"cn":"他最近胖了不少。","pinyin":"Tā zuìjìn pàngle bù shǎo.","vn":"Dạo gần đây anh ấy mập lên khá nhiều."},{"cn":"吃太多会变胖。","pinyin":"Chī tài duō huì biàn pàng.","vn":"Ăn quá nhiều sẽ bị béo."},{"cn":"我觉得自己有点儿胖,想减肥。","pinyin":"Wǒ juéde zìjǐ yǒudiǎnr pàng, xiǎng jiǎnféi.","vn":"Tôi thấy mình hơi mập, muốn giảm cân."}]},{"hanzi":"健康","pinyin":"jiànkāng","pos":"tt.","vn":"khỏe mạnh","examples":[{"cn":"多运动对健康有好处。","pinyin":"Duō yùndòng duì jiànkāng yǒu hǎochù.","vn":"Vận động nhiều có lợi cho sức khỏe."},{"cn":"身体健康最重要。","pinyin":"Shēntǐ jiànkāng zuì zhòngyào.","vn":"Sức khỏe là quan trọng nhất."},{"cn":"他看起来很健康。","pinyin":"Tā kànqǐlái hěn jiànkāng.","vn":"Trông anh ấy rất khỏe mạnh."}]},{"hanzi":"以后","pinyin":"yǐhòu","pos":"dt.","vn":"sau đó, về sau","examples":[{"cn":"以后我要多运动。","pinyin":"Yǐhòu wǒ yào duō yùndòng.","vn":"Sau này tôi sẽ vận động nhiều hơn."},{"cn":"下班以后我们去看电影吧。","pinyin":"Xiàbān yǐhòu wǒmen qù kàn diànyǐng ba.","vn":"Sau khi tan làm chúng ta đi xem phim nhé."},{"cn":"三年以后他就毕业了。","pinyin":"Sān nián yǐhòu tā jiù bìyè le.","vn":"Ba năm sau anh ấy sẽ tốt nghiệp."}]},{"hanzi":"羽毛球","pinyin":"yǔmáoqiú","pos":"dt.","vn":"cầu lông","examples":[{"cn":"我每周打两次羽毛球。","pinyin":"Wǒ měi zhōu dǎ liǎng cì yǔmáoqiú.","vn":"Tôi chơi cầu lông hai lần mỗi tuần."},{"cn":"他羽毛球打得很好。","pinyin":"Tā yǔmáoqiú dǎ de hěn hǎo.","vn":"Anh ấy chơi cầu lông rất giỏi."},{"cn":"周末我们一起打羽毛球吧。","pinyin":"Zhōumò wǒmen yìqǐ dǎ yǔmáoqiú ba.","vn":"Cuối tuần chúng ta cùng chơi cầu lông nhé."}]},{"hanzi":"耳朵","pinyin":"ěrduo","pos":"dt.","vn":"tai","examples":[{"cn":"我的耳朵有点儿疼。","pinyin":"Wǒ de ěrduo yǒudiǎnr téng.","vn":"Tai tôi hơi đau."},{"cn":"他耳朵不太好,你声音大一点儿。","pinyin":"Tā ěrduo bú tài hǎo, nǐ shēngyīn dà yìdiǎnr.","vn":"Tai anh ấy không tốt lắm, bạn nói to hơn một chút."},{"cn":"小兔子的耳朵很长。","pinyin":"Xiǎo tùzi de ěrduo hěn cháng.","vn":"Tai của chú thỏ con rất dài."}]},{"hanzi":"感冒","pinyin":"gǎnmào","pos":"dgt./dt.","vn":"bị cảm; bệnh cảm cúm","examples":[{"cn":"我昨天感冒了,一直在咳嗽。","pinyin":"Wǒ zuótiān gǎnmào le, yìzhí zài késou.","vn":"Hôm qua tôi bị cảm, cứ ho mãi."},{"cn":"换季的时候容易感冒。","pinyin":"Huànjì de shíhou róngyì gǎnmào.","vn":"Lúc giao mùa dễ bị cảm."},{"cn":"多穿点儿衣服,小心感冒。","pinyin":"Duō chuān diǎnr yīfu, xiǎoxīn gǎnmào.","vn":"Mặc nhiều quần áo hơn, cẩn thận bị cảm."}]},{"hanzi":"发烧","pinyin":"fāshāo","pos":"dgt.","vn":"sốt","examples":[{"cn":"孩子昨晚发烧了。","pinyin":"Háizi zuówǎn fāshāo le.","vn":"Đêm qua đứa trẻ bị sốt."},{"cn":"我有点儿发烧,头很疼。","pinyin":"Wǒ yǒudiǎnr fāshāo, tóu hěn téng.","vn":"Tôi hơi sốt, đầu rất đau."},{"cn":"发烧的时候要多喝水。","pinyin":"Fāshāo de shíhou yào duō hēshuǐ.","vn":"Khi bị sốt cần uống nhiều nước."}]},{"hanzi":"低","pinyin":"dī","pos":"tt.","vn":"thấp","examples":[{"cn":"今天温度比较低。","pinyin":"Jīntiān wēndù bǐjiào dī.","vn":"Nhiệt độ hôm nay khá thấp."},{"cn":"他说话声音很低。","pinyin":"Tā shuōhuà shēngyīn hěn dī.","vn":"Anh ấy nói chuyện giọng rất thấp."},{"cn":"这个价格比别的地方低一些。","pinyin":"Zhège jiàgé bǐ bié de dìfang dī yìxiē.","vn":"Giá này thấp hơn chỗ khác một chút."}]},{"hanzi":"关心","pinyin":"guānxīn","pos":"dgt.","vn":"quan tâm","examples":[{"cn":"老师很关心我们的学习。","pinyin":"Lǎoshī hěn guānxīn wǒmen de xuéxí.","vn":"Thầy giáo rất quan tâm đến việc học của chúng tôi."},{"cn":"父母一直关心孩子的健康。","pinyin":"Fùmǔ yìzhí guānxīn háizi de jiànkāng.","vn":"Bố mẹ luôn quan tâm đến sức khỏe của con cái."},{"cn":"谢谢你这么关心我。","pinyin":"Xièxie nǐ zhème guānxīn wǒ.","vn":"Cảm ơn bạn đã quan tâm tôi nhiều như vậy."}]},{"hanzi":"注意","pinyin":"zhùyì","pos":"dgt.","vn":"chú ý, để ý","examples":[{"cn":"过马路一定要注意安全。","pinyin":"Guò mǎlù yídìng yào zhùyì ānquán.","vn":"Qua đường nhất định phải chú ý an toàn."},{"cn":"请大家注意这个问题。","pinyin":"Qǐng dàjiā zhùyì zhège wèntí.","vn":"Xin mọi người chú ý vấn đề này."},{"cn":"天气冷了,要注意保暖。","pinyin":"Tiānqì lěng le, yào zhùyì bǎonuǎn.","vn":"Trời lạnh rồi, cần chú ý giữ ấm."}]},{"hanzi":"突然","pinyin":"tūrán","pos":"tt.","vn":"đột ngột, bất ngờ","examples":[{"cn":"外面突然下起了大雨。","pinyin":"Wàimiàn tūrán xiàqǐle dàyǔ.","vn":"Bên ngoài bỗng nhiên đổ mưa to."},{"cn":"他突然生病住院了。","pinyin":"Tā tūrán shēngbìng zhùyuàn le.","vn":"Anh ấy đột nhiên bị bệnh phải nhập viện."},{"cn":"这件事发生得太突然了。","pinyin":"Zhè jiàn shì fāshēng de tài tūrán le.","vn":"Việc này xảy ra quá đột ngột."}]},{"hanzi":"住院","pinyin":"zhùyuàn","pos":"dgt.","vn":"nhập viện","examples":[{"cn":"他感冒很严重,得住院了。","pinyin":"Tā gǎnmào hěn yánzhòng, děi zhùyuàn le.","vn":"Anh ấy bị cảm rất nặng, phải nhập viện."},{"cn":"爷爷住院一个星期了。","pinyin":"Yéye zhùyuàn yí ge xīngqī le.","vn":"Ông nội nhập viện một tuần rồi."},{"cn":"住院期间他一直很担心家里。","pinyin":"Zhùyuàn qījiān tā yìzhí hěn dānxīn jiālǐ.","vn":"Trong thời gian nhập viện anh ấy luôn lo lắng cho gia đình."}]},{"hanzi":"担心","pinyin":"dānxīn","pos":"dgt.","vn":"lo lắng","examples":[{"cn":"别担心,一切都会好的。","pinyin":"Bié dānxīn, yíqiè dōu huì hǎo de.","vn":"Đừng lo lắng, mọi thứ sẽ ổn thôi."},{"cn":"妈妈很担心我一个人在外地。","pinyin":"Māma hěn dānxīn wǒ yí ge rén zài wàidì.","vn":"Mẹ rất lo lắng khi tôi một mình ở xa."},{"cn":"他没来上课,老师有点儿担心。","pinyin":"Tā méi lái shàngkè, lǎoshī yǒudiǎnr dānxīn.","vn":"Anh ấy không đến lớp, thầy giáo hơi lo lắng."}]},{"hanzi":"腿","pinyin":"tuǐ","pos":"dt.","vn":"chân (đùi)","examples":[{"cn":"我的腿有点儿疼。","pinyin":"Wǒ de tuǐ yǒudiǎnr téng.","vn":"Chân tôi hơi đau."},{"cn":"他跑步的时候摔伤了腿。","pinyin":"Tā pǎobù de shíhou shuāishāngle tuǐ.","vn":"Anh ấy chạy bộ bị ngã làm thương chân."},{"cn":"坐久了腿会麻。","pinyin":"Zuò jiǔ le tuǐ huì má.","vn":"Ngồi lâu chân sẽ bị tê."}]},{"hanzi":"病人","pinyin":"bìngrén","pos":"dt.","vn":"bệnh nhân","examples":[{"cn":"医院里有很多病人。","pinyin":"Yīyuàn lǐ yǒu hěn duō bìngrén.","vn":"Trong bệnh viện có rất nhiều bệnh nhân."},{"cn":"医生正在照顾病人。","pinyin":"Yīshēng zhèngzài zhàogù bìngrén.","vn":"Bác sĩ đang chăm sóc bệnh nhân."},{"cn":"这位病人恢复得很快。","pinyin":"Zhè wèi bìngrén huīfù de hěn kuài.","vn":"Bệnh nhân này hồi phục rất nhanh."}]},{"hanzi":"差不多","pinyin":"chàbuduō","pos":"phó./tt.","vn":"gần như, xấp xỉ","examples":[{"cn":"我们两个人的年龄差不多。","pinyin":"Wǒmen liǎng ge rén de niánlíng chàbuduō.","vn":"Tuổi của hai chúng tôi gần bằng nhau."},{"cn":"现在差不多六点了。","pinyin":"Xiànzài chàbuduō liù diǎn le.","vn":"Bây giờ gần sáu giờ rồi."},{"cn":"这件事差不多做完了。","pinyin":"Zhè jiàn shì chàbuduō zuò wán le.","vn":"Việc này gần như đã làm xong."}]},{"hanzi":"得","pinyin":"děi","pos":"đtnn.","vn":"phải, cần","examples":[{"cn":"我得走了,不然要迟到了。","pinyin":"Wǒ děi zǒu le, bùrán yào chídào le.","vn":"Tôi phải đi rồi, không thì sẽ muộn mất."},{"cn":"生病了就得去医院看看。","pinyin":"Shēngbìng le jiù děi qù yīyuàn kànkan.","vn":"Bị bệnh thì phải đi bệnh viện khám xem."},{"cn":"你得多注意休息。","pinyin":"Nǐ děi duō zhùyì xiūxi.","vn":"Bạn phải chú ý nghỉ ngơi nhiều hơn."}]},{"hanzi":"开心","pinyin":"kāixīn","pos":"tt.","vn":"vui vẻ","examples":[{"cn":"今天我玩儿得很开心。","pinyin":"Jīntiān wǒ wánr de hěn kāixīn.","vn":"Hôm nay tôi chơi rất vui."},{"cn":"看到朋友我特别开心。","pinyin":"Kàndào péngyou wǒ tèbié kāixīn.","vn":"Gặp bạn bè tôi đặc biệt vui."},{"cn":"她笑得很开心。","pinyin":"Tā xiào de hěn kāixīn.","vn":"Cô ấy cười rất vui vẻ."}]},{"hanzi":"出院","pinyin":"chūyuàn","pos":"dgt.","vn":"xuất viện","examples":[{"cn":"爷爷明天就可以出院了。","pinyin":"Yéye míngtiān jiù kěyǐ chūyuàn le.","vn":"Ngày mai ông nội có thể xuất viện rồi."},{"cn":"医生说他身体好了,可以出院。","pinyin":"Yīshēng shuō tā shēntǐ hǎo le, kěyǐ chūyuàn.","vn":"Bác sĩ nói anh ấy đã khỏe, có thể xuất viện."},{"cn":"出院以后要在家好好休息。","pinyin":"Chūyuàn yǐhòu yào zài jiā hǎohǎo xiūxi.","vn":"Sau khi xuất viện cần nghỉ ngơi thật tốt ở nhà."}]},{"hanzi":"开","pinyin":"kāi","pos":"dgt.","vn":"kê (đơn thuốc)","examples":[{"cn":"医生给我开了一些药。","pinyin":"Yīshēng gěi wǒ kāile yìxiē yào.","vn":"Bác sĩ kê cho tôi một ít thuốc."},{"cn":"你能帮我开个证明吗?","pinyin":"Nǐ néng bāng wǒ kāi ge zhèngmíng ma?","vn":"Bạn có thể giúp tôi viết một giấy chứng nhận không?"},{"cn":"医生开的药要按时吃。","pinyin":"Yīshēng kāi de yào yào ànshí chī.","vn":"Thuốc bác sĩ kê phải uống đúng giờ."}]},{"hanzi":"种","pinyin":"zhǒng","pos":"lượng.","vn":"loại","examples":[{"cn":"这种水果我没吃过。","pinyin":"Zhè zhǒng shuǐguǒ wǒ méi chīguo.","vn":"Loại trái cây này tôi chưa ăn qua."},{"cn":"有两种方法可以解决这个问题。","pinyin":"Yǒu liǎng zhǒng fāngfǎ kěyǐ jiějué zhège wèntí.","vn":"Có hai cách có thể giải quyết vấn đề này."},{"cn":"我喜欢这种颜色的衣服。","pinyin":"Wǒ xǐhuan zhè zhǒng yánsè de yīfu.","vn":"Tôi thích loại quần áo màu này."}]},{"hanzi":"方法","pinyin":"fāngfǎ","pos":"dt.","vn":"phương pháp, cách","examples":[{"cn":"这个方法很有效。","pinyin":"Zhège fāngfǎ hěn yǒuxiào.","vn":"Phương pháp này rất hiệu quả."},{"cn":"你能教我一个学习中文的好方法吗?","pinyin":"Nǐ néng jiāo wǒ yí ge xuéxí Zhōngwén de hǎo fāngfǎ ma?","vn":"Bạn có thể dạy tôi một cách học tiếng Trung tốt không?"},{"cn":"我们应该换个方法试试。","pinyin":"Wǒmen yīnggāi huàn ge fāngfǎ shìshi.","vn":"Chúng ta nên đổi một cách khác để thử."}]},{"hanzi":"其他","pinyin":"qítā","pos":"đt.","vn":"khác, cái khác","examples":[{"cn":"除了他,其他人都来了。","pinyin":"Chúle tā, qítā rén dōu lái le.","vn":"Ngoài anh ấy ra, những người khác đều đến rồi."},{"cn":"你还有其他问题吗?","pinyin":"Nǐ hái yǒu qítā wèntí ma?","vn":"Bạn còn vấn đề gì khác nữa không?"},{"cn":"这件事交给其他人做吧。","pinyin":"Zhè jiàn shì jiāo gěi qítā rén zuò ba.","vn":"Việc này giao cho người khác làm đi."}]},{"hanzi":"心里","pinyin":"xīnlǐ","pos":"dt.","vn":"trong lòng, trong tâm trí","examples":[{"cn":"我心里一直很担心他。","pinyin":"Wǒ xīnlǐ yìzhí hěn dānxīn tā.","vn":"Trong lòng tôi luôn lo lắng cho anh ấy."},{"cn":"听到这个消息,他心里很难过。","pinyin":"Tīngdào zhège xiāoxi, tā xīnlǐ hěn nánguò.","vn":"Nghe tin này, trong lòng anh ấy rất buồn."},{"cn":"我心里早就有了答案。","pinyin":"Wǒ xīnlǐ zǎo jiù yǒule dá'àn.","vn":"Trong lòng tôi đã có câu trả lời từ lâu."}]}],"grammar":[{"title":"趋向补语的引申用法（1）\"下去\" - Cách dùng mở rộng của bổ ngữ xu hướng (1)","explanation_vn":"Bổ ngữ xu hướng \"下去\" đặt sau động từ hoặc tính từ, biểu thị một động tác hoặc trạng thái đã bắt đầu sẽ tiếp tục diễn ra.","examples":[{"cn":"我今年胖了十多斤，不能再胖下去了。","pinyin":"Wǒ jīnnián pàng le shí duō jīn, bù néng zài pàng xiàqù le.","vn":""},{"cn":"她读完了第一个问题，后面的你读下去。","pinyin":"Tā dú wán le dì yī ge wèntí, hòumiàn de nǐ dú xiàqù.","vn":""},{"cn":"这几天太热了，如果再热下去就不能出门了。","pinyin":"Zhè jǐ tiān tài rè le, rúguǒ zài rè xiàqù jiù bù néng chūmén le.","vn":""}]},{"title":"离合词（2）- Từ ly hợp (2)","explanation_vn":"Từ ly hợp thường không thể trực tiếp mang tân ngữ. Trong câu dùng từ ly hợp, nếu có bổ ngữ thì bổ ngữ thường được đặt ở giữa hai thành phần của từ ly hợp.","examples":[{"cn":"昨天游完泳以后，我的耳朵一直有点儿疼。","pinyin":"Zuótiān yóu wán yǒng yǐhòu, wǒ de ěrduo yìzhí yǒudiǎnr téng.","vn":""},{"cn":"今年夏天只下了两次雨。","pinyin":"Jīnnián xiàtiān zhǐ xià le liǎng cì yǔ.","vn":""},{"cn":"小张下个月跟他女朋友结婚。","pinyin":"Xiǎo Zhāng xià ge yuè gēn tā nǚpéngyou jiéhūn.","vn":""}]},{"title":"时量补语（2）- Bổ ngữ thời lượng (2)","explanation_vn":"Bổ ngữ thời lượng đặt sau động từ, biểu thị độ dài thời gian mà động tác hoặc trạng thái kéo dài. Có một số động từ không thể tiếp diễn liên tục, khi đó bổ ngữ thời lượng đứng sau động từ biểu thị khoảng thời gian đã trôi qua kể từ khi động tác kết thúc đến lúc nói.","examples":[{"cn":"我上次来医院已经过去差不多两年了。","pinyin":"Wǒ shàng cì lái yīyuàn yǐjīng guòqù chàbuduō liǎng nián le.","vn":""},{"cn":"她回家两个月了。","pinyin":"Tā huí jiā liǎng ge yuè le.","vn":""},{"cn":"开学已经三个多星期了。","pinyin":"Kāixué yǐjīng sān ge duō xīngqī le.","vn":""}]},{"title":"固定格式\"……以前/以后/前/后\" - Cấu trúc cố định \"...以前/以后/前/后\"","explanation_vn":"\"Thời gian/sự kiện + 以前/前\" biểu thị thời điểm trước một thời gian hoặc sự kiện nào đó; \"thời gian/sự kiện + 以后/后\" biểu thị thời điểm sau một thời gian hoặc sự kiện nào đó.","examples":[{"cn":"这种药需要每天睡前吃一次。","pinyin":"Zhè zhǒng yào xūyào měitiān shuì qián chī yí cì.","vn":""},{"cn":"我们决定下班后一起去看个电影。","pinyin":"Wǒmen juédìng xiàbān hòu yìqǐ qù kàn ge diànyǐng.","vn":""},{"cn":"考完试以后，咱们一起去旅游吧。","pinyin":"Kǎo wán shì yǐhòu, zánmen yìqǐ qù lǚyóu ba.","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"李文","cn":"天中，最近常看见你来体育馆。","pinyin":"Tiānzhōng, zuìjìn cháng kànjiàn nǐ lái tǐyùguǎn."},{"speaker":"陈天中","cn":"我每天下午都来跑一个小时步。","pinyin":"Wǒ měitiān xiàwǔ dōu lái pǎo yí ge xiǎoshí bù."},{"speaker":"李文","cn":"你的运动习惯真不错。","pinyin":"Nǐ de yùndòng xíguàn zhēn búcuò."},{"speaker":"陈天中","cn":"因为我今年胖了十多斤，不能再胖下去了，有点儿不健康。","pinyin":"Yīnwèi wǒ jīnnián pàng le shí duō jīn, bù néng zài pàng xiàqù le, yǒudiǎnr bú jiànkāng."},{"speaker":"李文","cn":"我下课以后常去打羽毛球，你也来玩吧。","pinyin":"Wǒ xiàkè yǐhòu cháng qù dǎ yǔmáoqiú, nǐ yě lái wán ba."},{"speaker":"陈天中","cn":"我知道，但是你们的水平太高了，我打得不怎么样。","pinyin":"Wǒ zhīdào, dànshì nǐmen de shuǐpíng tài gāo le, wǒ dǎ de bù zěnmeyàng."},{"speaker":"李文","cn":"没关系，我可以教你。","pinyin":"Méi guānxi, wǒ kěyǐ jiāo nǐ."}],"translation_vn":"Lý Văn: Thiên Trung, dạo này mình thường thấy cậu đến nhà thi đấu.\nTrần Thiên Trung: Mình ngày nào buổi chiều cũng đến chạy bộ một tiếng.\nLý Văn: Thói quen vận động của cậu thật tốt đấy.\nTrần Thiên Trung: Vì năm nay mình béo lên hơn chục cân, không thể béo thêm nữa, hơi không khỏe mạnh.\nLý Văn: Sau giờ học mình thường đi đánh cầu lông, cậu cũng đến chơi nhé.\nTrần Thiên Trung: Mình biết, nhưng trình độ của các cậu cao quá, mình đánh không được tốt lắm.\nLý Văn: Không sao, mình có thể dạy cậu.","audio_dialogue":"8-1.mp3","audio_vocab":"8-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"安妮","cn":"你怎么了？看上去有点儿不舒服。","pinyin":"Nǐ zěnme le? Kàn shàngqù yǒudiǎnr bù shūfu."},{"speaker":"陈天中","cn":"昨天游完泳以后，耳朵一直有点儿疼。","pinyin":"Zuótiān yóu wán yǒng yǐhòu, ěrduo yìzhí yǒudiǎnr téng."},{"speaker":"安妮","cn":"是不是感冒了？发烧吗？","pinyin":"Shì bu shì gǎnmào le? Fāshāo ma?"},{"speaker":"陈天中","cn":"好像发低烧了。","pinyin":"Hǎoxiàng fā dīshāo le."},{"speaker":"安妮","cn":"我送你去医院，让医生检查一下吧。","pinyin":"Wǒ sòng nǐ qù yīyuàn, ràng yīshēng jiǎnchá yíxià ba."},{"speaker":"陈天中","cn":"我先回去睡一觉，可能休息休息就好了。","pinyin":"Wǒ xiān huíqù shuì yí jiào, kěnéng xiūxi xiūxi jiù hǎo le."},{"speaker":"安妮","cn":"好吧，如果下午还发烧，就一定要去看医生。","pinyin":"Hǎo ba, rúguǒ xiàwǔ hái fāshāo, jiù yídìng yào qù kàn yīshēng."},{"speaker":"陈天中","cn":"谢谢关心，我会注意的。","pinyin":"Xièxiè guānxīn, wǒ huì zhùyì de."}],"translation_vn":"Annie: Cậu sao vậy? Trông có vẻ hơi khó chịu.\nTrần Thiên Trung: Hôm qua bơi xong, tai mình cứ hơi đau.\nAnnie: Có phải bị cảm không? Có sốt không?\nTrần Thiên Trung: Hình như sốt nhẹ rồi.\nAnnie: Mình đưa cậu đi bệnh viện, để bác sĩ khám một chút nhé.\nTrần Thiên Trung: Mình về ngủ một giấc trước đã, có lẽ nghỉ ngơi là sẽ khỏi thôi.\nAnnie: Được rồi, nếu chiều vẫn còn sốt thì nhất định phải đi khám bác sĩ.\nTrần Thiên Trung: Cảm ơn cậu đã quan tâm, mình sẽ để ý.","audio_dialogue":"8-3.mp3","audio_vocab":"8-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"安妮","cn":"你怎么突然住院了？大家都很担心你。","pinyin":"Nǐ zěnme tūrán zhùyuàn le? Dàjiā dōu hěn dānxīn nǐ."},{"speaker":"陈天中","cn":"我的腿疼了几个星期了，医生说需要住院做检查。","pinyin":"Wǒ de tuǐ téng le jǐ ge xīngqī le, yīshēng shuō xūyào zhùyuàn zuò jiǎnchá."},{"speaker":"安妮","cn":"你看起来一点儿也不像病人。","pinyin":"Nǐ kàn qǐlái yìdiǎnr yě bú xiàng bìngrén."},{"speaker":"陈天中","cn":"是啊，我很少生病。我上次来医院已经过去差不多两年了。","pinyin":"Shì a, wǒ hěn shǎo shēngbìng. Wǒ shàng cì lái yīyuàn yǐjīng guòqù chàbuduō liǎng nián le."},{"speaker":"安妮","cn":"你每天跑步，有时候还去游泳，是不是运动太多了？","pinyin":"Nǐ měitiān pǎobù, yǒu shíhou hái qù yóuyǒng, shì bu shì yùndòng tài duō le?"},{"speaker":"陈天中","cn":"医生也这么说，但是还得做完检查才能知道。","pinyin":"Yīshēng yě zhème shuō, dànshì hái děi zuò wán jiǎnchá cái néng zhīdào."},{"speaker":"安妮","cn":"别担心！听医生的话，好好休息，你的腿一定能好。","pinyin":"Bié dānxīn! Tīng yīshēng de huà, hǎohǎo xiūxi, nǐ de tuǐ yídìng néng hǎo."},{"speaker":"陈天中","cn":"谢谢。有人来看我，我就开心多了。","pinyin":"Xièxie. Yǒu rén lái kàn wǒ, wǒ jiù kāixīn duō le."}],"translation_vn":"Annie: Sao cậu đột nhiên nhập viện vậy? Mọi người đều rất lo lắng cho cậu.\nTrần Thiên Trung: Chân mình đau mấy tuần rồi, bác sĩ nói cần nhập viện để kiểm tra.\nAnnie: Trông cậu chẳng giống bệnh nhân chút nào.\nTrần Thiên Trung: Đúng vậy, mình rất ít khi ốm. Lần trước mình đến bệnh viện đã gần hai năm rồi.\nAnnie: Ngày nào cậu cũng chạy bộ, thỉnh thoảng còn đi bơi nữa, có phải vận động quá nhiều không?\nTrần Thiên Trung: Bác sĩ cũng nói vậy, nhưng phải làm xong kiểm tra mới biết được.\nAnnie: Đừng lo! Nghe lời bác sĩ, nghỉ ngơi thật tốt, chân cậu chắc chắn sẽ khỏi.\nTrần Thiên Trung: Cảm ơn cậu. Có người đến thăm, mình thấy vui hơn nhiều.","audio_dialogue":"8-5.mp3","audio_vocab":"8-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"今天我出院了。","pinyin":"Jīntiān wǒ chūyuàn le."},{"speaker":"","cn":"出院前，医生给我开了几种药，而且告诉了我吃药的方法。","pinyin":"Chūyuàn qián, yīshēng gěi wǒ kāi le jǐ zhǒng yào, érqiě gàosu le wǒ chī yào de fāngfǎ."},{"speaker":"","cn":"有一种药需要每天睡前吃一次，其他几种每天吃三次，饭后吃。","pinyin":"Yǒu yì zhǒng yào xūyào měitiān shuì qián chī yí cì, qítā jǐ zhǒng měitiān chī sān cì, fàn hòu chī."},{"speaker":"","cn":"除了吃药，医生还说最重要的是多休息。","pinyin":"Chúle chī yào, yīshēng hái shuō zuì zhòngyào de shì duō xiūxi."},{"speaker":"","cn":"我都记在心里了，回家以后一定会多注意。","pinyin":"Wǒ dōu jì zài xīnlǐ le, huí jiā yǐhòu yídìng huì duō zhùyì."},{"speaker":"","cn":"希望我的腿能快一点儿好。","pinyin":"Xīwàng wǒ de tuǐ néng kuài yìdiǎnr hǎo."}],"translation_vn":"Hôm nay tôi đã xuất viện. Trước khi xuất viện, bác sĩ đã kê cho tôi vài loại thuốc, và còn nói cho tôi biết cách uống thuốc. Có một loại thuốc cần uống mỗi ngày một lần trước khi ngủ, mấy loại khác thì mỗi ngày uống ba lần, uống sau bữa ăn. Ngoài việc uống thuốc, bác sĩ còn nói điều quan trọng nhất là nghỉ ngơi nhiều. Tôi đã ghi nhớ tất cả trong lòng, về nhà nhất định sẽ chú ý nhiều hơn. Hy vọng chân tôi sẽ sớm khỏi.","audio_dialogue":"8-7.mp3","audio_vocab":"8-8.mp3"}]},{"id":9,"title_cn":"打不好没关系","title_pinyin":"Dǎ bù hǎo méi guānxi","title_vn":"Chơi không giỏi cũng không sao","goals":["Có thể nghe hiểu và giới thiệu tên gọi, vận động viên, ảnh hưởng... của các cuộc thi đấu thể thao.","Có thể nghe hiểu và sử dụng bổ ngữ khả năng để diễn đạt khả năng xảy ra của một tình huống.","Nắm vững cách dùng cấu trúc \"越A越B\", có thể diễn đạt sự thay đổi của sự vật hoặc tình huống."],"vocab":[{"hanzi":"校园","pinyin":"xiàoyuán","pos":"dt.","vn":"khuôn viên trường","examples":[{"cn":"我们学校的校园很漂亮。","pinyin":"Wǒmen xuéxiào de xiàoyuán hěn piàoliang.","vn":"Khuôn viên trường chúng tôi rất đẹp."},{"cn":"周末很多人在校园里散步。","pinyin":"Zhōumò hěn duō rén zài xiàoyuán lǐ sànbù.","vn":"Cuối tuần nhiều người đi dạo trong khuôn viên trường."},{"cn":"校园里有很多树和花。","pinyin":"Xiàoyuán lǐ yǒu hěn duō shù hé huā.","vn":"Trong khuôn viên trường có nhiều cây và hoa."}]},{"hanzi":"卡","pinyin":"kǎ","pos":"dt.","vn":"thẻ","examples":[{"cn":"我忘了带公交卡。","pinyin":"Wǒ wàngle dài gōngjiāo kǎ.","vn":"Tôi quên mang thẻ xe buýt."},{"cn":"你可以用学生卡进体育馆。","pinyin":"Nǐ kěyǐ yòng xuésheng kǎ jìn tǐyùguǎn.","vn":"Bạn có thể dùng thẻ sinh viên để vào nhà thi đấu."},{"cn":"这张银行卡是我新办的。","pinyin":"Zhè zhāng yínháng kǎ shì wǒ xīn bàn de.","vn":"Thẻ ngân hàng này là tôi mới làm."}]},{"hanzi":"球场","pinyin":"qiúchǎng","pos":"dt.","vn":"sân bóng","examples":[{"cn":"他每天下午在球场打篮球。","pinyin":"Tā měitiān xiàwǔ zài qiúchǎng dǎ lánqiú.","vn":"Mỗi chiều anh ấy chơi bóng rổ ở sân bóng."},{"cn":"学校新建了一个足球场。","pinyin":"Xuéxiào xīn jiànle yí ge zúqiúchǎng.","vn":"Trường mới xây một sân bóng đá."},{"cn":"周末球场上有很多人在踢球。","pinyin":"Zhōumò qiúchǎng shang yǒu hěn duō rén zài tīqiú.","vn":"Cuối tuần trên sân bóng có nhiều người đang đá bóng."}]},{"hanzi":"为了","pinyin":"wèile","pos":"giới.","vn":"để, vì","examples":[{"cn":"为了身体健康,他每天锻炼。","pinyin":"Wèile shēntǐ jiànkāng, tā měitiān duànliàn.","vn":"Vì sức khỏe, anh ấy luyện tập mỗi ngày."},{"cn":"为了参加比赛,他练习了很久。","pinyin":"Wèile cānjiā bǐsài, tā liànxíle hěn jiǔ.","vn":"Để tham gia cuộc thi, anh ấy đã luyện tập rất lâu."},{"cn":"她为了孩子放弃了工作。","pinyin":"Tā wèile háizi fàngqìle gōngzuò.","vn":"Vì con, cô ấy đã từ bỏ công việc."}]},{"hanzi":"运动会","pinyin":"yùndònghuì","pos":"dt.","vn":"hội thao, đại hội thể thao","examples":[{"cn":"下周学校要举行运动会。","pinyin":"Xià zhōu xuéxiào yào jǔxíng yùndònghuì.","vn":"Tuần sau trường sẽ tổ chức hội thao."},{"cn":"我参加了学校的运动会。","pinyin":"Wǒ cānjiāle xuéxiào de yùndònghuì.","vn":"Tôi đã tham gia hội thao của trường."},{"cn":"运动会上他得了第一名。","pinyin":"Yùndònghuì shang tā déle dì yī míng.","vn":"Trong hội thao anh ấy đã đạt giải nhất."}]},{"hanzi":"男生","pinyin":"nánshēng","pos":"dt.","vn":"nam sinh","examples":[{"cn":"我们班男生比女生多。","pinyin":"Wǒmen bān nánshēng bǐ nǚshēng duō.","vn":"Lớp chúng tôi nam sinh nhiều hơn nữ sinh."},{"cn":"那个男生篮球打得很好。","pinyin":"Nàge nánshēng lánqiú dǎ de hěn hǎo.","vn":"Nam sinh đó chơi bóng rổ rất giỏi."},{"cn":"男生们正在球场上练习。","pinyin":"Nánshēngmen zhèngzài qiúchǎng shang liànxí.","vn":"Các nam sinh đang luyện tập trên sân bóng."}]},{"hanzi":"练","pinyin":"liàn","pos":"dgt.","vn":"luyện tập","examples":[{"cn":"他每天都练书法。","pinyin":"Tā měitiān dōu liàn shūfǎ.","vn":"Anh ấy ngày nào cũng luyện thư pháp."},{"cn":"为了比赛,她每天练网球。","pinyin":"Wèile bǐsài, tā měitiān liàn wǎngqiú.","vn":"Để thi đấu, mỗi ngày cô ấy luyện quần vợt."},{"cn":"多练几次就会了。","pinyin":"Duō liàn jǐ cì jiù huì le.","vn":"Luyện tập nhiều lần sẽ biết thôi."}]},{"hanzi":"参加","pinyin":"cānjiā","pos":"dgt.","vn":"tham gia","examples":[{"cn":"我想参加这次比赛。","pinyin":"Wǒ xiǎng cānjiā zhè cì bǐsài.","vn":"Tôi muốn tham gia cuộc thi lần này."},{"cn":"他参加了学校的篮球队。","pinyin":"Tā cānjiāle xuéxiào de lánqiúduì.","vn":"Anh ấy đã tham gia đội bóng rổ của trường."},{"cn":"你会参加明天的运动会吗?","pinyin":"Nǐ huì cānjiā míngtiān de yùndònghuì ma?","vn":"Bạn có tham gia hội thao ngày mai không?"}]},{"hanzi":"网球","pinyin":"wǎngqiú","pos":"dt.","vn":"quần vợt, tennis","examples":[{"cn":"他周末常常打网球。","pinyin":"Tā zhōumò chángcháng dǎ wǎngqiú.","vn":"Cuối tuần anh ấy thường chơi quần vợt."},{"cn":"我想学打网球。","pinyin":"Wǒ xiǎng xué dǎ wǎngqiú.","vn":"Tôi muốn học chơi quần vợt."},{"cn":"这个网球场今天没人用。","pinyin":"Zhège wǎngqiúchǎng jīntiān méi rén yòng.","vn":"Sân quần vợt này hôm nay không ai dùng."}]},{"hanzi":"比赛","pinyin":"bǐsài","pos":"dt./dgt.","vn":"cuộc thi đấu; thi đấu","examples":[{"cn":"明天有一场足球比赛。","pinyin":"Míngtiān yǒu yì chǎng zúqiú bǐsài.","vn":"Ngày mai có một trận đấu bóng đá."},{"cn":"我们队赢了这场比赛。","pinyin":"Wǒmen duì yíngle zhè chǎng bǐsài.","vn":"Đội chúng tôi đã thắng trận đấu này."},{"cn":"他正在为比赛做准备。","pinyin":"Tā zhèngzài wèi bǐsài zuò zhǔnbèi.","vn":"Anh ấy đang chuẩn bị cho cuộc thi."}]},{"hanzi":"练习","pinyin":"liànxí","pos":"dgt./dt.","vn":"luyện tập; bài tập","examples":[{"cn":"我每天练习半小时汉字。","pinyin":"Wǒ měitiān liànxí bàn xiǎoshí hànzì.","vn":"Mỗi ngày tôi luyện tập chữ Hán nửa tiếng."},{"cn":"老师给我们布置了练习。","pinyin":"Lǎoshī gěi wǒmen bùzhìle liànxí.","vn":"Thầy giáo giao bài tập cho chúng tôi."},{"cn":"多做练习对学习很有帮助。","pinyin":"Duō zuò liànxí duì xuéxí hěn yǒu bāngzhù.","vn":"Làm nhiều bài tập rất có ích cho việc học."}]},{"hanzi":"好多","pinyin":"hǎoduō","pos":"số.","vn":"rất nhiều","examples":[{"cn":"操场上有好多人在跑步。","pinyin":"Cāochǎng shang yǒu hǎoduō rén zài pǎobù.","vn":"Trên sân vận động có rất nhiều người đang chạy bộ."},{"cn":"我好多年没见他了。","pinyin":"Wǒ hǎoduō nián méi jiàn tā le.","vn":"Tôi nhiều năm rồi không gặp anh ấy."},{"cn":"这件事我问了好多人。","pinyin":"Zhè jiàn shì wǒ wènle hǎoduō rén.","vn":"Việc này tôi đã hỏi rất nhiều người."}]},{"hanzi":"几乎","pinyin":"jīhū","pos":"phó.","vn":"hầu như, gần như","examples":[{"cn":"他几乎每天都来体育馆。","pinyin":"Tā jīhū měitiān dōu lái tǐyùguǎn.","vn":"Anh ấy gần như ngày nào cũng đến nhà thi đấu."},{"cn":"这道题几乎没人做对。","pinyin":"Zhè dào tí jīhū méi rén zuòduì.","vn":"Câu hỏi này gần như không ai làm đúng."},{"cn":"我几乎忘了今天是他的生日。","pinyin":"Wǒ jīhū wàngle jīntiān shì tā de shēngrì.","vn":"Tôi suýt quên hôm nay là sinh nhật của anh ấy."}]},{"hanzi":"只是","pinyin":"zhǐshì","pos":"phó.","vn":"chỉ là, chỉ","examples":[{"cn":"我只是随便问问。","pinyin":"Wǒ zhǐshì suíbiàn wènwen.","vn":"Tôi chỉ là hỏi thử thôi."},{"cn":"他只是有点儿紧张,没别的问题。","pinyin":"Tā zhǐshì yǒudiǎnr jǐnzhāng, méi bié de wèntí.","vn":"Anh ấy chỉ là hơi căng thẳng thôi, không có vấn đề gì khác."},{"cn":"这只是第一次比赛,别太担心。","pinyin":"Zhè zhǐshì dì yī cì bǐsài, bié tài dānxīn.","vn":"Đây chỉ là lần thi đấu đầu tiên thôi, đừng quá lo lắng."}]},{"hanzi":"啤酒","pinyin":"píjiǔ","pos":"dt.","vn":"bia","examples":[{"cn":"他下班后喜欢喝一杯啤酒。","pinyin":"Tā xiàbān hòu xǐhuan hē yì bēi píjiǔ.","vn":"Sau khi tan làm anh ấy thích uống một cốc bia."},{"cn":"这家店的啤酒很有名。","pinyin":"Zhè jiā diàn de píjiǔ hěn yǒumíng.","vn":"Bia của quán này rất nổi tiếng."},{"cn":"我们比赛赢了,一起喝啤酒庆祝吧。","pinyin":"Wǒmen bǐsài yíngle, yìqǐ hē píjiǔ qìngzhù ba.","vn":"Chúng ta đã thắng trận rồi, cùng uống bia ăn mừng nhé."}]},{"hanzi":"回","pinyin":"huí","pos":"lượng.","vn":"lần, việc (dùng cho sự việc)","examples":[{"cn":"这件事我已经说了好几回了。","pinyin":"Zhè jiàn shì wǒ yǐjīng shuōle hǎo jǐ huí le.","vn":"Việc này tôi đã nói mấy lần rồi."},{"cn":"我去过那儿一回。","pinyin":"Wǒ qùguo nàr yì huí.","vn":"Tôi đã đến đó một lần."},{"cn":"这回比赛我们一定要赢。","pinyin":"Zhè huí bǐsài wǒmen yídìng yào yíng.","vn":"Lần thi đấu này chúng ta nhất định phải thắng."}]},{"hanzi":"紧张","pinyin":"jǐnzhāng","pos":"tt.","vn":"căng thẳng, hồi hộp","examples":[{"cn":"比赛前他特别紧张。","pinyin":"Bǐsài qián tā tèbié jǐnzhāng.","vn":"Trước trận đấu anh ấy rất căng thẳng."},{"cn":"别紧张,你一定可以的。","pinyin":"Bié jǐnzhāng, nǐ yídìng kěyǐ de.","vn":"Đừng căng thẳng, bạn chắc chắn làm được."},{"cn":"最近工作太紧张了,我需要休息。","pinyin":"Zuìjìn gōngzuò tài jǐnzhāng le, wǒ xūyào xiūxi.","vn":"Dạo này công việc quá căng thẳng, tôi cần nghỉ ngơi."}]},{"hanzi":"主要","pinyin":"zhǔyào","pos":"tt.","vn":"chủ yếu","examples":[{"cn":"这次比赛主要是为了锻炼身体。","pinyin":"Zhè cì bǐsài zhǔyào shì wèile duànliàn shēntǐ.","vn":"Cuộc thi lần này chủ yếu là để rèn luyện sức khỏe."},{"cn":"他的主要工作是教学生打网球。","pinyin":"Tā de zhǔyào gōngzuò shì jiāo xuésheng dǎ wǎngqiú.","vn":"Công việc chủ yếu của anh ấy là dạy học sinh chơi quần vợt."},{"cn":"失败的主要原因是练习太少。","pinyin":"Shībài de zhǔyào yuányīn shì liànxí tài shǎo.","vn":"Nguyên nhân chủ yếu của thất bại là luyện tập quá ít."}]},{"hanzi":"受到","pinyin":"shòudào","pos":"dgt.","vn":"chịu, bị (tác động)","examples":[{"cn":"他的表演受到了大家的欢迎。","pinyin":"Tā de biǎoyǎn shòudàole dàjiā de huānyíng.","vn":"Màn biểu diễn của anh ấy được mọi người yêu thích."},{"cn":"他在比赛中受到了很大的影响。","pinyin":"Tā zài bǐsài zhōng shòudàole hěn dà de yǐngxiǎng.","vn":"Anh ấy đã chịu ảnh hưởng rất lớn trong trận đấu."},{"cn":"这位运动员受到了很多人的关心。","pinyin":"Zhè wèi yùndòngyuán shòudàole hěn duō rén de guānxīn.","vn":"Vận động viên này nhận được sự quan tâm của rất nhiều người."}]},{"hanzi":"影响","pinyin":"yǐngxiǎng","pos":"dt./dgt.","vn":"ảnh hưởng","examples":[{"cn":"天气对比赛的影响很大。","pinyin":"Tiānqì duì bǐsài de yǐngxiǎng hěn dà.","vn":"Thời tiết ảnh hưởng rất lớn đến trận đấu."},{"cn":"别让这件事影响你的心情。","pinyin":"Bié ràng zhè jiàn shì yǐngxiǎng nǐ de xīnqíng.","vn":"Đừng để việc này ảnh hưởng tới tâm trạng của bạn."},{"cn":"他从小受到父亲的影响,喜欢体育。","pinyin":"Tā cóngxiǎo shòudào fùqīn de yǐngxiǎng, xǐhuan tǐyù.","vn":"Anh ấy từ nhỏ chịu ảnh hưởng của bố nên thích thể thao."}]},{"hanzi":"得分","pinyin":"défēn","pos":"dgt./dt.","vn":"ghi điểm; điểm số","examples":[{"cn":"他在比赛中得分最多。","pinyin":"Tā zài bǐsài zhōng défēn zuì duō.","vn":"Anh ấy ghi điểm nhiều nhất trong trận đấu."},{"cn":"最后一分钟他得分了。","pinyin":"Zuìhòu yì fēnzhōng tā défēn le.","vn":"Ở phút cuối cùng anh ấy đã ghi điểm."},{"cn":"这场比赛的得分很接近。","pinyin":"Zhè chǎng bǐsài de défēn hěn jiējìn.","vn":"Điểm số của trận đấu này rất sít sao."}]},{"hanzi":"体育","pinyin":"tǐyù","pos":"dt.","vn":"thể thao","examples":[{"cn":"他从小就很喜欢体育。","pinyin":"Tā cóngxiǎo jiù hěn xǐhuan tǐyù.","vn":"Anh ấy từ nhỏ đã rất thích thể thao."},{"cn":"今天下午有体育课。","pinyin":"Jīntiān xiàwǔ yǒu tǐyù kè.","vn":"Chiều nay có tiết thể dục."},{"cn":"多参加体育活动对身体好。","pinyin":"Duō cānjiā tǐyù huódòng duì shēntǐ hǎo.","vn":"Tham gia nhiều hoạt động thể thao tốt cho sức khỏe."}]},{"hanzi":"世界","pinyin":"shìjiè","pos":"dt.","vn":"thế giới","examples":[{"cn":"他是世界有名的运动员。","pinyin":"Tā shì shìjiè yǒumíng de yùndòngyuán.","vn":"Anh ấy là vận động viên nổi tiếng thế giới."},{"cn":"这是世界上最大的体育馆。","pinyin":"Zhè shì shìjiè shàng zuì dà de tǐyùguǎn.","vn":"Đây là nhà thi đấu lớn nhất thế giới."},{"cn":"他想去世界各地旅游。","pinyin":"Tā xiǎng qù shìjiè gèdì lǚyóu.","vn":"Anh ấy muốn đi du lịch khắp nơi trên thế giới."}]},{"hanzi":"运动员","pinyin":"yùndòngyuán","pos":"dt.","vn":"vận động viên","examples":[{"cn":"他是一名专业运动员。","pinyin":"Tā shì yì míng zhuānyè yùndòngyuán.","vn":"Anh ấy là một vận động viên chuyên nghiệp."},{"cn":"这位运动员拿了金牌。","pinyin":"Zhè wèi yùndòngyuán nále jīnpái.","vn":"Vận động viên này đã giành huy chương vàng."},{"cn":"运动员们每天都要刻苦训练。","pinyin":"Yùndòngyuánmen měitiān dōu yào kèkǔ xùnliàn.","vn":"Các vận động viên ngày nào cũng phải khổ luyện."}]},{"hanzi":"得到","pinyin":"dédào","pos":"dgt.","vn":"nhận được, đạt được","examples":[{"cn":"他得到了老师的表扬。","pinyin":"Tā dédàole lǎoshī de biǎoyáng.","vn":"Anh ấy được thầy giáo khen ngợi."},{"cn":"这个消息得到了大家的关注。","pinyin":"Zhège xiāoxi dédàole dàjiā de guānzhù.","vn":"Tin này đã nhận được sự quan tâm của mọi người."},{"cn":"经过努力,他终于得到了想要的成绩。","pinyin":"Jīngguò nǔlì, tā zhōngyú dédàole xiǎngyào de chéngjì.","vn":"Qua nỗ lực, cuối cùng anh ấy đã đạt được thành tích mong muốn."}]},{"hanzi":"成绩","pinyin":"chéngjì","pos":"dt.","vn":"thành tích, kết quả","examples":[{"cn":"他这次考试的成绩很好。","pinyin":"Tā zhè cì kǎoshì de chéngjì hěn hǎo.","vn":"Kết quả thi lần này của anh ấy rất tốt."},{"cn":"这位运动员取得了很好的成绩。","pinyin":"Zhè wèi yùndòngyuán qǔdéle hěn hǎo de chéngjì.","vn":"Vận động viên này đã đạt được thành tích rất tốt."},{"cn":"努力练习才能提高成绩。","pinyin":"Nǔlì liànxí cái néng tígāo chéngjì.","vn":"Chăm chỉ luyện tập mới có thể nâng cao thành tích."}]},{"hanzi":"奥运会","pinyin":"Àoyùnhuì","pos":"danh từ riêng","vn":"Thế vận hội Olympic","examples":[{"cn":"奥运会每四年举行一次。","pinyin":"Àoyùnhuì měi sì nián jǔxíng yí cì.","vn":"Thế vận hội Olympic được tổ chức bốn năm một lần."},{"cn":"他梦想有一天能参加奥运会。","pinyin":"Tā mèngxiǎng yǒu yì tiān néng cānjiā Àoyùnhuì.","vn":"Anh ấy mơ ước một ngày nào đó có thể tham gia Olympic."},{"cn":"这位运动员在奥运会上得了金牌。","pinyin":"Zhè wèi yùndòngyuán zài Àoyùnhuì shang déle jīnpái.","vn":"Vận động viên này đã giành huy chương vàng tại Olympic."}]},{"hanzi":"刘长春","pinyin":"Liú Chángchūn","pos":"danh từ riêng","vn":"Lưu Trường Xuân (tên người)","examples":[{"cn":"刘长春是中国第一位参加奥运会的运动员。","pinyin":"Liú Chángchūn shì Zhōngguó dì yī wèi cānjiā Àoyùnhuì de yùndòngyuán.","vn":"Lưu Trường Xuân là vận động viên đầu tiên của Trung Quốc tham gia Olympic."},{"cn":"很多人都知道刘长春的故事。","pinyin":"Hěn duō rén dōu zhīdào Liú Chángchūn de gùshi.","vn":"Nhiều người đều biết câu chuyện về Lưu Trường Xuân."},{"cn":"老师在课上给我们讲了刘长春的事迹。","pinyin":"Lǎoshī zài kè shang gěi wǒmen jiǎngle Liú Chángchūn de shìjì.","vn":"Thầy giáo trong giờ học đã kể cho chúng tôi nghe về sự tích của Lưu Trường Xuân."}]}],"grammar":[{"title":"目的复句 \"为了……，……\" (Câu phức mục đích)","explanation_vn":"Trong câu phức mục đích \"为了……，……\", mệnh đề đứng sau \"为了\" nêu rõ mục đích, còn mệnh đề còn lại nêu hành động được thực hiện để đạt được mục đích đó.","examples":[{"cn":"听说为了准备运动会，你们几个男生每天都练球。","pinyin":"Tīngshuō wèile zhǔnbèi yùndònghuì, nǐmen jǐ gè nánshēng měitiān dōu liàn qiú.","vn":""},{"cn":"为了考上大学，她每天努力学习。","pinyin":"Wèile kǎoshàng dàxué, tā měitiān nǔlì xuéxí.","vn":""},{"cn":"为了早点儿到家，我打算坐飞机回去。","pinyin":"Wèile zǎodiǎnr dào jiā, wǒ dǎsuàn zuò fēijī huíqù.","vn":""}]},{"title":"可能补语 (Bổ ngữ khả năng)","explanation_vn":"Chèn \"得\" hoặc \"不\" vào giữa động từ và bổ ngữ kết quả hoặc bổ ngữ xu hướng để tạo thành bổ ngữ khả năng, biểu thị điều kiện có cho phép thực hiện được kết quả hoặc xu hướng đó hay không. Dạng khẳng định là \"Động từ + 得 + Bổ ngữ\", dạng phủ định là \"Động từ + 不 + Bổ ngữ\", dạng nghi vấn là \"Động từ + 得 + Bổ ngữ + Động từ + 不 + Bổ ngữ\" hoặc \"Động từ + 得 + Bổ ngữ + 吗\".","examples":[{"cn":"打不好没关系。","pinyin":"Dǎ bù hǎo méi guānxi.","vn":""},{"cn":"这本书你看得懂看不懂？","pinyin":"Zhè běn shū nǐ kàn de dǒng kàn bù dǒng?","vn":""},{"cn":"你只有一个星期的时间，学得会游泳吗？","pinyin":"Nǐ zhǐyǒu yí gè xīngqī de shíjiān, xué de huì yóuyǒng ma?","vn":""}]},{"title":"固定格式 \"越A越B\" (Cấu trúc cố định \"越A越B\")","explanation_vn":"Trong câu theo cấu trúc cố định \"越A越B\", A và B đều có thể là cụm động từ hoặc cụm tính từ, hoặc một bên là cụm động từ còn bên kia là cụm tính từ, biểu thị B thay đổi theo sự thay đổi của A.","examples":[{"cn":"今天的足球比赛我越看越着急。","pinyin":"Jīntiān de zúqiú bǐsài wǒ yuè kàn yuè zháojí.","vn":""},{"cn":"妈妈越说，他越不高兴。","pinyin":"Māma yuè shuō, tā yuè bù gāoxìng.","vn":""},{"cn":"我想认识中国朋友，越多越好。","pinyin":"Wǒ xiǎng rènshi Zhōngguó péngyou, yuè duō yuè hǎo.","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"李文","cn":"家月，对不起，我昨天忘了还你校园卡了。","pinyin":"Jiāyuè, duìbuqǐ, wǒ zuótiān wàngle huán nǐ xiàoyuánkǎ le."},{"speaker":"白家月","cn":"没关系。你怎么这么快就过来了？","pinyin":"Méi guānxi. Nǐ zěnme zhème kuài jiù guòlái le?"},{"speaker":"李文","cn":"我正在球场打球呢，接了你的电话就跑过来了。","pinyin":"Wǒ zhèngzài qiúchǎng dǎqiú ne, jiēle nǐ de diànhuà jiù pǎo guòlái le."},{"speaker":"白家月","cn":"听说为了准备运动会，你们几个男生每天都练球。","pinyin":"Tīngshuō wèile zhǔnbèi yùndònghuì, nǐmen jǐ gè nánshēng měitiān dōu liàn qiú."},{"speaker":"李文","cn":"是啊！你打算参加运动会吗？","pinyin":"Shì a! Nǐ dǎsuàn cānjiā yùndònghuì ma?"},{"speaker":"白家月","cn":"我想参加网球比赛，最近一直在练习。","pinyin":"Wǒ xiǎng cānjiā wǎngqiú bǐsài, zuìjìn yìzhí zài liànxí."},{"speaker":"李文","cn":"好，到时候我去看你的比赛。","pinyin":"Hǎo, dào shíhou wǒ qù kàn nǐ de bǐsài."}],"translation_vn":"Lý Văn: Gia Nguyệt, xin lỗi, hôm qua mình quên trả thẻ khuôn viên trường cho bạn rồi.\nBạch Gia Nguyệt: Không sao. Sao bạn đến nhanh vậy?\nLý Văn: Mình đang đánh bóng ở sân thì nhận được điện thoại của bạn nên chạy ngay tới.\nBạch Gia Nguyệt: Nghe nói để chuẩn bị cho hội thao, mấy bạn nam các cậu ngày nào cũng luyện bóng.\nLý Văn: Đúng vậy! Bạn định tham gia hội thao à?\nBạch Gia Nguyệt: Mình muốn tham gia thi đấu quần vợt, gần đây vẫn đang luyện tập.\nLý Văn: Được, đến lúc đó mình sẽ đi xem trận đấu của bạn.","audio_dialogue":"9-1.mp3","audio_vocab":"9-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"李文","cn":"家月，你跟我们一起打羽毛球吧？","pinyin":"Jiāyuè, nǐ gēn wǒmen yìqǐ dǎ yǔmáoqiú ba?"},{"speaker":"白家月","cn":"我好多年没打羽毛球了，几乎忘了怎么打了。","pinyin":"Wǒ hǎoduō nián méi dǎ yǔmáoqiú le, jīhū wàngle zěnme dǎ le."},{"speaker":"李文","cn":"不是比赛，打不好没关系。","pinyin":"Bú shì bǐsài, dǎ bù hǎo méi guānxi."},{"speaker":"白家月","cn":"这么多同学一起打，如果总是接不住球，就太不好意思了。","pinyin":"Zhème duō tóngxué yìqǐ dǎ, rúguǒ zǒngshì jiē bú zhù qiú, jiù tài bù hǎoyìsi le."},{"speaker":"李文","cn":"你想得太多了！大家打球只是为了锻炼身体。","pinyin":"Nǐ xiǎng de tài duō le! Dàjiā dǎqiú zhǐshì wèile duànliàn shēntǐ."},{"speaker":"白家月","cn":"我先自己练练吧，下周再跟你们一起打。","pinyin":"Wǒ xiān zìjǐ liàn liàn ba, xiàzhōu zài gēn nǐmen yìqǐ dǎ."},{"speaker":"李文","cn":"我在教天中打羽毛球，你可以过来跟我们一起练。","pinyin":"Wǒ zài jiāo Tiānzhōng dǎ yǔmáoqiú, nǐ kěyǐ guòlái gēn wǒmen yìqǐ liàn."}],"translation_vn":"Lý Văn: Gia Nguyệt, bạn chơi cầu lông cùng bọn mình nhé?\nBạch Gia Nguyệt: Mình đã nhiều năm không chơi cầu lông rồi, gần như quên mất cách chơi rồi.\nLý Văn: Không phải thi đấu đâu, chơi không giỏi cũng không sao.\nBạch Gia Nguyệt: Nhiều bạn cùng chơi với nhau như vậy, nếu mình cứ đỡ không được bóng thì ngại lắm.\nLý Văn: Bạn nghĩ nhiều quá rồi! Mọi người chơi bóng chỉ là để rèn luyện sức khỏe thôi.\nBạch Gia Nguyệt: Mình tự luyện tập một mình trước đã, tuần sau sẽ chơi cùng các bạn.\nLý Văn: Mình đang dạy Thiên Trung chơi cầu lông, bạn có thể qua luyện tập cùng chúng mình.","audio_dialogue":"9-3.mp3","audio_vocab":"9-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"陈天中","cn":"足球比赛已经开始了，快过来看吧！","pinyin":"Zúqiú bǐsài yǐjīng kāishǐ le, kuài guòlái kàn ba!"},{"speaker":"李文","cn":"你们先看，冰箱里有啤酒和饮料，我去拿一下。","pinyin":"Nǐmen xiān kàn, bīngxiāng li yǒu píjiǔ hé yǐnliào, wǒ qù ná yíxià."},{"speaker":"白家月","cn":"今天怎么回事？总是踢不进去！","pinyin":"Jīntiān zěnme huí shì? Zǒngshì tī bú jìnqù!"},{"speaker":"陈天中","cn":"几个老球员生病了，新球员第一次参加这么重要的比赛，太紧张了。","pinyin":"Jǐ gè lǎo qiúyuán shēngbìng le, xīn qiúyuán dì-yī cì cānjiā zhème zhòngyào de bǐsài, tài jǐnzhāng le."},{"speaker":"李文","cn":"是啊，主要的球员没参加比赛，所以大家也都受到影响了。","pinyin":"Shì a, zhǔyào de qiúyuán méi cānjiā bǐsài, suǒyǐ dàjiā yě dōu shòudào yǐngxiǎng le."},{"speaker":"白家月","cn":"越看越着急。我不看了，你们告诉我得分吧。","pinyin":"Yuè kàn yuè zháojí. Wǒ bú kàn le, nǐmen gàosù wǒ défēn ba."}],"translation_vn":"Trần Thiên Trung: Trận bóng đá đã bắt đầu rồi, mau lại xem đi!\nLý Văn: Các bạn xem trước đi, trong tủ lạnh có bia và nước giải khát, mình đi lấy một chút.\nBạch Gia Nguyệt: Hôm nay là chuyện gì vậy? Cứ sút mãi không vào!\nTrần Thiên Trung: Mấy cầu thủ kỳ cựu bị ốm rồi, cầu thủ mới lần đầu tham gia trận đấu quan trọng thế này nên căng thẳng quá.\nLý Văn: Đúng vậy, cầu thủ chủ lực không tham gia thi đấu, nên mọi người cũng đều bị ảnh hưởng.\nBạch Gia Nguyệt: Càng xem càng sốt ruột. Mình không xem nữa, các bạn cứ báo điểm số cho mình nhé.","audio_dialogue":"9-5.mp3","audio_vocab":"9-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"我喜欢看体育比赛，最爱看的就是奥运会。","pinyin":"Wǒ xǐhuan kàn tǐyù bǐsài, zuì ài kàn de jiùshì Àoyùnhuì."},{"speaker":"","cn":"奥运会是世界上影响最大的体育比赛。","pinyin":"Àoyùnhuì shì shìjiè shang yǐngxiǎng zuì dà de tǐyù bǐsài."},{"speaker":"","cn":"从1896年到2024年，每次奥运会都有非常多的运动员参加。","pinyin":"Cóng yī bā jiǔ liù nián dào èr líng èr sì nián, měi cì Àoyùnhuì dōu yǒu fēicháng duō de yùndòngyuán cānjiā."},{"speaker":"","cn":"第一位参加奥运会的中国运动员是刘长春，他1932年参加了100米和200米短跑比赛。","pinyin":"Dì-yī wèi cānjiā Àoyùnhuì de Zhōngguó yùndòngyuán shì Liú Chángchūn, tā yī jiǔ sān èr nián cānjiāle yìbǎi mǐ hé èrbǎi mǐ duǎnpǎo bǐsài."},{"speaker":"","cn":"虽然他没有得到好成绩，但是他让世界认识了中国。","pinyin":"Suīrán tā méiyǒu dédào hǎo chéngjì, dànshì tā ràng shìjiè rènshile Zhōngguó."}],"translation_vn":"Tôi thích xem các cuộc thi đấu thể thao, thích xem nhất là Thế vận hội Olympic. Olympic là cuộc thi đấu thể thao có ảnh hưởng lớn nhất trên thế giới. Từ năm 1896 đến năm 2024, mỗi kỳ Olympic đều có rất nhiều vận động viên tham gia. Vận động viên Trung Quốc đầu tiên tham gia Olympic là Lưu Trường Xuân, năm 1932 ông đã tham gia các nội dung chạy nước rút 100 mét và 200 mét. Tuy ông không đạt được thành tích tốt, nhưng ông đã giúp thế giới biết đến Trung Quốc.","audio_dialogue":"9-7.mp3","audio_vocab":"9-8.mp3"}]},{"id":10,"title_cn":"你明天再把书还给我","title_pinyin":"Nǐ Míngtiān Zài Bǎ Shū Huán Gěi Wǒ","title_vn":"Ngày mai bạn trả sách lại cho tôi nhé","goals":["Có thể nghe hiểu và giới thiệu về tình hình học tập và thi cử.","Có thể nghe hiểu và trao đổi về những vấn đề gặp phải trong học tập, chia sẻ phương pháp học tập.","Nắm vững cách dùng câu chữ \"把\" (1), có thể miêu tả sự thay đổi vị trí của sự vật.","Hiểu biết về hệ thống giáo dục và chế độ chuyển cấp học của Trung Quốc."],"vocab":[{"hanzi":"数学","pinyin":"shùxué","pos":"dt.","vn":"môn Toán, toán học","examples":[{"cn":"我数学考试考得不太好。","pinyin":"Wǒ shùxué kǎoshì kǎo de bú tài hǎo.","vn":"Tôi thi toán không được tốt lắm."},{"cn":"他对数学特别感兴趣。","pinyin":"Tā duì shùxué tèbié gǎn xìngqù.","vn":"Anh ấy đặc biệt hứng thú với môn toán."},{"cn":"数学老师讲的题我都听懂了。","pinyin":"Shùxué lǎoshī jiǎng de tí wǒ dōu tīngdǒng le.","vn":"Bài giảng của thầy toán tôi đều hiểu cả."}]},{"hanzi":"认真","pinyin":"rènzhēn","pos":"tt.","vn":"nghiêm túc, cẩn thận, chăm chú","examples":[{"cn":"他学习很认真。","pinyin":"Tā xuéxí hěn rènzhēn.","vn":"Anh ấy học rất nghiêm túc."},{"cn":"你要认真听老师讲课。","pinyin":"Nǐ yào rènzhēn tīng lǎoshī jiǎngkè.","vn":"Em phải chăm chú nghe thầy giảng bài."},{"cn":"她做事一直很认真。","pinyin":"Tā zuòshì yìzhí hěn rènzhēn.","vn":"Cô ấy làm việc luôn rất cẩn thận."}]},{"hanzi":"笔记","pinyin":"bǐjì","pos":"dt.","vn":"ghi chú, vở ghi chép","examples":[{"cn":"我把笔记记在本子上了。","pinyin":"Wǒ bǎ bǐjì jì zài běnzi shang le.","vn":"Tôi đã ghi chú vào vở rồi."},{"cn":"你能借我看看你的笔记吗？","pinyin":"Nǐ néng jiè wǒ kànkan nǐ de bǐjì ma?","vn":"Bạn có thể cho tôi xem vở ghi chép của bạn không?"},{"cn":"上课的时候我喜欢做笔记。","pinyin":"Shàngkè de shíhou wǒ xǐhuan zuò bǐjì.","vn":"Khi học tôi thích ghi chép lại."}]},{"hanzi":"清楚","pinyin":"qīngchu","pos":"tt./dgt.","vn":"rõ ràng; hiểu rõ","examples":[{"cn":"他说话说得很清楚。","pinyin":"Tā shuōhuà shuō de hěn qīngchu.","vn":"Anh ấy nói chuyện rất rõ ràng."},{"cn":"这个问题我还不太清楚。","pinyin":"Zhège wèntí wǒ hái bú tài qīngchu.","vn":"Vấn đề này tôi vẫn chưa hiểu rõ lắm."},{"cn":"请你讲清楚一点，好吗？","pinyin":"Qǐng nǐ jiǎng qīngchu yìdiǎn, hǎo ma?","vn":"Bạn nói rõ hơn một chút được không?"}]},{"hanzi":"黑板","pinyin":"hēibǎn","pos":"dt.","vn":"bảng đen","examples":[{"cn":"老师在黑板上写了几个字。","pinyin":"Lǎoshī zài hēibǎn shang xiěle jǐ ge zì.","vn":"Thầy giáo viết mấy chữ lên bảng đen."},{"cn":"请你看一下黑板上的内容。","pinyin":"Qǐng nǐ kàn yíxià hēibǎn shang de nèiróng.","vn":"Mời bạn xem nội dung trên bảng."},{"cn":"黑板上的字太小了，我看不清楚。","pinyin":"Hēibǎn shang de zì tài xiǎo le, wǒ kàn bu qīngchu.","vn":"Chữ trên bảng nhỏ quá, tôi nhìn không rõ."}]},{"hanzi":"把","pinyin":"bǎ","pos":"giới.","vn":"(giới từ đưa tân ngữ lên trước động từ)","examples":[{"cn":"请把门关上。","pinyin":"Qǐng bǎ mén guānshang.","vn":"Làm ơn đóng cửa lại."},{"cn":"我把作业做完了。","pinyin":"Wǒ bǎ zuòyè zuòwán le.","vn":"Tôi đã làm xong bài tập rồi."},{"cn":"你把这本书放在桌子上吧。","pinyin":"Nǐ bǎ zhè běn shū fàng zài zhuōzi shang ba.","vn":"Bạn để quyển sách này lên bàn đi."}]},{"hanzi":"作业","pinyin":"zuòyè","pos":"dt.","vn":"bài tập","examples":[{"cn":"今天的作业有点多。","pinyin":"Jīntiān de zuòyè yǒudiǎn duō.","vn":"Bài tập hôm nay hơi nhiều."},{"cn":"你做完作业了吗？","pinyin":"Nǐ zuòwán zuòyè le ma?","vn":"Bạn làm xong bài tập chưa?"},{"cn":"我每天晚上都要写作业。","pinyin":"Wǒ měitiān wǎnshang dōu yào xiě zuòyè.","vn":"Tối nào tôi cũng phải làm bài tập."}]},{"hanzi":"遍","pinyin":"biàn","pos":"lượng.","vn":"lần (chỉ một lượt hành động trọn vẹn)","examples":[{"cn":"这篇课文我读了三遍。","pinyin":"Zhè piān kèwén wǒ dúle sān biàn.","vn":"Bài khóa này tôi đã đọc ba lần."},{"cn":"你再说一遍，我没听清楚。","pinyin":"Nǐ zài shuō yí biàn, wǒ méi tīng qīngchu.","vn":"Bạn nói lại một lần nữa, tôi nghe chưa rõ."},{"cn":"这部电影我看了两遍。","pinyin":"Zhè bù diànyǐng wǒ kànle liǎng biàn.","vn":"Bộ phim này tôi đã xem hai lần."}]},{"hanzi":"提高","pinyin":"tígāo","pos":"dgt.","vn":"nâng cao, cải thiện","examples":[{"cn":"他最近努力提高自己的汉语水平。","pinyin":"Tā zuìjìn nǔlì tígāo zìjǐ de Hànyǔ shuǐpíng.","vn":"Gần đây anh ấy nỗ lực nâng cao trình độ tiếng Trung của mình."},{"cn":"多练习可以提高你的口语。","pinyin":"Duō liànxí kěyǐ tígāo nǐ de kǒuyǔ.","vn":"Luyện tập nhiều có thể nâng cao khẩu ngữ của bạn."},{"cn":"这个方法能提高学习效率。","pinyin":"Zhège fāngfǎ néng tígāo xuéxí xiàolǜ.","vn":"Phương pháp này có thể nâng cao hiệu quả học tập."}]},{"hanzi":"历史","pinyin":"lìshǐ","pos":"dt.","vn":"lịch sử","examples":[{"cn":"我对中国历史很感兴趣。","pinyin":"Wǒ duì Zhōngguó lìshǐ hěn gǎn xìngqù.","vn":"Tôi rất hứng thú với lịch sử Trung Quốc."},{"cn":"他是历史老师。","pinyin":"Tā shì lìshǐ lǎoshī.","vn":"Anh ấy là giáo viên lịch sử."},{"cn":"这座城市有很长的历史。","pinyin":"Zhè zuò chéngshì yǒu hěn cháng de lìshǐ.","vn":"Thành phố này có lịch sử rất lâu đời."}]},{"hanzi":"难","pinyin":"nán","pos":"tt.","vn":"khó","examples":[{"cn":"这个问题太难了。","pinyin":"Zhège wèntí tài nán le.","vn":"Vấn đề này khó quá."},{"cn":"汉语语法不太难。","pinyin":"Hànyǔ yǔfǎ bú tài nán.","vn":"Ngữ pháp tiếng Trung không khó lắm."},{"cn":"这次考试的题很难。","pinyin":"Zhè cì kǎoshì de tí hěn nán.","vn":"Đề thi lần này khó quá."}]},{"hanzi":"要求","pinyin":"yāoqiú","pos":"dt./dgt.","vn":"yêu cầu","examples":[{"cn":"老师对我们的要求很严格。","pinyin":"Lǎoshī duì wǒmen de yāoqiú hěn yángé.","vn":"Thầy giáo yêu cầu chúng tôi rất nghiêm khắc."},{"cn":"这份工作的要求很高。","pinyin":"Zhè fèn gōngzuò de yāoqiú hěn gāo.","vn":"Công việc này có yêu cầu rất cao."},{"cn":"公司提出了新的要求。","pinyin":"Gōngsī tíchūle xīn de yāoqiú.","vn":"Công ty đã đưa ra yêu cầu mới."}]},{"hanzi":"差","pinyin":"chà","pos":"tt./dgt.","vn":"kém; thiếu","examples":[{"cn":"他的成绩比以前差多了。","pinyin":"Tā de chéngjì bǐ yǐqián chà duō le.","vn":"Thành tích của anh ấy kém hơn trước nhiều."},{"cn":"还差五分钟就上课了。","pinyin":"Hái chà wǔ fēnzhōng jiù shàngkè le.","vn":"Còn thiếu năm phút nữa là vào học."},{"cn":"我们还差一个人。","pinyin":"Wǒmen hái chà yí ge rén.","vn":"Chúng tôi vẫn còn thiếu một người."}]},{"hanzi":"复习","pinyin":"fùxí","pos":"dgt.","vn":"ôn tập","examples":[{"cn":"考试前我要好好复习。","pinyin":"Kǎoshì qián wǒ yào hǎohāo fùxí.","vn":"Trước khi thi tôi phải ôn tập thật kỹ."},{"cn":"你复习完这一课了吗？","pinyin":"Nǐ fùxí wán zhè yí kè le ma?","vn":"Bạn ôn xong bài này chưa?"},{"cn":"我们每天都要复习生词。","pinyin":"Wǒmen měitiān dōu yào fùxí shēngcí.","vn":"Hằng ngày chúng tôi đều phải ôn từ mới."}]},{"hanzi":"外语","pinyin":"wàiyǔ","pos":"dt.","vn":"ngoại ngữ","examples":[{"cn":"学好一门外语不容易。","pinyin":"Xuéhǎo yì mén wàiyǔ bù róngyì.","vn":"Học giỏi một ngoại ngữ không dễ dàng."},{"cn":"他会说三种外语。","pinyin":"Tā huì shuō sān zhǒng wàiyǔ.","vn":"Anh ấy biết nói ba thứ tiếng ngoại ngữ."},{"cn":"我大学的专业是外语。","pinyin":"Wǒ dàxué de zhuānyè shì wàiyǔ.","vn":"Chuyên ngành đại học của tôi là ngoại ngữ."}]},{"hanzi":"当然","pinyin":"dāngrán","pos":"phó.","vn":"đương nhiên, tất nhiên","examples":[{"cn":"当然可以，没问题。","pinyin":"Dāngrán kěyǐ, méi wèntí.","vn":"Đương nhiên được, không vấn đề gì."},{"cn":"这当然是真的。","pinyin":"Zhè dāngrán shì zhēn de.","vn":"Đương nhiên đây là sự thật."},{"cn":"他当然会来参加聚会。","pinyin":"Tā dāngrán huì lái cānjiā jùhuì.","vn":"Anh ấy tất nhiên sẽ đến dự buổi tiệc."}]},{"hanzi":"遇到","pinyin":"yùdào","pos":"dgt.","vn":"gặp phải, gặp","examples":[{"cn":"我在路上遇到了老朋友。","pinyin":"Wǒ zài lùshang yùdàole lǎo péngyou.","vn":"Tôi gặp được người bạn cũ trên đường."},{"cn":"学习汉语难免会遇到困难。","pinyin":"Xuéxí Hànyǔ nánmiǎn huì yùdào kùnnan.","vn":"Học tiếng Trung khó tránh khỏi gặp khó khăn."},{"cn":"他最近遇到了不少麻烦。","pinyin":"Tā zuìjìn yùdàole bùshǎo máfan.","vn":"Gần đây anh ấy gặp phải không ít phiền toái."}]},{"hanzi":"办公室","pinyin":"bàngōngshì","pos":"dt.","vn":"văn phòng","examples":[{"cn":"经理在办公室等你。","pinyin":"Jīnglǐ zài bàngōngshì děng nǐ.","vn":"Giám đốc đang đợi bạn ở văn phòng."},{"cn":"我把文件放在办公室了。","pinyin":"Wǒ bǎ wénjiàn fàng zài bàngōngshì le.","vn":"Tôi để tài liệu ở văn phòng rồi."},{"cn":"他每天在办公室工作八个小时。","pinyin":"Tā měitiān zài bàngōngshì gōngzuò bā ge xiǎoshí.","vn":"Mỗi ngày anh ấy làm việc tám tiếng ở văn phòng."}]},{"hanzi":"页","pinyin":"yè","pos":"lượng.","vn":"trang","examples":[{"cn":"请打开书的第十页。","pinyin":"Qǐng dǎkāi shū de dì shí yè.","vn":"Mời mở sách đến trang mười."},{"cn":"这本书一共有两百页。","pinyin":"Zhè běn shū yígòng yǒu liǎngbǎi yè.","vn":"Quyển sách này có tổng cộng hai trăm trang."},{"cn":"我昨天看了三十页书。","pinyin":"Wǒ zuótiān kànle sānshí yè shū.","vn":"Hôm qua tôi đã đọc ba mươi trang sách."}]},{"hanzi":"对话","pinyin":"duìhuà","pos":"dgt.","vn":"hội thoại, đối thoại","examples":[{"cn":"我们来练习一下对话。","pinyin":"Wǒmen lái liànxí yíxià duìhuà.","vn":"Chúng ta cùng luyện tập hội thoại nhé."},{"cn":"这段对话很有意思。","pinyin":"Zhè duàn duìhuà hěn yǒu yìsi.","vn":"Đoạn hội thoại này rất thú vị."},{"cn":"老师让我们背这篇对话。","pinyin":"Lǎoshī ràng wǒmen bèi zhè piān duìhuà.","vn":"Thầy giáo yêu cầu chúng tôi học thuộc bài hội thoại này."}]},{"hanzi":"明白","pinyin":"míngbai","pos":"dgt./tt.","vn":"hiểu, hiểu rõ","examples":[{"cn":"我明白你的意思了。","pinyin":"Wǒ míngbai nǐ de yìsi le.","vn":"Tôi hiểu ý của bạn rồi."},{"cn":"这个道理他还不明白。","pinyin":"Zhège dàolǐ tā hái bù míngbai.","vn":"Đạo lý này anh ấy vẫn chưa hiểu."},{"cn":"你讲得很清楚，我都明白了。","pinyin":"Nǐ jiǎng de hěn qīngchu, wǒ dōu míngbai le.","vn":"Bạn giảng rất rõ ràng, tôi hiểu hết rồi."}]},{"hanzi":"讲","pinyin":"jiǎng","pos":"dgt.","vn":"giảng, giải thích","examples":[{"cn":"老师正在讲语法。","pinyin":"Lǎoshī zhèngzài jiǎng yǔfǎ.","vn":"Thầy giáo đang giảng ngữ pháp."},{"cn":"你能给我讲讲这个故事吗？","pinyin":"Nǐ néng gěi wǒ jiǎngjiang zhège gùshi ma?","vn":"Bạn có thể kể cho tôi nghe câu chuyện này không?"},{"cn":"他讲得很清楚，大家都懂了。","pinyin":"Tā jiǎng de hěn qīngchu, dàjiā dōu dǒng le.","vn":"Anh ấy giảng rất rõ ràng, mọi người đều hiểu rồi."}]},{"hanzi":"句","pinyin":"jù","pos":"lượng.","vn":"câu (lượng từ dùng cho câu nói)","examples":[{"cn":"他说了一句很有意思的话。","pinyin":"Tā shuōle yí jù hěn yǒu yìsi de huà.","vn":"Anh ấy nói một câu rất thú vị."},{"cn":"这句话是什么意思？","pinyin":"Zhè jù huà shì shénme yìsi?","vn":"Câu này có nghĩa là gì?"},{"cn":"我只会说几句中文。","pinyin":"Wǒ zhǐ huì shuō jǐ jù Zhōngwén.","vn":"Tôi chỉ biết nói vài câu tiếng Trung."}]},{"hanzi":"句子","pinyin":"jùzi","pos":"dt.","vn":"câu","examples":[{"cn":"请用这个词造一个句子。","pinyin":"Qǐng yòng zhège cí zào yí ge jùzi.","vn":"Hãy dùng từ này đặt một câu."},{"cn":"这个句子我不太明白。","pinyin":"Zhège jùzi wǒ bú tài míngbai.","vn":"Câu này tôi không hiểu lắm."},{"cn":"他写的句子很通顺。","pinyin":"Tā xiě de jùzi hěn tōngshùn.","vn":"Câu anh ấy viết rất trôi chảy."}]},{"hanzi":"年级","pinyin":"niánjí","pos":"dt.","vn":"khối lớp, cấp lớp","examples":[{"cn":"我弟弟上三年级。","pinyin":"Wǒ dìdi shàng sān niánjí.","vn":"Em trai tôi học lớp ba."},{"cn":"你是几年级的学生？","pinyin":"Nǐ shì jǐ niánjí de xuésheng?","vn":"Bạn là học sinh lớp mấy?"},{"cn":"这是高年级的课程。","pinyin":"Zhè shì gāo niánjí de kèchéng.","vn":"Đây là chương trình học của khối lớp lớn."}]},{"hanzi":"后年","pinyin":"hòunián","pos":"dt.","vn":"năm kia (năm sau năm sau)","examples":[{"cn":"我们打算后年结婚。","pinyin":"Wǒmen dǎsuàn hòunián jiéhūn.","vn":"Chúng tôi dự định năm kia kết hôn."},{"cn":"后年他就大学毕业了。","pinyin":"Hòunián tā jiù dàxué bìyè le.","vn":"Năm kia anh ấy sẽ tốt nghiệp đại học."},{"cn":"我后年想去中国留学。","pinyin":"Wǒ hòunián xiǎng qù Zhōngguó liúxué.","vn":"Năm kia tôi muốn đi du học Trung Quốc."}]},{"hanzi":"一般","pinyin":"yìbān","pos":"tt.","vn":"bình thường, thông thường","examples":[{"cn":"他的汉语水平一般。","pinyin":"Tā de Hànyǔ shuǐpíng yìbān.","vn":"Trình độ tiếng Trung của anh ấy bình thường."},{"cn":"我一般七点起床。","pinyin":"Wǒ yìbān qī diǎn qǐchuáng.","vn":"Tôi thường dậy lúc bảy giờ."},{"cn":"这家餐厅的菜一般般。","pinyin":"Zhè jiā cāntīng de cài yìbānbān.","vn":"Món ăn của nhà hàng này bình thường thôi."}]},{"hanzi":"努力","pinyin":"nǔlì","pos":"tt./dgt.","vn":"nỗ lực, cố gắng","examples":[{"cn":"他一直很努力学习。","pinyin":"Tā yìzhí hěn nǔlì xuéxí.","vn":"Anh ấy luôn nỗ lực học tập."},{"cn":"只要努力，就会有进步。","pinyin":"Zhǐyào nǔlì, jiù huì yǒu jìnbù.","vn":"Chỉ cần cố gắng thì sẽ có tiến bộ."},{"cn":"大家都在努力工作。","pinyin":"Dàjiā dōu zài nǔlì gōngzuò.","vn":"Mọi người đều đang nỗ lực làm việc."}]}],"grammar":[{"title":"\"把\"字句 (1) - Câu chữ \"把\" (1)","explanation_vn":"Câu chữ \"把\" biểu thị việc thực hiện một hành động tương ứng lên một người hoặc sự vật xác định, khiến nó xảy ra sự thay đổi về vị trí. Phó từ phủ định \"不/没\" và động từ năng nguyện phải đặt trước \"把\". Cấu trúc cơ bản: Chủ ngữ + (不/没/Động từ năng nguyện) + 把 + Tân ngữ + Động từ + 在/到 + Địa điểm.","examples":[{"cn":"我会把这些题都记在本子上。","pinyin":"Wǒ huì bǎ zhèxiē tí dōu jì zài běnzi shang.","vn":""},{"cn":"老师把作业本放到桌子上了。","pinyin":"Lǎoshī bǎ zuòyèběn fàng dào zhuōzi shang le.","vn":""},{"cn":"你不能把名字写在这里。","pinyin":"Nǐ bù néng bǎ míngzi xiě zài zhèlǐ.","vn":""}]},{"title":"固定格式 \"在……上/中/下\" - Cấu trúc cố định \"在……上/中/下\"","explanation_vn":"Giới từ \"在\" kết hợp với các phương vị từ \"上\" \"中\" \"下\" tạo thành cấu trúc \"在……上/中/下\", dùng để biểu thị phạm vi, thời gian, điều kiện, v.v. Cấu trúc \"在 + danh từ/cụm danh từ + 上\" biểu thị phạm vi, phương diện. Cấu trúc \"在……中\" biểu thị môi trường hoặc thời gian mà hành động xảy ra hay trạng thái tồn tại. Cấu trúc \"在 + động từ song âm tiết có định ngữ + 下\" biểu thị điều kiện.","examples":[{"cn":"在学习上，遇到什么问题都可以问我。","pinyin":"Zài xuéxí shang, yùdào shénme wèntí dōu kěyǐ wèn wǒ.","vn":""},{"cn":"在工作上，他总是能给我很多帮助。","pinyin":"Zài gōngzuò shang, tā zǒngshì néng gěi wǒ hěn duō bāngzhù.","vn":""},{"cn":"在比赛中，他得分最高。","pinyin":"Zài bǐsài zhōng, tā défēn zuì gāo.","vn":""},{"cn":"在假期中，我认识了几个新朋友。","pinyin":"Zài jiàqī zhōng, wǒ rènshi le jǐ gè xīn péngyou.","vn":""},{"cn":"在她的影响下，我开始喜欢拍照。","pinyin":"Zài tā de yǐngxiǎng xià, wǒ kāishǐ xǐhuan pāizhào.","vn":""},{"cn":"在老师的帮助下，我的成绩提高很快。","pinyin":"Zài lǎoshī de bāngzhù xià, wǒ de chéngjì tígāo hěn kuài.","vn":""}]},{"title":"\"把\"字句 (2) - Câu chữ \"把\" (2)","explanation_vn":"Câu chữ \"把\" ở dạng này biểu thị việc thông qua hành động khiến một sự vật xác định có sự chuyển giao về mặt quan hệ (từ người này sang người khác). Cấu trúc cơ bản: Chủ ngữ + 把 + Tân ngữ 1 + Động từ + 给 + Tân ngữ 2.","examples":[{"cn":"你明天再把书还给我。","pinyin":"Nǐ míngtiān zài bǎ shū huán gěi wǒ.","vn":""},{"cn":"我把礼物送给她了。","pinyin":"Wǒ bǎ lǐwù sòng gěi tā le.","vn":""},{"cn":"请你把这本书带给老师。","pinyin":"Qǐng nǐ bǎ zhè běn shū dài gěi lǎoshī.","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"同学","cn":"你的数学越来越好，能不能介绍一下学习方法？","pinyin":"Nǐ de shùxué yuè lái yuè hǎo, néng bu néng jièshào yíxià xuéxí fāngfǎ?"},{"speaker":"刘小雪","cn":"没有什么特别的方法，认真听课，认真记笔记。","pinyin":"Méiyǒu shénme tèbié de fāngfǎ, rènzhēn tīngkè, rènzhēn jì bǐjì."},{"speaker":"同学","cn":"我看过你的笔记，记得非常清楚。","pinyin":"Wǒ kàn guò nǐ de bǐjì, jì de fēicháng qīngchu."},{"speaker":"刘小雪","cn":"老师写在黑板上的题都很重要，所以我会把这些题都记在本子上。","pinyin":"Lǎoshī xiě zài hēibǎn shang de tí dōu hěn zhòngyào, suǒyǐ wǒ huì bǎ zhèxiē tí dōu jì zài běnzi shang."},{"speaker":"同学","cn":"你说得对。我没有记笔记的习惯。","pinyin":"Nǐ shuō de duì. Wǒ méiyǒu jì bǐjì de xíguàn."},{"speaker":"刘小雪","cn":"笔记挺重要的，我每天写作业以前，都要看一遍。","pinyin":"Bǐjì tǐng zhòngyào de, wǒ měitiān xiě zuòyè yǐqián, dōu yào kàn yí biàn."},{"speaker":"同学","cn":"这个方法真好！我以后也试试，希望能提高成绩。","pinyin":"Zhège fāngfǎ zhēn hǎo! Wǒ yǐhòu yě shìshi, xīwàng néng tígāo chéngjì."}],"translation_vn":"Bạn học: Toán của bạn ngày càng tốt lên, bạn có thể giới thiệu một chút phương pháp học tập không?\nLưu Tiểu Tuyết: Không có phương pháp gì đặc biệt cả, chỉ là nghe giảng chăm chú, ghi chép cẩn thận.\nBạn học: Mình đã xem vở ghi chép của bạn, ghi rất rõ ràng.\nLưu Tiểu Tuyết: Những bài thầy cô viết trên bảng đều rất quan trọng, nên mình ghi hết những bài đó vào vở.\nBạn học: Bạn nói đúng. Mình không có thói quen ghi chép.\nLưu Tiểu Tuyết: Vở ghi chép khá quan trọng, trước khi làm bài tập mỗi ngày mình đều xem lại một lượt.\nBạn học: Phương pháp này hay thật! Sau này mình cũng sẽ thử, hy vọng có thể nâng cao thành tích.","audio_dialogue":"10-1.mp3","audio_vocab":"10-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"同学","cn":"小雪，昨天的考试，你考得怎么样？","pinyin":"Xiǎoxuě, zuótiān de kǎoshì, nǐ kǎo de zěnmeyàng?"},{"speaker":"刘小雪","cn":"我觉得历史有点儿难，你呢？","pinyin":"Wǒ juéde lìshǐ yǒudiǎnr nán, nǐ ne?"},{"speaker":"同学","cn":"数学考试我没看清楚要求，做错了好几个题，考得挺差的。","pinyin":"Shùxué kǎoshì wǒ méi kàn qīngchu yāoqiú, zuò cuò le hǎo jǐ gè tí, kǎo de tǐng chà de."},{"speaker":"刘小雪","cn":"明天还有考试呢，别想那么多了，先复习外语吧。","pinyin":"Míngtiān hái yǒu kǎoshì ne, bié xiǎng nàme duō le, xiān fùxí wàiyǔ ba."},{"speaker":"同学","cn":"外语作业里有几个问题，我可以问问你吗？","pinyin":"Wàiyǔ zuòyè lǐ yǒu jǐ gè wèntí, wǒ kěyǐ wènwen nǐ ma?"},{"speaker":"刘小雪","cn":"当然可以。在学习上，遇到什么问题都可以问我。","pinyin":"Dāngrán kěyǐ. Zài xuéxí shang, yùdào shénme wèntí dōu kěyǐ wèn wǒ."},{"speaker":"刘小雪","cn":"不好意思，这几个题我也不会。咱们还是一起去办公室问问李老师吧。","pinyin":"Bù hǎoyìsi, zhè jǐ gè tí wǒ yě bú huì. Zánmen háishi yìqǐ qù bàngōngshì wènwen Lǐ lǎoshī ba."}],"translation_vn":"Bạn học: Tiểu Tuyết, bài thi hôm qua, bạn thi thế nào?\nLưu Tiểu Tuyết: Mình thấy môn Lịch sử hơi khó, còn bạn thì sao?\nBạn học: Bài thi Toán mình không đọc kỹ yêu cầu, làm sai mấy câu, thi khá tệ.\nLưu Tiểu Tuyết: Ngày mai còn có bài thi nữa đấy, đừng nghĩ nhiều quá, ôn ngoại ngữ trước đi.\nBạn học: Trong bài tập ngoại ngữ có mấy câu hỏi, mình có thể hỏi bạn không?\nLưu Tiểu Tuyết: Tất nhiên được rồi. Trong học tập, gặp vấn đề gì đều có thể hỏi mình.\n(……)\nLưu Tiểu Tuyết: Xin lỗi nhé, mấy câu này mình cũng không biết làm. Hay là chúng ta cùng đến văn phòng hỏi cô Lý vậy.","audio_dialogue":"10-3.mp3","audio_vocab":"10-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"同学","cn":"李老师，书上有几个问题，我们想问问您。","pinyin":"Lǐ lǎoshī, shū shang yǒu jǐ gè wèntí, wǒmen xiǎng wènwen nín."},{"speaker":"李老师","cn":"好，坐下说吧，哪个题不会？","pinyin":"Hǎo, zuò xià shuō ba, nǎge tí bú huì?"},{"speaker":"同学","cn":"书上第五页的这个对话我看不懂，小雪也不明白。","pinyin":"Shū shang dì-wǔ yè de zhège duìhuà wǒ kàn bu dǒng, Xiǎoxuě yě bù míngbai."},{"speaker":"李老师","cn":"我课上讲过这几句话，再给你们讲一遍。","pinyin":"Wǒ kè shang jiǎng guò zhè jǐ jù huà, zài gěi nǐmen jiǎng yí biàn."},{"speaker":"","cn":"（李老师给学生讲题。）","pinyin":"(Lǐ lǎoshī gěi xuésheng jiǎng tí.)"},{"speaker":"同学","cn":"我终于懂了。这些句子一点儿也不难。","pinyin":"Wǒ zhōngyú dǒng le. Zhèxiē jùzi yìdiǎnr yě bù nán."},{"speaker":"刘小雪","cn":"我也明白了，谢谢您，李老师。","pinyin":"Wǒ yě míngbai le, xièxie nín, Lǐ lǎoshī."},{"speaker":"李老师","cn":"我这本书上还有几个练习，你们回家也做一做，明天再把书还给我。","pinyin":"Wǒ zhè běn shū shang hái yǒu jǐ gè liànxí, nǐmen huí jiā yě zuò yi zuò, míngtiān zài bǎ shū huán gěi wǒ."}],"translation_vn":"Bạn học: Cô Lý ơi, trong sách có vài câu hỏi, chúng em muốn hỏi cô.\nCô Lý: Được, ngồi xuống nói đi, câu nào không hiểu?\nBạn học: Đoạn hội thoại ở trang 5 trong sách em không hiểu, Tiểu Tuyết cũng không hiểu.\nCô Lý: Cô đã giảng mấy câu này trên lớp rồi, cô sẽ giảng lại cho các em một lần nữa.\n(Cô Lý giảng bài cho học sinh.)\nBạn học: Cuối cùng em cũng hiểu rồi. Những câu này không khó chút nào.\nLưu Tiểu Tuyết: Em cũng hiểu rồi ạ, cảm ơn cô Lý.\nCô Lý: Quyển sách này của cô còn vài bài luyện tập nữa, các em về nhà làm thử nhé, mai lại trả sách cho cô.","audio_dialogue":"10-5.mp3","audio_vocab":"10-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"家月姐姐：","pinyin":"Jiāyuè jiějie:"},{"speaker":"","cn":"你最近怎么样？忙不忙？","pinyin":"Nǐ zuìjìn zěnmeyàng? Máng bu máng?"},{"speaker":"","cn":"我现在上初中二年级，学习越来越忙，后年就要考高中了。","pinyin":"Wǒ xiànzài shàng chūzhōng èr niánjí, xuéxí yuè lái yuè máng, hòunián jiù yào kǎo gāozhōng le."},{"speaker":"","cn":"中国的学校一般是小学六年，初中三年，高中三年。","pinyin":"Zhōngguó de xuéxiào yìbān shì xiǎoxué liù nián, chūzhōng sān nián, gāozhōng sān nián."},{"speaker":"","cn":"妈妈说想考上好大学，就得上一个好高中；为了考上好高中，初中就得有一个不错的成绩，所以我现在非常努力。","pinyin":"Māma shuō xiǎng kǎo shàng hǎo dàxué, jiù děi shàng yí gè hǎo gāozhōng; wèile kǎo shàng hǎo gāozhōng, chūzhōng jiù děi yǒu yí gè búcuò de chéngjì, suǒyǐ wǒ xiànzài fēicháng nǔlì."},{"speaker":"","cn":"家月姐姐，你知道吗？在你的影响下，我也开始喜欢拍照了。","pinyin":"Jiāyuè jiějie, nǐ zhīdào ma? Zài nǐ de yǐngxiǎng xià, wǒ yě kāishǐ xǐhuan pāizhào le."},{"speaker":"","cn":"下次你再来北京，我给你看看我照的照片。","pinyin":"Xiàcì nǐ zài lái Běijīng, wǒ gěi nǐ kànkan wǒ zhào de zhàopiàn."}],"translation_vn":"Chị Gia Nguyệt ơi: Dạo này chị thế nào? Có bận không? Em hiện đang học lớp hai trung học cơ sở, việc học ngày càng bận rộn, hai năm nữa là em phải thi vào trung học phổ thông rồi. Trường học ở Trung Quốc thường là tiểu học 6 năm, trung học cơ sở 3 năm, trung học phổ thông 3 năm. Mẹ em nói muốn thi đỗ đại học tốt thì phải học một trường trung học phổ thông tốt; để thi đỗ được trường trung học phổ thông tốt, ở bậc trung học cơ sở phải có thành tích khá mới được, vì vậy hiện giờ em đang rất nỗ lực học tập. Chị Gia Nguyệt biết không? Dưới ảnh hưởng của chị, em cũng bắt đầu thích chụp ảnh rồi đấy. Lần sau chị đến Bắc Kinh, em sẽ cho chị xem những bức ảnh em chụp nhé.","audio_dialogue":"10-7.mp3","audio_vocab":"10-8.mp3"}]},{"id":11,"title_cn":"看来我没办法解决这个问题","title_pinyin":"Kànlái wǒ méi bànfǎ jiějué zhège wèntí","title_vn":"Có vẻ như tôi không có cách nào giải quyết vấn đề này","goals":["Có thể nghe hiểu và trao đổi về tình hình công việc.","Có thể nghe hiểu và bàn luận về lựa chọn nghề nghiệp và cảm nhận về công việc.","Nắm vững cách dùng \"看来\" (có vẻ như), có thể suy đoán và phân tích sự việc."],"vocab":[{"hanzi":"会议","pinyin":"huìyì","pos":"dt.","vn":"cuộc họp, hội nghị","examples":[{"cn":"明天上午有一个重要会议。","pinyin":"Míngtiān shàngwǔ yǒu yí ge zhòngyào huìyì.","vn":"Sáng mai có một cuộc họp quan trọng."},{"cn":"会议还没开始。","pinyin":"Huìyì hái méi kāishǐ.","vn":"Cuộc họp vẫn chưa bắt đầu."},{"cn":"他因为开会议迟到了。","pinyin":"Tā yīnwèi kāi huìyì chídào le.","vn":"Anh ấy đến muộn vì phải họp."}]},{"hanzi":"经理","pinyin":"jīnglǐ","pos":"dt.","vn":"giám đốc, quản lý","examples":[{"cn":"我们公司的经理很年轻。","pinyin":"Wǒmen gōngsī de jīnglǐ hěn niánqīng.","vn":"Giám đốc công ty chúng tôi còn rất trẻ."},{"cn":"经理叫我去他办公室一下。","pinyin":"Jīnglǐ jiào wǒ qù tā bàngōngshì yíxià.","vn":"Giám đốc gọi tôi đến văn phòng của ông ấy một chút."},{"cn":"这件事要问一下经理。","pinyin":"Zhè jiàn shì yào wèn yíxià jīnglǐ.","vn":"Việc này phải hỏi giám đốc một chút."}]},{"hanzi":"开会","pinyin":"kāihuì","pos":"dgt.","vn":"họp, mở cuộc họp","examples":[{"cn":"他正在开会，不能接电话。","pinyin":"Tā zhèngzài kāihuì, bù néng jiē diànhuà.","vn":"Anh ấy đang họp nên không nghe điện thoại được."},{"cn":"我们明天下午开会。","pinyin":"Wǒmen míngtiān xiàwǔ kāihuì.","vn":"Chiều mai chúng tôi họp."},{"cn":"老板叫大家九点开会。","pinyin":"Lǎobǎn jiào dàjiā jiǔ diǎn kāihuì.","vn":"Sếp bảo mọi người chín giờ họp."}]},{"hanzi":"后天","pinyin":"hòutiān","pos":"dt.","vn":"ngày kia","examples":[{"cn":"后天是我的生日。","pinyin":"Hòutiān shì wǒ de shēngrì.","vn":"Ngày kia là sinh nhật của tôi."},{"cn":"我们后天出发去北京。","pinyin":"Wǒmen hòutiān chūfā qù Běijīng.","vn":"Ngày kia chúng tôi xuất phát đi Bắc Kinh."},{"cn":"后天有一个重要的考试。","pinyin":"Hòutiān yǒu yí ge zhòngyào de kǎoshì.","vn":"Ngày kia có một kỳ thi quan trọng."}]},{"hanzi":"地点","pinyin":"dìdiǎn","pos":"dt.","vn":"địa điểm","examples":[{"cn":"会议的地点改了。","pinyin":"Huìyì de dìdiǎn gǎi le.","vn":"Địa điểm họp đã thay đổi."},{"cn":"请告诉我见面的地点。","pinyin":"Qǐng gàosu wǒ jiànmiàn de dìdiǎn.","vn":"Làm ơn cho tôi biết địa điểm gặp mặt."},{"cn":"这个地点很难找。","pinyin":"Zhège dìdiǎn hěn nán zhǎo.","vn":"Địa điểm này rất khó tìm."}]},{"hanzi":"室","pinyin":"shì","pos":"dt.","vn":"phòng","examples":[{"cn":"办公室的灯坏了。","pinyin":"Bàngōngshì de dēng huài le.","vn":"Đèn văn phòng bị hỏng rồi."},{"cn":"他在教室里写作业。","pinyin":"Tā zài jiàoshì li xiě zuòyè.","vn":"Anh ấy đang làm bài tập trong phòng học."},{"cn":"这是会议室。","pinyin":"Zhè shì huìyìshì.","vn":"Đây là phòng họp."}]},{"hanzi":"发","pinyin":"fā","pos":"dgt.","vn":"gửi, phát","examples":[{"cn":"我给你发了一封邮件。","pinyin":"Wǒ gěi nǐ fāle yì fēng yóujiàn.","vn":"Tôi đã gửi cho bạn một email."},{"cn":"请把文件发给我。","pinyin":"Qǐng bǎ wénjiàn fā gěi wǒ.","vn":"Làm ơn gửi tài liệu cho tôi."},{"cn":"他发了一条消息给我。","pinyin":"Tā fāle yì tiáo xiāoxi gěi wǒ.","vn":"Anh ấy gửi cho tôi một tin nhắn."}]},{"hanzi":"笔记本（电脑）","pinyin":"bǐjìběn (diànnǎo)","pos":"dt.","vn":"máy tính xách tay","examples":[{"cn":"我的笔记本电脑坏了。","pinyin":"Wǒ de bǐjìběn diànnǎo huài le.","vn":"Máy tính xách tay của tôi bị hỏng rồi."},{"cn":"他每天都带着笔记本电脑上班。","pinyin":"Tā měitiān dōu dàizhe bǐjìběn diànnǎo shàngbān.","vn":"Hằng ngày anh ấy đều mang laptop đi làm."},{"cn":"这台笔记本电脑很轻。","pinyin":"Zhè tái bǐjìběn diànnǎo hěn qīng.","vn":"Chiếc laptop này rất nhẹ."}]},{"hanzi":"或者","pinyin":"huòzhě","pos":"liên.","vn":"hoặc, hoặc là","examples":[{"cn":"你可以喝茶或者咖啡。","pinyin":"Nǐ kěyǐ hē chá huòzhě kāfēi.","vn":"Bạn có thể uống trà hoặc cà phê."},{"cn":"我们明天或者后天去看电影。","pinyin":"Wǒmen míngtiān huòzhě hòutiān qù kàn diànyǐng.","vn":"Mai hoặc ngày kia chúng ta đi xem phim."},{"cn":"你打电话或者发短信都可以。","pinyin":"Nǐ dǎ diànhuà huòzhě fā duǎnxìn dōu kěyǐ.","vn":"Bạn gọi điện hoặc nhắn tin đều được."}]},{"hanzi":"声音","pinyin":"shēngyīn","pos":"dt.","vn":"âm thanh","examples":[{"cn":"外面的声音太吵了。","pinyin":"Wàimiàn de shēngyīn tài chǎo le.","vn":"Tiếng ồn bên ngoài ồn quá."},{"cn":"她的声音很好听。","pinyin":"Tā de shēngyīn hěn hǎotīng.","vn":"Giọng nói của cô ấy rất hay."},{"cn":"请把声音开大一点。","pinyin":"Qǐng bǎ shēngyīn kāi dà yìdiǎn.","vn":"Làm ơn mở âm thanh to hơn một chút."}]},{"hanzi":"看来","pinyin":"kànlái","pos":"dgt.","vn":"có vẻ như, xem ra","examples":[{"cn":"看来他今天不会来了。","pinyin":"Kànlái tā jīntiān bú huì lái le.","vn":"Xem ra hôm nay anh ấy sẽ không đến."},{"cn":"看来外面下雨了。","pinyin":"Kànlái wàimiàn xiàyǔ le.","vn":"Xem ra bên ngoài trời mưa rồi."},{"cn":"看来这件事没那么简单。","pinyin":"Kànlái zhè jiàn shì méi nàme jiǎndān.","vn":"Xem ra việc này không đơn giản như vậy."}]},{"hanzi":"办法","pinyin":"bànfǎ","pos":"dt.","vn":"cách, biện pháp","examples":[{"cn":"我们得想个办法解决这个问题。","pinyin":"Wǒmen děi xiǎng ge bànfǎ jiějué zhège wèntí.","vn":"Chúng ta phải nghĩ cách giải quyết vấn đề này."},{"cn":"这个办法不错。","pinyin":"Zhège bànfǎ búcuò.","vn":"Cách này khá hay đấy."},{"cn":"他总是有很多办法。","pinyin":"Tā zǒngshì yǒu hěn duō bànfǎ.","vn":"Anh ấy lúc nào cũng có nhiều cách."}]},{"hanzi":"解决","pinyin":"jiějué","pos":"dgt.","vn":"giải quyết","examples":[{"cn":"这个问题已经解决了。","pinyin":"Zhège wèntí yǐjīng jiějué le.","vn":"Vấn đề này đã được giải quyết rồi."},{"cn":"我们一起想办法解决困难。","pinyin":"Wǒmen yìqǐ xiǎng bànfǎ jiějué kùnnan.","vn":"Chúng ta cùng nghĩ cách giải quyết khó khăn."},{"cn":"这件事不好解决。","pinyin":"Zhè jiàn shì bù hǎo jiějué.","vn":"Việc này không dễ giải quyết."}]},{"hanzi":"只能","pinyin":"zhǐ néng","pos":"","vn":"chỉ có thể","examples":[{"cn":"现在下雨了，我们只能待在家里。","pinyin":"Xiànzài xiàyǔ le, wǒmen zhǐ néng dāi zài jiā li.","vn":"Bây giờ trời mưa rồi, chúng tôi chỉ có thể ở nhà."},{"cn":"票已经卖完了，我们只能明天再来。","pinyin":"Piào yǐjīng màiwán le, wǒmen zhǐ néng míngtiān zài lái.","vn":"Vé đã bán hết rồi, chúng tôi chỉ có thể mai đến lại."},{"cn":"他只能说一点点英语。","pinyin":"Tā zhǐ néng shuō yìdiǎndiǎn Yīngyǔ.","vn":"Anh ấy chỉ có thể nói một chút tiếng Anh."}]},{"hanzi":"别人","pinyin":"biérén","pos":"đt.","vn":"người khác","examples":[{"cn":"不要总是和别人比较。","pinyin":"Búyào zǒngshì hé biérén bǐjiào.","vn":"Đừng luôn so sánh mình với người khác."},{"cn":"这是别人的东西，不是我的。","pinyin":"Zhè shì biérén de dōngxi, bú shì wǒ de.","vn":"Đây là đồ của người khác, không phải của tôi."},{"cn":"他很关心别人的感受。","pinyin":"Tā hěn guānxīn biérén de gǎnshòu.","vn":"Anh ấy rất quan tâm đến cảm nhận của người khác."}]},{"hanzi":"请假","pinyin":"qǐngjià","pos":"dgt.","vn":"xin nghỉ phép","examples":[{"cn":"我今天身体不舒服，想请假。","pinyin":"Wǒ jīntiān shēntǐ bù shūfu, xiǎng qǐngjià.","vn":"Hôm nay tôi không khỏe, muốn xin nghỉ phép."},{"cn":"他向老板请了三天假。","pinyin":"Tā xiàng lǎobǎn qǐngle sān tiān jià.","vn":"Anh ấy đã xin sếp nghỉ phép ba ngày."},{"cn":"你可以帮我向老师请假吗？","pinyin":"Nǐ kěyǐ bāng wǒ xiàng lǎoshī qǐngjià ma?","vn":"Bạn có thể giúp tôi xin nghỉ với thầy giáo không?"}]},{"hanzi":"同事","pinyin":"tóngshì","pos":"dt.","vn":"đồng nghiệp","examples":[{"cn":"他是我的同事。","pinyin":"Tā shì wǒ de tóngshì.","vn":"Anh ấy là đồng nghiệp của tôi."},{"cn":"我和同事一起吃午饭。","pinyin":"Wǒ hé tóngshì yìqǐ chī wǔfàn.","vn":"Tôi ăn trưa cùng đồng nghiệp."},{"cn":"我们同事之间关系很好。","pinyin":"Wǒmen tóngshì zhī jiān guānxì hěn hǎo.","vn":"Quan hệ giữa các đồng nghiệp của chúng tôi rất tốt."}]},{"hanzi":"休假","pinyin":"xiūjià","pos":"dgt.","vn":"nghỉ phép, nghỉ mát","examples":[{"cn":"他下周要去休假。","pinyin":"Tā xià zhōu yào qù xiūjià.","vn":"Tuần sau anh ấy sẽ đi nghỉ phép."},{"cn":"我打算休假的时候去旅游。","pinyin":"Wǒ dǎsuàn xiūjià de shíhou qù lǚyóu.","vn":"Tôi định đi du lịch khi nghỉ phép."},{"cn":"经理最近在休假。","pinyin":"Jīnglǐ zuìjìn zài xiūjià.","vn":"Gần đây giám đốc đang nghỉ phép."}]},{"hanzi":"怕","pinyin":"pà","pos":"dgt.","vn":"sợ, e ngại","examples":[{"cn":"我有点怕黑。","pinyin":"Wǒ yǒudiǎn pà hēi.","vn":"Tôi hơi sợ bóng tối."},{"cn":"她怕一个人在家。","pinyin":"Tā pà yí ge rén zài jiā.","vn":"Cô ấy sợ ở nhà một mình."},{"cn":"别怕，有我在呢。","pinyin":"Bié pà, yǒu wǒ zài ne.","vn":"Đừng sợ, có tôi ở đây mà."}]},{"hanzi":"邮箱","pinyin":"yóuxiāng","pos":"dt.","vn":"hộp thư điện tử, email","examples":[{"cn":"请把文件发到我的邮箱。","pinyin":"Qǐng bǎ wénjiàn fā dào wǒ de yóuxiāng.","vn":"Làm ơn gửi tài liệu vào hộp thư của tôi."},{"cn":"我的邮箱里有很多邮件。","pinyin":"Wǒ de yóuxiāng li yǒu hěn duō yóujiàn.","vn":"Hộp thư của tôi có rất nhiều email."},{"cn":"你能告诉我你的邮箱地址吗？","pinyin":"Nǐ néng gàosu wǒ nǐ de yóuxiāng dìzhǐ ma?","vn":"Bạn có thể cho tôi biết địa chỉ email của bạn không?"}]},{"hanzi":"老张","pinyin":"Lǎo Zhāng","pos":"danh từ riêng","vn":"Lão Trương (tên người)","examples":[{"cn":"老张今天没来上班。","pinyin":"Lǎo Zhāng jīntiān méi lái shàngbān.","vn":"Hôm nay Lão Trương không đi làm."},{"cn":"这是老张的办公室。","pinyin":"Zhè shì Lǎo Zhāng de bàngōngshì.","vn":"Đây là văn phòng của Lão Trương."},{"cn":"老张，好久不见！","pinyin":"Lǎo Zhāng, hǎojiǔ bújiàn!","vn":"Lão Trương, lâu rồi không gặp!"}]},{"hanzi":"愿意","pinyin":"yuànyì","pos":"đtnn.","vn":"sẵn lòng, đồng ý","examples":[{"cn":"我愿意帮你的忙。","pinyin":"Wǒ yuànyì bāng nǐ de máng.","vn":"Tôi sẵn lòng giúp đỡ bạn."},{"cn":"他不愿意参加这次活动。","pinyin":"Tā bú yuànyì cānjiā zhè cì huódòng.","vn":"Anh ấy không muốn tham gia hoạt động lần này."},{"cn":"你愿意跟我一起去吗？","pinyin":"Nǐ yuànyì gēn wǒ yìqǐ qù ma?","vn":"Bạn có sẵn lòng đi cùng tôi không?"}]},{"hanzi":"城市","pinyin":"chéngshì","pos":"dt.","vn":"thành phố","examples":[{"cn":"这是一座很美的城市。","pinyin":"Zhè shì yí zuò hěn měi de chéngshì.","vn":"Đây là một thành phố rất đẹp."},{"cn":"我喜欢大城市的生活。","pinyin":"Wǒ xǐhuan dà chéngshì de shēnghuó.","vn":"Tôi thích cuộc sống ở thành phố lớn."},{"cn":"他从一个小城市搬到了北京。","pinyin":"Tā cóng yí ge xiǎo chéngshì bāndàole Běijīng.","vn":"Anh ấy đã chuyển từ một thành phố nhỏ đến Bắc Kinh."}]},{"hanzi":"离开","pinyin":"líkāi","pos":"dgt.","vn":"rời khỏi, rời xa","examples":[{"cn":"他昨天离开了这座城市。","pinyin":"Tā zuótiān líkāile zhè zuò chéngshì.","vn":"Hôm qua anh ấy đã rời khỏi thành phố này."},{"cn":"请不要离开这里。","pinyin":"Qǐng búyào líkāi zhèlǐ.","vn":"Làm ơn đừng rời khỏi đây."},{"cn":"她很舍不得离开家人。","pinyin":"Tā hěn shěbudé líkāi jiārén.","vn":"Cô ấy rất không nỡ rời xa người nhà."}]},{"hanzi":"机会","pinyin":"jīhuì","pos":"dt.","vn":"cơ hội","examples":[{"cn":"这是一个很好的机会。","pinyin":"Zhè shì yí ge hěn hǎo de jīhuì.","vn":"Đây là một cơ hội rất tốt."},{"cn":"我没有机会跟他说话。","pinyin":"Wǒ méiyǒu jīhuì gēn tā shuōhuà.","vn":"Tôi không có cơ hội nói chuyện với anh ấy."},{"cn":"不要错过这次机会。","pinyin":"Búyào cuòguò zhè cì jīhuì.","vn":"Đừng bỏ lỡ cơ hội lần này."}]},{"hanzi":"生活","pinyin":"shēnghuó","pos":"dt./dgt.","vn":"cuộc sống; sống","examples":[{"cn":"他的生活很简单。","pinyin":"Tā de shēnghuó hěn jiǎndān.","vn":"Cuộc sống của anh ấy rất đơn giản."},{"cn":"我们的生活越来越好了。","pinyin":"Wǒmen de shēnghuó yuèláiyuè hǎo le.","vn":"Cuộc sống của chúng tôi ngày càng tốt hơn."},{"cn":"她喜欢这里的生活。","pinyin":"Tā xǐhuan zhèlǐ de shēnghuó.","vn":"Cô ấy thích cuộc sống ở đây."}]},{"hanzi":"为","pinyin":"wèi","pos":"giới.","vn":"vì, cho","examples":[{"cn":"他为我们准备了晚饭。","pinyin":"Tā wèi wǒmen zhǔnbèile wǎnfàn.","vn":"Anh ấy đã chuẩn bị bữa tối cho chúng tôi."},{"cn":"大家都为她高兴。","pinyin":"Dàjiā dōu wèi tā gāoxìng.","vn":"Mọi người đều vui mừng cho cô ấy."},{"cn":"老师为学生们操心。","pinyin":"Lǎoshī wèi xuéshengmen cāoxīn.","vn":"Thầy giáo lo lắng cho các học sinh."}]},{"hanzi":"或","pinyin":"huò","pos":"liên.","vn":"hoặc","examples":[{"cn":"你可以坐车或走路去。","pinyin":"Nǐ kěyǐ zuòchē huò zǒulù qù.","vn":"Bạn có thể đi xe hoặc đi bộ đến."},{"cn":"明天或后天都可以。","pinyin":"Míngtiān huò hòutiān dōu kěyǐ.","vn":"Mai hoặc ngày kia đều được."},{"cn":"他喜欢喝茶或咖啡。","pinyin":"Tā xǐhuan hē chá huò kāfēi.","vn":"Anh ấy thích uống trà hoặc cà phê."}]}],"grammar":[{"title":"\"还是\" và \"或者\" (So sánh cách dùng \"还是\" và \"或者\")","explanation_vn":"\"还是\" thường dùng trong câu nghi vấn, đưa ra hai hoặc nhiều lựa chọn, yêu cầu người nghe chọn một trong số đó. \"或者\" chủ yếu dùng trong câu trần thuật, không dùng trong câu nghi vấn.","examples":[{"cn":"我们用会议室的电脑还是自己的笔记本电脑？","pinyin":"Wǒmen yòng huìyìshì de diànnǎo háishi zìjǐ de bǐjìběn diànnǎo?","vn":""},{"cn":"我们今天去、明天去还是后天去？","pinyin":"Wǒmen jīntiān qù, míngtiān qù háishi hòutiān qù?","vn":""},{"cn":"会议室的电脑或者自己的电脑都可以。","pinyin":"Huìyìshì de diànnǎo huòzhě zìjǐ de diànnǎo dōu kěyǐ.","vn":""},{"cn":"你可以坐地铁或者打车去学校。","pinyin":"Nǐ kěyǐ zuò dìtiě huòzhě dǎchē qù xuéxiào.","vn":""}]},{"title":"Cụm từ cố định \"看来\"","explanation_vn":"Cụm từ cố định \"看来\" đứng trước một kết luận, biểu thị người nói đưa ra phân tích hoặc suy đoán về tình huống hiện tại thông qua quan sát, suy nghĩ.","examples":[{"cn":"看来我没办法解决这个问题。","pinyin":"Kànlái wǒ méi bànfǎ jiějué zhège wèntí.","vn":""},{"cn":"这么晚了，看来他今天不会来了。","pinyin":"Zhème wǎn le, kànlái tā jīntiān bú huì lái le.","vn":""},{"cn":"电梯坏了，看来咱们只能走下去了。","pinyin":"Diàntī huài le, kànlái zánmen zhǐ néng zǒu xiàqù le.","vn":""}]},{"title":"Câu chữ \"把\" (3)","explanation_vn":"Câu chữ \"把\" biểu thị một hành động tác động lên người hoặc vật xác định, tạo ra một kết quả nào đó. Cấu trúc cơ bản: \"Chủ ngữ + 把 + Tân ngữ + Động từ + Bổ ngữ kết quả\".","examples":[{"cn":"我跟您一起把这些工作做完。","pinyin":"Wǒ gēn nín yìqǐ bǎ zhèxiē gōngzuò zuò wán.","vn":""},{"cn":"妈妈把衣服洗干净了。","pinyin":"Māma bǎ yīfu xǐ gānjìng le.","vn":""},{"cn":"他还没把笔记本电脑接好呢。","pinyin":"Tā hái méi bǎ bǐjìběn diànnǎo jiē hǎo ne.","vn":""}]},{"title":"Cấu trúc cố định \"对……来说\"","explanation_vn":"Cấu trúc cố định \"对……来说\" (đối với... mà nói) chỉ rõ đối tượng mà quan điểm, cảm nhận hoặc tình huống được nêu ra hướng tới.","examples":[{"cn":"对我来说，生活也很重要，我不愿意为工作或学习离开家人。","pinyin":"Duì wǒ lái shuō, shēnghuó yě hěn zhòngyào, wǒ bú yuànyì wèi gōngzuò huò xuéxí líkāi jiārén.","vn":""},{"cn":"对她来说，学习汉语很有意思。","pinyin":"Duì tā lái shuō, xuéxí Hànyǔ hěn yǒuyìsi.","vn":""},{"cn":"对孩子来说，玩也是一种学习。","pinyin":"Duì háizi lái shuō, wán yě shì yì zhǒng xuéxí.","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"王一雪","cn":"会议下午几点开始？","pinyin":"Huìyì xiàwǔ jǐ diǎn kāishǐ?"},{"speaker":"杨同乐","cn":"今天下午经理不在，不开会了。","pinyin":"Jīntiān xiàwǔ jīnglǐ bú zài, bù kāihuì le."},{"speaker":"王一雪","cn":"那什么时候开会？","pinyin":"Nà shénme shíhou kāihuì?"},{"speaker":"杨同乐","cn":"后天上午十点，会议地点换到第一会议室。我正要给大家发邮件。","pinyin":"Hòutiān shàngwǔ shí diǎn, huìyì dìdiǎn huàn dào dì yī huìyìshì. Wǒ zhèng yào gěi dàjiā fā yóujiàn."},{"speaker":"王一雪","cn":"开会的时候，我们用会议室的电脑还是自己的笔记本电脑？","pinyin":"Kāihuì de shíhou, wǒmen yòng huìyìshì de diànnǎo háishi zìjǐ de bǐjìběn diànnǎo?"},{"speaker":"杨同乐","cn":"会议室的电脑或者自己的电脑都可以。","pinyin":"Huìyìshì de diànnǎo huòzhě zìjǐ de diànnǎo dōu kěyǐ."},{"speaker":"王一雪","cn":"那到时候咱们早点儿过去，你帮我把电脑接好吧。","pinyin":"Nà dào shíhou zánmen zǎo diǎnr guòqù, nǐ bāng wǒ bǎ diànnǎo jiē hǎo ba."}],"translation_vn":"Vương Nhất Tuyết: Mấy giờ chiều nay bắt đầu họp?\nDương Đồng Nhạc: Chiều nay giám đốc không có mặt, nên không họp nữa.\nVương Nhất Tuyết: Vậy bao giờ thì họp?\nDương Đồng Nhạc: Mười giờ sáng ngày kia, địa điểm họp đổi sang phòng họp số 1. Tôi đang định gửi email cho mọi người.\nVương Nhất Tuyết: Lúc họp, chúng ta dùng máy tính của phòng họp hay máy tính xách tay của mình?\nDương Đồng Nhạc: Dùng máy tính của phòng họp hay máy tính của mình đều được.\nVương Nhất Tuyết: Vậy lúc đó chúng ta đến sớm một chút, anh giúp tôi cài đặt máy tính nhé.","audio_dialogue":"11-1.mp3","audio_vocab":"11-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"王一雪","cn":"电脑接好了吗？","pinyin":"Diànnǎo jiē hǎo le ma?"},{"speaker":"杨同乐","cn":"已经接好了，您开机看看有没有问题。","pinyin":"Yǐjīng jiē hǎo le, nín kāijī kànkan yǒu méiyǒu wèntí."},{"speaker":"王一雪","cn":"现在什么都看不见。","pinyin":"Xiànzài shénme dōu kàn bu jiàn."},{"speaker":"杨同乐","cn":"我检查一下哪里出问题了……您再试一下。","pinyin":"Wǒ jiǎnchá yíxià nǎlǐ chū wèntí le... nín zài shì yíxià."},{"speaker":"王一雪","cn":"看见了，但是听不见声音。","pinyin":"Kànjiàn le, dànshì tīng bu jiàn shēngyīn."},{"speaker":"杨同乐","cn":"现在呢？","pinyin":"Xiànzài ne?"},{"speaker":"王一雪","cn":"听得见声音，但是声音有点儿小，听不清楚。","pinyin":"Tīng de jiàn shēngyīn, dànshì shēngyīn yǒudiǎnr xiǎo, tīng bu qīngchu."},{"speaker":"杨同乐","cn":"看来我没办法解决这个问题，只能找别人来帮帮忙了。","pinyin":"Kànlái wǒ méi bànfǎ jiějué zhège wèntí, zhǐ néng zhǎo biérén lái bāngbangmáng le."}],"translation_vn":"Vương Nhất Tuyết: Máy tính đã kết nối xong chưa?\nDương Đồng Nhạc: Kết nối xong rồi, chị mở máy xem có vấn đề gì không.\nVương Nhất Tuyết: Bây giờ không nhìn thấy gì cả.\nDương Đồng Nhạc: Để tôi kiểm tra xem chỗ nào bị lỗi... chị thử lại lần nữa xem.\nVương Nhất Tuyết: Nhìn thấy rồi, nhưng không nghe thấy âm thanh.\nDương Đồng Nhạc: Bây giờ thì sao?\nVương Nhất Tuyết: Nghe thấy âm thanh rồi, nhưng âm thanh hơi nhỏ, nghe không rõ.\nDương Đồng Nhạc: Có vẻ như tôi không có cách nào giải quyết vấn đề này, chỉ có thể tìm người khác đến giúp thôi.","audio_dialogue":"11-3.mp3","audio_vocab":"11-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"王一雪","cn":"同乐，你看见老张了吗？","pinyin":"Tóng Lè, nǐ kànjiàn Lǎo Zhāng le ma?"},{"speaker":"杨同乐","cn":"老张没来。他说家里有点儿事，所以请假了。","pinyin":"Lǎo Zhāng méi lái. Tā shuō jiālǐ yǒudiǎnr shì, suǒyǐ qǐngjià le."},{"speaker":"王一雪","cn":"好几个同事都休假了，开会前这么多工作我怕干不完。","pinyin":"Hǎo jǐ gè tóngshì dōu xiūjià le, kāihuì qián zhème duō gōngzuò wǒ pà gàn bu wán."},{"speaker":"杨同乐","cn":"十二点多了，咱们先去吃饭吧。吃完饭，我跟您一起把这些工作做完。","pinyin":"Shí'èr diǎn duō le, zánmen xiān qù chīfàn ba. Chī wán fàn, wǒ gēn nín yìqǐ bǎ zhèxiē gōngzuò zuò wán."},{"speaker":"王一雪","cn":"你先去吃，我想再干一会儿。明天开会前要发到公司的邮箱里。","pinyin":"Nǐ xiān qù chī, wǒ xiǎng zài gàn yíhuìr. Míngtiān kāihuì qián yào fā dào gōngsī de yóuxiāng lǐ."},{"speaker":"杨同乐","cn":"您没看到邮件吗？经理还没回来呢，下周才能开会。","pinyin":"Nín méi kàndào yóujiàn ma? Jīnglǐ hái méi huílái ne, xiàzhōu cái néng kāihuì."},{"speaker":"王一雪","cn":"那不着急了。走，吃饭去。","pinyin":"Nà bù zháojí le. Zǒu, chīfàn qù."}],"translation_vn":"Vương Nhất Tuyết: Đồng Nhạc, anh có thấy Lão Trương không?\nDương Đồng Nhạc: Lão Trương không đến. Anh ấy nói nhà có chút việc nên xin nghỉ phép rồi.\nVương Nhất Tuyết: Mấy đồng nghiệp đều nghỉ phép cả, nhiều việc thế này trước khi họp tôi sợ làm không xong.\nDương Đồng Nhạc: Hơn mười hai giờ rồi, chúng ta đi ăn cơm trước đã. Ăn xong, tôi sẽ cùng chị làm nốt chỗ việc này.\nVương Nhất Tuyết: Anh đi ăn trước đi, tôi muốn làm thêm một lát nữa. Trước khi họp ngày mai phải gửi vào hộp thư của công ty.\nDương Đồng Nhạc: Chị không xem email à? Giám đốc vẫn chưa về, tuần sau mới có thể họp được.\nVương Nhất Tuyết: Vậy thì không vội nữa. Đi nào, đi ăn cơm thôi.","audio_dialogue":"11-5.mp3","audio_vocab":"11-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"前几天，上海的同事来北京了。","pinyin":"Qián jǐ tiān, Shànghǎi de tóngshì lái Běijīng le."},{"speaker":"","cn":"一起吃饭时，他们跟我说最近有不少同事去上海工作了，问我愿意不愿意也去上海。","pinyin":"Yìqǐ chīfàn shí, tāmen gēn wǒ shuō zuìjìn yǒu bù shǎo tóngshì qù Shànghǎi gōngzuò le, wèn wǒ yuànyì bu yuànyì yě qù Shànghǎi."},{"speaker":"","cn":"我是这样想的：现在丈夫和孩子都在北京，刘明的工作很忙，小雪和小明也还小，我去别的城市工作就要离开他们。","pinyin":"Wǒ shì zhèyàng xiǎng de: xiànzài zhàngfu hé háizi dōu zài Běijīng, Liú Míng de gōngzuò hěn máng, Xiǎoxuě hé Xiǎomíng yě hái xiǎo, wǒ qù bié de chéngshì gōngzuò jiù yào líkāi tāmen."},{"speaker":"","cn":"虽然去上海可能会有更好的机会，但是对我来说，生活也很重要，我不愿意为工作或学习离开家人。","pinyin":"Suīrán qù Shànghǎi kěnéng huì yǒu gèng hǎo de jīhuì, dànshì duì wǒ lái shuō, shēnghuó yě hěn zhòngyào, wǒ bú yuànyì wèi gōngzuò huò xuéxí líkāi jiārén."}],"translation_vn":"Mấy ngày trước, đồng nghiệp ở Thượng Hải đến Bắc Kinh. Khi cùng ăn cơm, họ nói với tôi rằng gần đây có không ít đồng nghiệp đã đi Thượng Hải làm việc, và hỏi tôi có sẵn lòng cũng đến Thượng Hải hay không. Tôi đã nghĩ như thế này: hiện tại chồng và các con đều ở Bắc Kinh, công việc của Lưu Minh rất bận, Tiểu Tuyết và Tiểu Minh cũng còn nhỏ, nếu tôi đi làm việc ở thành phố khác thì sẽ phải rời xa họ. Tuy đi Thượng Hải có thể sẽ có cơ hội tốt hơn, nhưng đối với tôi mà nói, cuộc sống gia đình cũng rất quan trọng, tôi không muốn vì công việc hay học tập mà rời xa người thân.","audio_dialogue":"11-7.mp3","audio_vocab":"11-8.mp3"}]},{"id":12,"title_cn":"这个季节天气变化很快","title_pinyin":"Zhège jìjié tiānqì biànhuà hěn kuài","title_vn":"Mùa này thời tiết thay đổi rất nhanh","goals":["Có thể nghe hiểu và nói chuyện về sự thay đổi của thời tiết.","Có thể nghe hiểu và giới thiệu tình hình khí hậu của một nơi cũng như sở thích của bản thân về các mùa.","Nắm được cách dùng của \"就\", có thể nhấn mạnh số lượng ít hoặc trường hợp ngoại lệ.","Hiểu được đặc điểm bốn mùa ở Bắc Kinh."],"vocab":[{"hanzi":"街","pinyin":"jiē","pos":"dt.","vn":"đường phố, phố","examples":[{"cn":"这条街很热闹。","pinyin":"Zhè tiáo jiē hěn rènao.","vn":"Con phố này rất náo nhiệt."},{"cn":"我们在街上散步。","pinyin":"Wǒmen zài jiē shang sànbù.","vn":"Chúng tôi đi dạo trên phố."},{"cn":"街对面有一家咖啡馆。","pinyin":"Jiē duìmiàn yǒu yì jiā kāfēiguǎn.","vn":"Bên kia phố có một quán cà phê."}]},{"hanzi":"开花","pinyin":"kāihuā","pos":"dgt.","vn":"nở hoa","examples":[{"cn":"春天到了，花都开花了。","pinyin":"Chūntiān dào le, huā dōu kāihuā le.","vn":"Mùa xuân đến rồi, hoa đều nở cả."},{"cn":"这棵树开花了。","pinyin":"Zhè kē shù kāihuā le.","vn":"Cây này đã ra hoa rồi."},{"cn":"公园里的花都开花了，很漂亮。","pinyin":"Gōngyuán li de huā dōu kāihuā le, hěn piàoliang.","vn":"Hoa trong công viên đều nở rộ, rất đẹp."}]},{"hanzi":"公园","pinyin":"gōngyuán","pos":"dt.","vn":"công viên","examples":[{"cn":"我们周末去公园散步。","pinyin":"Wǒmen zhōumò qù gōngyuán sànbù.","vn":"Cuối tuần chúng tôi đi dạo trong công viên."},{"cn":"公园里有很多人在锻炼。","pinyin":"Gōngyuán li yǒu hěn duō rén zài duànliàn.","vn":"Trong công viên có rất nhiều người đang tập thể dục."},{"cn":"这个公园很大。","pinyin":"Zhège gōngyuán hěn dà.","vn":"Công viên này rất rộng."}]},{"hanzi":"船","pinyin":"chuán","pos":"dt.","vn":"thuyền, tàu","examples":[{"cn":"我们坐船去对岸。","pinyin":"Wǒmen zuò chuán qù duì'àn.","vn":"Chúng tôi đi thuyền sang bờ bên kia."},{"cn":"河上有很多船。","pinyin":"Hé shang yǒu hěn duō chuán.","vn":"Trên sông có rất nhiều thuyền."},{"cn":"他喜欢坐船旅行。","pinyin":"Tā xǐhuan zuò chuán lǚxíng.","vn":"Anh ấy thích đi thuyền du lịch."}]},{"hanzi":"工作日","pinyin":"gōngzuòrì","pos":"dt.","vn":"ngày làm việc","examples":[{"cn":"工作日我很忙，周末才有时间。","pinyin":"Gōngzuòrì wǒ hěn máng, zhōumò cái yǒu shíjiān.","vn":"Ngày làm việc tôi rất bận, cuối tuần mới có thời gian."},{"cn":"这家店工作日不营业。","pinyin":"Zhè jiā diàn gōngzuòrì bù yíngyè.","vn":"Cửa hàng này không mở cửa vào ngày làm việc."},{"cn":"工作日的早上路上车很多。","pinyin":"Gōngzuòrì de zǎoshang lùshang chē hěn duō.","vn":"Sáng ngày làm việc trên đường rất nhiều xe."}]},{"hanzi":"地方","pinyin":"dìfang","pos":"dt.","vn":"nơi, địa điểm","examples":[{"cn":"这是一个很安静的地方。","pinyin":"Zhè shì yí ge hěn ānjìng de dìfang.","vn":"Đây là một nơi rất yên tĩnh."},{"cn":"你知道那个地方怎么走吗？","pinyin":"Nǐ zhīdao nàge dìfang zěnme zǒu ma?","vn":"Bạn có biết đi đến nơi đó như thế nào không?"},{"cn":"我找不到停车的地方。","pinyin":"Wǒ zhǎo bu dào tíngchē de dìfang.","vn":"Tôi không tìm được nơi đỗ xe."}]},{"hanzi":"刚才","pinyin":"gāngcái","pos":"dt.","vn":"vừa nãy, lúc nãy","examples":[{"cn":"刚才有人找你。","pinyin":"Gāngcái yǒu rén zhǎo nǐ.","vn":"Vừa nãy có người tìm bạn."},{"cn":"他刚才还在这儿呢。","pinyin":"Tā gāngcái hái zài zhèr ne.","vn":"Vừa nãy anh ấy vẫn còn ở đây mà."},{"cn":"刚才下了一场雨。","pinyin":"Gāngcái xiàle yì chǎng yǔ.","vn":"Vừa nãy trời đổ một trận mưa."}]},{"hanzi":"刮","pinyin":"guā","pos":"dgt.","vn":"thổi (gió)","examples":[{"cn":"外面刮大风了。","pinyin":"Wàimiàn guā dà fēng le.","vn":"Bên ngoài gió thổi mạnh rồi."},{"cn":"今天刮风刮得很厉害。","pinyin":"Jīntiān guāfēng guā de hěn lìhai.","vn":"Hôm nay gió thổi rất dữ dội."},{"cn":"刮风的时候别出门。","pinyin":"Guāfēng de shíhou bié chūmén.","vn":"Lúc gió thổi thì đừng ra ngoài."}]},{"hanzi":"风","pinyin":"fēng","pos":"dt.","vn":"gió","examples":[{"cn":"今天风很大。","pinyin":"Jīntiān fēng hěn dà.","vn":"Hôm nay gió rất to."},{"cn":"外面吹着凉风。","pinyin":"Wàimiàn chuīzhe liángfēng.","vn":"Bên ngoài đang thổi gió mát."},{"cn":"我喜欢秋天的风。","pinyin":"Wǒ xǐhuan qiūtiān de fēng.","vn":"Tôi thích gió mùa thu."}]},{"hanzi":"新闻","pinyin":"xīnwén","pos":"dt.","vn":"tin tức, bản tin thời sự","examples":[{"cn":"我每天早上看新闻。","pinyin":"Wǒ měitiān zǎoshang kàn xīnwén.","vn":"Mỗi sáng tôi xem tin tức."},{"cn":"这是今天的新闻。","pinyin":"Zhè shì jīntiān de xīnwén.","vn":"Đây là tin tức hôm nay."},{"cn":"他喜欢听新闻了解时事。","pinyin":"Tā xǐhuan tīng xīnwén liǎojiě shíshì.","vn":"Anh ấy thích nghe tin tức để hiểu thời sự."}]},{"hanzi":"伞","pinyin":"sǎn","pos":"dt.","vn":"cái ô, cái dù","examples":[{"cn":"下雨了，记得带伞。","pinyin":"Xiàyǔ le, jìde dài sǎn.","vn":"Trời mưa rồi, nhớ mang ô."},{"cn":"我忘了带伞。","pinyin":"Wǒ wàngle dài sǎn.","vn":"Tôi quên mang ô rồi."},{"cn":"这把伞是谁的？","pinyin":"Zhè bǎ sǎn shì shéi de?","vn":"Cái ô này là của ai?"}]},{"hanzi":"借","pinyin":"jiè","pos":"dgt.","vn":"mượn, cho mượn","examples":[{"cn":"我能借你的笔用一下吗？","pinyin":"Wǒ néng jiè nǐ de bǐ yòng yíxià ma?","vn":"Tôi có thể mượn bút của bạn dùng một chút không?"},{"cn":"他向我借了一本书。","pinyin":"Tā xiàng wǒ jièle yì běn shū.","vn":"Anh ấy mượn tôi một quyển sách."},{"cn":"我把伞借给他了。","pinyin":"Wǒ bǎ sǎn jiè gěi tā le.","vn":"Tôi đã cho anh ấy mượn cái ô."}]},{"hanzi":"把","pinyin":"bǎ","pos":"lượng.","vn":"cái (lượng từ dùng cho vật có cán cầm)","examples":[{"cn":"这把伞是我的。","pinyin":"Zhè bǎ sǎn shì wǒ de.","vn":"Cái ô này là của tôi."},{"cn":"他买了一把雨伞。","pinyin":"Tā mǎile yì bǎ yǔsǎn.","vn":"Anh ấy đã mua một cái ô."},{"cn":"桌子上有一把剪刀。","pinyin":"Zhuōzi shang yǒu yì bǎ jiǎndāo.","vn":"Trên bàn có một cái kéo."}]},{"hanzi":"雨衣","pinyin":"yǔyī","pos":"dt.","vn":"áo mưa","examples":[{"cn":"下雨了，快穿上雨衣。","pinyin":"Xiàyǔ le, kuài chuānshang yǔyī.","vn":"Trời mưa rồi, mau mặc áo mưa vào."},{"cn":"他没带伞，只穿了雨衣。","pinyin":"Tā méi dài sǎn, zhǐ chuānle yǔyī.","vn":"Anh ấy không mang ô, chỉ mặc áo mưa."},{"cn":"这件雨衣很好看。","pinyin":"Zhè jiàn yǔyī hěn hǎokàn.","vn":"Chiếc áo mưa này rất đẹp."}]},{"hanzi":"变","pinyin":"biàn","pos":"dgt.","vn":"biến đổi, thay đổi","examples":[{"cn":"天气变冷了。","pinyin":"Tiānqì biàn lěng le.","vn":"Thời tiết đã trở lạnh."},{"cn":"他的想法变了。","pinyin":"Tā de xiǎngfǎ biàn le.","vn":"Suy nghĩ của anh ấy đã thay đổi."},{"cn":"这个城市变化很大。","pinyin":"Zhège chéngshì biànhuà hěn dà.","vn":"Thành phố này thay đổi rất nhiều."}]},{"hanzi":"季节","pinyin":"jìjié","pos":"dt.","vn":"mùa, mùa trong năm","examples":[{"cn":"春天是我最喜欢的季节。","pinyin":"Chūntiān shì wǒ zuì xǐhuan de jìjié.","vn":"Mùa xuân là mùa tôi thích nhất."},{"cn":"不同的季节有不同的风景。","pinyin":"Bùtóng de jìjié yǒu bùtóng de fēngjǐng.","vn":"Các mùa khác nhau có phong cảnh khác nhau."},{"cn":"现在是换季节的时候。","pinyin":"Xiànzài shì huàn jìjié de shíhou.","vn":"Bây giờ là lúc giao mùa."}]},{"hanzi":"变化","pinyin":"biànhuà","pos":"dgt./dt.","vn":"thay đổi, biến hóa; sự thay đổi","examples":[{"cn":"这几年城市变化很大。","pinyin":"Zhè jǐ nián chéngshì biànhuà hěn dà.","vn":"Mấy năm nay thành phố thay đổi rất nhiều."},{"cn":"他的态度有了变化。","pinyin":"Tā de tàidu yǒule biànhuà.","vn":"Thái độ của anh ấy đã có sự thay đổi."},{"cn":"天气变化真快。","pinyin":"Tiānqì biànhuà zhēn kuài.","vn":"Thời tiết thay đổi thật nhanh."}]},{"hanzi":"冬天","pinyin":"dōngtiān","pos":"dt.","vn":"mùa đông","examples":[{"cn":"冬天很冷。","pinyin":"Dōngtiān hěn lěng.","vn":"Mùa đông rất lạnh."},{"cn":"我不喜欢冬天。","pinyin":"Wǒ bù xǐhuan dōngtiān.","vn":"Tôi không thích mùa đông."},{"cn":"冬天这里经常下雪。","pinyin":"Dōngtiān zhèlǐ jīngcháng xiàxuě.","vn":"Mùa đông ở đây thường xuyên có tuyết rơi."}]},{"hanzi":"常常","pinyin":"chángcháng","pos":"phó.","vn":"thường, thường xuyên","examples":[{"cn":"我常常去那家餐厅吃饭。","pinyin":"Wǒ chángcháng qù nà jiā cāntīng chīfàn.","vn":"Tôi thường xuyên đến nhà hàng đó ăn cơm."},{"cn":"他常常加班。","pinyin":"Tā chángcháng jiābān.","vn":"Anh ấy thường xuyên tăng ca."},{"cn":"我们常常一起运动。","pinyin":"Wǒmen chángcháng yìqǐ yùndòng.","vn":"Chúng tôi thường xuyên tập thể dục cùng nhau."}]},{"hanzi":"关注","pinyin":"guānzhù","pos":"dgt.","vn":"quan tâm, chú ý theo dõi","examples":[{"cn":"我一直关注这个新闻。","pinyin":"Wǒ yìzhí guānzhù zhège xīnwén.","vn":"Tôi luôn theo dõi tin tức này."},{"cn":"大家都很关注这件事。","pinyin":"Dàjiā dōu hěn guānzhù zhè jiàn shì.","vn":"Mọi người đều rất quan tâm đến việc này."},{"cn":"他很关注孩子的教育。","pinyin":"Tā hěn guānzhù háizi de jiàoyù.","vn":"Anh ấy rất quan tâm đến việc giáo dục con cái."}]},{"hanzi":"四季","pinyin":"sìjì","pos":"dt.","vn":"bốn mùa","examples":[{"cn":"这里四季分明。","pinyin":"Zhèlǐ sìjì fēnmíng.","vn":"Ở đây bốn mùa rõ rệt."},{"cn":"四季的风景都不一样。","pinyin":"Sìjì de fēngjǐng dōu bù yíyàng.","vn":"Phong cảnh bốn mùa đều khác nhau."},{"cn":"我喜欢这里的四季。","pinyin":"Wǒ xǐhuan zhèlǐ de sìjì.","vn":"Tôi thích bốn mùa ở đây."}]},{"hanzi":"春天","pinyin":"chūntiān","pos":"dt.","vn":"mùa xuân","examples":[{"cn":"春天来了，花都开了。","pinyin":"Chūntiān lái le, huā dōu kāi le.","vn":"Mùa xuân đến rồi, hoa đều nở cả."},{"cn":"我喜欢春天的天气。","pinyin":"Wǒ xǐhuan chūntiān de tiānqì.","vn":"Tôi thích thời tiết mùa xuân."},{"cn":"春天是旅游的好季节。","pinyin":"Chūntiān shì lǚyóu de hǎo jìjié.","vn":"Mùa xuân là mùa du lịch tốt."}]},{"hanzi":"夏天","pinyin":"xiàtiān","pos":"dt.","vn":"mùa hè","examples":[{"cn":"夏天很热。","pinyin":"Xiàtiān hěn rè.","vn":"Mùa hè rất nóng."},{"cn":"我喜欢在夏天游泳。","pinyin":"Wǒ xǐhuan zài xiàtiān yóuyǒng.","vn":"Tôi thích bơi lội vào mùa hè."},{"cn":"夏天的晚上很凉快。","pinyin":"Xiàtiān de wǎnshang hěn liángkuai.","vn":"Buổi tối mùa hè rất mát mẻ."}]},{"hanzi":"凉快","pinyin":"liángkuai","pos":"tt.","vn":"mát mẻ, dễ chịu","examples":[{"cn":"这里晚上很凉快。","pinyin":"Zhèlǐ wǎnshang hěn liángkuai.","vn":"Ở đây buổi tối rất mát mẻ."},{"cn":"秋天的天气很凉快。","pinyin":"Qiūtiān de tiānqì hěn liángkuai.","vn":"Thời tiết mùa thu rất mát mẻ."},{"cn":"开空调后房间凉快多了。","pinyin":"Kāi kōngtiáo hòu fángjiān liángkuai duō le.","vn":"Sau khi bật điều hòa, căn phòng mát hơn nhiều."}]},{"hanzi":"秋天","pinyin":"qiūtiān","pos":"dt.","vn":"mùa thu","examples":[{"cn":"秋天的树叶很漂亮。","pinyin":"Qiūtiān de shùyè hěn piàoliang.","vn":"Lá cây mùa thu rất đẹp."},{"cn":"我喜欢秋天的天气。","pinyin":"Wǒ xǐhuan qiūtiān de tiānqì.","vn":"Tôi thích thời tiết mùa thu."},{"cn":"秋天到了，天气变凉了。","pinyin":"Qiūtiān dào le, tiānqì biàn liáng le.","vn":"Mùa thu đến rồi, thời tiết trở nên mát mẻ."}]},{"hanzi":"叶子","pinyin":"yèzi","pos":"dt.","vn":"lá cây","examples":[{"cn":"秋天的叶子都变黄了。","pinyin":"Qiūtiān de yèzi dōu biàn huáng le.","vn":"Lá cây mùa thu đều chuyển vàng."},{"cn":"树上的叶子掉了很多。","pinyin":"Shù shang de yèzi diàole hěn duō.","vn":"Lá trên cây rụng rất nhiều."},{"cn":"这片叶子很大。","pinyin":"Zhè piàn yèzi hěn dà.","vn":"Chiếc lá này rất to."}]},{"hanzi":"变成","pinyin":"biànchéng","pos":"dgt.","vn":"biến thành, trở thành","examples":[{"cn":"他的梦想变成了现实。","pinyin":"Tā de mèngxiǎng biànchéngle xiànshí.","vn":"Ước mơ của anh ấy đã trở thành hiện thực."},{"cn":"水变成了冰。","pinyin":"Shuǐ biànchéngle bīng.","vn":"Nước đã biến thành băng."},{"cn":"这个小镇变成了一座大城市。","pinyin":"Zhège xiǎo zhèn biànchéngle yí zuò dà chéngshì.","vn":"Thị trấn nhỏ này đã biến thành một thành phố lớn."}]}],"grammar":[{"title":"选择复句\"或者……，或者……\" (Câu phức lựa chọn \"或者……，或者……\")","explanation_vn":"Câu phức lựa chọn \"或者……，或者……\" biểu thị việc chọn một trong hai hoặc nhiều khả năng có thể, thường dùng trong khẩu ngữ.","examples":[{"cn":"或者明天去，或者后天去，我给你打电话。","pinyin":"Huòzhě míngtiān qù, huòzhě hòutiān qù, wǒ gěi nǐ dǎ diànhuà.","vn":""},{"cn":"我们或者今天去电影院看电影，或者明天在家看电影。","pinyin":"Wǒmen huòzhě jīntiān qù diànyǐngyuàn kàn diànyǐng, huòzhě míngtiān zài jiā kàn diànyǐng.","vn":""},{"cn":"晚饭你自己选，或者吃中国菜，或者吃日本菜，或者吃泰国菜。","pinyin":"Wǎnfàn nǐ zìjǐ xuǎn, huòzhě chī Zhōngguó cài, huòzhě chī Rìběn cài, huòzhě chī Tàiguó cài.","vn":""}]},{"title":"趋向补语的引申用法（2）\"起来\" (Cách dùng mở rộng của bổ ngữ xu hướng \"起来\")","explanation_vn":"Bổ ngữ xu hướng \"起来\" dùng sau động từ hoặc tính từ, biểu thị động tác bắt đầu diễn ra hoặc bước vào một trạng thái mới. Nếu động từ có tân ngữ thì tân ngữ phải đặt giữa \"起\" và \"来\".","examples":[{"cn":"雨已经下起来了。","pinyin":"Yǔ yǐjīng xià qǐlái le.","vn":""},{"cn":"最近天气热起来了。","pinyin":"Zuìjìn tiānqì rè qǐlái le.","vn":""},{"cn":"怎么突然刮起风来了？","pinyin":"Zěnme tūrán guā qǐ fēng lái le?","vn":""}]},{"title":"范围副词\"就\" (Phó từ phạm vi \"就\")","explanation_vn":"Phó từ phạm vi \"就\" dùng trước động từ đi kèm số từ - lượng từ, biểu thị người nói cho rằng số lượng ít, mức độ nhẹ, thời gian ngắn. \"就\" cũng được dùng trước danh từ hoặc chủ ngữ danh từ để biểu thị trường hợp ngoại lệ.","examples":[{"cn":"北京常常下雪，但听说今年就下了一次。","pinyin":"Běijīng chángcháng xià xuě, dàn tīngshuō jīnnián jiù xiàle yí cì.","vn":""},{"cn":"他昨天就看了十分钟书。","pinyin":"Tā zuótiān jiù kànle shí fēnzhōng shū.","vn":""},{"cn":"我每天书包里都放着雨伞，就今天没带。","pinyin":"Wǒ měitiān shūbāo lǐ dōu fàngzhe yǔsǎn, jiù jīntiān méi dài.","vn":""},{"cn":"你们点的菜都挺好吃的，就我点的这个菜不太好吃。","pinyin":"Nǐmen diǎn de cài dōu tǐng hǎochī de, jiù wǒ diǎn de zhège cài bú tài hǎochī.","vn":""}]},{"title":"趋向补语的引申用法（3）\"下来\" (Cách dùng mở rộng của bổ ngữ xu hướng \"下来\")","explanation_vn":"Bổ ngữ xu hướng \"下来\" dùng sau động từ, biểu thị việc hoàn thành một hành động tốn thời gian, công sức, cần phải vượt qua khó khăn nhất định.","examples":[{"cn":"这一年多住下来，我还是更喜欢北京的四季。","pinyin":"Zhè yì nián duō zhù xiàlái, wǒ háishi gèng xǐhuan Běijīng de sìjì.","vn":""},{"cn":"这半年练下来，他画画的水平提高了不少。","pinyin":"Zhè bànnián liàn xiàlái, tā huàhuà de shuǐpíng tígāole bù shǎo.","vn":""},{"cn":"5000米的长跑比赛，没想到我跑下来了。","pinyin":"Wǔqiān mǐ de chángpǎo bǐsài, méi xiǎngdào wǒ pǎo xiàláile.","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"白家月","cn":"王老师，您看，这条街上的树都开花了。","pinyin":"Wáng lǎoshī, nín kàn, zhè tiáo jiē shàng de shù dōu kāihuā le."},{"speaker":"王一飞","cn":"上周我去公园坐船了，公园里的花也开了。","pinyin":"Shàng zhōu wǒ qù gōngyuán zuò chuán le, gōngyuán lǐ de huā yě kāi le."},{"speaker":"白家月","cn":"天气这么好，下午我也想去公园坐船。","pinyin":"Tiānqì zhème hǎo, xiàwǔ wǒ yě xiǎng qù gōngyuán zuò chuán."},{"speaker":"王一飞","cn":"去吧！今天是工作日，人应该不多。","pinyin":"Qù ba! Jīntiān shì gōngzuòrì, rén yīnggāi bù duō."},{"speaker":"白家月","cn":"您有时间吗？我想跟您一起去。","pinyin":"Nín yǒu shíjiān ma? Wǒ xiǎng gēn nín yìqǐ qù."},{"speaker":"王一飞","cn":"我今天下午有课，不能去太远的地方。","pinyin":"Wǒ jīntiān xiàwǔ yǒu kè, bù néng qù tài yuǎn de dìfang."},{"speaker":"白家月","cn":"那咱们换一天去？","pinyin":"Nà zánmen huàn yì tiān qù?"},{"speaker":"王一飞","cn":"行。或者明天去，或者后天去，我给你打电话。","pinyin":"Xíng. Huòzhě míngtiān qù, huòzhě hòutiān qù, wǒ gěi nǐ dǎ diànhuà."}],"translation_vn":"Bạch Gia Nguyệt: Thầy Vương ơi, thầy xem, cây trên con phố này đều nở hoa rồi.\nVương Nhất Phi: Tuần trước tôi đi công viên chèo thuyền, hoa trong công viên cũng nở rồi.\nBạch Gia Nguyệt: Thời tiết đẹp thế này, chiều nay em cũng muốn đi công viên chèo thuyền.\nVương Nhất Phi: Đi đi! Hôm nay là ngày làm việc, chắc không đông người đâu.\nBạch Gia Nguyệt: Thầy có thời gian không ạ? Em muốn đi cùng thầy.\nVương Nhất Phi: Chiều nay tôi có tiết dạy, không thể đi xa được.\nBạch Gia Nguyệt: Vậy chúng ta đổi sang ngày khác đi ạ?\nVương Nhất Phi: Được. Hoặc mai đi, hoặc ngày kia đi, tôi sẽ gọi điện cho em.","audio_dialogue":"12-1.mp3","audio_vocab":"12-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"白家月","cn":"刚才还是大晴天呢，怎么突然就刮起风来了？","pinyin":"Gāngcái hái shì dà qíngtiān ne, zěnme tūrán jiù guā qǐ fēng lái le?"},{"speaker":"王一飞","cn":"好像新闻里说今天有雨。","pinyin":"Hǎoxiàng xīnwén lǐ shuō jīntiān yǒu yǔ."},{"speaker":"白家月","cn":"啊？我每天书包里都放着雨伞，就今天没带。","pinyin":"Á? Wǒ měitiān shūbāo lǐ dōu fàngzhe yǔsǎn, jiù jīntiān méi dài."},{"speaker":"王一飞","cn":"我可以借给你，我车里有一把伞和一件雨衣。","pinyin":"Wǒ kěyǐ jiè gěi nǐ, wǒ chē lǐ yǒu yì bǎ sǎn hé yí jiàn yǔyī."},{"speaker":"白家月","cn":"谢谢，希望下午天气能变好。","pinyin":"Xièxie, xīwàng xiàwǔ tiānqì néng biàn hǎo."},{"speaker":"王一飞","cn":"这个季节天气变化很快。","pinyin":"Zhège jìjié tiānqì biànhuà hěn kuài."},{"speaker":"白家月","cn":"雨已经下起来了，咱们快点儿走吧。","pinyin":"Yǔ yǐjīng xià qǐlái le, zánmen kuài diǎnr zǒu ba."}],"translation_vn":"Bạch Gia Nguyệt: Vừa nãy còn nắng to thế mà, sao đột nhiên lại nổi gió lên rồi?\nVương Nhất Phi: Hình như bản tin thời sự nói hôm nay có mưa.\nBạch Gia Nguyệt: Hả? Ngày nào em cũng để sẵn ô trong cặp sách, vậy mà hôm nay lại không mang.\nVương Nhất Phi: Thầy có thể cho em mượn, trong xe thầy có một cái ô và một cái áo mưa.\nBạch Gia Nguyệt: Cảm ơn thầy, em hy vọng chiều nay thời tiết sẽ tốt hơn.\nVương Nhất Phi: Mùa này thời tiết thay đổi rất nhanh.\nBạch Gia Nguyệt: Mưa đã bắt đầu rơi rồi, chúng ta đi nhanh lên thôi.","audio_dialogue":"12-3.mp3","audio_vocab":"12-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"白家月","cn":"您来这里已经一年多了，习惯了吧？","pinyin":"Nín lái zhèlǐ yǐjīng yì nián duō le, xíguàn le ba?"},{"speaker":"王一飞","cn":"别的早就习惯了，就是天气我还不太习惯。","pinyin":"Biéde zǎo jiù xíguàn le, jiùshì tiānqì wǒ hái bú tài xíguàn."},{"speaker":"白家月","cn":"为什么？您不喜欢这里的天气吗？","pinyin":"Wèishénme? Nín bù xǐhuan zhèlǐ de tiānqì ma?"},{"speaker":"王一飞","cn":"我觉得冬天太冷了。","pinyin":"Wǒ juéde dōngtiān tài lěng le."},{"speaker":"白家月","cn":"冬天虽然冷，但是下雪的时候特别漂亮。","pinyin":"Dōngtiān suīrán lěng, dànshì xià xuě de shíhou tèbié piàoliang."},{"speaker":"王一飞","cn":"我也喜欢雪。北京常常下雪，但听说今年就下了一次。","pinyin":"Wǒ yě xǐhuan xuě. Běijīng chángcháng xià xuě, dàn tīngshuō jīnnián jiù xiàle yí cì."},{"speaker":"白家月","cn":"我没关注过北京的天气，但是新闻里说过，今年冬天很多地方雪下得都少了。","pinyin":"Wǒ méi guānzhùguò Běijīng de tiānqì, dànshì xīnwén lǐ shuōguò, jīnnián dōngtiān hěn duō dìfang xuě xià de dōu shǎo le."}],"translation_vn":"Bạch Gia Nguyệt: Thầy đến đây đã hơn một năm rồi, chắc đã quen rồi nhỉ?\nVương Nhất Phi: Những thứ khác thì quen lâu rồi, chỉ có thời tiết là tôi vẫn chưa quen lắm.\nBạch Gia Nguyệt: Tại sao ạ? Thầy không thích thời tiết ở đây sao?\nVương Nhất Phi: Tôi thấy mùa đông ở đây quá lạnh.\nBạch Gia Nguyệt: Mùa đông tuy lạnh nhưng lúc có tuyết rơi thì đẹp lắm.\nVương Nhất Phi: Tôi cũng thích tuyết. Bắc Kinh thường hay có tuyết, nhưng nghe nói năm nay chỉ có tuyết một lần thôi.\nBạch Gia Nguyệt: Em chưa từng để ý đến thời tiết ở Bắc Kinh, nhưng nghe bản tin thời sự nói, mùa đông năm nay tuyết ở nhiều nơi đều rơi ít đi.","audio_dialogue":"12-5.mp3","audio_vocab":"12-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"我离开北京到这里工作一年多了。","pinyin":"Wǒ líkāi Běijīng dào zhèlǐ gōngzuò yì nián duō le."},{"speaker":"","cn":"这一年多住下来，我还是更喜欢北京的四季。","pinyin":"Zhè yì nián duō zhù xiàlái, wǒ háishi gèng xǐhuan Běijīng de sìjì."},{"speaker":"","cn":"北京的春天最舒服，天气不冷不热。","pinyin":"Běijīng de chūntiān zuì shūfu, tiānqì bù lěng bú rè."},{"speaker":"","cn":"夏天白天很热，但是晚上比较凉快。","pinyin":"Xiàtiān báitiān hěn rè, dànshì wǎnshang bǐjiào liángkuai."},{"speaker":"","cn":"秋天树上的叶子都变成了红色、黄色，非常漂亮。","pinyin":"Qiūtiān shùshàng de yèzi dōu biànchéngle hóngsè, huángsè, fēicháng piàoliang."},{"speaker":"","cn":"冬天不但冷，而且风很大，我最不喜欢冬天。","pinyin":"Dōngtiān búdàn lěng, érqiě fēng hěn dà, wǒ zuì bù xǐhuan dōngtiān."},{"speaker":"","cn":"每个人都有自己最喜欢的季节，你最喜欢哪个季节呢？","pinyin":"Měi gè rén dōu yǒu zìjǐ zuì xǐhuan de jìjié, nǐ zuì xǐhuan nǎge jìjié ne?"}],"translation_vn":"Tôi đã rời Bắc Kinh đến đây làm việc được hơn một năm rồi. Sống ở đây hơn một năm, tôi vẫn thích bốn mùa của Bắc Kinh hơn. Mùa xuân ở Bắc Kinh dễ chịu nhất, thời tiết không lạnh không nóng. Mùa hè ban ngày rất nóng, nhưng buổi tối lại khá mát mẻ. Mùa thu, lá trên cây đều chuyển sang màu đỏ, màu vàng, rất đẹp. Mùa đông không chỉ lạnh mà gió còn rất to, tôi ghét mùa đông nhất. Mỗi người đều có mùa mình yêu thích nhất, bạn thích mùa nào nhất?","audio_dialogue":"12-7.mp3","audio_vocab":"12-8.mp3"}]},{"id":13,"title_cn":"我的新邻居来自英国","title_pinyin":"Wǒ de xīn línjū láizì Yīngguó","title_vn":"Người hàng xóm mới của tôi đến từ Anh","goals":["Có thể nghe hiểu và thảo luận về sự khác biệt trong thói quen sinh hoạt giữa các vùng miền khác nhau.","Có thể nghe hiểu và sử dụng các cách nói lịch sự như cảm ơn, chúc phúc và khen ngợi.","Nắm vững cách dùng \"一边……, 一边……\" để miêu tả các hành động diễn ra đồng thời."],"vocab":[{"hanzi":"请客","pinyin":"qǐngkè","pos":"dgt.","vn":"mời khách, đãi khách","examples":[{"cn":"今天我请客,大家想吃什么就点什么。","pinyin":"Jīntiān wǒ qǐngkè, dàjiā xiǎng chī shénme jiù diǎn shénme.","vn":"Hôm nay tôi mời khách, mọi người muốn ăn gì cứ gọi món đó."},{"cn":"他找到工作了,说要请客庆祝一下。","pinyin":"Tā zhǎodào gōngzuò le, shuō yào qǐngkè qìngzhù yíxià.","vn":"Anh ấy tìm được việc rồi, nói là sẽ mời khách để ăn mừng."},{"cn":"下次我请客,你们随便吃。","pinyin":"Xiàcì wǒ qǐngkè, nǐmen suíbiàn chī.","vn":"Lần sau tôi mời khách, mọi người cứ ăn thoải mái."}]},{"hanzi":"南方","pinyin":"nánfāng","pos":"dt.","vn":"miền Nam","examples":[{"cn":"我老家在南方,冬天不怎么冷。","pinyin":"Wǒ lǎojiā zài nánfāng, dōngtiān bù zěnme lěng.","vn":"Quê tôi ở miền Nam, mùa đông không lạnh lắm."},{"cn":"南方人喜欢吃米饭,北方人喜欢吃面食。","pinyin":"Nánfāng rén xǐhuan chī mǐfàn, běifāng rén xǐhuan chī miànshí.","vn":"Người miền Nam thích ăn cơm, người miền Bắc thích ăn các món bột mì."},{"cn":"她大学毕业后去南方工作了。","pinyin":"Tā dàxué bìyè hòu qù nánfāng gōngzuò le.","vn":"Sau khi tốt nghiệp đại học, cô ấy đã đi làm ở miền Nam."}]},{"hanzi":"北方","pinyin":"běifāng","pos":"dt.","vn":"miền Bắc","examples":[{"cn":"北方的冬天特别冷,还经常下雪。","pinyin":"Běifāng de dōngtiān tèbié lěng, hái jīngcháng xiàxuě.","vn":"Mùa đông ở miền Bắc rất lạnh, lại còn hay có tuyết rơi."},{"cn":"他是北方人,说话带点儿口音。","pinyin":"Tā shì běifāng rén, shuōhuà dài diǎnr kǒuyīn.","vn":"Anh ấy là người miền Bắc, nói chuyện có chút âm điệu."},{"cn":"我打算暑假去北方旅游。","pinyin":"Wǒ dǎsuan shǔjià qù běifāng lǚyóu.","vn":"Tôi dự định nghỉ hè sẽ đi du lịch miền Bắc."}]},{"hanzi":"做法","pinyin":"zuòfǎ","pos":"dt.","vn":"cách làm, cách chế biến","examples":[{"cn":"这道菜的做法其实很简单。","pinyin":"Zhè dào cài de zuòfǎ qíshí hěn jiǎndān.","vn":"Cách làm món ăn này thực ra rất đơn giản."},{"cn":"你能教我一下饺子的做法吗?","pinyin":"Nǐ néng jiāo wǒ yíxià jiǎozi de zuòfǎ ma?","vn":"Bạn có thể chỉ cho tôi cách làm sủi cảo không?"},{"cn":"每个地方做法不一样,味道也不同。","pinyin":"Měi gè dìfang zuòfǎ bù yíyàng, wèidao yě bùtóng.","vn":"Mỗi nơi có cách làm khác nhau, hương vị cũng khác nhau."}]},{"hanzi":"不同","pinyin":"bùtóng","pos":"tt.","vn":"khác nhau, không giống","examples":[{"cn":"我们俩的想法不同,所以经常吵架。","pinyin":"Wǒmen liǎ de xiǎngfǎ bùtóng, suǒyǐ jīngcháng chǎojià.","vn":"Suy nghĩ của hai chúng tôi khác nhau nên hay cãi nhau."},{"cn":"这两种颜色看起来不同,其实很像。","pinyin":"Zhè liǎng zhǒng yánsè kàn qǐlái bùtóng, qíshí hěn xiàng.","vn":"Hai màu này nhìn có vẻ khác nhau nhưng thực ra rất giống."},{"cn":"不同国家的文化真的差别很大。","pinyin":"Bùtóng guójiā de wénhuà zhēnde chābié hěn dà.","vn":"Văn hóa của các nước khác nhau thực sự có sự khác biệt rất lớn."}]},{"hanzi":"加","pinyin":"jiā","pos":"dgt.","vn":"thêm","examples":[{"cn":"咖啡有点儿苦,再加点儿糖吧。","pinyin":"Kāfēi yǒudiǎnr kǔ, zài jiā diǎnr táng ba.","vn":"Cà phê hơi đắng, cho thêm chút đường nhé."},{"cn":"老师在我的作文后面加了几句话。","pinyin":"Lǎoshī zài wǒ de zuòwén hòumiàn jiāle jǐ jù huà.","vn":"Cô giáo thêm vào mấy câu ở cuối bài văn của tôi."},{"cn":"三加五等于八。","pinyin":"Sān jiā wǔ děngyú bā.","vn":"Ba cộng năm bằng tám."}]},{"hanzi":"的话","pinyin":"dehuà","pos":"trợ.","vn":"nếu... thì (dùng cuối mệnh đề giả thiết)","examples":[{"cn":"有空的话,我们一起去看电影吧。","pinyin":"Yǒu kòng dehuà, wǒmen yìqǐ qù kàn diànyǐng ba.","vn":"Nếu rảnh thì chúng ta cùng đi xem phim nhé."},{"cn":"明天下雨的话,比赛就要取消了。","pinyin":"Míngtiān xiàyǔ dehuà, bǐsài jiù yào qǔxiāo le.","vn":"Nếu ngày mai mưa thì trận đấu sẽ bị hủy."},{"cn":"你不喜欢的话,就不用勉强自己。","pinyin":"Nǐ bù xǐhuan dehuà, jiù búyòng miǎnqiǎng zìjǐ.","vn":"Nếu bạn không thích thì không cần phải gượng ép bản thân."}]},{"hanzi":"做客","pinyin":"zuòkè","pos":"dgt.","vn":"làm khách, đến thăm nhà","examples":[{"cn":"周末我要去朋友家做客。","pinyin":"Zhōumò wǒ yào qù péngyou jiā zuòkè.","vn":"Cuối tuần tôi sẽ đến nhà bạn chơi."},{"cn":"第一次去老师家做客,我有点儿紧张。","pinyin":"Dìyī cì qù lǎoshī jiā zuòkè, wǒ yǒudiǎnr jǐnzhāng.","vn":"Lần đầu đến nhà thầy giáo chơi, tôi hơi lo lắng."},{"cn":"欢迎你来我家做客。","pinyin":"Huānyíng nǐ lái wǒ jiā zuòkè.","vn":"Hoan nghênh bạn đến nhà tôi chơi."}]},{"hanzi":"邻居","pinyin":"línjū","pos":"dt.","vn":"hàng xóm","examples":[{"cn":"我们的邻居是一对老夫妻,人很好。","pinyin":"Wǒmen de línjū shì yí duì lǎo fūqī, rén hěn hǎo.","vn":"Hàng xóm của chúng tôi là một cặp vợ chồng già, rất tốt bụng."},{"cn":"搬家以后,我还不太认识新邻居。","pinyin":"Bānjiā yǐhòu, wǒ hái bú tài rènshi xīn línjū.","vn":"Sau khi chuyển nhà, tôi vẫn chưa quen lắm với hàng xóm mới."},{"cn":"邻居家的小狗总是叫个不停。","pinyin":"Línjū jiā de xiǎo gǒu zǒngshì jiào gè bùtíng.","vn":"Con chó nhà hàng xóm cứ sủa suốt không ngừng."}]},{"hanzi":"放心","pinyin":"fàngxīn","pos":"dgt.","vn":"yên tâm","examples":[{"cn":"放心吧,这件事我会处理好的。","pinyin":"Fàngxīn ba, zhè jiàn shì wǒ huì chǔlǐ hǎo de.","vn":"Yên tâm đi, việc này tôi sẽ xử lý tốt."},{"cn":"孩子一个人出门,妈妈总是不放心。","pinyin":"Háizi yí gè rén chūmén, māma zǒngshì bú fàngxīn.","vn":"Con đi ra ngoài một mình, mẹ lúc nào cũng không yên tâm."},{"cn":"看到他平安到家,我才放心了。","pinyin":"Kàndào tā píng'ān dào jiā, wǒ cái fàngxīn le.","vn":"Thấy anh ấy về nhà an toàn, tôi mới yên tâm."}]},{"hanzi":"酒","pinyin":"jiǔ","pos":"dt.","vn":"rượu","examples":[{"cn":"他不太会喝酒,一杯就脸红。","pinyin":"Tā bú tài huì hē jiǔ, yì bēi jiù liǎn hóng.","vn":"Anh ấy không uống rượu giỏi lắm, mới một ly đã đỏ mặt."},{"cn":"开车不能喝酒,这是最基本的规定。","pinyin":"Kāichē bù néng hē jiǔ, zhè shì zuì jīběn de guīdìng.","vn":"Lái xe không được uống rượu, đây là quy định cơ bản nhất."},{"cn":"过年的时候,家里常常会准备一些酒。","pinyin":"Guònián de shíhou, jiā lǐ chángcháng huì zhǔnbèi yìxiē jiǔ.","vn":"Dịp Tết, nhà thường chuẩn bị sẵn một ít rượu."}]},{"hanzi":"放","pinyin":"fàng","pos":"dgt.","vn":"đặt, để","examples":[{"cn":"你把书放在桌子上吧。","pinyin":"Nǐ bǎ shū fàng zài zhuōzi shàng ba.","vn":"Bạn để quyển sách lên bàn nhé."},{"cn":"咖啡里不用放糖,我喜欢喝苦的。","pinyin":"Kāfēi lǐ búyòng fàng táng, wǒ xǐhuan hē kǔ de.","vn":"Không cần cho đường vào cà phê, tôi thích uống vị đắng."},{"cn":"钥匙我放在门口的柜子里了。","pinyin":"Yàoshi wǒ fàng zài ménkǒu de guìzi lǐ le.","vn":"Tôi đã để chìa khóa trong tủ ở cửa ra vào."}]},{"hanzi":"客人","pinyin":"kèrén","pos":"dt.","vn":"khách","examples":[{"cn":"家里来客人了,快把房间收拾一下。","pinyin":"Jiā lǐ lái kèrén le, kuài bǎ fángjiān shōushi yíxià.","vn":"Nhà có khách đến rồi, mau dọn phòng đi."},{"cn":"这家饭店的客人总是很多。","pinyin":"Zhè jiā fàndiàn de kèrén zǒngshì hěn duō.","vn":"Nhà hàng này lúc nào khách cũng rất đông."},{"cn":"服务员热情地接待了每一位客人。","pinyin":"Fúwùyuán rèqíng de jiēdàile měi yí wèi kèrén.","vn":"Nhân viên phục vụ đã niềm nở tiếp đón từng vị khách."}]},{"hanzi":"晚会","pinyin":"wǎnhuì","pos":"dt.","vn":"buổi dạ hội, tiệc tối","examples":[{"cn":"学校今晚有一个新年晚会。","pinyin":"Xuéxiào jīnwǎn yǒu yí gè xīnnián wǎnhuì.","vn":"Tối nay trường có một buổi dạ hội mừng năm mới."},{"cn":"我们打算在晚会上表演一个节目。","pinyin":"Wǒmen dǎsuan zài wǎnhuì shàng biǎoyǎn yí gè jiémù.","vn":"Chúng tôi dự định sẽ biểu diễn một tiết mục trong buổi dạ hội."},{"cn":"晚会结束后,大家都舍不得离开。","pinyin":"Wǎnhuì jiéshù hòu, dàjiā dōu shěbude líkāi.","vn":"Sau khi buổi dạ hội kết thúc, mọi người đều không nỡ rời đi."}]},{"hanzi":"礼物","pinyin":"lǐwù","pos":"dt.","vn":"quà tặng","examples":[{"cn":"这是我给你准备的生日礼物。","pinyin":"Zhè shì wǒ gěi nǐ zhǔnbèi de shēngrì lǐwù.","vn":"Đây là món quà sinh nhật tôi chuẩn bị cho bạn."},{"cn":"我还没想好送她什么礼物。","pinyin":"Wǒ hái méi xiǎnghǎo sòng tā shénme lǐwù.","vn":"Tôi vẫn chưa nghĩ ra nên tặng cô ấy quà gì."},{"cn":"他收到礼物以后特别开心。","pinyin":"Tā shōudào lǐwù yǐhòu tèbié kāixīn.","vn":"Sau khi nhận được quà, anh ấy vui lắm."}]},{"hanzi":"画家","pinyin":"huàjiā","pos":"dt.","vn":"họa sĩ","examples":[{"cn":"他从小的理想就是当一名画家。","pinyin":"Tā cóngxiǎo de lǐxiǎng jiù shì dāng yì míng huàjiā.","vn":"Ước mơ từ nhỏ của anh ấy là trở thành một họa sĩ."},{"cn":"这位画家的作品在展览馆里展出。","pinyin":"Zhè wèi huàjiā de zuòpǐn zài zhǎnlǎnguǎn lǐ zhǎnchū.","vn":"Tác phẩm của họa sĩ này đang được trưng bày trong nhà triển lãm."},{"cn":"她是一位很有名的画家。","pinyin":"Tā shì yí wèi hěn yǒumíng de huàjiā.","vn":"Cô ấy là một họa sĩ rất nổi tiếng."}]},{"hanzi":"盘子","pinyin":"pánzi","pos":"dt.","vn":"cái đĩa","examples":[{"cn":"妈妈把菜装进盘子里端上了桌。","pinyin":"Māma bǎ cài zhuāng jìn pánzi lǐ duān shàngle zhuō.","vn":"Mẹ xới thức ăn vào đĩa rồi bưng lên bàn."},{"cn":"小心点儿,别把盘子打碎了。","pinyin":"Xiǎoxīn diǎnr, bié bǎ pánzi dǎsuì le.","vn":"Cẩn thận chút, đừng làm vỡ cái đĩa."},{"cn":"桌子上摆着好几个盘子。","pinyin":"Zhuōzi shàng bǎizhe hǎojǐ gè pánzi.","vn":"Trên bàn bày mấy cái đĩa."}]},{"hanzi":"一边","pinyin":"yìbiān","pos":"phó.","vn":"vừa... vừa (đồng thời)","examples":[{"cn":"他一边吃饭一边看手机。","pinyin":"Tā yìbiān chīfàn yìbiān kàn shǒujī.","vn":"Anh ấy vừa ăn cơm vừa xem điện thoại."},{"cn":"我们一边走一边聊天儿。","pinyin":"Wǒmen yìbiān zǒu yìbiān liáotiānr.","vn":"Chúng tôi vừa đi vừa trò chuyện."},{"cn":"她一边听音乐一边做作业。","pinyin":"Tā yìbiān tīng yīnyuè yìbiān zuò zuòyè.","vn":"Cô ấy vừa nghe nhạc vừa làm bài tập."}]},{"hanzi":"聊天儿","pinyin":"liáotiānr","pos":"dgt.","vn":"trò chuyện, tán gẫu","examples":[{"cn":"我和朋友经常在网上聊天儿。","pinyin":"Wǒ hé péngyou jīngcháng zài wǎngshàng liáotiānr.","vn":"Tôi và bạn thường hay trò chuyện qua mạng."},{"cn":"晚饭后,爷爷喜欢和邻居聊天儿。","pinyin":"Wǎnfàn hòu, yéye xǐhuan hé línjū liáotiānr.","vn":"Sau bữa tối, ông nội thích trò chuyện cùng hàng xóm."},{"cn":"我们聊天儿聊得太投入,忘了时间。","pinyin":"Wǒmen liáotiānr liáo de tài tóurù, wàngle shíjiān.","vn":"Chúng tôi nói chuyện mải mê quá quên cả giờ giấc."}]},{"hanzi":"来自","pinyin":"láizì","pos":"dgt.","vn":"đến từ","examples":[{"cn":"这些留学生来自世界各地。","pinyin":"Zhèxiē liúxuéshēng láizì shìjiè gèdì.","vn":"Những du học sinh này đến từ khắp nơi trên thế giới."},{"cn":"她来自一个小城市,现在在北京工作。","pinyin":"Tā láizì yí gè xiǎo chéngshì, xiànzài zài Běijīng gōngzuò.","vn":"Cô ấy đến từ một thành phố nhỏ, giờ đang làm việc ở Bắc Kinh."},{"cn":"他的成功来自不断的努力。","pinyin":"Tā de chénggōng láizì búduàn de nǔlì.","vn":"Thành công của anh ấy đến từ sự nỗ lực không ngừng."}]},{"hanzi":"夫妻","pinyin":"fūqī","pos":"dt.","vn":"vợ chồng","examples":[{"cn":"他们是一对结婚多年的夫妻。","pinyin":"Tāmen shì yí duì jiéhūn duōnián de fūqī.","vn":"Họ là một cặp vợ chồng đã kết hôn nhiều năm."},{"cn":"这对夫妻经常一起出去旅游。","pinyin":"Zhè duì fūqī jīngcháng yìqǐ chūqù lǚyóu.","vn":"Cặp vợ chồng này thường hay cùng nhau đi du lịch."},{"cn":"夫妻之间最重要的是互相理解。","pinyin":"Fūqī zhījiān zuì zhòngyào de shì hùxiāng lǐjiě.","vn":"Điều quan trọng nhất giữa vợ chồng là hiểu nhau."}]},{"hanzi":"直到","pinyin":"zhídào","pos":"dgt.","vn":"cho đến khi","examples":[{"cn":"他一直工作,直到晚上十点才回家。","pinyin":"Tā yìzhí gōngzuò, zhídào wǎnshang shí diǎn cái huíjiā.","vn":"Anh ấy làm việc liên tục, mãi đến mười giờ tối mới về nhà."},{"cn":"我等她,直到她出现为止。","pinyin":"Wǒ děng tā, zhídào tā chūxiàn wéizhǐ.","vn":"Tôi chờ cô ấy cho đến khi cô ấy xuất hiện."},{"cn":"他一直没放弃,直到最后成功了。","pinyin":"Tā yìzhí méi fàngqì, zhídào zuìhòu chénggōng le.","vn":"Anh ấy chưa bao giờ từ bỏ, cho đến cuối cùng đã thành công."}]},{"hanzi":"地图","pinyin":"dìtú","pos":"dt.","vn":"bản đồ","examples":[{"cn":"我用手机地图找到了那家饭店。","pinyin":"Wǒ yòng shǒujī dìtú zhǎodàole nà jiā fàndiàn.","vn":"Tôi dùng bản đồ điện thoại tìm được nhà hàng đó."},{"cn":"墙上挂着一张中国地图。","pinyin":"Qiáng shàng guàzhe yì zhāng Zhōngguó dìtú.","vn":"Trên tường treo một tấm bản đồ Trung Quốc."},{"cn":"不认识路的话,可以看看地图。","pinyin":"Bú rènshi lù dehuà, kěyǐ kànkan dìtú.","vn":"Nếu không biết đường thì có thể xem bản đồ."}]},{"hanzi":"点","pinyin":"diǎn","pos":"dt.","vn":"chấm, điểm","examples":[{"cn":"黑板上有一个红色的点。","pinyin":"Hēibǎn shàng yǒu yí gè hóngsè de diǎn.","vn":"Trên bảng đen có một dấu chấm màu đỏ."},{"cn":"她在地图上画了一个点,表示我们的位置。","pinyin":"Tā zài dìtú shàng huàle yí gè diǎn, biǎoshì wǒmen de wèizhi.","vn":"Cô ấy vẽ một chấm trên bản đồ để biểu thị vị trí của chúng ta."},{"cn":"这件衣服上有很多小白点。","pinyin":"Zhè jiàn yīfu shàng yǒu hěn duō xiǎo bái diǎn.","vn":"Chiếc áo này có rất nhiều chấm trắng nhỏ."}]},{"hanzi":"感到","pinyin":"gǎndào","pos":"dgt.","vn":"cảm thấy","examples":[{"cn":"听到这个消息,我感到非常意外。","pinyin":"Tīngdào zhège xiāoxi, wǒ gǎndào fēicháng yìwài.","vn":"Nghe tin này, tôi cảm thấy rất bất ngờ."},{"cn":"第一次来中国,他感到有点儿不习惯。","pinyin":"Dìyī cì lái Zhōngguó, tā gǎndào yǒudiǎnr bù xíguàn.","vn":"Lần đầu đến Trung Quốc, anh ấy cảm thấy hơi chưa quen."},{"cn":"能帮到你,我感到很高兴。","pinyin":"Néng bāngdào nǐ, wǒ gǎndào hěn gāoxìng.","vn":"Giúp được bạn, tôi cảm thấy rất vui."}]},{"hanzi":"东方","pinyin":"dōngfāng","pos":"dt.","vn":"phương Đông","examples":[{"cn":"太阳从东方升起。","pinyin":"Tàiyáng cóng dōngfāng shēngqǐ.","vn":"Mặt trời mọc ở phương Đông."},{"cn":"东方文化和西方文化有很多不同。","pinyin":"Dōngfāng wénhuà hé xīfāng wénhuà yǒu hěn duō bùtóng.","vn":"Văn hóa phương Đông và văn hóa phương Tây có nhiều điểm khác nhau."},{"cn":"他对东方的历史很感兴趣。","pinyin":"Tā duì dōngfāng de lìshǐ hěn gǎn xìngqù.","vn":"Anh ấy rất hứng thú với lịch sử phương Đông."}]},{"hanzi":"文化","pinyin":"wénhuà","pos":"dt.","vn":"văn hóa","examples":[{"cn":"我对中国文化很感兴趣。","pinyin":"Wǒ duì Zhōngguó wénhuà hěn gǎn xìngqù.","vn":"Tôi rất hứng thú với văn hóa Trung Quốc."},{"cn":"不同国家的文化各有特点。","pinyin":"Bùtóng guójiā de wénhuà gè yǒu tèdiǎn.","vn":"Văn hóa của các nước khác nhau đều có nét đặc trưng riêng."},{"cn":"学一门语言也是在了解一种文化。","pinyin":"Xué yì mén yǔyán yě shì zài liǎojiě yì zhǒng wénhuà.","vn":"Học một ngôn ngữ cũng là đang tìm hiểu một nền văn hóa."}]},{"hanzi":"英国","pinyin":"Yīngguó","pos":"danh từ riêng","vn":"nước Anh","examples":[{"cn":"她去英国留学了三年。","pinyin":"Tā qù Yīngguó liúxué le sān nián.","vn":"Cô ấy đã đi du học ở Anh ba năm."},{"cn":"英国的天气经常下雨。","pinyin":"Yīngguó de tiānqì jīngcháng xiàyǔ.","vn":"Thời tiết ở Anh thường hay mưa."},{"cn":"他来自英国,中文说得很好。","pinyin":"Tā láizì Yīngguó, Zhōngwén shuō de hěn hǎo.","vn":"Anh ấy đến từ nước Anh, nói tiếng Trung rất giỏi."}]}],"grammar":[{"title":"假设复句\"……的话，就……\" - Câu phức giả thiết \"……的话，就……\"","explanation_vn":"Trong câu phức giả thiết \"……的话，就……\", mệnh đề trước nêu ra tình huống giả định, mệnh đề sau nêu kết quả hoặc kết luận được rút ra; cấu trúc này chủ yếu dùng trong khẩu ngữ.","examples":[{"cn":"你们有时间的话，就来我家做客。","pinyin":"Nǐmen yǒu shíjiān dehuà, jiù lái wǒ jiā zuòkè.","vn":""},{"cn":"你觉得满意的话，咱们就买。","pinyin":"Nǐ juéde mǎnyì dehuà, zánmen jiù mǎi.","vn":""},{"cn":"明天天气好的话，我就去爬山。","pinyin":"Míngtiān tiānqì hǎo dehuà, wǒ jiù qù pá shān.","vn":""}]},{"title":"\"把\"字句（4） - Câu chữ \"把\" (4)","explanation_vn":"Trong câu chữ \"把\", sau động từ sử dụng bổ ngữ xu hướng hoặc bổ ngữ trạng thái, biểu thị động tác làm cho người hoặc sự vật xác định có sự thay đổi về vị trí hoặc trạng thái. Cấu trúc cơ bản: Chủ ngữ + 把 + Tân ngữ + Động từ + Bổ ngữ xu hướng/trạng thái.","examples":[{"cn":"你把声音开得太大了。","pinyin":"Nǐ bǎ shēngyīn kāi de tài dà le.","vn":""},{"cn":"他把球踢进去了吗？","pinyin":"Tā bǎ qiú tī jìnqù le ma?","vn":""},{"cn":"你把字写得太小了，我看不清楚。","pinyin":"Nǐ bǎ zì xiě de tài xiǎo le, wǒ kàn bù qīngchǔ.","vn":""}]},{"title":"并列复句\"一边……，一边……\" - Câu phức song song \"一边……，一边……\"","explanation_vn":"Câu phức song song \"一边……，一边……\" biểu thị hai hành động diễn ra đồng thời, có thể rút gọn thành \"边……边……\".","examples":[{"cn":"咱们一边吃蛋糕，一边聊天儿吧。","pinyin":"Zánmen yìbiān chī dàngāo, yìbiān liáotiānr ba.","vn":""},{"cn":"我喜欢一边跑步，一边听音乐。","pinyin":"Wǒ xǐhuan yìbiān pǎobù, yìbiān tīng yīnyuè.","vn":""},{"cn":"你不应该边开车边打电话。","pinyin":"Nǐ bù yīnggāi biān kāichē biān dǎ diànhuà.","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"杨同乐","cn":"今天我请客，你们想吃什么就点什么！","pinyin":"Jīntiān wǒ qǐngkè, nǐmen xiǎng chī shénme jiù diǎn shénme!"},{"speaker":"王一雪","cn":"那我就不客气了。听说这家饭馆的鱼做得很特别？","pinyin":"Nà wǒ jiù bú kèqi le. Tīngshuō zhè jiā fànguǎn de yú zuò de hěn tèbié?"},{"speaker":"杨同乐","cn":"对，南方菜跟你们北方菜的做法不同。除了鱼，你们还想吃什么？","pinyin":"Duì, nánfāng cài gēn nǐmen běifāng cài de zuòfǎ bùtóng. Chúle yú, nǐmen hái xiǎng chī shénme?"},{"speaker":"同事","cn":"我不常吃南方菜，还是你决定吧。","pinyin":"Wǒ bù cháng chī nánfāng cài, háishi nǐ juédìng ba."},{"speaker":"杨同乐","cn":"好，那再加一个鸡肉，一个……","pinyin":"Hǎo, nà zài jiā yí gè jīròu, yí gè……"},{"speaker":"王一雪","cn":"咱们就三个人，别点那么多。","pinyin":"Zánmen jiù sān gè rén, bié diǎn nàme duō."},{"speaker":"杨同乐","cn":"好，那先来这几个菜。","pinyin":"Hǎo, nà xiān lái zhè jǐ gè cài."},{"speaker":"王一雪","cn":"对了，下周我儿子过生日，你们有时间的话，就来我家做客，我给你们做北京菜。","pinyin":"Duìle, xiàzhōu wǒ érzi guò shēngrì, nǐmen yǒu shíjiān dehuà, jiù lái wǒ jiā zuòkè, wǒ gěi nǐmen zuò Běijīng cài."}],"translation_vn":"Dương Đồng Nhạc: Hôm nay tôi mời khách, các bạn muốn ăn gì thì cứ gọi!\nVương Nhất Tuyết: Vậy thì tôi không khách sáo nữa. Nghe nói món cá ở nhà hàng này làm rất đặc biệt?\nDương Đồng Nhạc: Đúng vậy, món ăn miền Nam có cách chế biến khác với món ăn miền Bắc của các bạn. Ngoài cá ra, các bạn còn muốn ăn gì nữa?\nĐồng nghiệp: Tôi không thường ăn món miền Nam, cứ để anh quyết định đi.\nDương Đồng Nhạc: Được, vậy gọi thêm một món thịt gà, một...\nVương Nhất Tuyết: Chúng ta chỉ có ba người thôi, đừng gọi nhiều quá.\nDương Đồng Nhạc: Được, vậy trước tiên cứ mang mấy món này lên.\nVương Nhất Tuyết: Đúng rồi, tuần sau con trai tôi sinh nhật, nếu các bạn có thời gian thì đến nhà tôi chơi, tôi sẽ làm món Bắc Kinh cho các bạn.","audio_dialogue":"13-1.mp3","audio_vocab":"13-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"王一雪","cn":"第一次请新邻居来做客，总是担心有什么没准备好。","pinyin":"Dì yī cì qǐng xīn línjū lái zuòkè, zǒngshì dānxīn yǒu shénme méi zhǔnbèi hǎo."},{"speaker":"刘明","cn":"放心吧，我帮你看了，都已经准备好了。","pinyin":"Fàngxīn ba, wǒ bāng nǐ kàn le, dōu yǐjīng zhǔnbèi hǎo le."},{"speaker":"王一雪","cn":"我记得刚才已经把饮料拿出来了，怎么不见了？","pinyin":"Wǒ jìde gāngcái yǐjīng bǎ yǐnliào ná chūlái le, zěnme bú jiàn le?"},{"speaker":"刘明","cn":"我把饮料和酒都放进冰箱里了，客人来了再拿出来。","pinyin":"Wǒ bǎ yǐnliào hé jiǔ dōu fàng jìn bīngxiāng lǐ le, kèrén lái le zài ná chūlái."},{"speaker":"王一雪","cn":"音乐的声音合适吗？","pinyin":"Yīnyuè de shēngyīn héshì ma?"},{"speaker":"刘明","cn":"你把声音开得太大了，我去关小一点儿。","pinyin":"Nǐ bǎ shēngyīn kāi de tài dà le, wǒ qù guān xiǎo yìdiǎnr."},{"speaker":"王一雪","cn":"好，那我们就等客人来吧。","pinyin":"Hǎo, nà wǒmen jiù děng kèrén lái ba."}],"translation_vn":"Vương Nhất Tuyết: Lần đầu tiên mời hàng xóm mới đến chơi, cứ lo lắng không biết có chuẩn bị thiếu gì không.\nLưu Minh: Yên tâm đi, anh đã kiểm tra giúp em rồi, mọi thứ đều đã chuẩn bị xong cả rồi.\nVương Nhất Tuyết: Em nhớ là vừa nãy đã lấy đồ uống ra rồi, sao giờ không thấy nữa?\nLưu Minh: Anh đã cất đồ uống và rượu vào tủ lạnh rồi, đợi khách đến thì lấy ra sau.\nVương Nhất Tuyết: Âm lượng nhạc như vậy có phù hợp không?\nLưu Minh: Em mở to quá rồi, để anh đi vặn nhỏ lại một chút.\nVương Nhất Tuyết: Được rồi, vậy chúng ta cứ đợi khách đến thôi.","audio_dialogue":"13-3.mp3","audio_vocab":"13-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"王一雪","cn":"谢谢你们来参加我儿子的生日晚会，希望大家今晚玩得开心。","pinyin":"Xièxie nǐmen lái cānjiā wǒ érzi de shēngrì wǎnhuì, xīwàng dàjiā jīnwǎn wán de kāixīn."},{"speaker":"杨同乐","cn":"小明，生日快乐！我准备了一个小礼物，希望你喜欢！","pinyin":"Xiǎomíng, shēngrì kuàilè! Wǒ zhǔnbèi le yí gè xiǎo lǐwù, xīwàng nǐ xǐhuan!"},{"speaker":"刘小明","cn":"谢谢您，我可以打开吗？","pinyin":"Xièxie nín, wǒ kěyǐ dǎkāi ma?"},{"speaker":"杨同乐","cn":"当然可以，你妈妈说你跟姐姐一样，都喜欢画画，对吗？","pinyin":"Dāngrán kěyǐ, nǐ māma shuō nǐ gēn jiějie yíyàng, dōu xǐhuan huàhuà, duì ma?"},{"speaker":"刘小明","cn":"对，我想做一名画家。啊！画板和画笔，这正是我需要的。我太喜欢了。","pinyin":"Duì, wǒ xiǎng zuò yì míng huàjiā. À! Huàbǎn hé huàbǐ, zhè zhèng shì wǒ xūyào de. Wǒ tài xǐhuan le."},{"speaker":"王一雪","cn":"我去把盘子拿过来，咱们一边吃蛋糕，一边聊天儿吧。","pinyin":"Wǒ qù bǎ pánzi ná guòlái, zánmen yìbiān chī dàngāo, yìbiān liáotiānr ba."}],"translation_vn":"Vương Nhất Tuyết: Cảm ơn mọi người đã đến dự tiệc sinh nhật của con trai tôi, mong mọi người tối nay chơi vui vẻ.\nDương Đồng Nhạc: Tiểu Minh, chúc mừng sinh nhật! Chú đã chuẩn bị một món quà nhỏ, mong cháu thích nhé!\nLưu Tiểu Minh: Cháu cảm ơn chú, cháu mở ra được không ạ?\nDương Đồng Nhạc: Đương nhiên được, mẹ cháu nói cháu giống chị gái, đều thích vẽ tranh, đúng không?\nLưu Tiểu Minh: Đúng ạ, cháu muốn trở thành một họa sĩ. A! Bảng vẽ và bút vẽ, đây đúng là thứ cháu cần. Cháu thích quá.\nVương Nhất Tuyết: Mẹ đi lấy đĩa đây, chúng ta vừa ăn bánh vừa trò chuyện nhé.","audio_dialogue":"13-5.mp3","audio_vocab":"13-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"我的新邻居是来自英国的夫妻。","pinyin":"Wǒ de xīn línjū shì láizì Yīngguó de fūqī."},{"speaker":"","cn":"上周我去他们家做客了。","pinyin":"Shàng zhōu wǒ qù tāmen jiā zuòkè le."},{"speaker":"","cn":"他们做了很多好吃的，还准备了英国的红茶。","pinyin":"Tāmen zuò le hěn duō hǎochī de, hái zhǔnbèi le Yīngguó de hóngchá."},{"speaker":"","cn":"那天我跟他们一边喝红茶，一边聊天儿，直到十二点多才回家。","pinyin":"Nà tiān wǒ gēn tāmen yìbiān hē hóngchá, yìbiān liáotiānr, zhídào shí'èr diǎn duō cái huí jiā."},{"speaker":"","cn":"他们年轻的时候喜欢旅游，他家有一张世界地图，上面每一个红点都是他们去过的地方。","pinyin":"Tāmen niánqīng de shíhou xǐhuan lǚyóu, tā jiā yǒu yì zhāng shìjiè dìtú, shàngmiàn měi yí gè hóngdiǎn dōu shì tāmen qù guò de dìfāng."},{"speaker":"","cn":"后来，他们感到东方的文化很特别，就开始学习中文。","pinyin":"Hòulái, tāmen gǎndào dōngfāng de wénhuà hěn tèbié, jiù kāishǐ xuéxí Zhōngwén."},{"speaker":"","cn":"今天是小明的生日，我请他们到我家玩，来看看中国人的家，也尝尝中国菜。","pinyin":"Jīntiān shì Xiǎomíng de shēngrì, wǒ qǐng tāmen dào wǒ jiā wán, lái kànkan Zhōngguórén de jiā, yě chángchang Zhōngguó cài."}],"translation_vn":"Hàng xóm mới của tôi là một cặp vợ chồng đến từ nước Anh. Tuần trước tôi đã đến nhà họ chơi. Họ đã làm rất nhiều món ngon, còn chuẩn bị cả trà đen của Anh. Hôm đó tôi vừa uống trà đen với họ vừa trò chuyện, mãi đến hơn mười hai giờ mới về nhà. Lúc còn trẻ họ rất thích đi du lịch, nhà họ có một tấm bản đồ thế giới, trên đó mỗi một chấm đỏ đều là nơi họ đã từng đến. Sau này, họ cảm thấy văn hóa phương Đông rất đặc biệt, nên bắt đầu học tiếng Trung. Hôm nay là sinh nhật của Tiểu Minh, tôi mời họ đến nhà tôi chơi, để xem nhà của người Trung Quốc như thế nào, và cũng để nếm thử món ăn Trung Quốc.","audio_dialogue":"13-7.mp3","audio_vocab":"13-8.mp3"}]},{"id":14,"title_cn":"这本书被别人借走了","title_pinyin":"Zhè běn shū bèi biérén jiè zǒu le","title_vn":"Cuốn sách này đã bị người khác mượn mất rồi","goals":["Có thể nghe hiểu và giới thiệu về các hoạt động trong khuôn viên trường học.","Có thể nghe hiểu và bày tỏ sự động viên, khích lệ đối với người khác.","Nắm vững cách dùng câu bị động (1) để biểu đạt ý nghĩa bị động."],"vocab":[{"hanzi":"词典","pinyin":"cídiǎn","pos":"dt.","vn":"từ điển","examples":[{"cn":"我不认识这个字,查一下词典吧。","pinyin":"Wǒ bú rènshi zhège zì, chá yíxià cídiǎn ba.","vn":"Tôi không biết chữ này, tra từ điển xem."},{"cn":"学外语的时候,词典是很有用的工具。","pinyin":"Xué wàiyǔ de shíhou, cídiǎn shì hěn yǒuyòng de gōngjù.","vn":"Khi học ngoại ngữ, từ điển là một công cụ rất hữu ích."},{"cn":"我手机里有一个汉语词典。","pinyin":"Wǒ shǒujī lǐ yǒu yí gè Hànyǔ cídiǎn.","vn":"Trong điện thoại tôi có một quyển từ điển tiếng Hán."}]},{"hanzi":"最好","pinyin":"zuìhǎo","pos":"phó.","vn":"tốt nhất nên","examples":[{"cn":"下雨了,你最好带把伞。","pinyin":"Xiàyǔ le, nǐ zuìhǎo dài bǎ sǎn.","vn":"Trời mưa rồi, bạn tốt nhất nên mang theo cây dù."},{"cn":"身体不舒服的话,最好去医院看看。","pinyin":"Shēntǐ bù shūfu dehuà, zuìhǎo qù yīyuàn kànkan.","vn":"Nếu cơ thể không khỏe thì tốt nhất nên đi khám bệnh viện."},{"cn":"考试前最好多复习几遍。","pinyin":"Kǎoshì qián zuìhǎo duō fùxí jǐ biàn.","vn":"Trước khi thi tốt nhất nên ôn lại nhiều lần."}]},{"hanzi":"节","pinyin":"jié","pos":"lượng.","vn":"tiết (buổi học)","examples":[{"cn":"我们今天有四节课。","pinyin":"Wǒmen jīntiān yǒu sì jié kè.","vn":"Hôm nay chúng tôi có bốn tiết học."},{"cn":"下一节是数学课。","pinyin":"Xià yì jié shì shùxué kè.","vn":"Tiết sau là tiết toán."},{"cn":"这节课讲得特别有意思。","pinyin":"Zhè jié kè jiǎng de tèbié yǒu yìsi.","vn":"Tiết học này giảng rất thú vị."}]},{"hanzi":"图书馆","pinyin":"túshūguǎn","pos":"dt.","vn":"thư viện","examples":[{"cn":"周末我常常去图书馆看书。","pinyin":"Zhōumò wǒ chángcháng qù túshūguǎn kànshū.","vn":"Cuối tuần tôi thường hay đến thư viện đọc sách."},{"cn":"图书馆里很安静,很适合学习。","pinyin":"Túshūguǎn lǐ hěn ānjìng, hěn shìhé xuéxí.","vn":"Trong thư viện rất yên tĩnh, rất thích hợp để học bài."},{"cn":"这本书可以在图书馆借到。","pinyin":"Zhè běn shū kěyǐ zài túshūguǎn jièdào.","vn":"Quyển sách này có thể mượn được ở thư viện."}]},{"hanzi":"被","pinyin":"bèi","pos":"giới.","vn":"bị (dùng biểu thị ý bị động)","examples":[{"cn":"我的自行车被偷了。","pinyin":"Wǒ de zìxíngchē bèi tōu le.","vn":"Xe đạp của tôi bị mất trộm rồi."},{"cn":"他被老师叫到办公室去了。","pinyin":"Tā bèi lǎoshī jiào dào bàngōngshì qù le.","vn":"Cậu ấy bị thầy giáo gọi lên văn phòng."},{"cn":"这个故事被拍成了电影。","pinyin":"Zhège gùshi bèi pāichéngle diànyǐng.","vn":"Câu chuyện này đã được dựng thành phim."}]},{"hanzi":"名人","pinyin":"míngrén","pos":"dt.","vn":"người nổi tiếng","examples":[{"cn":"这个饭店里挂着很多名人的照片。","pinyin":"Zhège fàndiàn lǐ guàzhe hěn duō míngrén de zhàopiàn.","vn":"Trong nhà hàng này treo rất nhiều ảnh người nổi tiếng."},{"cn":"他从一个普通人变成了名人。","pinyin":"Tā cóng yí gè pǔtōng rén biànchéngle míngrén.","vn":"Anh ấy từ một người bình thường trở thành người nổi tiếng."},{"cn":"很多名人都来过这所大学演讲。","pinyin":"Hěn duō míngrén dōu láiguo zhè suǒ dàxué yǎnjiǎng.","vn":"Rất nhiều người nổi tiếng đã từng đến trường đại học này diễn thuyết."}]},{"hanzi":"故事","pinyin":"gùshi","pos":"dt.","vn":"câu chuyện","examples":[{"cn":"妈妈每天晚上都给我讲故事。","pinyin":"Māma měitiān wǎnshang dōu gěi wǒ jiǎng gùshi.","vn":"Mỗi tối mẹ đều kể chuyện cho tôi nghe."},{"cn":"这是一个真实发生的故事。","pinyin":"Zhè shì yí gè zhēnshí fāshēng de gùshi.","vn":"Đây là một câu chuyện có thật."},{"cn":"这部电影讲的是一个爱情故事。","pinyin":"Zhè bù diànyǐng jiǎng de shì yí gè àiqíng gùshi.","vn":"Bộ phim này kể về một câu chuyện tình yêu."}]},{"hanzi":"然后","pinyin":"ránhòu","pos":"liên.","vn":"sau đó","examples":[{"cn":"我先写作业,然后再看电视。","pinyin":"Wǒ xiān xiě zuòyè, ránhòu zài kàn diànshì.","vn":"Tôi làm bài tập trước, sau đó mới xem ti vi."},{"cn":"把菜洗干净,然后切成小块。","pinyin":"Bǎ cài xǐ gānjìng, ránhòu qiēchéng xiǎo kuài.","vn":"Rửa sạch rau, sau đó cắt thành miếng nhỏ."},{"cn":"我们先去图书馆,然后一起吃饭。","pinyin":"Wǒmen xiān qù túshūguǎn, ránhòu yìqǐ chīfàn.","vn":"Chúng ta đi thư viện trước, sau đó cùng ăn cơm."}]},{"hanzi":"报纸","pinyin":"bàozhǐ","pos":"dt.","vn":"báo","examples":[{"cn":"爷爷每天早上都看报纸。","pinyin":"Yéye měitiān zǎoshang dōu kàn bàozhǐ.","vn":"Sáng nào ông nội cũng đọc báo."},{"cn":"这件事上了今天的报纸。","pinyin":"Zhè jiàn shì shàngle jīntiān de bàozhǐ.","vn":"Chuyện này đã lên báo hôm nay."},{"cn":"现在很少有人买报纸了。","pinyin":"Xiànzài hěn shǎo yǒu rén mǎi bàozhǐ le.","vn":"Bây giờ rất ít người mua báo nữa."}]},{"hanzi":"忘记","pinyin":"wàngjì","pos":"dgt.","vn":"quên","examples":[{"cn":"我忘记带钥匙了。","pinyin":"Wǒ wàngjì dài yàoshi le.","vn":"Tôi quên mang chìa khóa rồi."},{"cn":"别忘记明天的考试。","pinyin":"Bié wàngjì míngtiān de kǎoshì.","vn":"Đừng quên kỳ thi vào ngày mai."},{"cn":"我永远不会忘记这件事。","pinyin":"Wǒ yǒngyuǎn bú huì wàngjì zhè jiàn shì.","vn":"Tôi sẽ không bao giờ quên chuyện này."}]},{"hanzi":"电子书","pinyin":"diànzǐshū","pos":"dt.","vn":"sách điện tử","examples":[{"cn":"现在很多人喜欢看电子书。","pinyin":"Xiànzài hěn duō rén xǐhuan kàn diànzǐshū.","vn":"Bây giờ rất nhiều người thích đọc sách điện tử."},{"cn":"电子书不占地方,很方便带着。","pinyin":"Diànzǐshū bú zhàn dìfang, hěn fāngbiàn dàizhe.","vn":"Sách điện tử không chiếm chỗ, mang theo rất tiện."},{"cn":"我在手机上下载了一本电子书。","pinyin":"Wǒ zài shǒujī shàng xiàzàile yì běn diànzǐshū.","vn":"Tôi đã tải một quyển sách điện tử trên điện thoại."}]},{"hanzi":"女生","pinyin":"nǚshēng","pos":"dt.","vn":"nữ sinh","examples":[{"cn":"我们班的女生比男生多。","pinyin":"Wǒmen bān de nǚshēng bǐ nánshēng duō.","vn":"Lớp chúng tôi nữ sinh nhiều hơn nam sinh."},{"cn":"那个女生唱歌唱得很好听。","pinyin":"Nàge nǚshēng chànggē chàng de hěn hǎotīng.","vn":"Cô nữ sinh đó hát rất hay."},{"cn":"她是我们学校最优秀的女生之一。","pinyin":"Tā shì wǒmen xuéxiào zuì yōuxiù de nǚshēng zhīyī.","vn":"Cô ấy là một trong những nữ sinh xuất sắc nhất trường chúng tôi."}]},{"hanzi":"表演","pinyin":"biǎoyǎn","pos":"dgt.","vn":"biểu diễn","examples":[{"cn":"晚会上,她为大家表演了一个舞蹈。","pinyin":"Wǎnhuì shàng, tā wèi dàjiā biǎoyǎnle yí gè wǔdǎo.","vn":"Trong buổi dạ hội, cô ấy đã biểu diễn một tiết mục múa cho mọi người."},{"cn":"他从小就喜欢在大家面前表演。","pinyin":"Tā cóngxiǎo jiù xǐhuan zài dàjiā miànqián biǎoyǎn.","vn":"Từ nhỏ cậu ấy đã thích biểu diễn trước mặt mọi người."},{"cn":"这场表演真的太精彩了。","pinyin":"Zhè chǎng biǎoyǎn zhēnde tài jīngcǎi le.","vn":"Buổi biểu diễn này thật sự quá tuyệt vời."}]},{"hanzi":"节目","pinyin":"jiémù","pos":"dt.","vn":"tiết mục","examples":[{"cn":"你最近在看什么电视节目?","pinyin":"Nǐ zuìjìn zài kàn shénme diànshì jiémù?","vn":"Gần đây bạn đang xem chương trình truyền hình gì?"},{"cn":"晚会上有很多精彩的节目。","pinyin":"Wǎnhuì shàng yǒu hěn duō jīngcǎi de jiémù.","vn":"Trong buổi dạ hội có rất nhiều tiết mục hấp dẫn."},{"cn":"我们班准备了一个跳舞的节目。","pinyin":"Wǒmen bān zhǔnbèile yí gè tiàowǔ de jiémù.","vn":"Lớp chúng tôi đã chuẩn bị một tiết mục nhảy múa."}]},{"hanzi":"怎么办","pinyin":"zěnme bàn","pos":"","vn":"phải làm sao, làm thế nào","examples":[{"cn":"手机丢了,怎么办?","pinyin":"Shǒujī diū le, zěnme bàn?","vn":"Điện thoại bị mất rồi, phải làm sao đây?"},{"cn":"如果明天下雨,怎么办?","pinyin":"Rúguǒ míngtiān xiàyǔ, zěnme bàn?","vn":"Nếu ngày mai mưa thì phải làm thế nào?"},{"cn":"我不知道该怎么办才好。","pinyin":"Wǒ bù zhīdào gāi zěnme bàn cái hǎo.","vn":"Tôi không biết nên làm sao cho phải."}]},{"hanzi":"校长","pinyin":"xiàozhǎng","pos":"dt.","vn":"hiệu trưởng","examples":[{"cn":"校长今天在全校大会上讲话了。","pinyin":"Xiàozhǎng jīntiān zài quánxiào dàhuì shàng jiǎnghuà le.","vn":"Hôm nay hiệu trưởng đã phát biểu trong buổi họp toàn trường."},{"cn":"我们校长对学生特别严格。","pinyin":"Wǒmen xiàozhǎng duì xuésheng tèbié yángé.","vn":"Hiệu trưởng trường chúng tôi rất nghiêm khắc với học sinh."},{"cn":"校长办公室在三楼。","pinyin":"Xiàozhǎng bàngōngshì zài sān lóu.","vn":"Văn phòng hiệu trưởng ở tầng ba."}]},{"hanzi":"面前","pinyin":"miànqián","pos":"dt.","vn":"trước mặt","examples":[{"cn":"他在老师面前从来不说谎。","pinyin":"Tā zài lǎoshī miànqián cónglái bù shuōhuǎng.","vn":"Trước mặt thầy giáo, cậu ấy không bao giờ nói dối."},{"cn":"困难摆在我们面前,但我们不会放弃。","pinyin":"Kùnnan bǎi zài wǒmen miànqián, dàn wǒmen bú huì fàngqì.","vn":"Khó khăn bày ra trước mắt chúng tôi nhưng chúng tôi sẽ không bỏ cuộc."},{"cn":"她不敢在那么多人面前讲话。","pinyin":"Tā bù gǎn zài nàme duō rén miànqián jiǎnghuà.","vn":"Cô ấy không dám phát biểu trước mặt nhiều người như vậy."}]},{"hanzi":"有些","pinyin":"yǒuxiē","pos":"phó.","vn":"hơi, có chút","examples":[{"cn":"这道题有些难,我不太会做。","pinyin":"Zhè dào tí yǒuxiē nán, wǒ bú tài huì zuò.","vn":"Câu hỏi này hơi khó, tôi không làm được lắm."},{"cn":"听到这个消息,她有些激动。","pinyin":"Tīngdào zhège xiāoxi, tā yǒuxiē jīdòng.","vn":"Nghe tin này, cô ấy có chút xúc động."},{"cn":"他今天看起来有些累。","pinyin":"Tā jīntiān kàn qǐlái yǒuxiē lèi.","vn":"Hôm nay nhìn anh ấy có vẻ hơi mệt."}]},{"hanzi":"相信","pinyin":"xiāngxìn","pos":"dgt.","vn":"tin tưởng","examples":[{"cn":"我相信他一定会成功的。","pinyin":"Wǒ xiāngxìn tā yídìng huì chénggōng de.","vn":"Tôi tin rằng anh ấy chắc chắn sẽ thành công."},{"cn":"你说的话我都相信。","pinyin":"Nǐ shuō de huà wǒ dōu xiāngxìn.","vn":"Những gì bạn nói tôi đều tin."},{"cn":"没有人相信他说的故事。","pinyin":"Méiyǒu rén xiāngxìn tā shuō de gùshi.","vn":"Không ai tin câu chuyện anh ấy kể."}]},{"hanzi":"新年","pinyin":"xīnnián","pos":"dt.","vn":"năm mới","examples":[{"cn":"祝你新年快乐!","pinyin":"Zhù nǐ xīnnián kuàilè!","vn":"Chúc bạn năm mới vui vẻ!"},{"cn":"新年到了,家家户户都很热闹。","pinyin":"Xīnnián dào le, jiājiāhùhù dōu hěn rènao.","vn":"Năm mới đến rồi, nhà nhà đều nhộn nhịp."},{"cn":"我们学校举办了一个新年晚会。","pinyin":"Wǒmen xuéxiào jǔbànle yí gè xīnnián wǎnhuì.","vn":"Trường chúng tôi đã tổ chức một buổi dạ hội năm mới."}]},{"hanzi":"班级","pinyin":"bānjí","pos":"dt.","vn":"lớp học (các lớp)","examples":[{"cn":"我们班级一共有三十个学生。","pinyin":"Wǒmen bānjí yígòng yǒu sānshí gè xuésheng.","vn":"Lớp chúng tôi có tổng cộng ba mươi học sinh."},{"cn":"每个班级都要表演一个节目。","pinyin":"Měi gè bānjí dōu yào biǎoyǎn yí gè jiémù.","vn":"Mỗi lớp đều phải biểu diễn một tiết mục."},{"cn":"这个班级的成绩在学校里是最好的。","pinyin":"Zhège bānjí de chéngjì zài xuéxiào lǐ shì zuì hǎo de.","vn":"Thành tích của lớp này tốt nhất trong trường."}]},{"hanzi":"跳","pinyin":"tiào","pos":"dgt.","vn":"nhảy","examples":[{"cn":"她跳得特别好看。","pinyin":"Tā tiào de tèbié hǎokàn.","vn":"Cô ấy nhảy rất đẹp."},{"cn":"孩子们高兴得跳了起来。","pinyin":"Háizimen gāoxìng de tiàole qǐlái.","vn":"Bọn trẻ vui đến mức nhảy cẫng lên."},{"cn":"晚会上我们要一起跳舞。","pinyin":"Wǎnhuì shàng wǒmen yào yìqǐ tiàowǔ.","vn":"Trong buổi dạ hội chúng tôi sẽ cùng nhau nhảy múa."}]},{"hanzi":"留学生","pinyin":"liúxuéshēng","pos":"dt.","vn":"du học sinh","examples":[{"cn":"这所大学有很多留学生。","pinyin":"Zhè suǒ dàxué yǒu hěn duō liúxuéshēng.","vn":"Trường đại học này có rất nhiều du học sinh."},{"cn":"我是来自越南的留学生。","pinyin":"Wǒ shì láizì Yuènán de liúxuéshēng.","vn":"Tôi là du học sinh đến từ Việt Nam."},{"cn":"留学生们一起过了一个特别的新年。","pinyin":"Liúxuéshēngmen yìqǐ guòle yí gè tèbié de xīnnián.","vn":"Các du học sinh đã cùng nhau đón một cái Tết đặc biệt."}]},{"hanzi":"最后","pinyin":"zuìhòu","pos":"dt.","vn":"cuối cùng","examples":[{"cn":"最后,他还是决定留下来。","pinyin":"Zuìhòu, tā háishi juédìng liú xiàlái.","vn":"Cuối cùng, anh ấy vẫn quyết định ở lại."},{"cn":"比赛的最后,我们队赢了。","pinyin":"Bǐsài de zuìhòu, wǒmen duì yíng le.","vn":"Cuối trận đấu, đội chúng tôi đã thắng."},{"cn":"这是我今天说的最后一句话。","pinyin":"Zhè shì wǒ jīntiān shuō de zuìhòu yí jù huà.","vn":"Đây là câu nói cuối cùng của tôi hôm nay."}]},{"hanzi":"一块儿","pinyin":"yíkuàir","pos":"phó.","vn":"cùng nhau","examples":[{"cn":"我们一块儿去吃饭吧。","pinyin":"Wǒmen yíkuàir qù chīfàn ba.","vn":"Chúng ta cùng nhau đi ăn cơm nhé."},{"cn":"周末你想不想和我一块儿去逛街?","pinyin":"Zhōumò nǐ xiǎng bu xiǎng hé wǒ yíkuàir qù guàngjiē?","vn":"Cuối tuần bạn có muốn cùng tôi đi dạo phố không?"},{"cn":"我们从小一块儿长大。","pinyin":"Wǒmen cóngxiǎo yíkuàir zhǎngdà.","vn":"Chúng tôi cùng nhau lớn lên từ nhỏ."}]},{"hanzi":"网站","pinyin":"wǎngzhàn","pos":"dt.","vn":"trang web","examples":[{"cn":"我在这个网站上买了一件衣服。","pinyin":"Wǒ zài zhège wǎngzhàn shàng mǎile yí jiàn yīfu.","vn":"Tôi đã mua một chiếc áo trên trang web này."},{"cn":"这个网站的信息不太可靠。","pinyin":"Zhège wǎngzhàn de xìnxī bú tài kěkào.","vn":"Thông tin trên trang web này không đáng tin cậy lắm."},{"cn":"你可以在学校网站上查课程表。","pinyin":"Nǐ kěyǐ zài xuéxiào wǎngzhàn shàng chá kèchéngbiǎo.","vn":"Bạn có thể tra thời khóa biểu trên trang web của trường."}]},{"hanzi":"视频","pinyin":"shìpín","pos":"dt.","vn":"video","examples":[{"cn":"我每天都会看一些有意思的视频。","pinyin":"Wǒ měitiān dōu huì kàn yìxiē yǒu yìsi de shìpín.","vn":"Mỗi ngày tôi đều xem một vài video thú vị."},{"cn":"他拍了一个视频发到网站上。","pinyin":"Tā pāile yí gè shìpín fā dào wǎngzhàn shàng.","vn":"Anh ấy quay một video rồi đăng lên trang web."},{"cn":"我们可以用视频聊天。","pinyin":"Wǒmen kěyǐ yòng shìpín liáotiān.","vn":"Chúng ta có thể trò chuyện qua video."}]}],"grammar":[{"title":"被动句（1） - Câu bị động (1)","explanation_vn":"Trong tiếng Hán, câu có chữ \"被\" biểu đạt ý nghĩa bị động, nhấn mạnh chủ ngữ chịu ảnh hưởng của một động tác nào đó, thường mang sắc thái bị động, bất đắc dĩ hoặc tiêu cực. Phó từ và động từ năng nguyện đặt trước chữ \"被\", tân ngữ sau chữ \"被\" có thể lược bỏ. Cấu trúc cơ bản: Chủ ngữ + 被 + Tân ngữ + Động từ + Thành phần khác.","examples":[{"cn":"这本书被别人借走了。","pinyin":"Zhè běn shū bèi biérén jiè zǒu le.","vn":""},{"cn":"水果可能被弟弟吃了。","pinyin":"Shuǐguǒ kěnéng bèi dìdi chī le.","vn":""},{"cn":"我们俩经常被叫错名字。","pinyin":"Wǒmen liǎ jīngcháng bèi jiào cuò míngzi.","vn":""}]},{"title":"承接复句\"先……，再/然后……\" - Câu phức tiếp nối \"先……，再/然后……\"","explanation_vn":"Trong câu phức tiếp nối \"先……，再/然后……\", hai mệnh đề biểu thị trình tự trước sau của các hành động.","examples":[{"cn":"我要先去图书馆借书，然后去游泳。","pinyin":"Wǒ yào xiān qù túshūguǎn jiè shū, ránhòu qù yóuyǒng.","vn":""},{"cn":"你先去买门票，再来这里找我。","pinyin":"Nǐ xiān qù mǎi ménpiào, zài lái zhèlǐ zhǎo wǒ.","vn":""},{"cn":"你们先回房间休息一会儿，然后再出来吃晚饭。","pinyin":"Nǐmen xiān huí fángjiān xiūxi yíhuìr, ránhòu zài chūlái chī wǎnfàn.","vn":""}]},{"title":"固定格式\"×什么（啊）\" - Cấu trúc cố định \"×什么（啊）\"","explanation_vn":"Cấu trúc cố định \"×什么（啊）\" thường dùng để phủ nhận sự lo lắng, nghi ngờ của đối phương hoặc nhấn mạnh một sự thật, mang giọng điệu phản bác hoặc an ủi.","examples":[{"cn":"紧张什么啊，我们都喜欢听你唱歌，你要相信自己。","pinyin":"Jǐnzhāng shénme a, wǒmen dōu xǐhuan tīng nǐ chànggē, nǐ yào xiāngxìn zìjǐ.","vn":""},{"cn":"胖什么啊，你看起来不胖也不瘦。","pinyin":"Pàng shénme a, nǐ kànqǐlái bú pàng yě bú shòu.","vn":""},{"cn":"急什么啊，马上就到了。","pinyin":"Jí shénme a, mǎshàng jiù dào le.","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"李文","cn":"我借的这本词典最好今天还，但是我没时间去。","pinyin":"Wǒ jiè de zhè běn cídiǎn zuìhǎo jīntiān huán, dànshì wǒ méi shíjiān qù."},{"speaker":"白家月","cn":"下午我只有两节课，可以帮你去图书馆还书。","pinyin":"Xiàwǔ wǒ zhǐyǒu liǎng jié kè, kěyǐ bāng nǐ qù túshūguǎn huán shū."},{"speaker":"李文","cn":"那太谢谢了。你能再帮我借本书吗？","pinyin":"Nà tài xièxie le. Nǐ néng zài bāng wǒ jiè běn shū ma?"},{"speaker":"白家月","cn":"行，你告诉我书名。","pinyin":"Xíng, nǐ gàosu wǒ shūmíng."},{"speaker":"李文","cn":"我把名字写在纸上吧。我去了好几次图书馆，这本书都被别人借走了。","pinyin":"Wǒ bǎ míngzi xiě zài zhǐ shàng ba. Wǒ qù le hǎo jǐ cì túshūguǎn, zhè běn shū dōu bèi biérén jiè zǒu le."},{"speaker":"白家月","cn":"《名人的故事》？我有这本书。明天我借给你吧。","pinyin":"《Míngrén de Gùshi》? Wǒ yǒu zhè běn shū. Míngtiān wǒ jiè gěi nǐ ba."}],"translation_vn":"Lý Văn: Cuốn từ điển mình mượn tốt nhất nên trả hôm nay, nhưng mình không có thời gian đi.\nBạch Gia Nguyệt: Chiều nay mình chỉ có hai tiết học, có thể giúp bạn đi trả sách ở thư viện.\nLý Văn: Vậy cảm ơn bạn nhiều lắm. Bạn có thể giúp mình mượn thêm một cuốn sách nữa được không?\nBạch Gia Nguyệt: Được, bạn cho mình biết tên sách đi.\nLý Văn: Để mình viết tên sách ra giấy nhé. Mình đã đến thư viện mấy lần rồi, cuốn sách này đều đã bị người khác mượn mất.\nBạch Gia Nguyệt: \"Câu chuyện về những người nổi tiếng\"? Mình có cuốn này. Ngày mai mình cho bạn mượn nhé.","audio_dialogue":"14-1.mp3","audio_vocab":"14-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"安妮","cn":"今天下课早，你一会儿做什么？","pinyin":"Jīntiān xiàkè zǎo, nǐ yíhuìr zuò shénme?"},{"speaker":"白家月","cn":"我今天忙得很，要先去图书馆借书，然后去游泳。","pinyin":"Wǒ jīntiān máng de hěn, yào xiān qù túshūguǎn jiè shū, ránhòu qù yóuyǒng."},{"speaker":"安妮","cn":"咱们一起走吧，我想去图书馆看看中文报纸。","pinyin":"Zánmen yìqǐ zǒu ba, wǒ xiǎng qù túshūguǎn kànkan Zhōngwén bàozhǐ."},{"speaker":"白家月","cn":"等等，我的校园卡不见了，没有卡进不去图书馆。","pinyin":"Děngděng, wǒ de xiàoyuánkǎ bú jiàn le, méiyǒu kǎ jìn bu qù túshūguǎn."},{"speaker":"安妮","cn":"你想想上一次用是什么时候？","pinyin":"Nǐ xiǎngxiang shàng yí cì yòng shì shénme shíhou?"},{"speaker":"白家月","cn":"我忘记了，可能被我放在家里了。","pinyin":"Wǒ wàngjì le, kěnéng bèi wǒ fàng zài jiā lǐ le."},{"speaker":"安妮","cn":"进不去图书馆也没关系，上网看看有没有电子书。","pinyin":"Jìn bu qù túshūguǎn yě méi guānxi, shàngwǎng kànkan yǒu méiyǒu diànzǐshū."},{"speaker":"白家月","cn":"不行，我必须去，我还得帮李文还书呢。","pinyin":"Bù xíng, wǒ bìxū qù, wǒ hái děi bāng Lǐ Wén huán shū ne."}],"translation_vn":"Annie: Hôm nay tan học sớm, lát nữa bạn làm gì?\nBạch Gia Nguyệt: Hôm nay mình bận lắm, phải đi thư viện mượn sách trước, sau đó đi bơi.\nAnnie: Chúng ta cùng đi nhé, mình muốn đến thư viện xem báo tiếng Trung.\nBạch Gia Nguyệt: Khoan đã, thẻ sinh viên của mình không thấy đâu rồi, không có thẻ thì không vào thư viện được.\nAnnie: Bạn thử nghĩ xem lần trước dùng là khi nào?\nBạch Gia Nguyệt: Mình quên mất rồi, có thể đã bị mình để quên ở nhà.\nAnnie: Không vào được thư viện cũng không sao, lên mạng xem có sách điện tử không.\nBạch Gia Nguyệt: Không được, mình nhất định phải đi, mình còn phải giúp Lý Văn trả sách nữa.","audio_dialogue":"14-3.mp3","audio_vocab":"14-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"李文","cn":"下周学校有晚会，你知道吗？","pinyin":"Xiàzhōu xuéxiào yǒu wǎnhuì, nǐ zhīdào ma?"},{"speaker":"白家月","cn":"知道，我和几个女生要表演一个节目。你也参加吗？","pinyin":"Zhīdào, wǒ hé jǐ gè nǚshēng yào biǎoyǎn yí gè jiémù. Nǐ yě cānjiā ma?"},{"speaker":"李文","cn":"我想唱中文歌，但是还没找到人一起表演，不知道怎么办。","pinyin":"Wǒ xiǎng chàng Zhōngwén gē, dànshì hái méi zhǎodào rén yìqǐ biǎoyǎn, bù zhīdào zěnme bàn."},{"speaker":"白家月","cn":"找不到人，你就一个人唱吧。","pinyin":"Zhǎo bu dào rén, nǐ jiù yí gè rén chàng ba."},{"speaker":"李文","cn":"一想到要在校长、老师和那么多同学面前表演，我就有些紧张。","pinyin":"Yì xiǎngdào yào zài xiàozhǎng, lǎoshī hé nàme duō tóngxué miànqián biǎoyǎn, wǒ jiù yǒuxiē jǐnzhāng."},{"speaker":"白家月","cn":"紧张什么啊，我们都喜欢听你唱歌，你要相信自己。","pinyin":"Jǐnzhāng shénme a, wǒmen dōu xǐhuan tīng nǐ chànggē, nǐ yào xiāngxìn zìjǐ."}],"translation_vn":"Lý Văn: Tuần sau trường có tổ chức dạ hội, bạn biết chưa?\nBạch Gia Nguyệt: Biết rồi, mình và vài bạn nữ sẽ biểu diễn một tiết mục. Bạn cũng tham gia à?\nLý Văn: Mình muốn hát một bài tiếng Trung, nhưng vẫn chưa tìm được người biểu diễn cùng, không biết phải làm sao.\nBạch Gia Nguyệt: Không tìm được người thì bạn cứ hát một mình đi.\nLý Văn: Hễ nghĩ đến việc phải biểu diễn trước mặt hiệu trưởng, thầy cô và bao nhiêu bạn học là mình lại thấy hơi hồi hộp.\nBạch Gia Nguyệt: Hồi hộp gì chứ, chúng mình đều thích nghe bạn hát, bạn phải tin vào bản thân mình.","audio_dialogue":"14-5.mp3","audio_vocab":"14-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"昨天是我们学校的新年晚会，每个班级的同学都表演节目了。","pinyin":"Zuótiān shì wǒmen xuéxiào de xīnnián wǎnhuì, měi gè bānjí de tóngxué dōu biǎoyǎn jiémù le."},{"speaker":"","cn":"晚会是八点开始的，差不多十二点才结束。","pinyin":"Wǎnhuì shì bā diǎn kāishǐ de, chàbuduō shí'èr diǎn cái jiéshù."},{"speaker":"","cn":"我一个晚上跟大家一起又唱又跳，开心极了，也累坏了。","pinyin":"Wǒ yí gè wǎnshàng gēn dàjiā yìqǐ yòu chàng yòu tiào, kāixīn jí le, yě lèi huài le."},{"speaker":"","cn":"我最喜欢的节目是留学生们跳舞，最后老师和校长也被叫起来一块儿跳，特别有意思。","pinyin":"Wǒ zuì xǐhuan de jiémù shì liúxuéshēngmen tiàowǔ, zuìhòu lǎoshī hé xiàozhǎng yě bèi jiào qǐlái yíkuàir tiào, tèbié yǒu yìsi."},{"speaker":"","cn":"过几天学校的网站上会有晚会的视频，我打算再看一遍。","pinyin":"Guò jǐ tiān xuéxiào de wǎngzhàn shàng huì yǒu wǎnhuì de shìpín, wǒ dǎsuàn zài kàn yí biàn."}],"translation_vn":"Hôm qua là buổi dạ hội mừng năm mới của trường chúng tôi, các bạn học sinh mỗi lớp đều biểu diễn tiết mục. Buổi dạ hội bắt đầu lúc tám giờ, gần mười hai giờ mới kết thúc. Cả buổi tối tôi cùng mọi người vừa hát vừa nhảy, vui vô cùng, cũng mệt lử luôn. Tiết mục tôi thích nhất là các du học sinh nhảy múa, cuối cùng thầy cô và hiệu trưởng cũng bị gọi lên nhảy cùng, thật là thú vị. Vài hôm nữa trên trang web của trường sẽ có video buổi dạ hội, tôi định xem lại một lần nữa.","audio_dialogue":"14-7.mp3","audio_vocab":"14-8.mp3"}]},{"id":15,"title_cn":"我是半个南京人","title_pinyin":"Wǒ shì bàn gè Nánjīngrén","title_vn":"Tôi coi như nửa người Nam Kinh","goals":["Có thể nghe hiểu và miêu tả vị trí cũng như thông tin môi trường xung quanh của một địa điểm.","Có thể nghe hiểu và giới thiệu về cảnh quan thiên nhiên hoặc lịch sử văn hóa của một địa điểm.","Nắm vững cụm từ \"在……看来\" để biểu đạt quan điểm của cá nhân hoặc một nhóm người.","Tìm hiểu những thông tin cơ bản về Nam Kinh và sông Hoàng Hà."],"vocab":[{"hanzi":"蓝","pinyin":"lán","pos":"tt.","vn":"xanh lam","examples":[{"cn":"今天天空特别蓝。","pinyin":"Jīntiān tiānkōng tèbié lán.","vn":"Hôm nay bầu trời xanh lam đặc biệt đẹp."},{"cn":"她穿了一条蓝色的裙子。","pinyin":"Tā chuānle yì tiáo lánsè de qúnzi.","vn":"Cô ấy mặc một chiếc váy màu xanh lam."},{"cn":"我最喜欢的颜色是蓝色。","pinyin":"Wǒ zuì xǐhuan de yánsè shì lánsè.","vn":"Màu tôi thích nhất là màu xanh lam."}]},{"hanzi":"段","pinyin":"duàn","pos":"lượng.","vn":"đoạn (quãng thời gian hoặc quãng đường)","examples":[{"cn":"这段路不长,走路十分钟就到了。","pinyin":"Zhè duàn lù bù cháng, zǒulù shí fēnzhōng jiù dào le.","vn":"Đoạn đường này không dài, đi bộ mười phút là tới."},{"cn":"那段时间我特别忙。","pinyin":"Nà duàn shíjiān wǒ tèbié máng.","vn":"Khoảng thời gian đó tôi rất bận."},{"cn":"请你再读一遍这段课文。","pinyin":"Qǐng nǐ zài dú yí biàn zhè duàn kèwén.","vn":"Xin bạn đọc lại đoạn văn này một lần nữa."}]},{"hanzi":"附近","pinyin":"fùjìn","pos":"dt.","vn":"gần đó, lân cận","examples":[{"cn":"我家附近有一个公园。","pinyin":"Wǒ jiā fùjìn yǒu yí gè gōngyuán.","vn":"Gần nhà tôi có một công viên."},{"cn":"学校附近新开了一家饭店。","pinyin":"Xuéxiào fùjìn xīn kāile yì jiā fàndiàn.","vn":"Gần trường mới mở một nhà hàng."},{"cn":"我在附近找了一下,没看到他。","pinyin":"Wǒ zài fùjìn zhǎole yíxià, méi kàndào tā.","vn":"Tôi tìm quanh đây một chút nhưng không thấy anh ấy."}]},{"hanzi":"马路","pinyin":"mǎlù","pos":"dt.","vn":"đường phố, đường cái","examples":[{"cn":"过马路的时候要小心。","pinyin":"Guò mǎlù de shíhou yào xiǎoxīn.","vn":"Khi qua đường phải cẩn thận."},{"cn":"这条马路上的车特别多。","pinyin":"Zhè tiáo mǎlù shàng de chē tèbié duō.","vn":"Con đường này xe cộ rất nhiều."},{"cn":"不要在马路中间停车。","pinyin":"Búyào zài mǎlù zhōngjiān tíngchē.","vn":"Đừng dừng xe giữa đường."}]},{"hanzi":"平时","pinyin":"píngshí","pos":"dt.","vn":"lúc bình thường","examples":[{"cn":"我平时六点半起床。","pinyin":"Wǒ píngshí liù diǎn bàn qǐchuáng.","vn":"Lúc bình thường tôi dậy lúc sáu rưỡi."},{"cn":"她平时话不多,今天却说了很多。","pinyin":"Tā píngshí huà bù duō, jīntiān què shuōle hěn duō.","vn":"Bình thường cô ấy ít nói, hôm nay lại nói rất nhiều."},{"cn":"平时我很少喝咖啡。","pinyin":"Píngshí wǒ hěn shǎo hē kāfēi.","vn":"Bình thường tôi rất ít khi uống cà phê."}]},{"hanzi":"放学","pinyin":"fàngxué","pos":"dgt.","vn":"tan học","examples":[{"cn":"我们下午四点放学。","pinyin":"Wǒmen xiàwǔ sì diǎn fàngxué.","vn":"Chúng tôi tan học lúc bốn giờ chiều."},{"cn":"放学后,我喜欢和朋友一起去打球。","pinyin":"Fàngxué hòu, wǒ xǐhuan hé péngyou yìqǐ qù dǎqiú.","vn":"Sau khi tan học, tôi thích cùng bạn đi chơi bóng."},{"cn":"妈妈每天去学校接我放学。","pinyin":"Māma měitiān qù xuéxiào jiē wǒ fàngxué.","vn":"Mỗi ngày mẹ đều đến trường đón tôi tan học."}]},{"hanzi":"游戏","pinyin":"yóuxì","pos":"dt.","vn":"trò chơi","examples":[{"cn":"他每天晚上都要玩一会儿游戏。","pinyin":"Tā měitiān wǎnshang dōu yào wán yíhuìr yóuxì.","vn":"Mỗi tối cậu ấy đều chơi game một lúc."},{"cn":"这个游戏特别受年轻人欢迎。","pinyin":"Zhège yóuxì tèbié shòu niánqīng rén huānyíng.","vn":"Trò chơi này đặc biệt được giới trẻ yêu thích."},{"cn":"我们来玩一个游戏吧。","pinyin":"Wǒmen lái wán yí gè yóuxì ba.","vn":"Chúng ta chơi một trò chơi đi."}]},{"hanzi":"老人","pinyin":"lǎorén","pos":"dt.","vn":"người già","examples":[{"cn":"公园里有很多老人在锻炼身体。","pinyin":"Gōngyuán lǐ yǒu hěn duō lǎorén zài duànliàn shēntǐ.","vn":"Trong công viên có nhiều người già đang tập thể dục."},{"cn":"我们应该多关心家里的老人。","pinyin":"Wǒmen yīnggāi duō guānxīn jiālǐ de lǎorén.","vn":"Chúng ta nên quan tâm nhiều hơn đến người già trong nhà."},{"cn":"那位老人每天都来这条街散步。","pinyin":"Nà wèi lǎorén měitiān dōu lái zhè tiáo jiē sànbù.","vn":"Cụ già đó ngày nào cũng đến con phố này đi dạo."}]},{"hanzi":"根据","pinyin":"gēnjù","pos":"giới.","vn":"căn cứ vào, dựa vào","examples":[{"cn":"根据天气预报,明天会下雨。","pinyin":"Gēnjù tiānqì yùbào, míngtiān huì xiàyǔ.","vn":"Căn cứ vào dự báo thời tiết, ngày mai sẽ có mưa."},{"cn":"我们应该根据实际情况做决定。","pinyin":"Wǒmen yīnggāi gēnjù shíjì qíngkuàng zuò juédìng.","vn":"Chúng ta nên dựa vào tình hình thực tế để đưa ra quyết định."},{"cn":"根据调查,很多人都喜欢这个产品。","pinyin":"Gēnjù diàochá, hěn duō rén dōu xǐhuan zhège chǎnpǐn.","vn":"Căn cứ vào khảo sát, rất nhiều người thích sản phẩm này."}]},{"hanzi":"了解","pinyin":"liǎojiě","pos":"dgt.","vn":"hiểu, tìm hiểu","examples":[{"cn":"我想更多地了解中国文化。","pinyin":"Wǒ xiǎng gèng duō de liǎojiě Zhōngguó wénhuà.","vn":"Tôi muốn tìm hiểu nhiều hơn về văn hóa Trung Quốc."},{"cn":"你了解他吗?他是个什么样的人?","pinyin":"Nǐ liǎojiě tā ma? Tā shì gè shénme yàng de rén?","vn":"Bạn hiểu anh ấy không? Anh ấy là người thế nào?"},{"cn":"通过这次旅行,我了解了很多历史知识。","pinyin":"Tōngguò zhè cì lǚxíng, wǒ liǎojiěle hěn duō lìshǐ zhīshi.","vn":"Qua chuyến đi này, tôi đã hiểu thêm rất nhiều kiến thức lịch sử."}]},{"hanzi":"可是","pinyin":"kěshì","pos":"liên.","vn":"nhưng, tuy nhiên","examples":[{"cn":"我很想去,可是没有时间。","pinyin":"Wǒ hěn xiǎng qù, kěshì méiyǒu shíjiān.","vn":"Tôi rất muốn đi, nhưng không có thời gian."},{"cn":"他个子不高,可是篮球打得很好。","pinyin":"Tā gèzi bù gāo, kěshì lánqiú dǎ de hěn hǎo.","vn":"Anh ấy không cao nhưng chơi bóng rổ rất giỏi."},{"cn":"这道题看起来简单,可是做起来很难。","pinyin":"Zhè dào tí kàn qǐlái jiǎndān, kěshì zuò qǐlái hěn nán.","vn":"Câu hỏi này nhìn có vẻ đơn giản nhưng làm lại rất khó."}]},{"hanzi":"以上","pinyin":"yǐshàng","pos":"dt.","vn":"trở lên","examples":[{"cn":"十八岁以上才能开车。","pinyin":"Shíbā suì yǐshàng cái néng kāichē.","vn":"Mười tám tuổi trở lên mới được lái xe."},{"cn":"这件衣服一百块以上才包邮。","pinyin":"Zhè jiàn yīfu yìbǎi kuài yǐshàng cái bāo yóu.","vn":"Quần áo này phải từ một trăm tệ trở lên mới được miễn phí vận chuyển."},{"cn":"参加这个活动的人有一百以上。","pinyin":"Cānjiā zhège huódòng de rén yǒu yìbǎi yǐshàng.","vn":"Số người tham gia hoạt động này có hơn một trăm người."}]},{"hanzi":"有名","pinyin":"yǒumíng","pos":"tt.","vn":"nổi tiếng","examples":[{"cn":"这家饭店因为烤鸭很有名。","pinyin":"Zhè jiā fàndiàn yīnwèi kǎoyā hěn yǒumíng.","vn":"Nhà hàng này nổi tiếng vì món vịt quay."},{"cn":"他是我们学校最有名的老师。","pinyin":"Tā shì wǒmen xuéxiào zuì yǒumíng de lǎoshī.","vn":"Thầy ấy là thầy giáo nổi tiếng nhất trường chúng tôi."},{"cn":"这个地方风景很美,很有名。","pinyin":"Zhège dìfang fēngjǐng hěn měi, hěn yǒumíng.","vn":"Nơi này phong cảnh rất đẹp, rất nổi tiếng."}]},{"hanzi":"景点","pinyin":"jǐngdiǎn","pos":"dt.","vn":"điểm tham quan, thắng cảnh","examples":[{"cn":"这个城市有很多有名的景点。","pinyin":"Zhège chéngshì yǒu hěn duō yǒumíng de jǐngdiǎn.","vn":"Thành phố này có rất nhiều điểm tham quan nổi tiếng."},{"cn":"暑假我们去了好几个景点旅游。","pinyin":"Shǔjià wǒmen qùle hǎojǐ gè jǐngdiǎn lǚyóu.","vn":"Kỳ nghỉ hè chúng tôi đã đi du lịch ở mấy điểm tham quan."},{"cn":"这个景点每天都有很多游客。","pinyin":"Zhège jǐngdiǎn měitiān dōu yǒu hěn duō yóukè.","vn":"Điểm tham quan này ngày nào cũng có rất nhiều du khách."}]},{"hanzi":"游客","pinyin":"yóukè","pos":"dt.","vn":"du khách","examples":[{"cn":"暑假期间,这里挤满了游客。","pinyin":"Shǔjià qījiān, zhèlǐ jǐmǎnle yóukè.","vn":"Trong dịp nghỉ hè, nơi đây đông nghịt du khách."},{"cn":"很多外国游客喜欢来中国旅游。","pinyin":"Hěn duō wàiguó yóukè xǐhuan lái Zhōngguó lǚyóu.","vn":"Nhiều du khách nước ngoài thích đến Trung Quốc du lịch."},{"cn":"导游带着游客参观了博物馆。","pinyin":"Dǎoyóu dàizhe yóukè cānguānle bówùguǎn.","vn":"Hướng dẫn viên đã dẫn du khách tham quan bảo tàng."}]},{"hanzi":"外地","pinyin":"wàidì","pos":"dt.","vn":"nơi khác, tỉnh ngoài","examples":[{"cn":"他是外地人,刚搬到这个城市不久。","pinyin":"Tā shì wàidì rén, gāng bāndào zhège chéngshì bùjiǔ.","vn":"Anh ấy là người tỉnh ngoài, mới chuyển đến thành phố này không lâu."},{"cn":"过年的时候,很多在外地工作的人都会回家。","pinyin":"Guònián de shíhou, hěn duō zài wàidì gōngzuò de rén dōu huì huíjiā.","vn":"Dịp Tết, nhiều người làm việc ở nơi khác đều về nhà."},{"cn":"他要去外地出差一个星期。","pinyin":"Tā yào qù wàidì chūchāi yí gè xīngqī.","vn":"Anh ấy phải đi công tác ở nơi khác một tuần."}]},{"hanzi":"聊","pinyin":"liáo","pos":"dgt.","vn":"trò chuyện","examples":[{"cn":"我们聊了一会儿就散了。","pinyin":"Wǒmen liáole yíhuìr jiù sàn le.","vn":"Chúng tôi trò chuyện một lúc rồi giải tán."},{"cn":"有空的时候,我喜欢和朋友聊聊天。","pinyin":"Yǒu kòng de shíhou, wǒ xǐhuan hé péngyou liáoliao tiān.","vn":"Lúc rảnh, tôi thích trò chuyện cùng bạn bè."},{"cn":"我们聊了很多关于未来的计划。","pinyin":"Wǒmen liáole hěn duō guānyú wèilái de jìhuà.","vn":"Chúng tôi đã trò chuyện nhiều về kế hoạch tương lai."}]},{"hanzi":"南京","pinyin":"Nánjīng","pos":"danh từ riêng","vn":"Nam Kinh","examples":[{"cn":"南京是一座历史悠久的城市。","pinyin":"Nánjīng shì yí zuò lìshǐ yōujiǔ de chéngshì.","vn":"Nam Kinh là một thành phố có lịch sử lâu đời."},{"cn":"我打算暑假去南京旅游。","pinyin":"Wǒ dǎsuan shǔjià qù Nánjīng lǚyóu.","vn":"Tôi dự định nghỉ hè sẽ đi du lịch Nam Kinh."},{"cn":"他大学毕业以后留在南京工作了。","pinyin":"Tā dàxué bìyè yǐhòu liú zài Nánjīng gōngzuò le.","vn":"Sau khi tốt nghiệp đại học, anh ấy đã ở lại Nam Kinh làm việc."}]},{"hanzi":"河","pinyin":"hé","pos":"dt.","vn":"sông","examples":[{"cn":"这条河又长又宽。","pinyin":"Zhè tiáo hé yòu cháng yòu kuān.","vn":"Con sông này vừa dài vừa rộng."},{"cn":"孩子们喜欢在河边玩儿。","pinyin":"Háizimen xǐhuan zài hébiān wánr.","vn":"Bọn trẻ thích chơi đùa bên bờ sông."},{"cn":"夏天的时候,有人在河里游泳。","pinyin":"Xiàtiān de shíhou, yǒu rén zài hé lǐ yóuyǒng.","vn":"Vào mùa hè, có người bơi lội trên sông."}]},{"hanzi":"关系","pinyin":"guānxì","pos":"dt.","vn":"quan hệ, liên quan","examples":[{"cn":"他们俩关系很好,经常一起出去玩。","pinyin":"Tāmen liǎ guānxi hěn hǎo, jīngcháng yìqǐ chūqù wán.","vn":"Quan hệ của hai người họ rất tốt, hay cùng nhau đi chơi."},{"cn":"这件事和我没有关系。","pinyin":"Zhè jiàn shì hé wǒ méiyǒu guānxi.","vn":"Chuyện này không liên quan gì đến tôi."},{"cn":"多运动和身体健康有很大关系。","pinyin":"Duō yùndòng hé shēntǐ jiànkāng yǒu hěn dà guānxi.","vn":"Vận động nhiều có liên quan rất lớn đến sức khỏe."}]},{"hanzi":"养","pinyin":"yǎng","pos":"dgt.","vn":"nuôi","examples":[{"cn":"我家养了一只小猫。","pinyin":"Wǒ jiā yǎngle yì zhī xiǎo māo.","vn":"Nhà tôi nuôi một con mèo nhỏ."},{"cn":"他从小就想养一只狗。","pinyin":"Tā cóngxiǎo jiù xiǎng yǎng yì zhī gǒu.","vn":"Từ nhỏ cậu ấy đã muốn nuôi một con chó."},{"cn":"养孩子不容易,需要花很多时间和精力。","pinyin":"Yǎng háizi bù róngyì, xūyào huā hěn duō shíjiān hé jīnglì.","vn":"Nuôi con không dễ, cần phải dành nhiều thời gian và công sức."}]},{"hanzi":"黄河","pinyin":"Huáng Hé","pos":"danh từ riêng","vn":"sông Hoàng Hà","examples":[{"cn":"黄河是中国有名的大河。","pinyin":"Huáng Hé shì Zhōngguó yǒumíng de dà hé.","vn":"Sông Hoàng Hà là con sông lớn nổi tiếng của Trung Quốc."},{"cn":"我们去参观了黄河边上的景点。","pinyin":"Wǒmen qù cānguānle Huáng Hé biānshàng de jǐngdiǎn.","vn":"Chúng tôi đã đi tham quan điểm du lịch bên bờ sông Hoàng Hà."},{"cn":"黄河流经中国的西北地区。","pinyin":"Huáng Hé liújīng Zhōngguó de xīběi dìqū.","vn":"Sông Hoàng Hà chảy qua khu vực tây bắc Trung Quốc."}]},{"hanzi":"西北","pinyin":"xīběi","pos":"dt.","vn":"tây bắc","examples":[{"cn":"这个城市在中国的西北方向。","pinyin":"Zhège chéngshì zài Zhōngguó de xīběi fāngxiàng.","vn":"Thành phố này nằm ở hướng tây bắc Trung Quốc."},{"cn":"西北地区的气候比较干燥。","pinyin":"Xīběi dìqū de qìhòu bǐjiào gānzào.","vn":"Khí hậu vùng tây bắc tương đối khô."},{"cn":"我们打算下个月去西北旅游。","pinyin":"Wǒmen dǎsuan xià gè yuè qù xīběi lǚyóu.","vn":"Chúng tôi dự định tháng sau sẽ đi du lịch vùng tây bắc."}]},{"hanzi":"经过","pinyin":"jīngguò","pos":"dgt.","vn":"đi qua, trải qua","examples":[{"cn":"上班路上,我每天都会经过那座桥。","pinyin":"Shàngbān lùshàng, wǒ měitiān dōu huì jīngguò nà zuò qiáo.","vn":"Trên đường đi làm, hằng ngày tôi đều đi qua cây cầu đó."},{"cn":"经过几年的努力,他终于成功了。","pinyin":"Jīngguò jǐ nián de nǔlì, tā zhōngyú chénggōng le.","vn":"Trải qua mấy năm nỗ lực, cuối cùng anh ấy đã thành công."},{"cn":"这列火车经过三个城市。","pinyin":"Zhè liè huǒchē jīngguò sān gè chéngshì.","vn":"Chuyến tàu này đi qua ba thành phố."}]},{"hanzi":"草地","pinyin":"cǎodì","pos":"dt.","vn":"bãi cỏ","examples":[{"cn":"孩子们在草地上踢足球。","pinyin":"Háizimen zài cǎodì shàng tī zúqiú.","vn":"Bọn trẻ đang đá bóng trên bãi cỏ."},{"cn":"我们在草地上坐了一会儿,聊了聊天。","pinyin":"Wǒmen zài cǎodì shàng zuòle yíhuìr, liáole liáotiān.","vn":"Chúng tôi ngồi trên bãi cỏ một lúc, trò chuyện với nhau."},{"cn":"公园里有一大片绿色的草地。","pinyin":"Gōngyuán lǐ yǒu yí dà piàn lǜsè de cǎodì.","vn":"Trong công viên có một bãi cỏ xanh rộng lớn."}]},{"hanzi":"遇见","pinyin":"yùjiàn","pos":"dgt.","vn":"gặp gỡ, gặp","examples":[{"cn":"我昨天在超市遇见了一个老朋友。","pinyin":"Wǒ zuótiān zài chāoshì yùjiànle yí gè lǎo péngyou.","vn":"Hôm qua tôi gặp một người bạn cũ ở siêu thị."},{"cn":"我们是在大学里遇见的。","pinyin":"Wǒmen shì zài dàxué lǐ yùjiàn de.","vn":"Chúng tôi đã gặp nhau ở trường đại học."},{"cn":"旅行的时候,我遇见了很多有意思的人。","pinyin":"Lǚxíng de shíhou, wǒ yùjiànle hěn duō yǒu yìsi de rén.","vn":"Trong chuyến du lịch, tôi đã gặp rất nhiều người thú vị."}]}],"grammar":[{"title":"介词\"根据\" - Giới từ \"根据\"","explanation_vn":"Giới từ \"根据\" dùng trong câu để đưa ra căn cứ hoặc lý do của sự việc.","examples":[{"cn":"这几年小区根据他们的需要，有了很多变化。","pinyin":"Zhè jǐ nián xiǎoqū gēnjù tāmen de xūyào, yǒu le hěn duō biànhuà.","vn":""},{"cn":"根据要求，我们必须参加明天的会议。","pinyin":"Gēnjù yāoqiú, wǒmen bìxū cānjiā míngtiān de huìyì.","vn":""},{"cn":"老师根据每个学生的兴趣，选择了不一样的书。","pinyin":"Lǎoshī gēnjù měi gè xuéshēng de xìngqù, xuǎnzé le bù yíyàng de shū.","vn":""}]},{"title":"数量重叠\"数词+量词+数词+量词\" - Dạng láy số lượng từ \"Số từ + Lượng từ + Số từ + Lượng từ\"","explanation_vn":"Cụm số lượng từ có thể láy lại, sau khi láy có thể làm trạng ngữ, thường biểu thị phương thức của động tác, có tác dụng miêu tả sinh động. Cấu trúc cơ bản: Số từ+Lượng từ+Số từ+Lượng từ+(地)+Động từ.","examples":[{"cn":"我得一点儿一点儿给您讲。","pinyin":"Wǒ děi yìdiǎnr yìdiǎnr gěi nín jiǎng.","vn":""},{"cn":"学生们的汉语水平一天一天地提高了。","pinyin":"Xuéshēngmen de Hànyǔ shuǐpíng yì tiān yì tiān de tígāo le.","vn":""},{"cn":"他们两个两个地走进去了。","pinyin":"Tāmen liǎng gè liǎng gè de zǒu jìnqù le.","vn":""}]},{"title":"固定短语\"在……看来\" - Cụm cố định \"在……看来\"","explanation_vn":"Cụm cố định \"在……看来\" dùng để biểu đạt quan điểm của một cá nhân hoặc một nhóm người.","examples":[{"cn":"在我们中国人看来，黄河像妈妈一样，养了我们几千年。","pinyin":"Zài wǒmen Zhōngguórén kàn lái, Huáng Hé xiàng māma yíyàng, yǎng le wǒmen jǐ qiān nián.","vn":""},{"cn":"在同事们看来，她工作非常认真。","pinyin":"Zài tóngshìmen kàn lái, tā gōngzuò fēicháng rènzhēn.","vn":""},{"cn":"在我看来，每天读书是一种很好的习惯。","pinyin":"Zài wǒ kàn lái, měitiān dúshū shì yì zhǒng hěn hǎo de xíguàn.","vn":""}]},{"title":"固定短语\"不一会儿\" - Cụm cố định \"不一会儿\"","explanation_vn":"Cụm cố định \"不一会儿\" biểu thị khoảng thời gian rất ngắn, trong câu làm trạng ngữ, thường dùng trong khẩu ngữ.","examples":[{"cn":"难过的事情不一会儿就忘了。","pinyin":"Nánguò de shìqing bù yíhuìr jiù wàng le.","vn":""},{"cn":"不一会儿，张校长就来了。","pinyin":"Bù yíhuìr, Zhāng xiàozhǎng jiù lái le.","vn":""},{"cn":"两个小时看起来长，但是不一会儿就过去了。","pinyin":"Liǎng ge xiǎoshí kànqǐlái cháng, dànshì bù yíhuìr jiù guòqù le.","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"杨同乐","cn":"您搬到蓝天小区一段时间了，觉得怎么样？","pinyin":"Nín bān dào Lántiān Xiǎoqū yí duàn shíjiān le, juéde zěnmeyàng?"},{"speaker":"王一雪","cn":"小区环境挺好的，附近买东西也很方便，过马路就是超市。","pinyin":"Xiǎoqū huánjìng tǐng hǎo de, fùjìn mǎi dōngxi yě hěn fāngbiàn, guò mǎlù jiù shì chāoshì."},{"speaker":"杨同乐","cn":"平时孩子们在哪儿玩？","pinyin":"Píngshí háizimen zài nǎr wán?"},{"speaker":"王一雪","cn":"小区里有很多树，孩子们放学后就在树下做游戏。你想买房子吗？","pinyin":"Xiǎoqū lǐ yǒu hěn duō shù, háizimen fàngxué hòu jiù zài shù xià zuò yóuxì. Nǐ xiǎng mǎi fángzi ma?"},{"speaker":"杨同乐","cn":"是。我想买一个大房子，让我爸妈过来跟我一起住。","pinyin":"Shì. Wǒ xiǎng mǎi yí gè dà fángzi, ràng wǒ bàmā guòlái gēn wǒ yìqǐ zhù."},{"speaker":"王一雪","cn":"蓝天小区的老人挺多的，这几年小区根据他们的需要，有了很多变化。","pinyin":"Lántiān Xiǎoqū de lǎorén tǐng duō de, zhè jǐ nián xiǎoqū gēnjù tāmen de xūyào, yǒu le hěn duō biànhuà."},{"speaker":"杨同乐","cn":"真不错！过几天我去蓝天小区看看。","pinyin":"Zhēn búcuò! Guò jǐ tiān wǒ qù Lántiān Xiǎoqū kànkan."}],"translation_vn":"Dương Đồng Nhạc: Chị chuyển đến khu Lam Thiên được một thời gian rồi, chị thấy thế nào?\nVương Nhất Tuyết: Môi trường khu này khá tốt, gần đó mua đồ cũng rất tiện, qua đường là đến siêu thị luôn.\nDương Đồng Nhạc: Bình thường bọn trẻ chơi ở đâu?\nVương Nhất Tuyết: Trong khu có rất nhiều cây, sau khi tan học bọn trẻ liền chơi trò chơi dưới gốc cây. Anh muốn mua nhà à?\nDương Đồng Nhạc: Đúng vậy. Tôi muốn mua một căn nhà lớn, để bố mẹ tôi chuyển đến ở cùng tôi.\nVương Nhất Tuyết: Khu Lam Thiên có khá nhiều người già, mấy năm nay khu này đã căn cứ vào nhu cầu của họ mà có nhiều thay đổi.\nDương Đồng Nhạc: Thật tốt quá! Vài hôm nữa tôi sẽ đến khu Lam Thiên xem thử.","audio_dialogue":"15-1.mp3","audio_vocab":"15-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"王一雪","cn":"假期我想去南京旅游，但是我不太了解那里。","pinyin":"Jiàqī wǒ xiǎng qù Nánjīng lǚyóu, dànshì wǒ bú tài liǎojiě nàlǐ."},{"speaker":"杨同乐","cn":"我虽然不是南京人，可是我是在南京上的大学，可以说是半个南京人。","pinyin":"Wǒ suīrán bú shì Nánjīngrén, kěshì wǒ shì zài Nánjīng shàng de dàxué, kěyǐ shuō shì bàn gè Nánjīngrén."},{"speaker":"王一雪","cn":"太好了！你快给我介绍一下南京吧。","pinyin":"Tài hǎo le! Nǐ kuài gěi wǒ jièshào yíxià Nánjīng ba."},{"speaker":"杨同乐","cn":"南京有两千年以上的历史，有老城、老街，还有很多有名的景点，每年去旅游的游客特别多。","pinyin":"Nánjīng yǒu liǎng qiān nián yǐshàng de lìshǐ, yǒu lǎochéng, lǎojiē, hái yǒu hěn duō yǒumíng de jǐngdiǎn, měi nián qù lǚyóu de yóukè tèbié duō."},{"speaker":"王一雪","cn":"除了这些以外，你再告诉我一些外地人不知道的地方。","pinyin":"Chúle zhèxiē yǐwài, nǐ zài gàosu wǒ yìxiē wàidìrén bù zhīdào de dìfāng."},{"speaker":"杨同乐","cn":"那太多了，我得一点儿一点儿给您讲。","pinyin":"Nà tài duō le, wǒ děi yìdiǎnr yìdiǎnr gěi nín jiǎng."},{"speaker":"王一雪","cn":"行，下班后我请你吃晚饭，咱们边吃边聊。","pinyin":"Xíng, xiàbān hòu wǒ qǐng nǐ chī wǎnfàn, zánmen biān chī biān liáo."}],"translation_vn":"Vương Nhất Tuyết: Kỳ nghỉ này tôi muốn đi Nam Kinh du lịch, nhưng tôi không hiểu rõ về nơi đó lắm.\nDương Đồng Nhạc: Tôi tuy không phải người Nam Kinh, nhưng tôi học đại học ở Nam Kinh, có thể nói là coi như nửa người Nam Kinh rồi.\nVương Nhất Tuyết: Tuyệt quá! Anh mau giới thiệu cho tôi về Nam Kinh đi.\nDương Đồng Nhạc: Nam Kinh có lịch sử hơn hai nghìn năm, có thành cổ, phố cổ, còn có rất nhiều điểm tham quan nổi tiếng, mỗi năm du khách đến du lịch rất đông.\nVương Nhất Tuyết: Ngoài những điều đó ra, anh nói cho tôi biết thêm vài nơi mà người ở tỉnh khác không biết đến.\nDương Đồng Nhạc: Vậy thì nhiều lắm, tôi phải kể cho chị từ từ từng chút một.\nVương Nhất Tuyết: Được, tan làm tôi mời anh ăn tối, chúng ta vừa ăn vừa nói chuyện.","audio_dialogue":"15-3.mp3","audio_vocab":"15-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"王一雪","cn":"小明，中国有一条大河，它的名字跟颜色有关系，你知道是什么河吗？","pinyin":"Xiǎomíng, Zhōngguó yǒu yì tiáo dà hé, tā de míngzi gēn yánsè yǒu guānxì, nǐ zhīdào shì shénme hé ma?"},{"speaker":"刘小明","cn":"我知道，是黄河！","pinyin":"Wǒ zhīdào, shì Huáng Hé!"},{"speaker":"王一雪","cn":"你说对了。我再问问你，你知道它为什么叫黄河吗？","pinyin":"Nǐ shuō duì le. Wǒ zài wènwèn nǐ, nǐ zhīdào tā wèishénme jiào Huáng Hé ma?"},{"speaker":"刘小明","cn":"因为河水看起来是黄色的，所以叫这个名字。黄河是中国最长的河吗？","pinyin":"Yīnwèi héshuǐ kànqǐlái shì huángsè de, suǒyǐ jiào zhège míngzi. Huáng Hé shì Zhōngguó zuì cháng de hé ma?"},{"speaker":"王一雪","cn":"不是。黄河虽然不是最长的，可是在历史上很重要。","pinyin":"Bú shì. Huáng Hé suīrán bú shì zuì cháng de, kěshì zài lìshǐ shàng hěn zhòngyào."},{"speaker":"刘小明","cn":"这个我知道。很久以前，很多中国人都住在黄河边上。","pinyin":"Zhège wǒ zhīdào. Hěn jiǔ yǐqián, hěn duō Zhōngguórén dōu zhù zài Huáng Hé biān shàng."},{"speaker":"王一雪","cn":"对。在我们中国人看来，黄河像妈妈一样，养了我们几千年。","pinyin":"Duì. Zài wǒmen Zhōngguórén kàn lái, Huáng Hé xiàng māma yíyàng, yǎng le wǒmen jǐ qiān nián."}],"translation_vn":"Vương Nhất Tuyết: Tiểu Minh, Trung Quốc có một con sông lớn, tên của nó có liên quan đến màu sắc, con có biết đó là sông gì không?\nLưu Tiểu Minh: Con biết, là sông Hoàng Hà!\nVương Nhất Tuyết: Con nói đúng rồi. Mẹ hỏi thêm con nhé, con có biết tại sao nó lại gọi là Hoàng Hà không?\nLưu Tiểu Minh: Vì nhìn nước sông có màu vàng, nên mới gọi tên như vậy. Hoàng Hà có phải là con sông dài nhất Trung Quốc không ạ?\nVương Nhất Tuyết: Không phải. Hoàng Hà tuy không phải là con sông dài nhất, nhưng rất quan trọng trong lịch sử.\nLưu Tiểu Minh: Cái này con biết. Rất lâu trước đây, rất nhiều người Trung Quốc đều sống ở ven sông Hoàng Hà.\nVương Nhất Tuyết: Đúng vậy. Trong mắt người Trung Quốc chúng ta, sông Hoàng Hà giống như người mẹ, đã nuôi dưỡng chúng ta mấy nghìn năm nay.","audio_dialogue":"15-5.mp3","audio_vocab":"15-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"我小时候住在北京的西北边，有一条非常有名的河经过那里。","pinyin":"Wǒ xiǎoshíhou zhù zài Běijīng de xīběi biān, yǒu yì tiáo fēicháng yǒumíng de hé jīngguò nàlǐ."},{"speaker":"","cn":"我家就住在河边。","pinyin":"Wǒ jiā jiù zhù zài hébiān."},{"speaker":"","cn":"那里有高高的大树和绿绿的草地。","pinyin":"Nàlǐ yǒu gāogāo de dàshù hé lǜlǜ de cǎodì."},{"speaker":"","cn":"春天，河边的花都开了，看起来特别漂亮。","pinyin":"Chūntiān, hébiān de huā dōu kāi le, kànqǐlái tèbié piàoliang."},{"speaker":"","cn":"还记得小时候，一到夏天我就去河里游泳。","pinyin":"Hái jìde xiǎoshíhou, yí dào xiàtiān wǒ jiù qù hé lǐ yóuyǒng."},{"speaker":"","cn":"长大以后，遇到什么不开心的事情，我就去河边的树下坐着，听听鸟叫，看看河水，跟遇见的朋友聊聊天儿，难过的事情不一会儿就忘了。","pinyin":"Zhǎngdà yǐhòu, yùdào shénme bù kāixīn de shìqing, wǒ jiù qù hébiān de shù xià zuò zhe, tīngting niǎojiào, kànkan héshuǐ, gēn yùjiàn de péngyou liáoliao tiānr, nánguò de shìqing bù yíhuìr jiù wàng le."},{"speaker":"","cn":"那是我最喜欢的地方。","pinyin":"Nà shì wǒ zuì xǐhuan de dìfāng."}],"translation_vn":"Hồi nhỏ tôi sống ở phía tây bắc Bắc Kinh, có một con sông rất nổi tiếng chảy qua nơi đó. Nhà tôi ở ngay bên bờ sông. Nơi đó có những cây cổ thụ cao vút và những bãi cỏ xanh mướt. Mùa xuân, hoa bên bờ sông nở rộ, trông đặc biệt đẹp. Vẫn còn nhớ hồi nhỏ, cứ đến mùa hè là tôi lại xuống sông bơi. Lớn lên rồi, mỗi khi gặp chuyện gì không vui, tôi lại ra ngồi dưới gốc cây bên bờ sông, nghe tiếng chim hót, ngắm dòng nước, trò chuyện cùng những người bạn gặp được, những chuyện buồn chẳng mấy chốc là quên hết. Đó là nơi tôi yêu thích nhất.","audio_dialogue":"15-7.mp3","audio_vocab":"15-8.mp3"}]},{"id":16,"title_cn":"我听说有的熊猫出国了","title_pinyin":"Wǒ tīngshuō yǒude xióngmāo chūguó le","title_vn":"Tôi nghe nói có con gấu trúc đã ra nước ngoài","goals":["Có thể nghe hiểu và miêu tả đặc điểm, tập tính và môi trường sống của động vật.","Có thể nghe hiểu và bày tỏ quan điểm cá nhân về động vật.","Nắm vững cách dùng câu so sánh (11), có thể diễn đạt sự khác biệt về số lượng hoặc thời gian giữa các sự vật.","Tìm hiểu những thông tin cơ bản về gấu trúc lớn."],"vocab":[{"hanzi":"脏","pinyin":"zāng","pos":"tt.","vn":"bẩn, dơ","examples":[{"cn":"你的手太脏了,快去洗一洗。","pinyin":"Nǐ de shǒu tài zāng le, kuài qù xǐ yi xǐ.","vn":"Tay bạn bẩn quá, mau đi rửa đi."},{"cn":"这件衣服穿了一天,已经脏了。","pinyin":"Zhè jiàn yīfu chuān le yì tiān, yǐjīng zāng le.","vn":"Cái áo này mặc một ngày đã bị bẩn rồi."},{"cn":"别把地板弄脏了。","pinyin":"Bié bǎ dìbǎn nòng zāng le.","vn":"Đừng làm bẩn sàn nhà."}]},{"hanzi":"可爱","pinyin":"kě'ài","pos":"tt.","vn":"dễ thương, đáng yêu","examples":[{"cn":"这只小狗太可爱了,我想抱抱它。","pinyin":"Zhè zhī xiǎo gǒu tài kě'ài le, wǒ xiǎng bàobào tā.","vn":"Con chó con này dễ thương quá, mình muốn ôm nó."},{"cn":"她笑起来很可爱。","pinyin":"Tā xiào qǐlái hěn kě'ài.","vn":"Cô ấy cười trông rất dễ thương."},{"cn":"孩子们都觉得熊猫很可爱。","pinyin":"Háizimen dōu juéde xióngmāo hěn kě'ài.","vn":"Bọn trẻ đều thấy gấu trúc rất đáng yêu."}]},{"hanzi":"一会儿","pinyin":"yíhuìr","pos":"phó.","vn":"lúc...lúc... (chỉ sự thay đổi liên tục)","examples":[{"cn":"他一会儿说要去,一会儿又说不去,真难猜。","pinyin":"Tā yíhuìr shuō yào qù, yíhuìr yòu shuō bú qù, zhēn nán cāi.","vn":"Anh ấy lúc thì nói muốn đi, lúc lại nói không đi, thật khó đoán."},{"cn":"天气一会儿晴一会儿阴。","pinyin":"Tiānqì yíhuìr qíng yíhuìr yīn.","vn":"Thời tiết lúc nắng lúc âm u."},{"cn":"你等我一会儿,我马上就好。","pinyin":"Nǐ děng wǒ yíhuìr, wǒ mǎshàng jiù hǎo.","vn":"Bạn đợi mình một lát, mình xong ngay đây."}]},{"hanzi":"脚","pinyin":"jiǎo","pos":"dt.","vn":"chân","examples":[{"cn":"我走了一天路,脚都疼了。","pinyin":"Wǒ zǒu le yì tiān lù, jiǎo dōu téng le.","vn":"Mình đi bộ cả ngày, chân đau quá."},{"cn":"小心,别踩到我的脚。","pinyin":"Xiǎoxīn, bié cǎi dào wǒ de jiǎo.","vn":"Cẩn thận, đừng giẫm vào chân mình."},{"cn":"他的脚受伤了,不能跑步。","pinyin":"Tā de jiǎo shòushāng le, bù néng pǎobù.","vn":"Chân anh ấy bị thương, không chạy bộ được."}]},{"hanzi":"照顾","pinyin":"zhàogù","pos":"dgt.","vn":"chăm sóc","examples":[{"cn":"妈妈每天都在家照顾孩子。","pinyin":"Māma měitiān dōu zài jiā zhàogù háizi.","vn":"Mẹ ngày nào cũng ở nhà chăm sóc con cái."},{"cn":"谢谢你这几天对我的照顾。","pinyin":"Xièxie nǐ zhè jǐ tiān duì wǒ de zhàogù.","vn":"Cảm ơn bạn mấy ngày nay đã chăm sóc mình."},{"cn":"爷爷生病了,我们要好好照顾他。","pinyin":"Yéye shēngbìng le, wǒmen yào hǎohǎo zhàogù tā.","vn":"Ông bị ốm rồi, chúng ta phải chăm sóc ông thật tốt."}]},{"hanzi":"好像","pinyin":"hǎoxiàng","pos":"dgt.","vn":"dường như, giống như","examples":[{"cn":"外面好像下雨了。","pinyin":"Wàimiàn hǎoxiàng xiàyǔ le.","vn":"Bên ngoài dường như đang mưa."},{"cn":"她今天好像不太高兴。","pinyin":"Tā jīntiān hǎoxiàng bú tài gāoxìng.","vn":"Hôm nay cô ấy có vẻ không vui lắm."},{"cn":"这个人我好像在哪儿见过。","pinyin":"Zhège rén wǒ hǎoxiàng zài nǎr jiàn guo.","vn":"Người này hình như mình từng gặp ở đâu đó."}]},{"hanzi":"认得","pinyin":"rènde","pos":"dgt.","vn":"nhận ra, quen biết","examples":[{"cn":"这个字我不认得。","pinyin":"Zhège zì wǒ bú rènde.","vn":"Chữ này mình không nhận ra."},{"cn":"你还认得我吗?我们以前是同学。","pinyin":"Nǐ hái rènde wǒ ma? Wǒmen yǐqián shì tóngxué.","vn":"Bạn còn nhận ra mình không? Chúng ta từng là bạn học."},{"cn":"这条路我认得,跟我走吧。","pinyin":"Zhè tiáo lù wǒ rènde, gēn wǒ zǒu ba.","vn":"Con đường này mình quen, đi theo mình nhé."}]},{"hanzi":"周末","pinyin":"zhōumò","pos":"dt.","vn":"cuối tuần","examples":[{"cn":"周末你有什么安排?","pinyin":"Zhōumò nǐ yǒu shénme ānpái?","vn":"Cuối tuần bạn có kế hoạch gì không?"},{"cn":"我们周末一起去爬山吧。","pinyin":"Wǒmen zhōumò yìqǐ qù páshān ba.","vn":"Cuối tuần chúng ta cùng đi leo núi nhé."},{"cn":"这个周末我要在家休息。","pinyin":"Zhège zhōumò wǒ yào zài jiā xiūxi.","vn":"Cuối tuần này mình sẽ nghỉ ngơi ở nhà."}]},{"hanzi":"动物园","pinyin":"dòngwùyuán","pos":"dt.","vn":"vườn thú, sở thú","examples":[{"cn":"周末爸爸带我去动物园看大熊猫。","pinyin":"Zhōumò bàba dài wǒ qù dòngwùyuán kàn dàxióngmāo.","vn":"Cuối tuần bố đưa mình đi sở thú xem gấu trúc."},{"cn":"动物园里有很多种动物。","pinyin":"Dòngwùyuán lǐ yǒu hěn duō zhǒng dòngwù.","vn":"Trong sở thú có rất nhiều loài động vật."},{"cn":"我小时候最喜欢去动物园玩。","pinyin":"Wǒ xiǎoshíhou zuì xǐhuan qù dòngwùyuán wán.","vn":"Lúc nhỏ mình thích nhất là đi chơi sở thú."}]},{"hanzi":"动物","pinyin":"dòngwù","pos":"dt.","vn":"động vật","examples":[{"cn":"我女儿很喜欢小动物。","pinyin":"Wǒ nǚ'ér hěn xǐhuan xiǎo dòngwù.","vn":"Con gái mình rất thích động vật nhỏ."},{"cn":"大象是一种很大的动物。","pinyin":"Dàxiàng shì yì zhǒng hěn dà de dòngwù.","vn":"Voi là một loài động vật rất to lớn."},{"cn":"我们应该保护野生动物。","pinyin":"Wǒmen yīnggāi bǎohù yěshēng dòngwù.","vn":"Chúng ta nên bảo vệ động vật hoang dã."}]},{"hanzi":"大熊猫","pinyin":"dàxióngmāo","pos":"dt.","vn":"gấu trúc lớn","examples":[{"cn":"大熊猫是中国的国宝。","pinyin":"Dàxióngmāo shì Zhōngguó de guóbǎo.","vn":"Gấu trúc lớn là quốc bảo của Trung Quốc."},{"cn":"大熊猫最喜欢吃竹子。","pinyin":"Dàxióngmāo zuì xǐhuan chī zhúzi.","vn":"Gấu trúc lớn thích ăn tre nhất."},{"cn":"我在动物园第一次见到真的大熊猫。","pinyin":"Wǒ zài dòngwùyuán dì-yī cì jiàndào zhēn de dàxióngmāo.","vn":"Mình lần đầu tiên nhìn thấy gấu trúc thật ở sở thú."}]},{"hanzi":"奇怪","pinyin":"qíguài","pos":"tt.","vn":"kỳ lạ","examples":[{"cn":"他今天的样子有点儿奇怪。","pinyin":"Tā jīntiān de yàngzi yǒudiǎnr qíguài.","vn":"Dáng vẻ của anh ấy hôm nay hơi kỳ lạ."},{"cn":"我觉得很奇怪,他怎么突然不说话了。","pinyin":"Wǒ juéde hěn qíguài, tā zěnme tūrán bù shuōhuà le.","vn":"Mình thấy lạ, sao anh ấy đột nhiên không nói gì nữa."},{"cn":"这件事说起来有点儿奇怪。","pinyin":"Zhè jiàn shì shuō qǐlái yǒudiǎnr qíguài.","vn":"Chuyện này nói ra hơi kỳ lạ."}]},{"hanzi":"其实","pinyin":"qíshí","pos":"phó.","vn":"thực ra","examples":[{"cn":"他看起来很严肃,其实人很好。","pinyin":"Tā kàn qǐlái hěn yánsù, qíshí rén hěn hǎo.","vn":"Anh ấy trông có vẻ nghiêm nghị, nhưng thực ra rất tốt bụng."},{"cn":"我其实不太喜欢吃辣的。","pinyin":"Wǒ qíshí bú tài xǐhuan chī là de.","vn":"Thực ra mình không thích ăn cay lắm."},{"cn":"这件事其实没那么复杂。","pinyin":"Zhè jiàn shì qíshí méi nàme fùzá.","vn":"Chuyện này thực ra không phức tạp đến thế."}]},{"hanzi":"竹子","pinyin":"zhúzi","pos":"dt.","vn":"tre","examples":[{"cn":"熊猫一天要吃很多竹子。","pinyin":"Xióngmāo yì tiān yào chī hěn duō zhúzi.","vn":"Gấu trúc một ngày phải ăn rất nhiều tre."},{"cn":"这座山上长满了竹子。","pinyin":"Zhè zuò shān shàng zhǎngmǎn le zhúzi.","vn":"Ngọn núi này mọc đầy tre."},{"cn":"中国南方有很多竹子。","pinyin":"Zhōngguó nánfāng yǒu hěn duō zhúzi.","vn":"Miền nam Trung Quốc có rất nhiều tre."}]},{"hanzi":"国宝","pinyin":"guóbǎo","pos":"dt.","vn":"quốc bảo","examples":[{"cn":"大熊猫被称为中国的国宝。","pinyin":"Dàxióngmāo bèi chēngwéi Zhōngguó de guóbǎo.","vn":"Gấu trúc lớn được gọi là quốc bảo của Trung Quốc."},{"cn":"这件古代文物是国宝级的。","pinyin":"Zhè jiàn gǔdài wénwù shì guóbǎo jí de.","vn":"Cổ vật này thuộc cấp quốc bảo."},{"cn":"能看到这些国宝,我特别激动。","pinyin":"Néng kàndào zhèxiē guóbǎo, wǒ tèbié jīdòng.","vn":"Được xem những quốc bảo này, mình rất xúc động."}]},{"hanzi":"全","pinyin":"quán","pos":"tt.","vn":"toàn bộ, cả","examples":[{"cn":"这件事全班同学都知道了。","pinyin":"Zhè jiàn shì quán bān tóngxué dōu zhīdào le.","vn":"Chuyện này cả lớp đều biết rồi."},{"cn":"他把蛋糕全吃完了。","pinyin":"Tā bǎ dàngāo quán chī wán le.","vn":"Anh ấy ăn hết sạch cả cái bánh."},{"cn":"全世界的人都喜欢熊猫。","pinyin":"Quán shìjiè de rén dōu xǐhuan xióngmāo.","vn":"Người trên toàn thế giới đều yêu thích gấu trúc."}]},{"hanzi":"野生","pinyin":"yěshēng","pos":"tt.","vn":"hoang dã","examples":[{"cn":"野生动物应该生活在大自然里。","pinyin":"Yěshēng dòngwù yīnggāi shēnghuó zài dà zìrán lǐ.","vn":"Động vật hoang dã nên sống trong tự nhiên."},{"cn":"这里有一片野生竹林。","pinyin":"Zhèlǐ yǒu yí piàn yěshēng zhúlín.","vn":"Ở đây có một rừng tre hoang dã."},{"cn":"我们要保护野生大熊猫。","pinyin":"Wǒmen yào bǎohù yěshēng dàxióngmāo.","vn":"Chúng ta cần bảo vệ gấu trúc hoang dã."}]},{"hanzi":"关于","pinyin":"guānyú","pos":"giới.","vn":"về, liên quan đến","examples":[{"cn":"这本书是关于中国历史的。","pinyin":"Zhè běn shū shì guānyú Zhōngguó lìshǐ de.","vn":"Cuốn sách này viết về lịch sử Trung Quốc."},{"cn":"关于这个问题,我们再讨论一下。","pinyin":"Guānyú zhège wèntí, wǒmen zài tǎolùn yíxià.","vn":"Về vấn đề này, chúng ta thảo luận thêm một chút."},{"cn":"老师给我们讲了关于熊猫的故事。","pinyin":"Lǎoshī gěi wǒmen jiǎng le guānyú xióngmāo de gùshi.","vn":"Thầy giáo kể cho chúng tôi câu chuyện về gấu trúc."}]},{"hanzi":"饱","pinyin":"bǎo","pos":"tt.","vn":"no","examples":[{"cn":"我吃饱了,不能再吃了。","pinyin":"Wǒ chībǎo le, bù néng zài chī le.","vn":"Mình no rồi, không ăn nổi nữa."},{"cn":"熊猫吃饱了就睡觉。","pinyin":"Xióngmāo chībǎo le jiù shuìjiào.","vn":"Gấu trúc ăn no là đi ngủ."},{"cn":"你吃饱了吗?要不要再来一碗?","pinyin":"Nǐ chībǎo le ma? Yàobuyào zài lái yì wǎn?","vn":"Bạn ăn no chưa? Có muốn ăn thêm bát nữa không?"}]},{"hanzi":"张","pinyin":"zhāng","pos":"dgt.","vn":"mở, há (miệng)","examples":[{"cn":"他张大嘴笑了起来。","pinyin":"Tā zhāng dà zuǐ xiào le qǐlái.","vn":"Anh ấy há to miệng cười lên."},{"cn":"医生让我张开嘴看看牙齿。","pinyin":"Yīshēng ràng wǒ zhāngkāi zuǐ kànkan yáchǐ.","vn":"Bác sĩ bảo mình há miệng ra để xem răng."},{"cn":"小鸟张着嘴等妈妈喂食。","pinyin":"Xiǎo niǎo zhāng zhe zuǐ děng māma wèi shí.","vn":"Chim con há miệng chờ mẹ cho ăn."}]},{"hanzi":"嘴","pinyin":"zuǐ","pos":"dt.","vn":"miệng","examples":[{"cn":"吃饭的时候别一直说话,把嘴闭上。","pinyin":"Chīfàn de shíhou bié yìzhí shuōhuà, bǎ zuǐ bì shang.","vn":"Lúc ăn cơm đừng nói chuyện suốt, ngậm miệng lại."},{"cn":"他嘴里含着一口饭。","pinyin":"Tā zuǐ lǐ hán zhe yì kǒu fàn.","vn":"Miệng anh ấy đang ngậm một miếng cơm."},{"cn":"小孩子的嘴很甜,很会说话。","pinyin":"Xiǎo háizi de zuǐ hěn tián, hěn huì shuōhuà.","vn":"Đứa trẻ nói chuyện ngọt ngào, rất khéo mồm."}]},{"hanzi":"身边","pinyin":"shēnbiān","pos":"dt.","vn":"bên cạnh, bên người","examples":[{"cn":"她一直陪在我身边。","pinyin":"Tā yìzhí péi zài wǒ shēnbiān.","vn":"Cô ấy luôn ở bên cạnh mình."},{"cn":"我身边没有带钱包。","pinyin":"Wǒ shēnbiān méiyǒu dài qiánbāo.","vn":"Bên người mình không mang theo ví tiền."},{"cn":"每个人身边都有一些可爱的小动物。","pinyin":"Měi ge rén shēnbiān dōu yǒu yìxiē kě'ài de xiǎo dòngwù.","vn":"Bên cạnh mỗi người đều có những con vật nhỏ dễ thương."}]},{"hanzi":"半天","pinyin":"bàntiān","pos":"sl.","vn":"nửa ngày, hồi lâu","examples":[{"cn":"我等了他半天,他才来。","pinyin":"Wǒ děng le tā bàntiān, tā cái lái.","vn":"Mình đợi anh ấy hồi lâu, mãi anh ấy mới đến."},{"cn":"这道题我想了半天也没想明白。","pinyin":"Zhè dào tí wǒ xiǎng le bàntiān yě méi xiǎng míngbai.","vn":"Bài này mình nghĩ mãi mà vẫn không hiểu ra."},{"cn":"他找了半天也没找到钥匙。","pinyin":"Tā zhǎo le bàntiān yě méi zhǎodào yàoshi.","vn":"Anh ấy tìm mãi mà vẫn không thấy chìa khóa."}]},{"hanzi":"脸","pinyin":"liǎn","pos":"dt.","vn":"mặt","examples":[{"cn":"她一听这话,脸就红了。","pinyin":"Tā yì tīng zhè huà, liǎn jiù hóng le.","vn":"Cô ấy vừa nghe câu đó liền đỏ mặt."},{"cn":"每天早上我都要洗脸。","pinyin":"Měitiān zǎoshang wǒ dōu yào xǐliǎn.","vn":"Mỗi sáng mình đều phải rửa mặt."},{"cn":"他的脸上带着笑容。","pinyin":"Tā de liǎn shang dài zhe xiàoróng.","vn":"Trên mặt anh ấy nở nụ cười."}]},{"hanzi":"大人","pinyin":"dàren","pos":"dt.","vn":"người lớn","examples":[{"cn":"这个问题你应该问大人。","pinyin":"Zhège wèntí nǐ yīnggāi wèn dàren.","vn":"Vấn đề này bạn nên hỏi người lớn."},{"cn":"小孩子有时候比大人还聪明。","pinyin":"Xiǎo háizi yǒushíhou bǐ dàren hái cōngmíng.","vn":"Trẻ con đôi khi còn thông minh hơn cả người lớn."},{"cn":"大人们在客厅聊天,孩子们在院子里玩。","pinyin":"Dàrenmen zài kètīng liáotiān, háizimen zài yuànzi lǐ wán.","vn":"Người lớn trò chuyện trong phòng khách, bọn trẻ chơi ở sân."}]},{"hanzi":"喜爱","pinyin":"xǐ'ài","pos":"dgt.","vn":"yêu thích","examples":[{"cn":"大熊猫受到全世界人民的喜爱。","pinyin":"Dàxióngmāo shòudào quán shìjiè rénmín de xǐ'ài.","vn":"Gấu trúc lớn được người dân toàn thế giới yêu thích."},{"cn":"这首歌很受年轻人喜爱。","pinyin":"Zhè shǒu gē hěn shòu niánqīngrén xǐ'ài.","vn":"Bài hát này rất được giới trẻ yêu thích."},{"cn":"她从小就喜爱画画。","pinyin":"Tā cóngxiǎo jiù xǐ'ài huàhuà.","vn":"Cô ấy từ nhỏ đã yêu thích vẽ tranh."}]}],"grammar":[{"title":"并列复句\"一会儿……，一会儿……\" - Câu phức song song \"一会儿……，一会儿……\"","explanation_vn":"Câu phức song song \"一会儿……，一会儿……\" diễn tả những hành động khác nhau xảy ra trong một khoảng thời gian ngắn, hoặc một tình huống đối lập, luân phiên.","examples":[{"cn":"它一会儿在你脚边睡觉，一会儿在你身上爬。","pinyin":"Tā yíhuìr zài nǐ jiǎobiān shuìjiào, yíhuìr zài nǐ shēnshang pá.","vn":""},{"cn":"他一会儿进来，一会儿出去，忙得很。","pinyin":"Tā yíhuìr jìnlái, yíhuìr chūqù, máng de hěn.","vn":""},{"cn":"最近天气变化很快，一会儿冷，一会儿热。","pinyin":"Zuìjìn tiānqì biànhuà hěn kuài, yíhuìr lěng, yíhuìr rè.","vn":""}]},{"title":"介词\"关于\" - Giới từ \"关于\"","explanation_vn":"Giới từ \"关于\" đi kèm theo sau là danh từ, dùng để nêu ra đối tượng hoặc chủ đề có liên quan.","examples":[{"cn":"关于这个问题，我得慢慢给你讲。","pinyin":"Guānyú zhège wèntí, wǒ děi mànmàn gěi nǐ jiǎng.","vn":""},{"cn":"关于他的要求，我们还要开会以后再决定。","pinyin":"Guānyú tā de yāoqiú, wǒmen hái yào kāihuì yǐhòu zài juédìng.","vn":""},{"cn":"关于比赛的时间，我明天一定告诉大家。","pinyin":"Guānyú bǐsài de shíjiān, wǒ míngtiān yídìng gàosu dàjiā.","vn":""}]},{"title":"固定短语\"一般来说\" - Cụm cố định \"一般来说\"","explanation_vn":"\"一般来说\" là cụm từ cố định, nghĩa là \"nói chung\", \"trong đa số trường hợp là như vậy\", thường dùng ở đầu câu.","examples":[{"cn":"一般来说，熊猫每天要睡很多次觉。","pinyin":"Yìbān lái shuō, xióngmāo měitiān yào shuì hěn duō cì jiào.","vn":""},{"cn":"一般来说，这种树每年开一次花。","pinyin":"Yìbān lái shuō, zhè zhǒng shù měi nián kāi yí cì huā.","vn":""},{"cn":"一般来说，学习外语需要多练习。","pinyin":"Yìbān lái shuō, xuéxí wàiyǔ xūyào duō liànxí.","vn":""}]},{"title":"比较句（11） - Câu so sánh (11)","explanation_vn":"Trong câu so sánh dùng \"比\", khi vị ngữ là động từ thường, có thể thêm \"多/少/早/晚\" trước động từ để diễn đạt sự khác biệt về số lượng hoặc thời gian giữa hai đối tượng. Cấu trúc cơ bản: A比B+多/少/早/晚+Động từ+Cụm số lượng.","examples":[{"cn":"冬天比夏天早关门一个小时。","pinyin":"Dōngtiān bǐ xiàtiān zǎo guānmén yí ge xiǎoshí.","vn":""},{"cn":"哥哥比弟弟多吃了三个饺子。","pinyin":"Gēge bǐ dìdi duō chīle sān ge jiǎozi.","vn":""},{"cn":"我比他晚到了十分钟。","pinyin":"Wǒ bǐ tā wǎn dàole shí fēnzhōng.","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"刘小雪","cn":"这只小猫你们养了多久了？","pinyin":"Zhè zhī xiǎo māo nǐmen yǎngle duōjiǔ le?"},{"speaker":"服务员","cn":"已经一年多了。第一天看见它的时候，它又脏又乱。","pinyin":"Yǐjīng yì nián duō le. Dì-yī tiān kànjiàn tā de shíhou, tā yòu zāng yòu luàn."},{"speaker":"刘小雪","cn":"现在它变得又干净又漂亮。","pinyin":"Xiànzài tā biàn de yòu gānjìng yòu piàoliang."},{"speaker":"服务员","cn":"是啊。它还特别可爱，一会儿在你脚边睡觉，一会儿在你身上爬。","pinyin":"Shì a. Tā hái tèbié kě'ài, yíhuìr zài nǐ jiǎobiān shuìjiào, yíhuìr zài nǐ shēnshang pá."},{"speaker":"刘小雪","cn":"你们把它照顾得真好。","pinyin":"Nǐmen bǎ tā zhàogù de zhēn hǎo."},{"speaker":"服务员","cn":"它就好像我们的孩子，我们照顾它，它也认得我们了。","pinyin":"Tā jiù hǎoxiàng wǒmen de háizi, wǒmen zhàogù tā, tā yě rènde wǒmen le."},{"speaker":"刘小雪","cn":"妈妈，我们家也养一只小猫吧。","pinyin":"Māma, wǒmen jiā yě yǎng yì zhī xiǎo māo ba."},{"speaker":"王一雪","cn":"咱们没时间照顾，还是别养了，我周末带你去北京动物园看动物吧。","pinyin":"Zánmen méi shíjiān zhàogù, háishi bié yǎng le, wǒ zhōumò dài nǐ qù Běijīng Dòngwùyuán kàn dòngwù ba."}],"translation_vn":"Lưu Tiểu Tuyết: Con mèo con này nhà anh/chị nuôi được bao lâu rồi?\nNhân viên phục vụ: Đã hơn một năm rồi. Ngày đầu tiên nhìn thấy nó, nó vừa bẩn vừa lộn xộn.\nLưu Tiểu Tuyết: Bây giờ nó trở nên vừa sạch sẽ vừa xinh đẹp.\nNhân viên phục vụ: Đúng vậy. Nó còn đặc biệt đáng yêu, lúc thì ngủ bên chân bạn, lúc thì leo trèo trên người bạn.\nLưu Tiểu Tuyết: Các anh chị chăm sóc nó thật tốt.\nNhân viên phục vụ: Nó giống như con của chúng tôi vậy, chúng tôi chăm sóc nó, nó cũng nhận ra chúng tôi rồi.\nLưu Tiểu Tuyết: Mẹ ơi, nhà mình cũng nuôi một con mèo con đi.\nVương Nhất Tuyết: Nhà mình không có thời gian chăm sóc đâu, thôi đừng nuôi nữa, cuối tuần mẹ đưa con đi vườn thú Bắc Kinh xem động vật nhé.","audio_dialogue":"16-1.mp3","audio_vocab":"16-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"刘小明","cn":"妈妈，大熊猫这个名字很奇怪，它们跟猫有什么关系？","pinyin":"Māma, dàxióngmāo zhège míngzi hěn qíguài, tāmen gēn māo yǒu shénme guānxi?"},{"speaker":"王一雪","cn":"这个问题问得好，它们跟猫没什么关系，其实应该叫大猫熊。","pinyin":"Zhège wèntí wèn de hǎo, tāmen gēn māo méi shénme guānxi, qíshí yīnggāi jiào dàmāoxióng."},{"speaker":"刘小明","cn":"大熊猫为什么只吃竹子不吃肉？","pinyin":"Dàxióngmāo wèishénme zhǐ chī zhúzi bù chī ròu?"},{"speaker":"王一雪","cn":"它们跟人一样，也可以吃肉，但是对肉不感兴趣。","pinyin":"Tāmen gēn rén yíyàng, yě kěyǐ chī ròu, dànshì duì ròu bù gǎn xìngqù."},{"speaker":"刘小明","cn":"大熊猫为什么是中国的国宝？","pinyin":"Dàxióngmāo wèishénme shì Zhōngguó de guóbǎo?"},{"speaker":"王一雪","cn":"全世界只有中国有野生大熊猫，中国是大熊猫的家。","pinyin":"Quán shìjiè zhǐyǒu Zhōngguó yǒu yěshēng dàxióngmāo, Zhōngguó shì dàxióngmāo de jiā."},{"speaker":"刘小明","cn":"我听说有的熊猫出国了，他们去哪儿了？","pinyin":"Wǒ tīngshuō yǒude xióngmāo chūguó le, tāmen qù nǎr le?"},{"speaker":"王一雪","cn":"关于这个问题，我得慢慢给你讲。","pinyin":"Guānyú zhège wèntí, wǒ děi mànmàn gěi nǐ jiǎng."},{"speaker":"刘小雪","cn":"弟弟，你真是\"十万个为什么\"。","pinyin":"Dìdi, nǐ zhēn shì \"shíwàn gè wèishénme\"."}],"translation_vn":"Lưu Tiểu Minh: Mẹ ơi, tên gọi gấu trúc lớn này nghe lạ quá, chúng có quan hệ gì với mèo không?\nVương Nhất Tuyết: Câu hỏi này hay đấy, chúng không có quan hệ gì với mèo cả, thực ra nên gọi là gấu mèo lớn mới đúng.\nLưu Tiểu Minh: Tại sao gấu trúc lớn chỉ ăn tre mà không ăn thịt?\nVương Nhất Tuyết: Chúng cũng giống như con người, cũng có thể ăn thịt, nhưng không hứng thú với thịt.\nLưu Tiểu Minh: Tại sao gấu trúc lớn là quốc bảo của Trung Quốc?\nVương Nhất Tuyết: Trên toàn thế giới chỉ có Trung Quốc mới có gấu trúc lớn hoang dã, Trung Quốc là quê nhà của gấu trúc lớn.\nLưu Tiểu Minh: Con nghe nói có con gấu trúc đã ra nước ngoài, chúng đã đi đâu vậy?\nVương Nhất Tuyết: Về vấn đề này thì mẹ phải từ từ kể cho con nghe.\nLưu Tiểu Tuyết: Em trai à, em đúng là \"trăm nghìn câu hỏi vì sao\" mà.","audio_dialogue":"16-3.mp3","audio_vocab":"16-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"刘小雪","cn":"这只大熊猫一会儿爬上去，一会儿跳下来，可爱极了！","pinyin":"Zhè zhī dàxióngmāo yíhuìr pá shàngqù, yíhuìr tiào xiàlái, kě'ài jíle!"},{"speaker":"王一雪","cn":"它好像还没吃饱，站起来张着嘴找吃的呢。","pinyin":"Tā hǎoxiàng hái méi chībǎo, zhàn qǐlái zhāngzhe zuǐ zhǎo chī de ne."},{"speaker":"刘小雪","cn":"它身边那只熊猫半天没动，是不是在睡觉呢？","pinyin":"Tā shēnbiān nà zhī xióngmāo bàntiān méi dòng, shì bú shì zài shuìjiào ne?"},{"speaker":"王一雪","cn":"我看不见它的脸，可能是吧。一般来说，熊猫每天要睡很多次觉。","pinyin":"Wǒ kàn bu jiàn tā de liǎn, kěnéng shì ba. Yìbān lái shuō, xióngmāo měitiān yào shuì hěn duō cì jiào."},{"speaker":"刘小雪","cn":"对，除了睡觉以外，很多时间都在吃东西。","pinyin":"Duì, chúle shuìjiào yǐwài, hěn duō shíjiān dōu zài chī dōngxi."},{"speaker":"刘小明","cn":"大熊猫的生活真舒服啊！","pinyin":"Dàxióngmāo de shēnghuó zhēn shūfu a!"},{"speaker":"刘小雪","cn":"妈妈，您帮我和这两只大熊猫照一张照片吧。","pinyin":"Māma, nín bāng wǒ hé zhè liǎng zhī dàxióngmāo zhào yì zhāng zhàopiàn ba."}],"translation_vn":"Lưu Tiểu Tuyết: Con gấu trúc này lúc thì leo lên, lúc thì nhảy xuống, đáng yêu quá đi mất!\nVương Nhất Tuyết: Nó có vẻ như vẫn chưa ăn no, đứng dậy há miệng tìm đồ ăn kìa.\nLưu Tiểu Tuyết: Con gấu trúc bên cạnh nó nửa ngày rồi không động đậy, có phải đang ngủ không nhỉ?\nVương Nhất Tuyết: Mẹ không nhìn thấy mặt nó, có thể là vậy. Nói chung, gấu trúc mỗi ngày phải ngủ rất nhiều lần.\nLưu Tiểu Tuyết: Đúng vậy, ngoài ngủ ra, phần lớn thời gian đều dùng để ăn.\nLưu Tiểu Minh: Cuộc sống của gấu trúc thật thoải mái!\nLưu Tiểu Tuyết: Mẹ ơi, mẹ giúp con chụp một tấm ảnh với hai con gấu trúc này đi.","audio_dialogue":"16-5.mp3","audio_vocab":"16-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"今天我带小雪和小明去动物园玩了。北京动物园是中国很有名的动物园，里面有非常多的动物，当然，大人和孩子最喜爱的还是大熊猫。每天有很多游客去熊猫馆，他们带着相机去给可爱的大熊猫拍照。动物园早上七点半开门，晚上七点关门，冬天比夏天游客少，所以也比平时早关门一个小时。如果第一次来北京旅游，跟家人一起去北京动物园是个不错的选择。","pinyin":"Jīntiān wǒ dài Xiǎoxuě hé Xiǎomíng qù dòngwùyuán wán le. Běijīng Dòngwùyuán shì Zhōngguó hěn yǒumíng de dòngwùyuán, lǐmiàn yǒu fēicháng duō de dòngwù, dāngrán, dàren hé háizi zuì xǐ'ài de háishi dàxióngmāo. Měitiān yǒu hěn duō yóukè qù xióngmāoguǎn, tāmen dàizhe xiàngjī qù gěi kě'ài de dàxióngmāo pāizhào. Dòngwùyuán zǎoshang qī diǎn bàn kāimén, wǎnshang qī diǎn guānmén, dōngtiān bǐ xiàtiān yóukè shǎo, suǒyǐ yě bǐ píngshí zǎo guānmén yí ge xiǎoshí. Rúguǒ dì-yī cì lái Běijīng lǚyóu, gēn jiārén yìqǐ qù Běijīng Dòngwùyuán shì ge búcuò de xuǎnzé."}],"translation_vn":"Hôm nay tôi đã đưa Tiểu Tuyết và Tiểu Minh đi chơi sở thú. Vườn thú Bắc Kinh là vườn thú rất nổi tiếng của Trung Quốc, bên trong có rất nhiều động vật, tất nhiên, thứ mà người lớn và trẻ em yêu thích nhất vẫn là gấu trúc lớn. Mỗi ngày có rất nhiều du khách đến nhà gấu trúc, họ mang theo máy ảnh để chụp hình cho những chú gấu trúc đáng yêu. Vườn thú mở cửa lúc bảy giờ rưỡi sáng, đóng cửa lúc bảy giờ tối, mùa đông du khách ít hơn mùa hè, nên cũng đóng cửa sớm hơn bình thường một tiếng. Nếu lần đầu đến Bắc Kinh du lịch, cùng người nhà đi vườn thú Bắc Kinh là một lựa chọn không tồi.","audio_dialogue":"16-7.mp3","audio_vocab":"16-8.mp3"}]},{"id":17,"title_cn":"我要多向认真的人学习","title_pinyin":"Wǒ yào duō xiàng rènzhēn de rén xuéxí","title_vn":"Tôi phải học hỏi nhiều hơn từ những người làm việc nghiêm túc","goals":["Có thể nghe hiểu và bày tỏ các cảm xúc như buồn bã, bối rối, không hài lòng trong lòng.","Có thể nghe hiểu và sử dụng câu hỏi phản vấn \"不是……吗？\" để biểu đạt tình cảm và ngữ khí.","Nắm vững cách dùng \"只有\", có thể diễn đạt điều kiện duy nhất và kết quả."],"vocab":[{"hanzi":"向","pinyin":"xiàng","pos":"giới.","vn":"hướng về, về phía","examples":[{"cn":"请一直向前走,然后右转。","pinyin":"Qǐng yìzhí xiàng qián zǒu, ránhòu yòu zhuǎn.","vn":"Xin đi thẳng về phía trước, rồi rẽ phải."},{"cn":"我想向你请教一个问题。","pinyin":"Wǒ xiǎng xiàng nǐ qǐngjiào yí ge wèntí.","vn":"Mình muốn hỏi bạn một vấn đề."},{"cn":"花朵都向着太阳生长。","pinyin":"Huāduǒ dōu xiàng zhe tàiyáng shēngzhǎng.","vn":"Những bông hoa đều hướng về phía mặt trời mà mọc."}]},{"hanzi":"楼梯","pinyin":"lóutī","pos":"dt.","vn":"cầu thang","examples":[{"cn":"电梯坏了,我们只能走楼梯。","pinyin":"Diàntī huài le, wǒmen zhǐ néng zǒu lóutī.","vn":"Thang máy hỏng rồi, chúng ta chỉ có thể đi cầu thang."},{"cn":"小心,楼梯上有点滑。","pinyin":"Xiǎoxīn, lóutī shàng yǒudiǎn huá.","vn":"Cẩn thận, cầu thang hơi trơn đấy."},{"cn":"他从楼梯上摔了下来。","pinyin":"Tā cóng lóutī shàng shuāi le xiàlái.","vn":"Anh ấy bị ngã từ cầu thang xuống."}]},{"hanzi":"害怕","pinyin":"hàipà","pos":"dgt.","vn":"sợ hãi","examples":[{"cn":"我从小就害怕打针。","pinyin":"Wǒ cóngxiǎo jiù hàipà dǎzhēn.","vn":"Mình từ nhỏ đã sợ tiêm."},{"cn":"别害怕,有我在呢。","pinyin":"Bié hàipà, yǒu wǒ zài ne.","vn":"Đừng sợ, có mình ở đây mà."},{"cn":"她一个人在家很害怕。","pinyin":"Tā yí ge rén zài jiā hěn hàipà.","vn":"Cô ấy ở nhà một mình rất sợ."}]},{"hanzi":"生气","pinyin":"shēngqì","pos":"dgt.","vn":"tức giận, nổi giận","examples":[{"cn":"你怎么了?好像很生气的样子。","pinyin":"Nǐ zěnme le? Hǎoxiàng hěn shēngqì de yàngzi.","vn":"Bạn sao thế? Trông có vẻ đang tức giận."},{"cn":"别生气了,这不是什么大事。","pinyin":"Bié shēngqì le, zhè bú shì shénme dà shì.","vn":"Đừng giận nữa, chuyện này không lớn đâu."},{"cn":"他一生气就不说话了。","pinyin":"Tā yì shēngqì jiù bù shuōhuà le.","vn":"Anh ấy hễ nổi giận là không nói gì nữa."}]},{"hanzi":"常见","pinyin":"chángjiàn","pos":"tt.","vn":"thường gặp, phổ biến","examples":[{"cn":"感冒是一种很常见的病。","pinyin":"Gǎnmào shì yì zhǒng hěn chángjiàn de bìng.","vn":"Cảm cúm là một loại bệnh rất thường gặp."},{"cn":"这种情况在生活中很常见。","pinyin":"Zhè zhǒng qíngkuàng zài shēnghuó zhōng hěn chángjiàn.","vn":"Tình huống này rất phổ biến trong cuộc sống."},{"cn":"这是汉语里一个常见的语法错误。","pinyin":"Zhè shì Hànyǔ lǐ yí ge chángjiàn de yǔfǎ cuòwù.","vn":"Đây là một lỗi ngữ pháp thường gặp trong tiếng Hán."}]},{"hanzi":"聪明","pinyin":"cōngmíng","pos":"tt.","vn":"thông minh","examples":[{"cn":"他从小就很聪明,学什么都快。","pinyin":"Tā cóngxiǎo jiù hěn cōngmíng, xué shénme dōu kuài.","vn":"Anh ấy từ nhỏ đã rất thông minh, học gì cũng nhanh."},{"cn":"这个办法真聪明。","pinyin":"Zhège bànfǎ zhēn cōngmíng.","vn":"Cách này thật thông minh."},{"cn":"这只狗很聪明,能听懂主人的话。","pinyin":"Zhè zhī gǒu hěn cōngmíng, néng tīngdǒng zhǔrén de huà.","vn":"Con chó này rất thông minh, hiểu được lời của chủ."}]},{"hanzi":"错","pinyin":"cuò","pos":"dt.","vn":"lỗi, sai lầm","examples":[{"cn":"这道题我做错了。","pinyin":"Zhè dào tí wǒ zuò cuò le.","vn":"Bài này mình làm sai rồi."},{"cn":"对不起,是我的错。","pinyin":"Duìbuqǐ, shì wǒ de cuò.","vn":"Xin lỗi, là lỗi của mình."},{"cn":"每个人都会犯错,没关系。","pinyin":"Měi ge rén dōu huì fàn cuò, méi guānxi.","vn":"Ai cũng có lúc mắc lỗi, không sao đâu."}]},{"hanzi":"认为","pinyin":"rènwéi","pos":"dgt.","vn":"cho rằng","examples":[{"cn":"我认为这个办法不错。","pinyin":"Wǒ rènwéi zhège bànfǎ búcuò.","vn":"Mình cho rằng cách này khá tốt."},{"cn":"大家都认为他会同意。","pinyin":"Dàjiā dōu rènwéi tā huì tóngyì.","vn":"Mọi người đều cho rằng anh ấy sẽ đồng ý."},{"cn":"你认为这件事该怎么办?","pinyin":"Nǐ rènwéi zhè jiàn shì gāi zěnme bàn?","vn":"Bạn cho rằng việc này nên xử lý thế nào?"}]},{"hanzi":"到处","pinyin":"dàochù","pos":"phó.","vn":"khắp nơi","examples":[{"cn":"春天到处都开满了花。","pinyin":"Chūntiān dàochù dōu kāimǎn le huā.","vn":"Mùa xuân khắp nơi hoa nở đầy."},{"cn":"我到处找你,你去哪儿了?","pinyin":"Wǒ dàochù zhǎo nǐ, nǐ qù nǎr le?","vn":"Mình tìm bạn khắp nơi, bạn đi đâu vậy?"},{"cn":"到处都是人,根本挤不进去。","pinyin":"Dàochù dōu shì rén, gēnběn jǐ bú jìnqù.","vn":"Khắp nơi đều là người, chen vào không nổi."}]},{"hanzi":"继续","pinyin":"jìxù","pos":"dgt.","vn":"tiếp tục","examples":[{"cn":"休息一下,我们继续工作吧。","pinyin":"Xiūxi yíxià, wǒmen jìxù gōngzuò ba.","vn":"Nghỉ một chút rồi chúng ta tiếp tục làm việc nhé."},{"cn":"他虽然很累,但还是继续坚持跑步。","pinyin":"Tā suīrán hěn lèi, dàn háishi jìxù jiānchí pǎobù.","vn":"Mặc dù rất mệt nhưng anh ấy vẫn tiếp tục kiên trì chạy bộ."},{"cn":"下雨了,比赛还会继续吗?","pinyin":"Xiàyǔ le, bǐsài hái huì jìxù ma?","vn":"Trời mưa rồi, trận đấu còn tiếp tục không?"}]},{"hanzi":"同意","pinyin":"tóngyì","pos":"dgt.","vn":"đồng ý","examples":[{"cn":"我同意你的看法。","pinyin":"Wǒ tóngyì nǐ de kànfǎ.","vn":"Mình đồng ý với quan điểm của bạn."},{"cn":"爸爸还没同意我去旅行。","pinyin":"Bàba hái méi tóngyì wǒ qù lǚxíng.","vn":"Bố vẫn chưa đồng ý cho mình đi du lịch."},{"cn":"大家都同意这个计划。","pinyin":"Dàjiā dōu tóngyì zhège jìhuà.","vn":"Mọi người đều đồng ý với kế hoạch này."}]},{"hanzi":"可","pinyin":"kě","pos":"liên.","vn":"nhưng","examples":[{"cn":"这个办法可行,可太麻烦了。","pinyin":"Zhège bànfǎ kěxíng, kě tài máfan le.","vn":"Cách này khả thi, nhưng quá phiền phức."},{"cn":"他很想去,可是没有时间。","pinyin":"Tā hěn xiǎng qù, kě shì méiyǒu shíjiān.","vn":"Anh ấy rất muốn đi, nhưng không có thời gian."},{"cn":"东西不贵,可质量不太好。","pinyin":"Dōngxi bú guì, kě zhìliàng bú tài hǎo.","vn":"Đồ không đắt, nhưng chất lượng không tốt lắm."}]},{"hanzi":"屋子","pinyin":"wūzi","pos":"dt.","vn":"phòng","examples":[{"cn":"这间屋子又干净又暖和。","pinyin":"Zhè jiān wūzi yòu gānjìng yòu nuǎnhuo.","vn":"Căn phòng này vừa sạch sẽ vừa ấm áp."},{"cn":"他一个人住在一间小屋子里。","pinyin":"Tā yí ge rén zhù zài yì jiān xiǎo wūzi lǐ.","vn":"Anh ấy sống một mình trong một căn phòng nhỏ."},{"cn":"快把屋子收拾一下,客人要来了。","pinyin":"Kuài bǎ wūzi shōushi yíxià, kèrén yào lái le.","vn":"Mau dọn dẹp phòng đi, khách sắp đến rồi."}]},{"hanzi":"有关","pinyin":"yǒuguān","pos":"dgt.","vn":"có liên quan đến","examples":[{"cn":"这件事跟他没有关系,他不知道。","pinyin":"Zhè jiàn shì gēn tā méiyǒu guānxi, tā bù zhīdào.","vn":"Chuyện này không liên quan đến anh ấy, anh ấy không biết."},{"cn":"这本书跟历史有关。","pinyin":"Zhè běn shū gēn lìshǐ yǒuguān.","vn":"Cuốn sách này có liên quan đến lịch sử."},{"cn":"这次会议和公司的新计划有关。","pinyin":"Zhè cì huìyì hé gōngsī de xīn jìhuà yǒuguān.","vn":"Cuộc họp lần này có liên quan đến kế hoạch mới của công ty."}]},{"hanzi":"关机","pinyin":"guānjī","pos":"dgt.","vn":"tắt máy (điện thoại)","examples":[{"cn":"上课的时候请把手机关机。","pinyin":"Shàngkè de shíhou qǐng bǎ shǒujī guānjī.","vn":"Lúc học bài xin hãy tắt máy điện thoại."},{"cn":"我的手机没电了,自动关机了。","pinyin":"Wǒ de shǒujī méi diàn le, zìdòng guānjī le.","vn":"Điện thoại của mình hết pin rồi, tự động tắt máy luôn."},{"cn":"坐飞机的时候要把手机关机。","pinyin":"Zuò fēijī de shíhou yào bǎ shǒujī guānjī.","vn":"Khi đi máy bay phải tắt nguồn điện thoại."}]},{"hanzi":"前天","pinyin":"qiántiān","pos":"dt.","vn":"hôm kia","examples":[{"cn":"前天我去医院看了一次病。","pinyin":"Qiántiān wǒ qù yīyuàn kàn le yí cì bìng.","vn":"Hôm kia mình đi bệnh viện khám bệnh một lần."},{"cn":"她前天才从北京回来。","pinyin":"Tā qiántiān cái cóng Běijīng huílái.","vn":"Mãi đến hôm kia cô ấy mới từ Bắc Kinh về."},{"cn":"前天晚上下了一场大雨。","pinyin":"Qiántiān wǎnshang xià le yì chǎng dàyǔ.","vn":"Tối hôm kia có một trận mưa to."}]},{"hanzi":"留学","pinyin":"liúxué","pos":"dgt.","vn":"du học","examples":[{"cn":"他打算明年去美国留学。","pinyin":"Tā dǎsuàn míngnián qù Měiguó liúxué.","vn":"Anh ấy dự định sang năm sẽ đi du học ở Mỹ."},{"cn":"我姐姐在英国留学了三年。","pinyin":"Wǒ jiějie zài Yīngguó liúxué le sān nián.","vn":"Chị gái mình đã du học ở Anh ba năm."},{"cn":"留学生活既辛苦又有意思。","pinyin":"Liúxué shēnghuó jì xīnkǔ yòu yǒu yìsi.","vn":"Cuộc sống du học vừa vất vả vừa thú vị."}]},{"hanzi":"国家","pinyin":"guójiā","pos":"dt.","vn":"quốc gia, đất nước","examples":[{"cn":"我去过很多国家旅行。","pinyin":"Wǒ qù guo hěn duō guójiā lǚxíng.","vn":"Mình đã từng đi du lịch ở nhiều quốc gia."},{"cn":"每个国家都有自己的文化。","pinyin":"Měi ge guójiā dōu yǒu zìjǐ de wénhuà.","vn":"Mỗi quốc gia đều có nền văn hóa riêng."},{"cn":"中国是一个历史悠久的国家。","pinyin":"Zhōngguó shì yí ge lìshǐ yōujiǔ de guójiā.","vn":"Trung Quốc là một quốc gia có lịch sử lâu đời."}]},{"hanzi":"比如","pinyin":"bǐrú","pos":"dgt.","vn":"ví dụ như","examples":[{"cn":"我喜欢运动,比如游泳、跑步。","pinyin":"Wǒ xǐhuan yùndòng, bǐrú yóuyǒng, pǎobù.","vn":"Mình thích thể thao, ví dụ như bơi lội, chạy bộ."},{"cn":"有些问题很难解决,比如交通问题。","pinyin":"Yǒuxiē wèntí hěn nán jiějué, bǐrú jiāotōng wèntí.","vn":"Có một số vấn đề rất khó giải quyết, ví dụ như vấn đề giao thông."},{"cn":"这里有很多水果,比如苹果、香蕉。","pinyin":"Zhèlǐ yǒu hěn duō shuǐguǒ, bǐrú píngguǒ, xiāngjiāo.","vn":"Ở đây có nhiều loại hoa quả, ví dụ như táo, chuối."}]},{"hanzi":"查","pinyin":"chá","pos":"dgt.","vn":"tra cứu","examples":[{"cn":"我不认识这个字,去查查字典。","pinyin":"Wǒ bú rènshi zhège zì, qù chá chá zìdiǎn.","vn":"Mình không biết chữ này, để tra từ điển xem."},{"cn":"你可以上网查一下这个消息是不是真的。","pinyin":"Nǐ kěyǐ shàngwǎng chá yíxià zhège xiāoxi shì bu shì zhēn de.","vn":"Bạn có thể lên mạng tra xem tin này có thật không."},{"cn":"医生让我去医院查一下身体。","pinyin":"Yīshēng ràng wǒ qù yīyuàn chá yíxià shēntǐ.","vn":"Bác sĩ bảo mình đi bệnh viện kiểm tra sức khỏe."}]},{"hanzi":"有用","pinyin":"yǒuyòng","pos":"tt.","vn":"hữu ích, có ích","examples":[{"cn":"这本书对我学习汉语很有用。","pinyin":"Zhè běn shū duì wǒ xuéxí Hànyǔ hěn yǒuyòng.","vn":"Cuốn sách này rất hữu ích cho việc học tiếng Hán của mình."},{"cn":"这个方法真的有用吗?","pinyin":"Zhège fāngfǎ zhēn de yǒuyòng ma?","vn":"Phương pháp này thực sự có hiệu quả không?"},{"cn":"多学一门语言总是有用的。","pinyin":"Duō xué yì mén yǔyán zǒngshì yǒuyòng de.","vn":"Học thêm một ngôn ngữ luôn luôn hữu ích."}]},{"hanzi":"容易","pinyin":"róngyì","pos":"tt.","vn":"dễ dàng","examples":[{"cn":"这道题很容易,我一下就做完了。","pinyin":"Zhè dào tí hěn róngyì, wǒ yíxià jiù zuò wán le.","vn":"Bài này rất dễ, mình làm xong ngay."},{"cn":"学好一门外语不容易。","pinyin":"Xuéhǎo yì mén wàiyǔ bù róngyì.","vn":"Học giỏi một ngoại ngữ không dễ dàng."},{"cn":"夏天食物容易坏,要放进冰箱。","pinyin":"Xiàtiān shíwù róngyì huài, yào fàng jìn bīngxiāng.","vn":"Mùa hè đồ ăn dễ hỏng, phải cho vào tủ lạnh."}]},{"hanzi":"回答","pinyin":"huídá","pos":"dgt.","vn":"trả lời","examples":[{"cn":"请回答我的问题。","pinyin":"Qǐng huídá wǒ de wèntí.","vn":"Xin hãy trả lời câu hỏi của tôi."},{"cn":"他想了很久才回答。","pinyin":"Tā xiǎng le hěn jiǔ cái huídá.","vn":"Anh ấy suy nghĩ rất lâu mới trả lời."},{"cn":"这个问题我不知道怎么回答。","pinyin":"Zhège wèntí wǒ bù zhīdào zěnme huídá.","vn":"Câu hỏi này mình không biết trả lời thế nào."}]},{"hanzi":"方向","pinyin":"fāngxiàng","pos":"dt.","vn":"phương hướng","examples":[{"cn":"我走错方向了。","pinyin":"Wǒ zǒu cuò fāngxiàng le.","vn":"Mình đi nhầm hướng rồi."},{"cn":"请问去火车站是哪个方向?","pinyin":"Qǐngwèn qù huǒchēzhàn shì nǎge fāngxiàng?","vn":"Xin hỏi đi đến ga tàu là hướng nào?"},{"cn":"他对自己的未来有明确的方向。","pinyin":"Tā duì zìjǐ de wèilái yǒu míngquè de fāngxiàng.","vn":"Anh ấy có phương hướng rõ ràng cho tương lai của mình."}]},{"hanzi":"只有","pinyin":"zhǐyǒu","pos":"liên.","vn":"chỉ có","examples":[{"cn":"只有努力学习,才能考上好大学。","pinyin":"Zhǐyǒu nǔlì xuéxí, cái néng kǎoshang hǎo dàxué.","vn":"Chỉ có nỗ lực học tập mới có thể thi đỗ trường đại học tốt."},{"cn":"这件事只有他一个人知道。","pinyin":"Zhè jiàn shì zhǐyǒu tā yí ge rén zhīdào.","vn":"Chuyện này chỉ có một mình anh ấy biết."},{"cn":"屋子里只有一张桌子和两把椅子。","pinyin":"Wūzi lǐ zhǐyǒu yì zhāng zhuōzi hé liǎng bǎ yǐzi.","vn":"Trong phòng chỉ có một cái bàn và hai cái ghế."}]},{"hanzi":"真正","pinyin":"zhēnzhèng","pos":"phó.","vn":"thực sự, thật sự","examples":[{"cn":"他是我真正的朋友。","pinyin":"Tā shì wǒ zhēnzhèng de péngyou.","vn":"Anh ấy là người bạn thực sự của mình."},{"cn":"我现在才真正明白他的意思。","pinyin":"Wǒ xiànzài cái zhēnzhèng míngbai tā de yìsi.","vn":"Bây giờ mình mới thực sự hiểu ý của anh ấy."},{"cn":"真正的成功需要长时间的坚持。","pinyin":"Zhēnzhèng de chénggōng xūyào cháng shíjiān de jiānchí.","vn":"Thành công thực sự cần sự kiên trì trong thời gian dài."}]},{"hanzi":"难题","pinyin":"nántí","pos":"dt.","vn":"vấn đề khó, bài toán khó","examples":[{"cn":"这道数学难题我想了一个晚上。","pinyin":"Zhè dào shùxué nántí wǒ xiǎng le yí ge wǎnshang.","vn":"Bài toán khó này mình đã nghĩ cả một buổi tối."},{"cn":"环境污染是一个全球性的难题。","pinyin":"Huánjìng wūrǎn shì yí ge quánqiúxìng de nántí.","vn":"Ô nhiễm môi trường là một vấn đề khó toàn cầu."},{"cn":"老师帮我解决了这个难题。","pinyin":"Lǎoshī bāng wǒ jiějué le zhège nántí.","vn":"Thầy giáo đã giúp mình giải quyết vấn đề khó này."}]}],"grammar":[{"title":"介词\"向\" - Giới từ \"向\"","explanation_vn":"Giới từ \"向\" đi kèm theo sau là đại từ, danh từ hoặc cụm danh từ, biểu thị phương hướng hoặc đối tượng của hành động.","examples":[{"cn":"别再向前走了。","pinyin":"Bié zài xiàng qián zǒu le.","vn":""},{"cn":"以后我要多向认真的人学习。","pinyin":"Yǐhòu wǒ yào duō xiàng rènzhēn de rén xuéxí.","vn":""},{"cn":"孩子一看见妈妈，就向她跑过去了。","pinyin":"Háizi yí kànjiàn māma, jiù xiàng tā pǎo guòqù le.","vn":""}]},{"title":"反问句\"不是……吗？\" - Câu hỏi phản vấn \"不是……吗？\"","explanation_vn":"Câu hỏi phản vấn \"不是……吗？\" thường dùng để biểu đạt sự không hiểu hoặc không hài lòng của người nói, đôi khi cũng dùng để nhắc nhở hoặc xác nhận. Hình thức là phủ định nhưng ý nghĩa lại là khẳng định.","examples":[{"cn":"你不是喜欢玩电脑吗？你可以去看看跟电脑有关系的书。","pinyin":"Nǐ bú shì xǐhuan wán diànnǎo ma? Nǐ kěyǐ qù kànkan gēn diànnǎo yǒu guānxi de shū.","vn":""},{"cn":"你不是说今天有事吗？为什么来了？","pinyin":"Nǐ bú shì shuō jīntiān yǒushì ma? Wèishénme lái le?","vn":""},{"cn":"考试不是下个月吗？你怎么今天就开始复习？","pinyin":"Kǎoshì bú shì xià ge yuè ma? Nǐ zěnme jīntiān jiù kāishǐ fùxí?","vn":""}]},{"title":"递进复句\"……，更……\" - Câu phức tăng tiến \"……，更……\"","explanation_vn":"Trong câu phức tăng tiến \"……，更……\", vế thứ hai biểu thị mức độ sâu hơn so với vế thứ nhất.","examples":[{"cn":"我还没想好学什么，更没想好去哪个国家。","pinyin":"Wǒ hái méi xiǎnghǎo xué shénme, gèng méi xiǎnghǎo qù nǎge guójiā.","vn":""},{"cn":"想提高中文水平要多听多看，更要多说多练。","pinyin":"Xiǎng tígāo Zhōngwén shuǐpíng yào duō tīng duō kàn, gèng yào duō shuō duō liàn.","vn":""},{"cn":"来中国学习，我学会了中文，更了解了中国文化。","pinyin":"Lái Zhōngguó xuéxí, wǒ xuéhuìle Zhōngwén, gèng liǎojiěle Zhōngguó wénhuà.","vn":""}]},{"title":"条件复句\"只有……，才……\" - Câu phức điều kiện \"只有……，才……\"","explanation_vn":"Trong câu phức điều kiện \"只有……，才……\", vế đi sau \"只有\" là điều kiện duy nhất để đạt được kết quả; nếu không có điều kiện này thì sẽ không có kết quả nêu sau \"才\".","examples":[{"cn":"只有想清楚自己真正喜欢什么，才能做出最合适的选择。","pinyin":"Zhǐyǒu xiǎng qīngchu zìjǐ zhēnzhèng xǐhuan shénme, cái néng zuòchū zuì héshì de xuǎnzé.","vn":""},{"cn":"只有每天锻炼身体，才会越来越健康。","pinyin":"Zhǐyǒu měitiān duànliàn shēntǐ, cái huì yuè lái yuè jiànkāng.","vn":""},{"cn":"只有多听、多说、多看，你的中文水平才能提高。","pinyin":"Zhǐyǒu duō tīng, duō shuō, duō kàn, nǐ de Zhōngwén shuǐpíng cái néng tígāo.","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"刘小雪","cn":"别再向前走了，李老师的办公室已经到了。","pinyin":"Bié zài xiàng qián zǒu le, Lǐ lǎoshī de bàngōngshì yǐjīng dào le."},{"speaker":"同学","cn":"你进去吧，我在楼梯那儿等你。我害怕见李老师。","pinyin":"Nǐ jìnqù ba, wǒ zài lóutī nàr děng nǐ. Wǒ hàipà jiàn Lǐ lǎoshī."},{"speaker":"刘小雪","cn":"怎么回事？","pinyin":"Zěnme huí shì?"},{"speaker":"同学","cn":"最近我做错了好几件事，我怕李老师生气。","pinyin":"Zuìjìn wǒ zuòcuòle hǎo jǐ jiàn shì, wǒ pà Lǐ lǎoshī shēngqì."},{"speaker":"刘小雪","cn":"你想多了，做错事情是很常见的。","pinyin":"Nǐ xiǎngduō le, zuòcuò shìqing shì hěn chángjiàn de."},{"speaker":"同学","cn":"我把简单的事情做错了，李老师一定觉得我不认真。","pinyin":"Wǒ bǎ jiǎndān de shìqing zuòcuò le, Lǐ lǎoshī yídìng juéde wǒ bú rènzhēn."},{"speaker":"刘小雪","cn":"有的人虽然很聪明，但是会在简单的事情中出错，因为他们认为事情简单，就不会认真去做了。","pinyin":"Yǒude rén suīrán hěn cōngmíng, dànshì huì zài jiǎndān de shìqing zhōng chūcuò, yīnwèi tāmen rènwéi shìqing jiǎndān, jiù bú huì rènzhēn qù zuò le."},{"speaker":"同学","cn":"你说的就是我，以后我要多向认真的人学习。","pinyin":"Nǐ shuō de jiù shì wǒ, yǐhòu wǒ yào duō xiàng rènzhēn de rén xuéxí."}],"translation_vn":"Lưu Tiểu Tuyết: Đừng đi về phía trước nữa, văn phòng thầy Lý đến rồi.\nBạn học: Cậu vào đi, mình đợi cậu ở chỗ cầu thang. Mình sợ gặp thầy Lý.\nLưu Tiểu Tuyết: Chuyện gì vậy?\nBạn học: Gần đây mình đã làm sai mấy việc, mình sợ thầy Lý nổi giận.\nLưu Tiểu Tuyết: Cậu nghĩ nhiều rồi, làm sai việc là chuyện rất thường gặp mà.\nBạn học: Mình đã làm sai những việc đơn giản, thầy Lý chắc chắn sẽ nghĩ mình không nghiêm túc.\nLưu Tiểu Tuyết: Có những người tuy rất thông minh, nhưng lại hay mắc lỗi trong những việc đơn giản, vì họ cho rằng việc đơn giản nên sẽ không làm một cách nghiêm túc nữa.\nBạn học: Cậu nói đúng là mình đấy, sau này mình phải học hỏi nhiều hơn từ những người làm việc nghiêm túc.","audio_dialogue":"17-1 @xitoytili_luoluodafang.mp3","audio_vocab":"17-2 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"白家月","cn":"太阳从西边出来了？这几天怎么总是在图书馆看见你？","pinyin":"Tàiyáng cóng xībian chūlái le? Zhè jǐ tiān zěnme zǒngshì zài túshūguǎn kànjiàn nǐ?"},{"speaker":"陈天中","cn":"这有什么奇怪的？我是来学习的。","pinyin":"Zhè yǒu shénme qíguài de? Wǒ shì lái xuéxí de."},{"speaker":"白家月","cn":"你怎么还来图书馆学习？同学们都在到处找工作呢。","pinyin":"Nǐ zěnme hái lái túshūguǎn xuéxí? Tóngxuémen dōu zài dàochù zhǎo gōngzuò ne."},{"speaker":"陈天中","cn":"我不想现在就工作，还想继续学习，我爸妈也同意。可我还没想好学什么，所以来图书馆看看。","pinyin":"Wǒ bù xiǎng xiànzài jiù gōngzuò, hái xiǎng jìxù xuéxí, wǒ bàmā yě tóngyì. Kě wǒ hái méi xiǎnghǎo xué shénme, suǒyǐ lái túshūguǎn kànkan."},{"speaker":"白家月","cn":"你不是喜欢玩电脑吗？你可以去看看跟电脑有关系的书。","pinyin":"Nǐ bú shì xǐhuan wán diànnǎo ma? Nǐ kěyǐ qù kànkan gēn diànnǎo yǒu guānxi de shū."},{"speaker":"陈天中","cn":"你说得对，我记得那个屋子里有些跟电脑有关的书，我去找找。","pinyin":"Nǐ shuō de duì, wǒ jìde nàge wūzi lǐ yǒuxiē gēn diànnǎo yǒuguān de shū, wǒ qù zhǎozhao."}],"translation_vn":"Bạch Gia Nguyệt: Mặt trời mọc từ hướng tây rồi à? Sao mấy ngày nay lúc nào cũng thấy cậu ở thư viện vậy?\nTrần Thiên Trung: Có gì lạ đâu? Mình đến để học mà.\nBạch Gia Nguyệt: Sao cậu còn đến thư viện học nữa? Các bạn cùng lớp đều đang đi khắp nơi tìm việc làm kìa.\nTrần Thiên Trung: Mình không muốn đi làm ngay bây giờ, vẫn muốn tiếp tục học, bố mẹ mình cũng đồng ý. Nhưng mình vẫn chưa nghĩ ra nên học gì, nên đến thư viện xem thử.\nBạch Gia Nguyệt: Cậu không phải thích chơi máy tính sao? Cậu có thể đi xem những sách liên quan đến máy tính.\nTrần Thiên Trung: Cậu nói đúng đấy, mình nhớ trong căn phòng đó có một số sách liên quan đến máy tính, mình đi tìm thử xem.","audio_dialogue":"17-3 @xitoytili_luoluodafang.mp3","audio_vocab":"17-4 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"李文","cn":"天中，你的手机怎么关机了？","pinyin":"Tiānzhōng, nǐ de shǒujī zěnme guānjī le?"},{"speaker":"陈天中","cn":"我的手机没电了。你找我有事吗？","pinyin":"Wǒ de shǒujī méi diàn le. Nǐ zhǎo wǒ yǒushì ma?"},{"speaker":"李文","cn":"前天我看见家月了，她告诉我你打算继续留学？","pinyin":"Qiántiān wǒ kànjiàn Jiāyuè le, tā gàosu wǒ nǐ dǎsuan jìxù liúxué?"},{"speaker":"陈天中","cn":"是，可是我还没想好学什么，更没想好去哪个国家。","pinyin":"Shì, kěshì wǒ hái méi xiǎnghǎo xué shénme, gèng méi xiǎnghǎo qù nǎge guójiā."},{"speaker":"李文","cn":"你可以去中国学中文啊。比如可以去北京、上海这样的大城市，那里有很多好大学，也有很多留学生。","pinyin":"Nǐ kěyǐ qù Zhōngguó xué Zhōngwén a. Bǐrú kěyǐ qù Běijīng, Shànghǎi zhèyàng de dà chéngshì, nàlǐ yǒu hěn duō hǎo dàxué, yě yǒu hěn duō liúxuéshēng."},{"speaker":"陈天中","cn":"好，那我上网查一查。","pinyin":"Hǎo, nà wǒ shàngwǎng chá yi chá."},{"speaker":"李文","cn":"我给你介绍几个有用的网站。","pinyin":"Wǒ gěi nǐ jièshào jǐ ge yǒuyòng de wǎngzhàn."}],"translation_vn":"Lý Văn: Thiên Trung, sao điện thoại của cậu lại tắt máy vậy?\nTrần Thiên Trung: Điện thoại mình hết pin rồi. Cậu tìm mình có việc gì à?\nLý Văn: Hôm kia mình gặp Gia Nguyệt, cô ấy nói với mình là cậu định tiếp tục đi du học?\nTrần Thiên Trung: Đúng vậy, nhưng mình vẫn chưa nghĩ ra nên học gì, càng chưa nghĩ ra nên đi nước nào nữa.\nLý Văn: Cậu có thể sang Trung Quốc học tiếng Trung mà. Ví dụ có thể đến những thành phố lớn như Bắc Kinh, Thượng Hải, ở đó có rất nhiều trường đại học tốt, cũng có rất nhiều du học sinh.\nTrần Thiên Trung: Được, vậy mình lên mạng tra thử xem.\nLý Văn: Mình giới thiệu cho cậu vài trang web hữu ích nhé.","audio_dialogue":"17-5 @xitoytili_luoluodafang.mp3","audio_vocab":"17-6 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"大学生活马上就要结束了，我最近经常被问到一个问题——\"你以后想做什么\"，这个问题真不容易回答。我也问了几个同学，大家选择的方向都不同。有的想继续在学校学习，有的打算出国留学，还有的决定先找工作。我认为只有想清楚自己真正喜欢什么，才能做出最合适的选择。对我来说，想清楚\"真正喜欢什么\"是个难题。","pinyin":"Dàxué shēnghuó mǎshàng jiù yào jiéshù le, wǒ zuìjìn jīngcháng bèi wèndào yí ge wèntí — \"nǐ yǐhòu xiǎng zuò shénme\", zhège wèntí zhēn bù róngyì huídá. Wǒ yě wènle jǐ ge tóngxué, dàjiā xuǎnzé de fāngxiàng dōu bù tóng. Yǒude xiǎng jìxù zài xuéxiào xuéxí, yǒude dǎsuan chūguó liúxué, hái yǒude juédìng xiān zhǎo gōngzuò. Wǒ rènwéi zhǐyǒu xiǎng qīngchu zìjǐ zhēnzhèng xǐhuan shénme, cái néng zuòchū zuì héshì de xuǎnzé. Duì wǒ lái shuō, xiǎng qīngchu \"zhēnzhèng xǐhuan shénme\" shì ge nántí."}],"translation_vn":"Cuộc sống đại học sắp kết thúc rồi, gần đây tôi thường xuyên bị hỏi một câu hỏi — \"Sau này bạn muốn làm gì\", câu hỏi này thật không dễ trả lời. Tôi cũng đã hỏi vài người bạn học, hướng lựa chọn của mọi người đều khác nhau. Có người muốn tiếp tục học ở trường, có người định đi du học nước ngoài, lại có người quyết định tìm việc làm trước. Tôi cho rằng chỉ khi nghĩ rõ bản thân thực sự thích gì, mới có thể đưa ra lựa chọn phù hợp nhất. Đối với tôi, việc nghĩ rõ \"thực sự thích gì\" là một bài toán khó.","audio_dialogue":"17-7 @xitoytili_luoluodafang.mp3","audio_vocab":"17-8 @xitoytili_luoluodafang.mp3"}]},{"id":18,"title_cn":"我学会了包饺子","title_pinyin":"Wǒ xuéhuìle bāo jiǎozi","title_vn":"Tôi đã học được cách gói sủi cảo","goals":["Có thể nghe hiểu và miêu tả những thay đổi trong cuộc sống và trải nghiệm trưởng thành.","Có thể nghe hiểu và sử dụng số ước lượng để diễn đạt số lượng không chắc chắn.","Nắm vững cách dùng \"只要\", có thể diễn đạt điều kiện đủ và kết quả.","Tìm hiểu phong tục của ngày lễ truyền thống Trung Quốc \"Xuân Tiết\" (Tết Nguyên Đán)."],"vocab":[{"hanzi":"怎样","pinyin":"zěnyàng","pos":"đt.","vn":"như thế nào","examples":[{"cn":"你觉得这个办法怎样?","pinyin":"Nǐ juéde zhège bànfǎ zěnyàng?","vn":"Bạn thấy cách này thế nào?"},{"cn":"我们应该怎样解决这个问题?","pinyin":"Wǒmen yīnggāi zěnyàng jiějué zhège wèntí?","vn":"Chúng ta nên giải quyết vấn đề này như thế nào?"},{"cn":"不管生活怎样变化,他都很乐观。","pinyin":"Bùguǎn shēnghuó zěnyàng biànhuà, tā dōu hěn lèguān.","vn":"Dù cuộc sống thay đổi thế nào, anh ấy vẫn luôn lạc quan."}]},{"hanzi":"过节","pinyin":"guòjié","pos":"dgt.","vn":"ăn mừng lễ, đón lễ","examples":[{"cn":"春节的时候,大家都回家过节。","pinyin":"Chūnjié de shíhou, dàjiā dōu huí jiā guòjié.","vn":"Vào dịp Tết, mọi người đều về nhà ăn Tết."},{"cn":"我们今年打算在国外过节。","pinyin":"Wǒmen jīnnián dǎsuàn zài guówài guòjié.","vn":"Năm nay chúng tôi dự định đón lễ ở nước ngoài."},{"cn":"过节的时候街上特别热闹。","pinyin":"Guòjié de shíhou jiē shang tèbié rènao.","vn":"Những ngày lễ phố xá đặc biệt nhộn nhịp."}]},{"hanzi":"节","pinyin":"jié","pos":"dt.","vn":"lễ, tết","examples":[{"cn":"中秋节是中国重要的节日。","pinyin":"Zhōngqiūjié shì Zhōngguó zhòngyào de jiérì.","vn":"Tết Trung Thu là ngày lễ quan trọng của Trung Quốc."},{"cn":"快到过节的时候了,我们准备买些礼物。","pinyin":"Kuài dào guòjié de shíhou le, wǒmen zhǔnbèi mǎi xiē lǐwù.","vn":"Sắp đến ngày lễ rồi, chúng tôi chuẩn bị mua ít quà."},{"cn":"每年这个节我们全家都会一起聚聚。","pinyin":"Měi nián zhège jié wǒmen quánjiā dōu huì yìqǐ jùju.","vn":"Mỗi năm vào dịp lễ này cả nhà tôi đều sum họp."}]},{"hanzi":"节日","pinyin":"jiérì","pos":"dt.","vn":"ngày lễ","examples":[{"cn":"春节是中国最重要的节日。","pinyin":"Chūnjié shì Zhōngguó zuì zhòngyào de jiérì.","vn":"Tết Nguyên Đán là ngày lễ quan trọng nhất của Trung Quốc."},{"cn":"这个节日你们是怎么过的?","pinyin":"Zhège jiérì nǐmen shì zěnme guò de?","vn":"Ngày lễ này các bạn đón như thế nào?"},{"cn":"每个国家都有自己独特的节日。","pinyin":"Měi ge guójiā dōu yǒu zìjǐ dútè de jiérì.","vn":"Mỗi quốc gia đều có ngày lễ đặc trưng riêng."}]},{"hanzi":"联欢","pinyin":"liánhuān","pos":"dgt.","vn":"liên hoan, họp mặt vui vẻ","examples":[{"cn":"学校今晚举行新年联欢晚会。","pinyin":"Xuéxiào jīnwǎn jǔxíng xīnnián liánhuān wǎnhuì.","vn":"Tối nay trường tổ chức dạ hội liên hoan mừng năm mới."},{"cn":"我们班打算周五晚上联欢一下。","pinyin":"Wǒmen bān dǎsuàn zhōuwǔ wǎnshang liánhuān yíxià.","vn":"Lớp chúng tôi dự định tối thứ sáu liên hoan một chút."},{"cn":"春节联欢晚会每年都有很多人看。","pinyin":"Chūnjié liánhuān wǎnhuì měi nián dōu yǒu hěn duō rén kàn.","vn":"Chương trình liên hoan Tết mỗi năm đều có rất nhiều người xem."}]},{"hanzi":"大概","pinyin":"dàgài","pos":"phó.","vn":"khoảng, đại khái","examples":[{"cn":"这个工作大概需要三天才能完成。","pinyin":"Zhège gōngzuò dàgài xūyào sān tiān cái néng wánchéng.","vn":"Công việc này đại khái cần ba ngày mới hoàn thành được."},{"cn":"他大概不会来了。","pinyin":"Tā dàgài bú huì lái le.","vn":"Anh ấy có lẽ sẽ không đến nữa."},{"cn":"现在大概是晚上八点。","pinyin":"Xiànzài dàgài shì wǎnshang bā diǎn.","vn":"Bây giờ khoảng tám giờ tối."}]},{"hanzi":"春节","pinyin":"Chūnjié","pos":"danh từ riêng","vn":"Tết Nguyên Đán (Xuân Tiết)","examples":[{"cn":"春节的时候我们都要吃饺子。","pinyin":"Chūnjié de shíhou wǒmen dōu yào chī jiǎozi.","vn":"Vào dịp Tết chúng tôi đều phải ăn sủi cảo."},{"cn":"今年春节我打算回老家看爷爷奶奶。","pinyin":"Jīnnián Chūnjié wǒ dǎsuàn huí lǎojiā kàn yéye nǎinai.","vn":"Tết năm nay mình dự định về quê thăm ông bà."},{"cn":"春节前,街上到处都挂着红灯笼。","pinyin":"Chūnjié qián, jiē shang dàochù dōu guà zhe hóng dēnglong.","vn":"Trước Tết, trên phố khắp nơi treo đèn lồng đỏ."}]},{"hanzi":"阿姨","pinyin":"āyí","pos":"dt.","vn":"dì, cô","examples":[{"cn":"这是我妈妈的妹妹,我叫她阿姨。","pinyin":"Zhè shì wǒ māma de mèimei, wǒ jiào tā āyí.","vn":"Đây là em gái của mẹ mình, mình gọi là dì."},{"cn":"阿姨,请问洗手间在哪儿?","pinyin":"Āyí, qǐngwèn xǐshǒujiān zài nǎr?","vn":"Cô ơi, cho hỏi nhà vệ sinh ở đâu ạ?"},{"cn":"楼下那位阿姨对我们特别好。","pinyin":"Lóuxià nà wèi āyí duì wǒmen tèbié hǎo.","vn":"Cô hàng xóm ở tầng dưới đối xử với chúng tôi rất tốt."}]},{"hanzi":"叔叔","pinyin":"shūshu","pos":"dt.","vn":"chú, bác","examples":[{"cn":"这是我爸爸的弟弟,我叫他叔叔。","pinyin":"Zhè shì wǒ bàba de dìdi, wǒ jiào tā shūshu.","vn":"Đây là em trai của bố mình, mình gọi là chú."},{"cn":"叔叔,您好,请坐。","pinyin":"Shūshu, nín hǎo, qǐng zuò.","vn":"Chào chú, mời chú ngồi."},{"cn":"我叔叔是一名医生。","pinyin":"Wǒ shūshu shì yì míng yīshēng.","vn":"Chú của mình là bác sĩ."}]},{"hanzi":"收","pinyin":"shōu","pos":"dgt.","vn":"nhận","examples":[{"cn":"我收到了你寄来的礼物。","pinyin":"Wǒ shōudào le nǐ jì lái de lǐwù.","vn":"Mình đã nhận được món quà bạn gửi."},{"cn":"过年的时候,孩子们都能收到压岁钱。","pinyin":"Guònián de shíhou, háizimen dōu néng shōudào yāsuìqián.","vn":"Vào dịp Tết, bọn trẻ đều nhận được tiền lì xì."},{"cn":"这家店不收现金,只收手机支付。","pinyin":"Zhè jiā diàn bù shōu xiànjīn, zhǐ shōu shǒujī zhīfù.","vn":"Cửa hàng này không nhận tiền mặt, chỉ nhận thanh toán qua điện thoại."}]},{"hanzi":"总","pinyin":"zǒng","pos":"phó.","vn":"luôn luôn","examples":[{"cn":"他工作总是很认真。","pinyin":"Tā gōngzuò zǒngshì hěn rènzhēn.","vn":"Anh ấy làm việc lúc nào cũng rất nghiêm túc."},{"cn":"下雨天我总想睡觉。","pinyin":"Xiàyǔ tiān wǒ zǒng xiǎng shuìjiào.","vn":"Ngày mưa mình luôn muốn ngủ."},{"cn":"她总是第一个到教室。","pinyin":"Tā zǒngshì dì-yī ge dào jiàoshì.","vn":"Cô ấy luôn luôn là người đến lớp đầu tiên."}]},{"hanzi":"起","pinyin":"qǐ","pos":"dgt.","vn":"lên (bổ ngữ chỉ sự đề cập/bắt đầu, đi sau động từ)","examples":[{"cn":"我突然想起了一件重要的事。","pinyin":"Wǒ tūrán xiǎngqǐ le yí jiàn zhòngyào de shì.","vn":"Mình đột nhiên nhớ ra một việc quan trọng."},{"cn":"说起这件事,我就觉得很好笑。","pinyin":"Shuōqǐ zhè jiàn shì, wǒ jiù juéde hěn hǎoxiào.","vn":"Nhắc đến chuyện này, mình thấy buồn cười quá."},{"cn":"他拿起手机看了看时间。","pinyin":"Tā náqǐ shǒujī kàn le kàn shíjiān.","vn":"Anh ấy cầm điện thoại lên xem giờ."}]},{"hanzi":"见面","pinyin":"jiànmiàn","pos":"dgt.","vn":"gặp mặt","examples":[{"cn":"我们好久没见面了。","pinyin":"Wǒmen hǎojiǔ méi jiànmiàn le.","vn":"Chúng ta lâu rồi không gặp mặt."},{"cn":"我们明天下午三点见面吧。","pinyin":"Wǒmen míngtiān xiàwǔ sān diǎn jiànmiàn ba.","vn":"Ngày mai ba giờ chiều chúng ta gặp nhau nhé."},{"cn":"第一次见面,他给我留下了很好的印象。","pinyin":"Dì-yī cì jiànmiàn, tā gěi wǒ liúxià le hěn hǎo de yìnxiàng.","vn":"Lần đầu gặp mặt, anh ấy để lại cho mình ấn tượng rất tốt."}]},{"hanzi":"矿泉水","pinyin":"kuàngquánshuǐ","pos":"dt.","vn":"nước khoáng","examples":[{"cn":"请给我一瓶矿泉水。","pinyin":"Qǐng gěi wǒ yì píng kuàngquánshuǐ.","vn":"Cho mình xin một chai nước khoáng."},{"cn":"出门旅行,记得带几瓶矿泉水。","pinyin":"Chūmén lǚxíng, jìde dài jǐ píng kuàngquánshuǐ.","vn":"Ra ngoài du lịch nhớ mang theo vài chai nước khoáng."},{"cn":"天气太热了,我一天要喝好几瓶矿泉水。","pinyin":"Tiānqì tài rè le, wǒ yì tiān yào hē hǎo jǐ píng kuàngquánshuǐ.","vn":"Thời tiết nóng quá, mình một ngày phải uống mấy chai nước khoáng."}]},{"hanzi":"刚刚","pinyin":"gānggāng","pos":"phó.","vn":"vừa mới","examples":[{"cn":"他刚刚还在这儿,怎么突然不见了?","pinyin":"Tā gānggāng hái zài zhèr, zěnme tūrán bú jiàn le?","vn":"Anh ấy vừa mới còn ở đây, sao đột nhiên biến mất rồi?"},{"cn":"我刚刚吃完饭,现在不饿。","pinyin":"Wǒ gānggāng chī wán fàn, xiànzài bú è.","vn":"Mình vừa mới ăn cơm xong, bây giờ không đói."},{"cn":"这件事是我刚刚才知道的。","pinyin":"Zhè jiàn shì shì wǒ gānggāng cái zhīdào de.","vn":"Chuyện này là mình vừa mới biết thôi."}]},{"hanzi":"出发","pinyin":"chūfā","pos":"dgt.","vn":"xuất phát, khởi hành","examples":[{"cn":"我们明天早上八点出发。","pinyin":"Wǒmen míngtiān zǎoshang bā diǎn chūfā.","vn":"Chúng ta sáng mai tám giờ xuất phát."},{"cn":"快点儿,再不出发就赶不上火车了。","pinyin":"Kuài diǎnr, zài bù chūfā jiù gǎn bu shàng huǒchē le.","vn":"Nhanh lên, không xuất phát ngay là lỡ tàu đấy."},{"cn":"飞机已经出发了,我们只好改签。","pinyin":"Fēijī yǐjīng chūfā le, wǒmen zhǐhǎo gǎiqiān.","vn":"Máy bay đã khởi hành rồi, chúng tôi đành phải đổi vé."}]},{"hanzi":"不久","pinyin":"bùjiǔ","pos":"tt.","vn":"chẳng bao lâu, không lâu sau","examples":[{"cn":"他来中国不久,汉语说得已经不错了。","pinyin":"Tā lái Zhōngguó bùjiǔ, Hànyǔ shuō de yǐjīng búcuò le.","vn":"Anh ấy đến Trung Quốc chưa lâu mà tiếng Hán đã nói khá tốt rồi."},{"cn":"不久之后,我们就要毕业了。","pinyin":"Bùjiǔ zhīhòu, wǒmen jiù yào bìyè le.","vn":"Chẳng bao lâu nữa chúng tôi sẽ tốt nghiệp."},{"cn":"他们结婚不久就有了孩子。","pinyin":"Tāmen jiéhūn bùjiǔ jiù yǒu le háizi.","vn":"Họ kết hôn không lâu thì có con."}]},{"hanzi":"发生","pinyin":"fāshēng","pos":"dgt.","vn":"xảy ra, phát sinh","examples":[{"cn":"昨天这儿发生了一件奇怪的事。","pinyin":"Zuótiān zhèr fāshēng le yí jiàn qíguài de shì.","vn":"Hôm qua ở đây đã xảy ra một chuyện kỳ lạ."},{"cn":"这种事情是怎么发生的?","pinyin":"Zhè zhǒng shìqing shì zěnme fāshēng de?","vn":"Chuyện như thế này xảy ra như thế nào vậy?"},{"cn":"希望这样的事情不要再发生了。","pinyin":"Xīwàng zhèyàng de shìqing bú yào zài fāshēng le.","vn":"Hy vọng chuyện như thế này đừng xảy ra nữa."}]},{"hanzi":"刚","pinyin":"gāng","pos":"phó.","vn":"vừa, vừa mới (cách đây không lâu)","examples":[{"cn":"我刚到家,你就打电话来了。","pinyin":"Wǒ gāng dào jiā, nǐ jiù dǎ diànhuà lái le.","vn":"Mình vừa về đến nhà thì bạn gọi điện đến."},{"cn":"他刚走,你再等一会儿也许能追上他。","pinyin":"Tā gāng zǒu, nǐ zài děng yíhuìr yěxǔ néng zhuīshang tā.","vn":"Anh ấy vừa mới đi, bạn đợi thêm một chút có lẽ đuổi kịp."},{"cn":"这件衣服刚买的,还没穿过呢。","pinyin":"Zhè jiàn yīfu gāng mǎi de, hái méi chuān guo ne.","vn":"Cái áo này vừa mới mua, còn chưa mặc lần nào."}]},{"hanzi":"只要","pinyin":"zhǐyào","pos":"liên.","vn":"chỉ cần","examples":[{"cn":"只要你努力,就一定能成功。","pinyin":"Zhǐyào nǐ nǔlì, jiù yídìng néng chénggōng.","vn":"Chỉ cần bạn nỗ lực là nhất định sẽ thành công."},{"cn":"只要天气好,我们就去爬山。","pinyin":"Zhǐyào tiānqì hǎo, wǒmen jiù qù páshān.","vn":"Chỉ cần thời tiết đẹp là chúng ta sẽ đi leo núi."},{"cn":"只要你需要,我随时都可以帮你。","pinyin":"Zhǐyào nǐ xūyào, wǒ suíshí dōu kěyǐ bāng nǐ.","vn":"Chỉ cần bạn cần, mình lúc nào cũng có thể giúp bạn."}]},{"hanzi":"学期","pinyin":"xuéqī","pos":"dt.","vn":"học kỳ","examples":[{"cn":"这个学期我选了五门课。","pinyin":"Zhège xuéqī wǒ xuǎn le wǔ mén kè.","vn":"Học kỳ này mình đăng ký năm môn học."},{"cn":"下个学期我们要换教室了。","pinyin":"Xià ge xuéqī wǒmen yào huàn jiàoshì le.","vn":"Học kỳ sau chúng tôi phải đổi phòng học."},{"cn":"这个学期快结束了,大家都在准备考试。","pinyin":"Zhège xuéqī kuài jiéshù le, dàjiā dōu zài zhǔnbèi kǎoshì.","vn":"Học kỳ này sắp kết thúc rồi, mọi người đều đang chuẩn bị thi."}]},{"hanzi":"毕业","pinyin":"bìyè","pos":"dgt.","vn":"tốt nghiệp","examples":[{"cn":"我明年就要大学毕业了。","pinyin":"Wǒ míngnián jiù yào dàxué bìyè le.","vn":"Sang năm mình sẽ tốt nghiệp đại học."},{"cn":"毕业以后你打算做什么工作?","pinyin":"Bìyè yǐhòu nǐ dǎsuàn zuò shénme gōngzuò?","vn":"Sau khi tốt nghiệp bạn dự định làm công việc gì?"},{"cn":"他大学毕业后就去了上海工作。","pinyin":"Tā dàxué bìyè hòu jiù qù le Shànghǎi gōngzuò.","vn":"Sau khi tốt nghiệp đại học anh ấy liền đi làm ở Thượng Hải."}]},{"hanzi":"出生","pinyin":"chūshēng","pos":"dgt.","vn":"sinh ra, ra đời","examples":[{"cn":"我出生在一个小城市。","pinyin":"Wǒ chūshēng zài yí ge xiǎo chéngshì.","vn":"Mình sinh ra ở một thành phố nhỏ."},{"cn":"他是1995年出生的。","pinyin":"Tā shì yī jiǔ jiǔ wǔ nián chūshēng de.","vn":"Anh ấy sinh năm 1995."},{"cn":"孩子出生以后,他们的生活完全变了。","pinyin":"Háizi chūshēng yǐhòu, tāmen de shēnghuó wánquán biàn le.","vn":"Sau khi con ra đời, cuộc sống của họ hoàn toàn thay đổi."}]},{"hanzi":"过去","pinyin":"guòqù","pos":"dt.","vn":"quá khứ","examples":[{"cn":"过去的事情就让它过去吧。","pinyin":"Guòqù de shìqing jiù ràng tā guòqù ba.","vn":"Chuyện quá khứ thì cứ để nó qua đi."},{"cn":"我比过去更喜欢读书了。","pinyin":"Wǒ bǐ guòqù gèng xǐhuan dúshū le.","vn":"Mình thích đọc sách hơn so với trước kia."},{"cn":"那已经是过去的事了,别再提了。","pinyin":"Nà yǐjīng shì guòqù de shì le, bié zài tí le.","vn":"Đó đã là chuyện quá khứ rồi, đừng nhắc lại nữa."}]},{"hanzi":"懂得","pinyin":"dǒngde","pos":"dgt.","vn":"hiểu được","examples":[{"cn":"他很懂得照顾别人。","pinyin":"Tā hěn dǒngde zhàogù biérén.","vn":"Anh ấy rất biết cách chăm sóc người khác."},{"cn":"我们要懂得珍惜时间。","pinyin":"Wǒmen yào dǒngde zhēnxī shíjiān.","vn":"Chúng ta phải biết trân trọng thời gian."},{"cn":"长大以后,我才懂得父母的辛苦。","pinyin":"Zhǎngdà yǐhòu, wǒ cái dǒngde fùmǔ de xīnkǔ.","vn":"Sau khi lớn lên mình mới hiểu được sự vất vả của cha mẹ."}]},{"hanzi":"坚持","pinyin":"jiānchí","pos":"dgt.","vn":"kiên trì","examples":[{"cn":"他每天坚持跑步半个小时。","pinyin":"Tā měitiān jiānchí pǎobù bàn ge xiǎoshí.","vn":"Mỗi ngày anh ấy kiên trì chạy bộ nửa tiếng."},{"cn":"学习外语最重要的是坚持。","pinyin":"Xuéxí wàiyǔ zuì zhòngyào de shì jiānchí.","vn":"Học ngoại ngữ điều quan trọng nhất là kiên trì."},{"cn":"虽然很累,但他还是坚持完成了比赛。","pinyin":"Suīrán hěn lèi, dàn tā háishi jiānchí wánchéng le bǐsài.","vn":"Dù rất mệt nhưng anh ấy vẫn kiên trì hoàn thành cuộc thi."}]},{"hanzi":"完成","pinyin":"wánchéng","pos":"dgt.","vn":"hoàn thành","examples":[{"cn":"我今天要完成这份作业。","pinyin":"Wǒ jīntiān yào wánchéng zhè fèn zuòyè.","vn":"Hôm nay mình phải hoàn thành bài tập này."},{"cn":"这个项目终于完成了。","pinyin":"Zhège xiàngmù zhōngyú wánchéng le.","vn":"Dự án này cuối cùng đã hoàn thành."},{"cn":"他用三天时间完成了这幅画。","pinyin":"Tā yòng sān tiān shíjiān wánchéng le zhè fú huà.","vn":"Anh ấy dùng ba ngày để hoàn thành bức tranh này."}]},{"hanzi":"目标","pinyin":"mùbiāo","pos":"dt.","vn":"mục tiêu","examples":[{"cn":"我的目标是学好汉语。","pinyin":"Wǒ de mùbiāo shì xuéhǎo Hànyǔ.","vn":"Mục tiêu của mình là học giỏi tiếng Hán."},{"cn":"我们要为自己的目标努力奋斗。","pinyin":"Wǒmen yào wèi zìjǐ de mùbiāo nǔlì fèndòu.","vn":"Chúng ta phải nỗ lực phấn đấu vì mục tiêu của mình."},{"cn":"这个目标太高了,恐怕很难实现。","pinyin":"Zhège mùbiāo tài gāo le, kǒngpà hěn nán shíxiàn.","vn":"Mục tiêu này quá cao, e rằng khó thực hiện được."}]},{"hanzi":"发展","pinyin":"fāzhǎn","pos":"dgt.","vn":"phát triển","examples":[{"cn":"这几年这座城市发展得很快。","pinyin":"Zhè jǐ nián zhè zuò chéngshì fāzhǎn de hěn kuài.","vn":"Mấy năm nay thành phố này phát triển rất nhanh."},{"cn":"我们公司正在向国际市场发展。","pinyin":"Wǒmen gōngsī zhèngzài xiàng guójì shìchǎng fāzhǎn.","vn":"Công ty chúng tôi đang phát triển ra thị trường quốc tế."},{"cn":"科技的发展改变了我们的生活方式。","pinyin":"Kējì de fāzhǎn gǎibiàn le wǒmen de shēnghuó fāngshì.","vn":"Sự phát triển của khoa học kỹ thuật đã thay đổi cách sống của chúng ta."}]}],"grammar":[{"title":"概数表达法 - Cách diễn đạt số ước lượng","explanation_vn":"Trong tiếng Hán, hai con số liền kề nhau dùng chung với nhau để biểu thị một số lượng không chắc chắn, ước chừng.","examples":[{"cn":"春节大概放七八天假。","pinyin":"Chūnjié dàgài fàng qī-bā tiān jià.","vn":""},{"cn":"教室里来了五六个学生。","pinyin":"Jiàoshì lǐ láile wǔ-liù ge xuésheng.","vn":""},{"cn":"这些照片是三四年前照的吧？","pinyin":"Zhèxiē zhàopiàn shì sān-sì nián qián zhào de ba?","vn":""}]},{"title":"\"刚才\"和\"刚刚\" - So sánh \"刚才\" và \"刚刚\"","explanation_vn":"\"刚才\" là danh từ chỉ thời gian, biểu thị một khoảng thời gian rất ngắn trước đó, thường là vài phút trước; có thể đặt ở đầu câu hoặc sau chủ ngữ, trước động từ. \"刚刚\" là phó từ chỉ thời gian, biểu thị khoảng thời gian không dài đối với người nói, có thể là vài phút, vài ngày thậm chí vài tháng; \"刚刚\" nên đặt sau chủ ngữ, trước động từ.","examples":[{"cn":"刚才的电话是我妈妈打来的。","pinyin":"Gāngcái de diànhuà shì wǒ māma dǎlái de.","vn":""},{"cn":"我刚才看过一遍，不想再看了。","pinyin":"Wǒ gāngcái kànguo yí biàn, bù xiǎng zài kàn le.","vn":""},{"cn":"我刚刚看视频学会了包饺子。","pinyin":"Wǒ gānggāng kàn shìpín xuéhuìle bāo jiǎozi.","vn":""},{"cn":"他刚刚来北京两个月。","pinyin":"Tā gānggāng lái Běijīng liǎng ge yuè.","vn":""}]},{"title":"条件复句\"只要……，就……\" - Câu phức điều kiện \"只要……，就……\"","explanation_vn":"Trong câu phức điều kiện \"只要……，就……\", vế đi sau \"只要\" là điều kiện đủ cần thiết, chỉ cần có điều kiện này là có thể tạo ra kết quả nêu sau \"就\". Chủ ngữ có thể đặt trước hoặc sau \"只要\". Nếu câu có hai chủ ngữ, chủ ngữ thứ hai phải đặt trước \"就\".","examples":[{"cn":"我只要几天不跟他视频，就很想他。","pinyin":"Wǒ zhǐyào jǐ tiān bù gēn tā shìpín, jiù hěn xiǎng tā.","vn":""},{"cn":"只要你同意，我们就这么决定了。","pinyin":"Zhǐyào nǐ tóngyì, wǒmen jiù zhème juédìng le.","vn":""},{"cn":"只要你坚持每天早睡，身体就一定会好起来。","pinyin":"Zhǐyào nǐ jiānchí měitiān zǎo shuì, shēntǐ jiù yídìng huì hǎo qǐlái.","vn":""}]},{"title":"固定格式\"从……起\" - Cấu trúc cố định \"从……起\"","explanation_vn":"Cấu trúc cố định \"从……起\" có nghĩa là \"从……开始\" (bắt đầu từ...), phần lớn dùng để biểu thị thời gian, thường đặt ở đầu câu làm trạng ngữ.","examples":[{"cn":"他从那时起就努力学习。","pinyin":"Tā cóng nàshí qǐ jiù nǔlì xuéxí.","vn":""},{"cn":"从那天起，我们就变成了好朋友。","pinyin":"Cóng nà tiān qǐ, wǒmen jiù biànchéngle hǎo péngyou.","vn":""},{"cn":"从那次旅游起，我对中国文化更有兴趣了。","pinyin":"Cóng nà cì lǚyóu qǐ, wǒ duì Zhōngguó wénhuà gèng yǒu xìngqù le.","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"白家月","cn":"我要在中国过年，真开心。","pinyin":"Wǒ yào zài Zhōngguó guònián, zhēn kāixīn."},{"speaker":"李文","cn":"第一次请外国朋友来家里过春节，我也很高兴。","pinyin":"Dì-yī cì qǐng wàiguó péngyou lái jiā lǐ guò Chūnjié, wǒ yě hěn gāoxìng."},{"speaker":"白家月","cn":"你们怎样过节？","pinyin":"Nǐmen zěnyàng guòjié?"},{"speaker":"李文","cn":"春节是中国最重要的节日，我们一般会回家，跟家人一起过。","pinyin":"Chūnjié shì Zhōngguó zuì zhòngyào de jiérì, wǒmen yìbān huì huíjiā, gēn jiārén yìqǐ guò."},{"speaker":"白家月","cn":"那你跟家人会一起做什么？","pinyin":"Nà nǐ gēn jiārén huì yìqǐ zuò shénme?"},{"speaker":"李文","cn":"我们家会一边包饺子，一边看春节联欢晚会，一直到十二点以后才睡觉。","pinyin":"Wǒmen jiā huì yìbiān bāo jiǎozi, yìbiān kàn Chūnjié Liánhuān Wǎnhuì, yìzhí dào shí'èr diǎn yǐhòu cái shuìjiào."},{"speaker":"白家月","cn":"听起来很有意思。春节放几天假？","pinyin":"Tīng qǐlái hěn yǒu yìsi. Chūnjié fàng jǐ tiān jià?"},{"speaker":"李文","cn":"大概七八天。","pinyin":"Dàgài qī-bā tiān."}],"translation_vn":"Bạch Gia Nguyệt: Mình sắp được đón Tết ở Trung Quốc, thật vui quá.\nLý Văn: Lần đầu tiên mời bạn nước ngoài đến nhà ăn Tết, mình cũng rất vui.\nBạch Gia Nguyệt: Các bạn đón Tết như thế nào?\nLý Văn: Tết Nguyên Đán là ngày lễ quan trọng nhất của Trung Quốc, chúng mình thường sẽ về nhà, đón Tết cùng người thân.\nBạch Gia Nguyệt: Vậy cậu sẽ cùng gia đình làm những gì?\nLý Văn: Nhà mình sẽ vừa gói sủi cảo, vừa xem Chương trình Liên hoan Xuân Tiết, mãi đến sau mười hai giờ mới đi ngủ.\nBạch Gia Nguyệt: Nghe có vẻ rất thú vị. Tết được nghỉ mấy ngày vậy?\nLý Văn: Khoảng bảy tám ngày.","audio_dialogue":"18-1 @xitoytili_luoluodafang.mp3","audio_vocab":"18-2 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"白家月","cn":"张阿姨，李叔叔。过年好！这是我准备的礼物，请收下。","pinyin":"Zhāng āyí, Lǐ shūshu. Guònián hǎo! Zhè shì wǒ zhǔnbèi de lǐwù, qǐng shōuxià."},{"speaker":"李叔叔","cn":"谢谢家月，你太客气了！","pinyin":"Xièxie Jiāyuè, nǐ tài kèqi le!"},{"speaker":"张阿姨","cn":"总听小文说起你，今天终于有机会见面了。","pinyin":"Zǒng tīng Xiǎowén shuōqǐ nǐ, jīntiān zhōngyú yǒu jīhuì jiànmiàn le."},{"speaker":"白家月","cn":"谢谢您和叔叔请我来家里做客。","pinyin":"Xièxie nín hé shūshu qǐng wǒ lái jiā lǐ zuòkè."},{"speaker":"李叔叔","cn":"桌子上有饮料，还有矿泉水，你想喝什么就自己拿。","pinyin":"Zhuōzi shàng yǒu yǐnliào, hái yǒu kuàngquánshuǐ, nǐ xiǎng hē shénme jiù zìjǐ ná."},{"speaker":"张阿姨","cn":"你先坐着看会儿电视，饺子很快就包好了。","pinyin":"Nǐ xiān zuòzhe kàn huìr diànshì, jiǎozi hěn kuài jiù bāohǎo le."},{"speaker":"白家月","cn":"我刚刚看视频学会了包饺子，我跟你们一起包吧。","pinyin":"Wǒ gānggāng kàn shìpín xuéhuìle bāo jiǎozi, wǒ gēn nǐmen yìqǐ bāo ba."}],"translation_vn":"Bạch Gia Nguyệt: Dì Trương, chú Lý, chúc mừng năm mới! Đây là món quà con chuẩn bị, mời dì chú nhận cho.\nChú Lý: Cảm ơn Gia Nguyệt, con khách sáo quá!\nDì Trương: Dì vẫn luôn nghe Tiểu Văn nhắc đến con, hôm nay cuối cùng cũng có dịp gặp mặt rồi.\nBạch Gia Nguyệt: Cảm ơn dì và chú đã mời con đến nhà chơi.\nChú Lý: Trên bàn có nước giải khát, còn có nước khoáng nữa, con muốn uống gì thì tự lấy nhé.\nDì Trương: Con cứ ngồi xem ti vi một lát, sủi cảo sắp gói xong rồi.\nBạch Gia Nguyệt: Con vừa mới xem video học được cách gói sủi cảo, con gói cùng mọi người nhé.","audio_dialogue":"18-3 @xitoytili_luoluodafang.mp3","audio_vocab":"18-4 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"白家月","cn":"这张照片是李文出国前照的吗？","pinyin":"Zhè zhāng zhàopiàn shì Lǐ Wén chūguó qián zhào de ma?"},{"speaker":"张阿姨","cn":"对，这是他从北京出发时，我们全家在机场照的。","pinyin":"Duì, zhè shì tā cóng Běijīng chūfā shí, wǒmen quánjiā zài jīchǎng zhào de."},{"speaker":"白家月","cn":"那是三四年前吧？","pinyin":"Nà shì sān-sì nián qián ba?"},{"speaker":"张阿姨","cn":"是啊，时间过得真快，好像是不久前发生的一样。","pinyin":"Shì a, shíjiān guò de zhēn kuài, hǎoxiàng shì bùjiǔ qián fāshēng de yíyàng."},{"speaker":"白家月","cn":"您一定特别想李文吧？","pinyin":"Nín yídìng tèbié xiǎng Lǐ Wén ba?"},{"speaker":"张阿姨","cn":"他刚离开家时，我很不习惯，只要几天不跟他视频，就很想他。","pinyin":"Tā gāng líkāi jiā shí, wǒ hěn bù xíguàn, zhǐyào jǐ tiān bù gēn tā shìpín, jiù hěn xiǎng tā."},{"speaker":"白家月","cn":"还有最后一个学期就要毕业了，他很快就会回来了。","pinyin":"Hái yǒu zuìhòu yí ge xuéqī jiù yào bìyè le, tā hěn kuài jiù huì huílái le."}],"translation_vn":"Bạch Gia Nguyệt: Tấm ảnh này là chụp trước khi Lý Văn ra nước ngoài ạ?\nDì Trương: Đúng rồi, đây là lúc nó xuất phát từ Bắc Kinh, cả nhà dì chụp ở sân bay.\nBạch Gia Nguyệt: Lúc đó là khoảng ba bốn năm trước ạ?\nDì Trương: Đúng vậy, thời gian trôi nhanh thật, cứ như mới xảy ra gần đây vậy.\nBạch Gia Nguyệt: Chắc dì nhớ Lý Văn lắm phải không ạ?\nDì Trương: Lúc nó vừa rời nhà, dì rất không quen, chỉ cần vài ngày không gọi video với nó là dì nhớ nó lắm.\nBạch Gia Nguyệt: Còn một học kỳ cuối nữa là anh ấy sẽ tốt nghiệp rồi, anh ấy sẽ sớm trở về thôi ạ.","audio_dialogue":"18-5 @xitoytili_luoluodafang.mp3","audio_vocab":"18-6 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"这次来中国，我最高兴的是认识了李文的父母。他们给我看了李文出生时的照片，还给我讲了很多他过去的故事。李文高中的时候想学医，从那时起就努力学习。高三的时候，因为成绩特别好，他得到了出国留学的机会。在他身上，我懂得了，只要一直坚持，就能完成自己的目标。我相信，他以后一定会发展得更好。","pinyin":"Zhè cì lái Zhōngguó, wǒ zuì gāoxìng de shì rènshile Lǐ Wén de fùmǔ. Tāmen gěi wǒ kànle Lǐ Wén chūshēng shí de zhàopiàn, hái gěi wǒ jiǎngle hěn duō tā guòqù de gùshi. Lǐ Wén gāozhōng de shíhou xiǎng xué yī, cóng nàshí qǐ jiù nǔlì xuéxí. Gāosān de shíhou, yīnwèi chéngjì tèbié hǎo, tā dédàole chūguó liúxué de jīhuì. Zài tā shēnshang, wǒ dǒngde le, zhǐyào yìzhí jiānchí, jiù néng wánchéng zìjǐ de mùbiāo. Wǒ xiāngxìn, tā yǐhòu yídìng huì fāzhǎn de gèng hǎo."}],"translation_vn":"Lần này đến Trung Quốc, điều khiến tôi vui nhất là được quen biết bố mẹ của Lý Văn. Họ cho tôi xem những tấm ảnh lúc Lý Văn mới sinh ra, còn kể cho tôi nghe rất nhiều câu chuyện trong quá khứ của anh ấy. Khi học trung học phổ thông, Lý Văn muốn học y, từ đó anh đã nỗ lực học tập. Năm lớp mười hai, vì thành tích đặc biệt tốt, anh đã có được cơ hội đi du học nước ngoài. Qua anh ấy, tôi đã hiểu ra rằng, chỉ cần luôn kiên trì, thì sẽ có thể hoàn thành mục tiêu của bản thân. Tôi tin rằng, sau này anh ấy chắc chắn sẽ phát triển tốt hơn nữa.","audio_dialogue":"18-7 @xitoytili_luoluodafang.mp3","audio_vocab":"18-8 @xitoytili_luoluodafang.mp3"}]}],"pos_table":[{"pos_cn":"名词","pos_vn":"Danh từ","abbr":"dt."},{"pos_cn":"动词","pos_vn":"Động từ","abbr":"dgt."},{"pos_cn":"形容词","pos_vn":"Tính từ","abbr":"tt."},{"pos_cn":"代词","pos_vn":"Đại từ","abbr":"đt."},{"pos_cn":"副词","pos_vn":"Phó từ","abbr":"phó."},{"pos_cn":"介词","pos_vn":"Giới từ","abbr":"giới."},{"pos_cn":"连词","pos_vn":"Liên từ","abbr":"liên."},{"pos_cn":"助词","pos_vn":"Trợ từ","abbr":"trợ."},{"pos_cn":"数词","pos_vn":"Từ chỉ số đếm","abbr":"số."},{"pos_cn":"量词","pos_vn":"Lượng từ","abbr":"lượng."},{"pos_cn":"数量词","pos_vn":"Từ chỉ số lượng","abbr":"sl."},{"pos_cn":"叹词","pos_vn":"Từ cảm thán","abbr":"ct."},{"pos_cn":"拟声词","pos_vn":"Từ tượng thanh","abbr":"tượng."},{"pos_cn":"能愿动词","pos_vn":"Động từ năng nguyện","abbr":"đtnn."},{"pos_cn":"前缀","pos_vn":"Tiền tố","abbr":"ttố."},{"pos_cn":"后缀","pos_vn":"Hậu tố","abbr":"htố."}]};